--
-- Name: account_state(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.account_state(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $$
declare e collect_admin_access.email_approvals;w collect_admin_access.whatsapp_approvals;
 approved boolean;granted boolean;state text;approval_time timestamptz;expiry timestamptz;
begin
 select * into e from collect_admin_access.email_approvals where user_id=p_user;
 select * into w from collect_admin_access.whatsapp_approvals where user_id=p_user;
 approved:=collect_admin_access.approved_identity(p_user);
 granted:=exists(select 1 from public.admin_user_roles ur join public.admin_roles r on r.id=ur.role_id
  where ur.user_id=p_user and ur.revoked_at is null and r.name='platform_owner');
 if e.user_id is not null then
  approval_time:=e.approved_at;expiry:=e.expires_at;
  state:=case when e.revoked_at is not null then 'revoked'
   when e.expires_at<=statement_timestamp() then 'expired'
   when not approved then 'identity_changed' else 'approved' end;
 else
  approval_time:=w.approved_at;expiry:=w.expires_at;
  state:=case when w.user_id is null then 'not_approved' when w.revoked_at is not null then 'revoked'
   when w.expires_at<=statement_timestamp() then 'expired'
   when not approved then 'identity_changed' else 'approved' end;
 end if;
 return jsonb_build_object('user_id',p_user,'phone_masked',public.mask_phone(collect_admin_access.verified_phone(p_user)),
  'approved_at',approval_time,'expires_at',expiry,'status',state,'approved',approved,'role_granted',granted,
  'admin_access',approved and granted,'access_status',case when approved and granted then 'active'
   when granted then 'approval_required' when approved then 'approved' else 'revoked' end);
end $$;


ALTER FUNCTION collect_admin_access.account_state(p_user uuid) OWNER TO postgres;

--
-- Name: approval_status(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.approval_status(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.assert_admin_permission('admin_users.read');
  if not exists(select 1 from public.profiles where id=p_user) then
    raise exception 'Account unavailable' using errcode='22023';
  end if;
  return collect_admin_access.account_state(p_user);
end;
$$;


ALTER FUNCTION collect_admin_access.approval_status(p_user uuid) OWNER TO postgres;

--
-- Name: approve_whatsapp(uuid, text, text, timestamp with time zone, boolean); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.approve_whatsapp(p_user uuid, p_phone text, p_reason text, p_expires_at timestamp with time zone, p_bootstrap boolean) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  phone text := btrim(coalesce(p_phone,''));
  reason_text text := btrim(coalesce(p_reason,''));
  prior collect_admin_access.whatsapp_approvals%rowtype;
begin
  -- All access/approval mutations serialize, and caller authority is checked
  -- AFTER waiting so a revoked operator cannot finish a queued grant.
  perform public._lock_notification_session_gate();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  -- A request opened before cutover cannot create a legacy approval after
  -- waiting for the authority/mode lock. Private/bootstrap callers share it.
  perform 1 from collect_admin_access.operator_auth_policy where id and mode='transition' for share;
  if not found or exists(select 1 from collect_admin_access.email_approvals where user_id=p_user) then
    raise exception 'operator_legacy_approval_disabled' using errcode='42501';
  end if;
  if not p_bootstrap then
    perform collect_hybrid.require_roster_actor_authority(auth.uid(),
      public._lock_notification_registration_session(),'platform_owner',array['admin_users.manage']);
  end if;

  if p_bootstrap then
    if auth.jwt()->>'role' is distinct from 'service_role' then
      raise exception 'Service role required' using errcode='42501';
    end if;
    if exists(select 1 from public.admin_user_roles ur join public.admin_roles r on r.id=ur.role_id
      where ur.revoked_at is null and r.name='platform_owner'
        and collect_admin_access.approved_identity(ur.user_id)) then
      raise exception 'An approved Admin already exists' using errcode='42501';
    end if;
  else
    perform public.assert_admin_permission('admin_users.manage');
    if p_user=auth.uid() then
      raise exception 'Another Admin must approve your identity' using errcode='42501';
    end if;
  end if;
  if length(reason_text) not between 1 and 1000
    or phone !~ '^\+[1-9][0-9]{7,14}$'
    or (p_expires_at is not null and p_expires_at <= clock_timestamp()) then
    raise exception 'Verified international WhatsApp number and reason required' using errcode='22023';
  end if;
  perform 1 from auth.users where id=p_user for update;
  if phone is distinct from collect_admin_access.verified_phone(p_user) then
    raise exception 'WhatsApp identity could not be verified' using errcode='22023';
  end if;
  select * into prior from collect_admin_access.whatsapp_approvals where user_id=p_user;
  if prior.user_id is not null and prior.revoked_at is null and prior.phone_e164=phone
    and prior.expires_at is not distinct from p_expires_at
    and (prior.expires_at is null or prior.expires_at > statement_timestamp()) then
    return jsonb_build_object('ok',true,'status','approved','user_id',p_user);
  end if;
  insert into collect_admin_access.whatsapp_approvals(user_id,phone_e164,approved_by,reason,expires_at)
  values(p_user,phone,auth.uid(),reason_text,p_expires_at)
  on conflict(user_id) do update set phone_e164=excluded.phone_e164,
    approved_at=clock_timestamp(),approved_by=excluded.approved_by,reason=excluded.reason,
    expires_at=excluded.expires_at,revoked_at=null,revoked_by=null,revoke_reason=null;
  insert into public.audit_logs(actor_user_id,action,entity_type,entity_id,metadata)
  values(auth.uid(),'admin.whatsapp.approved','profile',p_user,
    jsonb_build_object('phone_masked',public.mask_phone(phone),'reason',reason_text,
      'expires_at',p_expires_at,'service_bootstrap',p_bootstrap));
  -- Approval alone never creates or reactivates an Admin role.
  return jsonb_build_object('ok',true,'status','approved','user_id',p_user);
end;
$_$;


ALTER FUNCTION collect_admin_access.approve_whatsapp(p_user uuid, p_phone text, p_reason text, p_expires_at timestamp with time zone, p_bootstrap boolean) OWNER TO postgres;

--
-- Name: approved_identity(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.approved_identity(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select collect_admin_access.email_identity(p_user) or
  (not exists(select 1 from collect_admin_access.email_approvals where user_id=p_user)
   and exists(select 1 from collect_admin_access.operator_auth_policy where id and mode='transition')
   and exists(select 1 from collect_admin_access.whatsapp_approvals a
    where a.user_id=p_user and a.revoked_at is null
     and (a.expires_at is null or a.expires_at>statement_timestamp())
     and a.phone_e164=collect_admin_access.verified_phone(p_user)))
$$;


ALTER FUNCTION collect_admin_access.approved_identity(p_user uuid) OWNER TO postgres;

--
-- Name: bootstrap_owner(uuid, text); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.bootstrap_owner(p_user uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare v_role_id uuid;
begin
 perform public._lock_notification_session_gate();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  if auth.jwt()->>'role' is distinct from 'service_role' then
    raise exception 'Service role required' using errcode='42501';
  end if;
  if length(btrim(coalesce(p_reason,''))) not between 1 and 1000
    or not collect_admin_access.approved_identity(p_user) then
    raise exception 'Pre-approved verified identity and reason required' using errcode='42501';
  end if;
  select id into v_role_id from public.admin_roles where name='platform_owner';
  if not exists(select 1 from public.admin_user_roles ur where ur.user_id=p_user
    and ur.role_id=v_role_id and ur.revoked_at is null) then
    insert into public.admin_user_roles(user_id,role_id,reason,created_at)
    values(p_user,v_role_id,p_reason,clock_timestamp());
    insert into public.audit_logs(action,entity_type,entity_id,metadata)
    values('admin.bootstrap.platform_owner','profile',p_user,jsonb_build_object('reason',p_reason));
  end if;
  return jsonb_build_object('ok',true);
end;
$$;


ALTER FUNCTION collect_admin_access.bootstrap_owner(p_user uuid, p_reason text) OWNER TO postgres;

--
-- Name: caller_eligible(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.caller_eligible(p_user uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE
    SET search_path TO ''
    AS $_$
declare session_key text := auth.jwt()->>'session_id';
begin
  if not collect_admin_access.approved_identity(p_user) then return false; end if;
  if auth.jwt()->>'role' = 'service_role' then return true; end if;
  if auth.role() is distinct from 'authenticated' then return false; end if;
  if p_user is distinct from auth.uid() or session_key is null
    or session_key !~ '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$' then
    return false;
  end if;
  if current_setting('transaction_isolation')<>'read committed' then
    raise exception 'admin_snapshot_retry' using errcode='40001';
  end if;
  return exists(select 1 from auth.sessions s join auth.users u on u.id=s.user_id
    join public.admin_user_roles ur on ur.user_id=u.id and ur.revoked_at is null
    join public.admin_roles r on r.id=ur.role_id and r.name='platform_owner'
    where s.id=session_key::uuid and s.user_id=p_user
      and public._notification_session_is_live(s.id,p_user) and s.created_at<=statement_timestamp()
      and s.created_at>=ur.created_at
      and (exists(select 1 from collect_admin_access.email_approvals a
        where a.user_id=p_user and collect_admin_access.email_identity(p_user) and s.created_at>=a.approved_at)
       or (exists(select 1 from collect_admin_access.operator_auth_policy where id and mode='transition')
        and exists(select 1 from collect_admin_access.whatsapp_approvals a where a.user_id=p_user
         and a.revoked_at is null and (a.expires_at is null or a.expires_at>statement_timestamp())
         and a.phone_e164=collect_admin_access.verified_phone(p_user) and s.created_at>=a.approved_at))));
end$_$;


ALTER FUNCTION collect_admin_access.caller_eligible(p_user uuid) OWNER TO postgres;

--
-- Name: current_identity(); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.current_identity() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  if not collect_admin_access.permission_allowed('overview.read',auth.uid()) then return '{}'::jsonb; end if;
  return coalesce((select jsonb_build_object('user_id',p.id,'display_name','Collect ID '||p.public_id,
    'phone_masked',public.mask_phone(collect_admin_access.verified_phone(p.id)),
    'roles','["admin"]'::jsonb,'permissions',(select coalesce(jsonb_agg(rp.permission_name order by rp.permission_name),'[]'::jsonb)
      from public.admin_role_permissions rp join public.admin_roles r on r.id=rp.role_id where r.name='platform_owner'))
    from public.profiles p where p.id=auth.uid()),'{}'::jsonb);
end;
$$;


ALTER FUNCTION collect_admin_access.current_identity() OWNER TO postgres;

--
-- Name: email_identity(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.email_identity(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select exists(select 1 from auth.users u join collect_admin_access.email_approvals a on a.user_id=u.id
  where u.id=p_user and u.deleted_at is null and not coalesce(u.is_anonymous,false)
   and (u.banned_until is null or u.banned_until<=statement_timestamp())
   and u.email_confirmed_at is not null and lower(btrim(u.email))=a.email
   and a.revoked_at is null and (a.expires_at is null or a.expires_at>statement_timestamp()))
$$;


ALTER FUNCTION collect_admin_access.email_identity(p_user uuid) OWNER TO postgres;

--
-- Name: get_admin_user(uuid); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.get_admin_user(p_user uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.assert_admin_permission('admin_users.read');
  return coalesce((select s.state || jsonb_build_object(
    'id',p.id,'public_id',p.public_id,'created_at',p.created_at,
    'status',s.state->>'access_status','whatsapp_approval',s.state->>'status',
    'active_roles',case when (s.state->>'admin_access')::boolean then '["admin"]'::jsonb else '[]'::jsonb end)
    from public.profiles p cross join lateral (select collect_admin_access.account_state(p.id) state) s
    where p.id=p_user and (exists(select 1 from public.admin_user_roles where user_id=p.id)
      or exists(select 1 from collect_admin_access.whatsapp_approvals where user_id=p.id))), '{}'::jsonb);
end;
$$;


ALTER FUNCTION collect_admin_access.get_admin_user(p_user uuid) OWNER TO postgres;

--
-- Name: list_admin_users(text, text, integer, integer, text); Type: FUNCTION; Schema: collect_admin_access; Owner: postgres
--

CREATE FUNCTION collect_admin_access.list_admin_users(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('admin_users.read');
  with accounts as (
    select p.id,p.public_id,p.created_at,collect_admin_access.account_state(p.id) state
    from public.profiles p where exists(select 1 from public.admin_user_roles where user_id=p.id)
      or exists(select 1 from collect_admin_access.whatsapp_approvals where user_id=p.id)
  ), filtered as (
    select * from accounts where (p_search is null or public_id=p_search
      or state->>'phone_masked' ilike '%'||p_search||'%')
      and (p_status is null or state->>'access_status'=p_status
        or (p_status='admin' and state->>'access_status'='active'))
  ), ordered as (
    select *,row_number() over(order by
      case when p_sort='created_at_asc' then created_at end asc nulls last,created_at desc,id) rank
    from filtered order by rank limit least(greatest(coalesce(p_limit,25),1),100) offset greatest(coalesce(p_offset,0),0)
  )
  select jsonb_build_object('total',(select count(*) from filtered),'rows',coalesce(jsonb_agg(
    public._admin_row(id,'Collect ID '||public_id,'',state->>'access_status','Admin',created_at,
      state || jsonb_build_object('public_id',public_id)) order by rank),'[]'::jsonb)) into result from ordered;
  return result;
end;
$$;


ALTER FUNCTION collect_admin_access.list_admin_users(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

