--
-- Name: protect_policy(); Type: FUNCTION; Schema: collect_automation; Owner: postgres
--

CREATE FUNCTION collect_automation.protect_policy() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$begin
 if tg_op='DELETE'or new.id is distinct from old.id or new.singleton is distinct from old.singleton
  or new.initialized_at is distinct from old.initialized_at or new.revision is distinct from old.revision+1
  or new.updated_at<old.updated_at or new.last_change_request_id is null
  or(new.configured_mode=old.configured_mode and new.emergency_stop=old.emergency_stop)then
  raise exception 'operating_policy_revision_invalid'using errcode='55000';end if;
 return new;end$$;


ALTER FUNCTION collect_automation.protect_policy() OWNER TO postgres;

SET default_tablespace = '';

SET default_table_access_method = heap;

--
-- Name: policy_requests; Type: TABLE; Schema: collect_automation; Owner: postgres
--

CREATE TABLE collect_automation.policy_requests (
    request_id uuid NOT NULL,
    policy_id uuid NOT NULL,
    actor_id uuid NOT NULL,
    session_id uuid NOT NULL,
    expected_revision bigint NOT NULL,
    revision bigint NOT NULL,
    mode_before text NOT NULL,
    mode_after text NOT NULL,
    stop_before boolean NOT NULL,
    stop_after boolean NOT NULL,
    changed boolean NOT NULL,
    reason_code text NOT NULL,
    recorded_at timestamp with time zone NOT NULL,
    CONSTRAINT policy_requests_check CHECK ((changed = ((mode_before <> mode_after) OR (stop_before <> stop_after)))),
    CONSTRAINT policy_requests_check1 CHECK ((revision = (expected_revision +
CASE
    WHEN changed THEN 1
    ELSE 0
END))),
    CONSTRAINT policy_requests_check2 CHECK (((mode_after <> 'Paused'::text) OR stop_after)),
    CONSTRAINT policy_requests_check3 CHECK (((reason_code <> 'operator_emergency_stop'::text) OR stop_after)),
    CONSTRAINT policy_requests_check4 CHECK (((reason_code <> 'operator_clear_future_stop'::text) OR (NOT stop_after))),
    CONSTRAINT policy_requests_expected_revision_check CHECK (((expected_revision >= 1) AND (expected_revision <= 1000000000))),
    CONSTRAINT policy_requests_mode_after_check CHECK ((mode_after = ANY (ARRAY['Shadow'::text, 'Dry-run'::text, 'Paused'::text]))),
    CONSTRAINT policy_requests_mode_before_check CHECK ((mode_before = ANY (ARRAY['Shadow'::text, 'Dry-run'::text, 'Paused'::text]))),
    CONSTRAINT policy_requests_reason_code_check CHECK ((reason_code = ANY (ARRAY['operator_reviewed_configuration'::text, 'operator_emergency_stop'::text, 'operator_clear_future_stop'::text]))),
    CONSTRAINT policy_requests_recorded_at_check CHECK (isfinite(recorded_at)),
    CONSTRAINT policy_requests_revision_check CHECK (((revision >= 1) AND (revision <= 1000000000)))
);


ALTER TABLE collect_automation.policy_requests OWNER TO postgres;

