    public_key_spki_base64 text NOT NULL,
    key_sha256 text NOT NULL,
    signing_certificate_sha256 text NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    activated_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT devices_check CHECK ((((state = 'pending'::text) AND (activated_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'active'::text) AND (activated_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((state = 'revoked'::text) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT devices_key_sha256_check CHECK ((key_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT devices_signing_certificate_sha256_check CHECK ((signing_certificate_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT devices_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'active'::text, 'revoked'::text])))
);


