-- Name: attempts; Type: TABLE; Schema: collect_gateway_dispatch; Owner: postgres
--

CREATE TABLE collect_gateway_dispatch.attempts (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    outbox_id uuid NOT NULL,
    device_id uuid NOT NULL,
    run_id uuid NOT NULL,
    principal_id uuid NOT NULL,
    fence_version bigint NOT NULL,
    policy_revision bigint NOT NULL,
    grant_request_id uuid NOT NULL,
    reservation_id uuid NOT NULL,
    body_sha256 text NOT NULL,
    destination_sha256 text NOT NULL,
    segment_count integer NOT NULL,
    health_observation_id uuid NOT NULL,
    sim_revision_sha256 text NOT NULL,
    issued_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    state text DEFAULT 'granted'::text NOT NULL,
    updated_at timestamp with time zone NOT NULL,
    CONSTRAINT attempts_body_sha256_check CHECK ((body_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT attempts_check CHECK (((expires_at > issued_at) AND (expires_at <= (issued_at + '00:00:30'::interval)))),
    CONSTRAINT attempts_destination_sha256_check CHECK ((destination_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT attempts_fence_version_check CHECK (((fence_version >= 1) AND (fence_version <= 1000000000))),
    CONSTRAINT attempts_segment_count_check CHECK (((segment_count >= 1) AND (segment_count <= 10))),
    CONSTRAINT attempts_sim_revision_sha256_check CHECK ((sim_revision_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT attempts_state_check CHECK ((state = ANY (ARRAY['granted'::text, 'send_started'::text, 'observed_sent'::text, 'uncertain'::text])))
);


