    local_pause boolean NOT NULL,
    CONSTRAINT health_observations_check CHECK (((sim_selected AND (sim_revision_sha256 IS NOT NULL) AND (sim_revision_sha256 ~ '^[0-9a-f]{64}$'::text)) OR ((NOT sim_selected) AND (sim_revision_sha256 IS NULL)))),
    CONSTRAINT health_observations_network_check CHECK ((network = ANY (ARRAY['validated'::text, 'unvalidated'::text, 'offline'::text, 'unknown'::text]))),
    CONSTRAINT health_observations_telephony_check CHECK ((telephony = ANY (ARRAY['ready'::text, 'unavailable'::text, 'unknown'::text])))
);


