--
-- Name: segment_count(text); Type: FUNCTION; Schema: collect_gateway_dispatch; Owner: postgres
--

CREATE FUNCTION collect_gateway_dispatch.segment_count(p_body text) RETURNS integer
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$declare n integer;begin
 if p_body is null or p_body!~'^[A-Za-z0-9 Éé.,/:_-]+$'or octet_length(p_body)>1000 then raise exception 'gateway_dispatch_encoding_unsupported'using errcode='55000';end if;
 n:=char_length(p_body);return case when n<=160 then 1 else ceil(n::numeric/153)::integer end;end$_$;


