--
-- Name: capture_escalation_event(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.capture_escalation_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare e collect_ops.exception_escalations;phase text;at timestamptz;
 who text;actor uuid;begin
 if tg_table_name='exception_escalations'then
  e:=new;
  if tg_op='INSERT'then phase:='queued';at:=new.queued_at;
  elsif new.state='obsolete'and new.state is distinct from old.state then phase:='obsolete';at:=new.completed_at;
  elsif new.state='recipient_unavailable'and(new.state is distinct from old.state or new.retry_at is distinct from old.retry_at)then
   phase:='recipient_unavailable';at:=clock_timestamp();
  else return new;end if;
 else
  select * into strict e from collect_ops.exception_escalations where id=new.escalation_id;
  if tg_table_name='exception_inbox_deliveries'then phase:='delivered';at:=new.delivered_at;
  else phase:='opened';at:=new.read_at;end if;
 end if;
 who:=case when auth.role()='service_role'then 'service'
  when auth.role()='authenticated'and auth.uid()is not null then 'operator'else 'unknown'end;
 actor:=case when who='operator'then auth.uid()end;
 insert into collect_ops.exception_escalation_events(escalation_id,exception_id,source_revision,action,recorded_at,actor_kind,actor_id,origin)
 values(e.id,e.exception_id,e.source_revision,phase,at,who,actor,'captured_transition');
 return new;
end$$;


ALTER FUNCTION collect_ops.capture_escalation_event() OWNER TO postgres;

--
-- Name: capture_receipt_backlog_budget_refusal(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.capture_receipt_backlog_budget_refusal() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_receipt_operations.runs;p collect_receipt_operations.policy;s collect_hybrid.momo_balance_snapshots;begin
 if new.action<>'reconcile_backlog'then return new;end if;
 r:=collect_receipt_operations.require_run((new.input->>'run_id')::uuid,(new.input->>'fence_version')::bigint,new.principal_id);
 select * into p from collect_receipt_operations.policy where singleton;
 if p.catchup_enabled and r.mode in('Live','Live-limited')and(new.result->>'examined')::integer<(new.input->>'limit')::integer then
  select * into s from collect_hybrid.momo_balance_snapshots snapshot
   where snapshot.event_type='receipt'and snapshot.collection_id=any(r.collection_ids)
    and snapshot.captured_at>=clock_timestamp()-make_interval(hours=>p.catchup_hours)
    and not exists(select 1 from collect_hybrid.sms_notification_outbox o where o.payment_id=snapshot.payment_id and o.template_key='buri_munsi.payment_received')
    and not exists(select 1 from collect_receipt_operations.backlog_results b where b.run_id=r.id and b.snapshot_id=snapshot.id)
   order by snapshot.captured_at,snapshot.id limit 1;
  if s.id is not null and not collect_ops.receipt_exception_run_budget_available(r.id,s.collection_id)then
   insert into collect_ops.receipt_backlog_budget_deferrals(request_id,run_id,snapshot_id)values(new.request_id,r.id,s.id);
  end if;
 end if;return new;end$$;


ALTER FUNCTION collect_ops.capture_receipt_backlog_budget_refusal() OWNER TO postgres;

--
-- Name: capture_source(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.capture_source() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare kind text;source uuid;
begin
 kind:=case tg_table_name when 'raw_payment_sms' then 'raw_sms' when 'parsed_payment_events' then 'allocation'
  when 'payments' then 'payment' when 'sms_notification_outbox' then 'receipt' when 'devices' then 'gateway'
  when 'health_observations' then 'gateway' when 'payment_provider_confirmations' then 'payment'
  when 'payment_provider_rejections' then 'payment' end;
 if tg_table_name='health_observations' then source:=new.device_id;
 elsif tg_table_name in('payment_provider_confirmations','payment_provider_rejections') then source:=new.payment_id;
 else source:=new.id;end if;
 perform collect_ops.refresh_source(kind,source);return new;
end$$;


ALTER FUNCTION collect_ops.capture_source() OWNER TO postgres;

--
-- Name: followup_v2_actor(boolean); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.followup_v2_actor(p_mutation boolean) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;
begin
 sid:=collect_ops.actor(p_mutation);
 -- A transition-mode WhatsApp owner remains valid for v1, never for v2.
 if collect_admin_access.email_identity(auth.uid()) is distinct from true
  or not exists(select 1 from collect_admin_access.email_approvals a
   where a.user_id=auth.uid() and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>clock_timestamp())) then
  raise exception 'exception_followup_email_owner_required' using errcode='42501';
 end if;
 return sid;
end $$;


ALTER FUNCTION collect_ops.followup_v2_actor(p_mutation boolean) OWNER TO postgres;

--
-- Name: followup_v2_fingerprint(uuid, uuid, bigint, bigint, text, uuid, timestamp with time zone, text, timestamp with time zone); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.followup_v2_fingerprint(p_request_id uuid, p_exception_id uuid, p_expected_source_revision bigint, p_expected_workflow_revision bigint, p_action text, p_assignee_id uuid, p_due_at timestamp with time zone, p_reason_code text, p_expires_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql IMMUTABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if p_request_id is null or p_exception_id is null or p_expected_source_revision is null
  or p_expected_source_revision not between 1 and 1000000000
  or p_expected_workflow_revision is null or p_expected_workflow_revision not between 0 and 999999999
  or p_action is null or p_action not in('assign','escalate','resolve')
  or p_reason_code is null or p_reason_code not in('review_started','owner_review_required',
   'uncertain_send_review','contact_review','source_rechecked')
  or (p_action='assign' and (p_assignee_id is null or p_due_at is null))
  or (p_action<>'assign' and (p_assignee_id is not null or p_due_at is not null))
  or (p_action='resolve' and p_reason_code<>'source_rechecked')
  or p_expires_at is null or not isfinite(p_expires_at)
  or p_expires_at<'0001-01-01T00:00:00Z'::timestamptz
  or p_expires_at>='10000-01-01T00:00:00Z'::timestamptz
  or (p_due_at is not null and (not isfinite(p_due_at)
   or p_due_at<'0001-01-01T00:00:00Z'::timestamptz
   or p_due_at>='10000-01-01T00:00:00Z'::timestamptz)) then
  raise exception 'exception_followup_input_invalid' using errcode='22023';
 end if;
 -- Closed enums, canonical UUID/decimal/UTC6 fields, exactly one LF between
 -- fields, and no final LF make this grammar unambiguous across clients.
 return encode(extensions.digest(convert_to(concat_ws(E'\n',
  'collect-exception-workflow-v2',p_request_id::text,p_exception_id::text,
  p_expected_source_revision::text,p_expected_workflow_revision::text,p_action,
  coalesce(p_assignee_id::text,'-'),coalesce(collect_ops.utc(p_due_at),'-'),
  p_reason_code,collect_ops.utc(p_expires_at)),'UTF8'),'sha256'),'hex');
end $$;


ALTER FUNCTION collect_ops.followup_v2_fingerprint(p_request_id uuid, p_exception_id uuid, p_expected_source_revision bigint, p_expected_workflow_revision bigint, p_action text, p_assignee_id uuid, p_due_at timestamp with time zone, p_reason_code text, p_expires_at timestamp with time zone) OWNER TO postgres;

