-- Name: protect_receipt_exception_work(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.protect_receipt_exception_work() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$begin
 if tg_op='DELETE'or(to_jsonb(new)-array['processed_at','outcome','processed_request_id'])is distinct from(to_jsonb(old)-array['processed_at','outcome','processed_request_id'])
  or old.processed_at is not null or new.processed_at is null then raise exception 'receipt_exception_work_immutable'using errcode='55000';end if;return new;end$$;


