--
-- Name: protect_workflow(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.protect_workflow() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$begin
 if tg_op='DELETE' or new.exception_id<>old.exception_id or new.revision<>old.revision+1
  or new.updated_at<old.updated_at then
  raise exception 'exception_workflow_revision_invalid'using errcode='55000';end if;
 return new;end$$;


