--
-- Name: receipt_exception_base_refresh_source(text, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_exception_base_refresh_source(p_kind text, p_source uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sms public.raw_payment_sms;event public.parsed_payment_events;payment public.payments;
 receipt collect_hybrid.sms_notification_outbox;device collect_gateway.devices;
 health collect_gateway.health_observations;codes text[]:='{}';signature jsonb;
 confirmation public.payment_provider_confirmations;rejected boolean;fresh boolean;
begin
 if p_source is null then raise exception 'operational_exception_source_invalid' using errcode='22023';end if;
 -- Acquire the source lock before taking its current predicate snapshot.
 -- A refresh queued behind a committed change must not reopen old evidence.
 perform pg_advisory_xact_lock(hashtextextended('collect-ops-source:'||p_kind||':'||p_source::text,0));
 if p_kind='raw_sms' then
  select * into sms from public.raw_payment_sms where id=p_source;
  if sms.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;
  if sms.parse_status='failed' and collect_security.rwanda_sms_scope(sms.id) then codes:=array['PARSING_FAILED'];end if;
  signature:=jsonb_build_array(sms.parse_status,collect_security.rwanda_sms_scope(sms.id));
 elsif p_kind='allocation' then
  select * into event from public.parsed_payment_events where id=p_source;
  if event.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;
  if event.allocation_status in('unallocated','ambiguous','needs_review') and collect_security.rwanda_sms_scope(event.raw_sms_id) then
   codes:=array['ALLOCATION_REVIEW'];end if;
  signature:=jsonb_build_array(event.allocation_status,event.collection_id,collect_security.rwanda_sms_scope(event.raw_sms_id));
 elsif p_kind='payment' then
  select * into payment from public.payments where id=p_source;
  if payment.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;
  select * into confirmation from public.payment_provider_confirmations where payment_id=payment.id;
  rejected:=exists(select 1 from collect_hybrid.payment_provider_rejections where payment_id=payment.id);
  if collect_ops.payment_scope(payment.id) then
   if rejected then codes:=array_append(codes,'VERIFICATION_REJECTED');end if;
   if confirmation.id is not null and(rejected or confirmation.amount_rwf<>payment.amount_rwf
    or confirmation.provider_network is distinct from payment.provider_network
    or confirmation.receiver_momo_number_hash is distinct from payment.receiver_momo_number_hash
    or upper(btrim(confirmation.transaction_id)) is distinct from upper(btrim(payment.transaction_id))) then
    codes:=array_append(codes,'VERIFICATION_CONFLICT');
   elsif payment.status='review' and confirmation.id is null and not rejected then codes:=array_append(codes,'VERIFICATION_PENDING');end if;
   if payment.status='posted' and not exists(select 1 from collect_hybrid.sms_notification_outbox where payment_id=payment.id)
    and exists(select 1 from collect_hybrid.member_records m
     join collect_hybrid.sms_receipt_policies policy on policy.collection_id=payment.collection_id and policy.enabled
     join collect_hybrid.sms_receipt_member_consents consent on consent.member_record_id=m.id and consent.enabled
     where m.id=payment.member_record_id and m.lifecycle='active' and m.linked_user_id is null
      and not exists(select 1 from collect_hybrid.member_momo_identities i where i.member_id=m.id)) then
    codes:=array_append(codes,'CONTACT_MISSING');end if;
  end if;
  signature:=jsonb_build_array(payment.status,confirmation.id,rejected,codes,collect_ops.payment_scope(payment.id));
 elsif p_kind='receipt' then
  select * into receipt from collect_hybrid.sms_notification_outbox where id=p_source;
  if receipt.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;
  if collect_ops.payment_scope(receipt.payment_id) then
   codes:=case receipt.state when 'uncertain' then array['SEND_UNCERTAIN']
    when 'failed_no_send' then array['SEND_FAILED_NO_SEND'] when 'suppressed' then array['RECEIPT_SUPPRESSED'] else '{}'::text[] end;
  end if;
  signature:=jsonb_build_array(receipt.state,receipt.fence_version,receipt.attempt_count,codes,collect_ops.payment_scope(receipt.payment_id));
 elsif p_kind='gateway' then
  select * into device from collect_gateway.devices where id=p_source;
  if device.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;
  select * into health from collect_gateway.health_observations where device_id=device.id order by ingested_at desc,id desc limit 1;
  fresh:=health.id is not null and clock_timestamp()<least(health.reported_at,health.ingested_at)+interval '120 seconds';
  if device.state='active' then
   if health.id is null then codes:=array['GATEWAY_UNOBSERVED'];
   elsif not fresh then codes:=array['GATEWAY_STALE'];
   else
    if not health.sms_permission then codes:=array_append(codes,'GATEWAY_SMS_PERMISSION');end if;
    if health.network<>'validated' then codes:=array_append(codes,'GATEWAY_NETWORK');end if;
    if health.telephony<>'ready' then codes:=array_append(codes,'GATEWAY_TELEPHONY');end if;
    if not health.sim_selected then codes:=array_append(codes,'GATEWAY_SIM');end if;
   end if;
  end if;
  signature:=jsonb_build_array(device.state,health.id,fresh,codes);
 else raise exception 'operational_exception_source_invalid' using errcode='22023';end if;
 perform collect_ops.observe(p_kind,p_source,codes,signature);
end$$;


ALTER FUNCTION collect_ops.receipt_exception_base_refresh_source(p_kind text, p_source uuid) OWNER TO postgres;

--
-- Name: receipt_exception_base_transaction_sms_id(text, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_exception_base_transaction_sms_id(p_kind text, p_source uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case p_kind
  when 'raw_sms' then(select sms.id from public.raw_payment_sms sms
   where sms.id=p_source and collect_security.rwanda_sms_scope(sms.id))
  when 'allocation' then(select sms.id from public.parsed_payment_events e
   join public.raw_payment_sms sms on sms.id=e.raw_sms_id
   where e.id=p_source and collect_security.rwanda_sms_scope(sms.id))
  when 'payment' then(select sms.id from public.payments p
   join public.parsed_payment_events e on e.id=p.parsed_event_id
   join public.raw_payment_sms sms on sms.id=e.raw_sms_id
   where p.id=p_source and p.currency='RWF'
    and e.receiver_user_id=p.receiver_user_id and e.network=p.provider_network
    and sms.receiver_momo_number_hash=p.receiver_momo_number_hash
    and collect_security.rwanda_sms_scope(sms.id))
  else null::uuid end
$$;


ALTER FUNCTION collect_ops.receipt_exception_base_transaction_sms_id(p_kind text, p_source uuid) OWNER TO postgres;

--
-- Name: receipt_exception_quota_available(text, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_exception_quota_available(p_kind text, p_source uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$declare run uuid;collection uuid;begin
 if p_kind='receipt_event'then
  select e.collection_id into collection from collect_hybrid.receipt_business_events e where id=p_source;
  select x.run_id into run from collect_receipt_operations.run_events x where x.event_id=p_source and x.code='QUOTA_EXHAUSTED'order by x.recorded_at desc,x.run_id desc limit 1;
 else
  select s.collection_id into collection from collect_hybrid.momo_balance_snapshots s where id=p_source;
  select x.run_id into run from(
   (select b.run_id,b.recorded_at from collect_receipt_operations.backlog_results b where b.snapshot_id=p_source and b.code='QUOTA_EXHAUSTED'order by b.recorded_at desc,b.run_id desc limit 1)
   union all(select b.run_id,b.recorded_at from collect_ops.receipt_backlog_budget_deferrals b where b.snapshot_id=p_source order by b.recorded_at desc,b.run_id desc limit 1))x order by x.recorded_at desc,x.run_id desc limit 1;
 end if;return collect_ops.receipt_exception_run_budget_available(run,collection);end$$;


ALTER FUNCTION collect_ops.receipt_exception_quota_available(p_kind text, p_source uuid) OWNER TO postgres;

--
-- Name: receipt_exception_run_budget_available(uuid, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_exception_run_budget_available(p_run uuid, collection uuid) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare p collect_receipt_operations.policy;r collect_receipt_operations.runs;e collect_hybrid.receipt_business_events;
 device uuid;run_used bigint;group_used bigint;device_used bigint;global_used bigint;day_start timestamptz;begin
 select * into r from collect_receipt_operations.runs where id=p_run;
 select * into p from collect_receipt_operations.policy where singleton;
 if p.emergency_stop or p.mode not in('Live','Live-limited')or r.id is null or not coalesce(collection=any(p.collection_ids),false)
  or not exists(select 1 from collect_supervisor.identities i where i.id=any(p.principal_ids)and i.scope='rw_receipt_operations'and i.state='active'and i.expires_at>clock_timestamp())then return false;end if;
 device:=p.device_ids[1];if device is null or not exists(select 1 from collect_gateway.devices d where d.id=device and d.state='active')then return false;end if;
 day_start:=date_trunc('day',clock_timestamp()at time zone 'UTC')at time zone 'UTC';
 select coalesce(sum(actions)filter(where run_id=r.id and r.policy_revision=p.revision and r.completed_at is null and r.expires_at>clock_timestamp()),0),
  coalesce(sum(actions)filter(where collection_id=collection and recorded_at>=day_start),0),
  coalesce(sum(actions)filter(where device_id=device and recorded_at>=day_start),0),
  coalesce(sum(actions)filter(where recorded_at>=day_start),0)
 into run_used,group_used,device_used,global_used from collect_receipt_operations.reservations where run_id=r.id or recorded_at>=day_start;
 return run_used<(p.caps->>'run_actions')::bigint and group_used<(p.caps->>'group_actions')::bigint
  and device_used<(p.caps->>'device_actions')::bigint and global_used<(p.caps->>'global_actions')::bigint;end$$;


ALTER FUNCTION collect_ops.receipt_exception_run_budget_available(p_run uuid, collection uuid) OWNER TO postgres;

--
-- Name: receipt_exception_service(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_exception_service() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$begin
 if auth.role()is distinct from 'service_role'then raise exception 'receipt_exception_service_required'using errcode='42501';end if;
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'receipt_exception_snapshot_retry'using errcode='40001';end if;end$$;


ALTER FUNCTION collect_ops.receipt_exception_service() OWNER TO postgres;

--
-- Name: receipt_exception_source(text, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_exception_source(p_kind text, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare e collect_hybrid.receipt_business_events;s collect_hybrid.momo_balance_snapshots;
 h collect_receipt_operations.handled_events;handled_backlog collect_receipt_operations.backlog_results;
 original text;code text;disposition text;payment uuid;receipt uuid;version bigint;kind text;business boolean:=false;inspected jsonb;
 signature jsonb;begin
 if p_kind='receipt_event'then
  select * into e from collect_hybrid.receipt_business_events where id=p_source;
  if e.id is null or e.collection_id is null then raise exception 'receipt_exception_source_unavailable'using errcode='22023';end if;
  payment:=e.payment_id;
  if payment is null and e.source_kind='allocation'then select p.id into payment from public.payments p where p.parsed_event_id=e.source_id and p.collection_id=e.collection_id;end if;
  if payment is null and e.source_kind='receipt'then select o.payment_id into payment from collect_hybrid.sms_notification_outbox o where o.id=e.source_id;end if;
  if payment is null then
   if e.source_kind<>'allocation'or not exists(select 1 from public.parsed_payment_events x where x.id=e.source_id and x.collection_id=e.collection_id and collect_security.rwanda_sms_scope(x.raw_sms_id))then
    raise exception 'receipt_exception_source_scope_refused'using errcode='42501';end if;
  elsif not collect_ops.payment_scope(payment)then raise exception 'receipt_exception_source_scope_refused'using errcode='42501';end if;
  version:=e.source_version;kind:=e.event_kind;
  select d.code into original from collect_receipt_operations.event_deferrals d where d.event_id=e.id;
  select * into h from collect_receipt_operations.handled_events where event_id=e.id;
  if h.event_id is not null then code:=h.code;receipt:=h.receipt_id;business:=true;disposition:='durably_handled';
  elsif exists(select 1 from collect_hybrid.receipt_business_event_heads head join collect_hybrid.receipt_business_events newer
   on newer.source_kind=head.source_kind and newer.source_id=head.source_id and newer.source_version=head.version
   where head.source_kind=e.source_kind and head.source_id=e.source_id and head.version>e.source_version)then
   code:='SOURCE_SUPERSEDED';disposition:='source_superseded';
  elsif original is null then disposition:='current_blocker_cleared';
  elsif original='QUOTA_EXHAUSTED'and not collect_ops.receipt_exception_quota_available(p_kind,p_source)then code:=original;disposition:='deferred';
  else
   select * into s from collect_hybrid.momo_balance_snapshots where payment_id=payment and event_type='receipt'order by captured_at,id limit 1;
   inspected:=collect_receipt_operations.ensure_snapshot(s.id,true,false);code:=inspected->>'code';receipt:=(inspected->>'receipt_id')::uuid;
  end if;
 elsif p_kind='receipt_backlog'then
  select * into s from collect_hybrid.momo_balance_snapshots where id=p_source and event_type='receipt';
  if s.id is null then raise exception 'receipt_exception_source_unavailable'using errcode='22023';end if;
  if not collect_ops.payment_scope(s.payment_id)then raise exception 'receipt_exception_source_scope_refused'using errcode='42501';end if;
  select x.code into original from(
   (select b.code,b.recorded_at,b.run_id from collect_receipt_operations.backlog_results b where b.snapshot_id=s.id and not b.business_handled order by b.recorded_at desc,b.run_id desc limit 1)
   union all(select 'QUOTA_EXHAUSTED',b.recorded_at,b.run_id from collect_ops.receipt_backlog_budget_deferrals b where b.snapshot_id=s.id order by b.recorded_at desc,b.run_id desc limit 1))x order by x.recorded_at desc,x.run_id desc limit 1;
  select * into handled_backlog from collect_receipt_operations.backlog_results x where x.snapshot_id=s.id and x.business_handled order by x.recorded_at,x.run_id limit 1;
  if handled_backlog.snapshot_id is not null then code:=handled_backlog.code;receipt:=handled_backlog.receipt_id;business:=true;disposition:='durably_handled';
  elsif original is null then disposition:='current_blocker_cleared';
  elsif original='QUOTA_EXHAUSTED'and not collect_ops.receipt_exception_quota_available(p_kind,p_source)then code:=original;disposition:='deferred';
  else inspected:=collect_receipt_operations.ensure_snapshot(s.id,true,false);code:=inspected->>'code';receipt:=(inspected->>'receipt_id')::uuid;end if;
 else raise exception 'receipt_exception_source_invalid'using errcode='22023';end if;
 if disposition is null then disposition:=case when code in('RECEIPT_EXISTS','PAYMENT_REVERSED','DRY_RUN_ELIGIBLE')then 'current_blocker_cleared'else 'deferred'end;end if;
 if disposition='deferred'and code not in('SOURCE_CHANGED','PAYMENT_NOT_POSTED','SNAPSHOT_MISSING','RECIPIENT_INELIGIBLE','POLICY_DISABLED',
  'CONSENT_MISSING','CONTACT_MISSING','CONTACT_HISTORY_UNPROVEN','POLICY_HISTORY_UNPROVEN','CONSENT_HISTORY_UNPROVEN','CATCHUP_DISABLED',
  'CATCHUP_WINDOW_EXCEEDED','CONTENT_REFUSED','LEGACY_CONTENT_REVIEW_REQUIRED','QUOTA_EXHAUSTED','SOURCE_BUSY')then
  raise exception 'receipt_exception_unknown_deferral'using errcode='55000';end if;
 signature:=jsonb_build_array(version,original,code,disposition,business,receipt,
  (select policy.revision from collect_hybrid.sms_receipt_policies policy where policy.collection_id=coalesce(e.collection_id,s.collection_id)),
  (select consent.revision from collect_hybrid.sms_receipt_member_consents consent where consent.member_record_id=coalesce(e.member_record_id,s.member_record_id)),
  (select identity.revision from collect_hybrid.member_momo_identities identity where identity.member_id=coalesce(e.member_record_id,s.member_record_id)),
  (select jsonb_build_array(p.catchup_enabled,p.catchup_hours)from collect_receipt_operations.policy p where singleton));
 return jsonb_build_object('source_version',version,'event_kind',kind,'original_code',original,'current_code',code,
  'disposition',disposition,'business_handled',business,'receipt_id',receipt,'signature',signature);end$$;


ALTER FUNCTION collect_ops.receipt_exception_source(p_kind text, p_source uuid) OWNER TO postgres;

--
-- Name: receipt_worker_transport(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.receipt_worker_transport() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare project_url text;api_key text;secret text;begin
 if to_regclass('vault.decrypted_secrets')is null then raise exception 'receipt_worker_transport_unconfigured'using errcode='55000';end if;
 select decrypted_secret into project_url from vault.decrypted_secrets where name='collect_receipt_exception_project_url';
 select decrypted_secret into api_key from vault.decrypted_secrets where name='collect_receipt_exception_api_key';
 select decrypted_secret into secret from vault.decrypted_secrets where name='collect_receipt_exception_worker_secret';
 -- Deliberately pinned to Collect's existing project; no request-supplied URL.
 if project_url is distinct from 'https://lhbowpbcpwoiparwnwgt.supabase.co'
  or coalesce(length(api_key),0)<20 or coalesce(length(secret),0)<32 or length(secret)>256
  or api_key~'[\r\n]'or secret~'[\r\n]'then raise exception 'receipt_worker_transport_unconfigured'using errcode='55000';end if;
 return jsonb_build_object('url',project_url||'/functions/v1/collect-receipt-exception-worker',
  'headers',jsonb_build_object('Content-Type','application/json','apikey',api_key,'x-collect-receipt-worker',secret));
end$$;


ALTER FUNCTION collect_ops.receipt_worker_transport() OWNER TO postgres;

--
-- Name: recipient_available(uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.recipient_available(p_user uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select collect_admin_access.email_identity(p_user) and exists(
  select 1 from public.admin_user_roles u join public.admin_roles r on r.id=u.role_id
  where u.user_id=p_user and u.revoked_at is null and r.name='platform_owner'
   and not exists(select 1 from unnest(array['payments.read','notifications.read','system_health.read'])permission
    where not exists(select 1 from public.admin_role_permissions p where p.role_id=r.id and p.permission_name=permission)))
$$;


ALTER FUNCTION collect_ops.recipient_available(p_user uuid) OWNER TO postgres;

--
-- Name: refresh_source(text, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.refresh_source(p_kind text, p_source uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare current jsonb;codes text[];begin
 if p_kind in('receipt_event','receipt_backlog')then
  perform pg_advisory_xact_lock(hashtextextended('collect-ops-source:'||p_kind||':'||p_source::text,0));
  current:=collect_ops.receipt_exception_source(p_kind,p_source);
  codes:=case when current->>'disposition'='deferred'then array['RECEIPT_OPERATION_'||(current->>'current_code')]else '{}'::text[]end;
  perform collect_ops.observe(p_kind,p_source,codes,current->'signature');
 else perform collect_ops.receipt_exception_base_refresh_source(p_kind,p_source);end if;end$$;


ALTER FUNCTION collect_ops.refresh_source(p_kind text, p_source uuid) OWNER TO postgres;

--
-- Name: run_receipt_exception_schedule(); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.run_receipt_exception_schedule() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '200ms'
    AS $$
declare c collect_ops.receipt_worker_configuration;j collect_ops.receipt_worker_jobs;transport jsonb;t timestamptz;
 prior_count integer;http_id bigint;last_dispatch timestamptz;day_count integer;scan_reserved integer;escalation_reserved integer;state text;begin
 if not pg_try_advisory_xact_lock(hashtext('collect-receipt-trusted-worker'))then return jsonb_build_object('status','overlap');end if;
 select * into c from collect_ops.receipt_worker_configuration where singleton for share;
 if not c.enabled then return jsonb_build_object('status','inactive');end if;
 transport:=collect_ops.receipt_worker_transport();t:=clock_timestamp();
 select * into j from collect_ops.receipt_worker_jobs order by created_at desc,request_id desc limit 1;
 if j.request_id is not null then
  perform pg_advisory_xact_lock(hashtextextended('collect-receipt-worker-job:'||j.request_id::text,0));
  if not exists(select 1 from collect_ops.receipt_worker_receipts where request_id=j.request_id)then
   if j.expires_at<=t or j.configuration_revision<>c.revision then
    if j.expires_at>t then return jsonb_build_object('status','fenced_pending','request_id',j.request_id);end if;
    -- Fresh exact job lock makes absence conclusive after its immutable deadline.
    insert into collect_ops.receipt_worker_expirations values(j.request_id,t,'expired_without_receipt')on conflict do nothing;
   else
    select count(*),max(dispatched_at)into prior_count,last_dispatch from collect_ops.receipt_worker_dispatches where request_id=j.request_id;
    if prior_count>=3 or last_dispatch>t-interval '30 seconds'then return jsonb_build_object('status','pending','request_id',j.request_id);end if;
    state:='redispatched';
   end if;
  end if;
 end if;
 if state is null then
  if j.created_at>t-interval '60 seconds'then return jsonb_build_object('status','cadence');end if;
  select count(*),coalesce(sum(scan_limit),0),coalesce(sum(escalation_limit),0)into day_count,scan_reserved,escalation_reserved
   from collect_ops.receipt_worker_jobs where reserved_day=(t at time zone 'UTC')::date;
  if day_count>=c.day_jobs or scan_reserved+c.scan_limit>c.day_scan_sources or escalation_reserved+c.escalation_limit>c.day_escalations
   then return jsonb_build_object('status','quota_exhausted');end if;
  insert into collect_ops.receipt_worker_jobs values(gen_random_uuid(),c.revision,c.scan_limit,c.escalation_limit,
   (t at time zone 'UTC')::date,t,t+interval '90 seconds')returning * into j;prior_count:=0;state:='queued';
 end if;
 select net.http_post(url:=transport->>'url',headers:=transport->'headers',body:=jsonb_build_object('contract_version',1,
  'action','execute','request_id',j.request_id,'configuration_revision',j.configuration_revision,'expires_at',collect_ops.utc(j.expires_at)),
  timeout_milliseconds:=15000)into http_id;
 insert into collect_ops.receipt_worker_dispatches values(j.request_id,prior_count+1,http_id,t);
 return jsonb_build_object('status',state,'request_id',j.request_id,'http_request_id',http_id,'attempt',prior_count+1,'expires_at',collect_ops.utc(j.expires_at));
end$$;


ALTER FUNCTION collect_ops.run_receipt_exception_schedule() OWNER TO postgres;

--
-- Name: transaction_sms_id(text, uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.transaction_sms_id(p_kind text, p_source uuid) RETURNS uuid
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case when p_kind in('receipt_event','receipt_backlog')then
  (select sms.id from public.parsed_payment_events parsed join public.raw_payment_sms sms on sms.id=parsed.raw_sms_id
   where parsed.id=case when p_kind='receipt_event'then
    (select coalesce(p.parsed_event_id,case when e.source_kind='allocation'then e.source_id end)
     from collect_hybrid.receipt_business_events e left join public.payments p on p.id=e.payment_id
     where e.id=p_source)
    else(select p.parsed_event_id from collect_hybrid.momo_balance_snapshots s join public.payments p on p.id=s.payment_id where s.id=p_source)end
   and collect_security.rwanda_sms_scope(sms.id))
 else collect_ops.receipt_exception_base_transaction_sms_id(p_kind,p_source)end
$$;


