--
-- Name: workflow_projection(uuid); Type: FUNCTION; Schema: collect_ops; Owner: postgres
--

CREATE FUNCTION collect_ops.workflow_projection(p_exception uuid) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select jsonb_build_object('contract_version',1,'exception_id',e.id,'source_revision',e.revision,
  'source_active',e.active,'workflow_revision',coalesce(w.revision,0),
  'assignee_id',w.assignee_id,'recipient_available',case when w.assignee_id is null then false
   else collect_ops.recipient_available(w.assignee_id)end,'due_at',collect_ops.utc(w.due_at),
  'overdue',coalesce(e.active and w.due_at<clock_timestamp(),false),
  'status',case when not e.active and w.resolved_source_revision=e.revision then 'resolved'
   when not e.active then 'source_cleared' when w.assignee_id is null then 'unassigned'else 'assigned'end,
  'escalations',coalesce((select jsonb_agg(jsonb_build_object('id',s.id,'source_revision',s.source_revision,
   'recipient_id',s.recipient_id,'state',s.state,'queued_at',collect_ops.utc(s.queued_at),
   'delivered_at',(select collect_ops.utc(d.delivered_at)from collect_ops.exception_inbox_deliveries d where d.escalation_id=s.id),
   'read_at',(select collect_ops.utc(d.read_at)from collect_ops.exception_inbox_reads d where d.escalation_id=s.id))order by s.queued_at desc,s.id desc)
   from(select * from collect_ops.exception_escalations where exception_id=e.id order by queued_at desc,id desc limit 10)s),'[]'::jsonb))
 from collect_ops.exceptions e left join collect_ops.exception_workflows w on w.exception_id=e.id where e.id=p_exception
$$;


ALTER FUNCTION collect_ops.workflow_projection(p_exception uuid) OWNER TO postgres;

--
-- Name: assert_ready(text); Type: FUNCTION; Schema: collect_profile_access; Owner: postgres
--

CREATE FUNCTION collect_profile_access.assert_ready(required_rail text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare
  profile_row public.profiles%rowtype;
  local_momo text;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if required_rail is not null and required_rail <> 'rwanda' then
    raise exception 'Only Rwanda MoMo contributions are supported';
  end if;
  select * into profile_row from public.profiles where id = auth.uid() for share;
  if profile_row.id is null or profile_row.country_code <> 'RW'
     or profile_row.currency_code <> 'RWF'
     or profile_row.public_id !~ '^[0-9]{6}$'
     or nullif(btrim(profile_row.whatsapp_phone), '') is null then
    raise exception 'Complete your Rwanda MoMo profile first';
  end if;
  local_momo := public._rwanda_momo_local(profile_row.momo_number);
  if local_momo is null
     or profile_row.momo_provider not in ('mtn_momo', 'airtel_money')
     or (profile_row.momo_provider = 'mtn_momo' and local_momo !~ '^07[89][0-9]{7}$')
     or (profile_row.momo_provider = 'airtel_money' and local_momo !~ '^07[23][0-9]{7}$')
     or profile_row.momo_number_hash is distinct from
        encode(extensions.digest('+250' || substr(local_momo, 2), 'sha256'), 'hex') then
    raise exception 'Complete your profile with a valid MoMo number first';
  end if;
end;
$_$;


ALTER FUNCTION collect_profile_access.assert_ready(required_rail text) OWNER TO postgres;

