--
-- Name: sms_notification_outbox; Type: TABLE; Schema: collect_hybrid; Owner: postgres
--

CREATE TABLE collect_hybrid.sms_notification_outbox (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    payment_id uuid NOT NULL,
    snapshot_id uuid NOT NULL,
    collection_id uuid NOT NULL,
    member_record_id uuid NOT NULL,
    destination_e164 text NOT NULL,
    destination_sha256 text NOT NULL,
    destination_revision integer NOT NULL,
    policy_revision integer NOT NULL,
    consent_revision integer NOT NULL,
    template_key text NOT NULL,
    template_version integer NOT NULL,
    amount_rwf bigint NOT NULL,
    member_balance_rwf bigint NOT NULL,
    group_balance_rwf bigint NOT NULL,
    reference text NOT NULL,
    message_body text,
    body_sha256 text,
    state text DEFAULT 'queued'::text NOT NULL,
    suppression_reason text,
    fence_version integer DEFAULT 0 NOT NULL,
    claim_token uuid,
    claimed_by text,
    claim_expires_at timestamp with time zone,
    attempt_count integer DEFAULT 0 NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    observed_sent_at timestamp with time zone,
    CONSTRAINT sms_notification_outbox_amount_rwf_check CHECK ((amount_rwf > 0)),
    CONSTRAINT sms_notification_outbox_attempt_count_check CHECK ((attempt_count >= 0)),
    CONSTRAINT sms_notification_outbox_body_sha256_check CHECK (((body_sha256 IS NULL) OR (body_sha256 ~ '^[0-9a-f]{64}$'::text))),
    CONSTRAINT sms_notification_outbox_check CHECK ((((state = 'suppressed'::text) AND (suppression_reason IS NOT NULL)) OR ((state <> 'suppressed'::text) AND (message_body IS NOT NULL) AND (body_sha256 IS NOT NULL)))),
    CONSTRAINT sms_notification_outbox_check1 CHECK ((((state = 'awaiting_confirmation'::text) AND (claim_token IS NOT NULL) AND (claimed_by IS NOT NULL) AND (claim_expires_at IS NOT NULL)) OR (state <> 'awaiting_confirmation'::text))),
    CONSTRAINT sms_notification_outbox_consent_revision_check CHECK ((consent_revision > 0)),
    CONSTRAINT sms_notification_outbox_destination_e164_check CHECK ((destination_e164 ~ '^\+2507[2389][0-9]{7}$'::text)),
    CONSTRAINT sms_notification_outbox_destination_revision_check CHECK ((destination_revision > 0)),
    CONSTRAINT sms_notification_outbox_destination_sha256_check CHECK ((destination_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT sms_notification_outbox_fence_version_check CHECK ((fence_version >= 0)),
    CONSTRAINT sms_notification_outbox_group_balance_rwf_check CHECK ((group_balance_rwf >= 0)),
    CONSTRAINT sms_notification_outbox_member_balance_rwf_check CHECK ((member_balance_rwf >= 0)),
    CONSTRAINT sms_notification_outbox_policy_revision_check CHECK ((policy_revision > 0)),
    CONSTRAINT sms_notification_outbox_state_check CHECK ((state = ANY (ARRAY['queued'::text, 'awaiting_confirmation'::text, 'send_started'::text, 'observed_sent'::text, 'failed_no_send'::text, 'uncertain'::text, 'suppressed'::text]))),
    CONSTRAINT sms_notification_outbox_template_key_check CHECK ((template_key = 'buri_munsi.payment_received'::text)),
    CONSTRAINT sms_notification_outbox_template_version_check CHECK ((template_version = ANY (ARRAY[1, 2])))
);


