    CONSTRAINT cancellations_expected_revision_check CHECK (((expected_revision >= 1) AND (expected_revision <= 999999999))),
    CONSTRAINT cancellations_reason_code_check CHECK ((reason_code = ANY (ARRAY['operator_cancelled'::text, 'recipient_review_required'::text, 'content_review_required'::text]))),
    CONSTRAINT cancellations_recorded_at_check CHECK (isfinite(recorded_at))
);


