--
-- Name: rwanda_source(collect_hybrid.sms_notification_outbox); Type: FUNCTION; Schema: collect_receipt_actions; Owner: postgres
--

CREATE FUNCTION collect_receipt_actions.rwanda_source(p_job collect_hybrid.sms_notification_outbox) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 -- A receiving route alone cannot override a contradictory linked parser.
 select exists(select 1 from public.payments p where p.id=p_job.payment_id
  and collect_ops.payment_scope(p.id)
  and(p.parsed_event_id is null or collect_ops.transaction_sms_id('payment',p.id)is not null))
$$;


