--
-- Name: caps_valid(jsonb); Type: FUNCTION; Schema: collect_receipt_operations; Owner: postgres
--

CREATE FUNCTION collect_receipt_operations.caps_valid(p_caps jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare k text;begin
 if p_caps is null or jsonb_typeof(p_caps)<>'object'or(select count(*)from jsonb_object_keys(p_caps))<>8 then return false;end if;
 foreach k in array array['run_actions','group_actions','device_actions','global_actions','run_sms_segments','group_sms_segments','device_sms_segments','global_sms_segments']loop
  if not p_caps?k or jsonb_typeof(p_caps->k)<>'number'or p_caps->>k!~'^[0-9]+$'or(p_caps->>k)::numeric not between 1 and 1000000 then return false;end if;
 end loop;return true;end$_$;


ALTER FUNCTION collect_receipt_operations.caps_valid(p_caps jsonb) OWNER TO postgres;

--
-- Name: identities; Type: TABLE; Schema: collect_supervisor; Owner: postgres
--

CREATE TABLE collect_supervisor.identities (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    enrollment_request_id uuid NOT NULL,
    owner_actor_id uuid NOT NULL,
    owner_session_id uuid NOT NULL,
    public_key_spki_base64 text NOT NULL,
    key_sha256 text NOT NULL,
    scope text DEFAULT 'rw_receipt_shadow'::text NOT NULL,
    state text DEFAULT 'pending'::text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    expires_at timestamp with time zone NOT NULL,
    activated_at timestamp with time zone,
    revoked_at timestamp with time zone,
    CONSTRAINT identities_check CHECK ((isfinite(created_at) AND isfinite(expires_at) AND (expires_at > created_at) AND (expires_at <= (created_at + '30 days'::interval)))),
    CONSTRAINT identities_check1 CHECK ((((state = 'pending'::text) AND (activated_at IS NULL) AND (revoked_at IS NULL)) OR ((state = 'active'::text) AND (activated_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((state = 'revoked'::text) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT identities_key_sha256_check CHECK ((key_sha256 ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT identities_scope_check CHECK ((scope = ANY (ARRAY['rw_receipt_shadow'::text, 'rw_receipt_operations'::text]))),
    CONSTRAINT identities_state_check CHECK ((state = ANY (ARRAY['pending'::text, 'active'::text, 'revoked'::text])))
);


