-- Name: content_is_current(collect_hybrid.sms_notification_outbox); Type: FUNCTION; Schema: collect_receipt_policy; Owner: postgres
--

CREATE FUNCTION collect_receipt_policy.content_is_current(p_job collect_hybrid.sms_notification_outbox) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select collect_receipt_policy.content_is_valid(p_job)and exists(select 1 from collect_hybrid.momo_balance_snapshots s
 where s.id=p_job.snapshot_id and collect_receipt_policy.snapshot_is_eligible(s))
$$;


ALTER FUNCTION collect_receipt_policy.content_is_current(p_job collect_hybrid.sms_notification_outbox) OWNER TO postgres;

--
-- Name: content_is_valid(collect_hybrid.sms_notification_outbox); Type: FUNCTION; Schema: collect_receipt_policy; Owner: postgres
--

CREATE FUNCTION collect_receipt_policy.content_is_valid(p_job collect_hybrid.sms_notification_outbox) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select coalesce(p_job.template_version=2 and exists(select 1 from collect_receipt_policy.content_evidence e
 join collect_hybrid.momo_balance_snapshots s on s.id=p_job.snapshot_id
 where e.outbox_id=p_job.id and e.content_version=2 and e.language in('rw','en','fr')
  and e.snapshot_recorded_at=s.captured_at and e.body_sha256=p_job.body_sha256
  and p_job.message_body=collect_receipt_policy.render_snapshot(s,2,p_job.reference,e.language)
  and p_job.body_sha256=encode(extensions.digest(p_job.message_body,'sha256'),'hex')),false)
$$;


ALTER FUNCTION collect_receipt_policy.content_is_valid(p_job collect_hybrid.sms_notification_outbox) OWNER TO postgres;

