--
-- Name: momo_balance_snapshots; Type: TABLE; Schema: collect_hybrid; Owner: postgres
--

CREATE TABLE collect_hybrid.momo_balance_snapshots (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    journal_entry_id uuid NOT NULL,
    payment_id uuid NOT NULL,
    collection_id uuid NOT NULL,
    member_record_id uuid,
    event_type text NOT NULL,
    delta_rwf bigint NOT NULL,
    member_balance_after_rwf bigint,
    group_balance_after_rwf bigint NOT NULL,
    captured_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT momo_balance_snapshots_delta_rwf_check CHECK ((delta_rwf <> 0)),
    CONSTRAINT momo_balance_snapshots_event_type_check CHECK ((event_type = ANY (ARRAY['receipt'::text, 'reversal'::text]))),
    CONSTRAINT momo_balance_snapshots_group_balance_after_rwf_check CHECK ((group_balance_after_rwf >= 0)),
    CONSTRAINT momo_balance_snapshots_member_balance_after_rwf_check CHECK ((member_balance_after_rwf >= 0))
);


ALTER TABLE collect_hybrid.momo_balance_snapshots OWNER TO postgres;

--
-- Name: TABLE momo_balance_snapshots; Type: COMMENT; Schema: collect_hybrid; Owner: postgres
--

COMMENT ON TABLE collect_hybrid.momo_balance_snapshots IS 'Immutable after-transaction member and group balances used by delayed notifications and audit readback.';


--
-- Name: render_snapshot(collect_hybrid.momo_balance_snapshots, integer, text); Type: FUNCTION; Schema: collect_receipt_policy; Owner: postgres
--

CREATE FUNCTION collect_receipt_policy.render_snapshot(p_snapshot collect_hybrid.momo_balance_snapshots, p_version integer, p_reference text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case p_version when 1 then collect_hybrid.render_buri_munsi_receipt(p_snapshot.delta_rwf,
  p_snapshot.member_balance_after_rwf,p_snapshot.group_balance_after_rwf,p_reference)
 when 2 then collect_receipt_policy.render_v2(p_snapshot.delta_rwf,p_snapshot.member_balance_after_rwf,
  p_snapshot.captured_at,p_reference,'rw')else null end
$$;


ALTER FUNCTION collect_receipt_policy.render_snapshot(p_snapshot collect_hybrid.momo_balance_snapshots, p_version integer, p_reference text) OWNER TO postgres;

--
-- Name: render_snapshot(collect_hybrid.momo_balance_snapshots, integer, text, text); Type: FUNCTION; Schema: collect_receipt_policy; Owner: postgres
--

CREATE FUNCTION collect_receipt_policy.render_snapshot(p_snapshot collect_hybrid.momo_balance_snapshots, p_version integer, p_reference text, p_language text) RETURNS text
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select case when p_version=1 then collect_hybrid.render_buri_munsi_receipt(p_snapshot.delta_rwf,
  p_snapshot.member_balance_after_rwf,p_snapshot.group_balance_after_rwf,p_reference)
 when p_version=2 and p_language in('rw','en','fr')then collect_receipt_policy.render_v2(
  p_snapshot.delta_rwf,p_snapshot.member_balance_after_rwf,p_snapshot.captured_at,p_reference,p_language)else null end
$$;


ALTER FUNCTION collect_receipt_policy.render_snapshot(p_snapshot collect_hybrid.momo_balance_snapshots, p_version integer, p_reference text, p_language text) OWNER TO postgres;

--
-- Name: render_v2(bigint, bigint, timestamp with time zone, text, text); Type: FUNCTION; Schema: collect_receipt_policy; Owner: postgres
--

CREATE FUNCTION collect_receipt_policy.render_v2(p_amount_rwf bigint, p_member_balance_rwf bigint, p_recorded_at timestamp with time zone, p_reference text, p_language text DEFAULT 'rw'::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO ''
    AS $_$
declare ref text:=btrim(coalesce(p_reference,''));at_text text;amount text;balance text;begin
 if p_amount_rwf is null or p_amount_rwf<=0 or p_member_balance_rwf is null or p_member_balance_rwf<0
  or p_recorded_at is null or not isfinite(p_recorded_at)
  or ref!~'^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$'or p_language is null or p_language not in('rw','en','fr')then
  raise exception 'receipt_content_input_invalid'using errcode='22023';end if;
 at_text:=to_char(p_recorded_at at time zone 'Africa/Kigali','YYYY-MM-DD HH24:MI')||' CAT';
 amount:=to_char(p_amount_rwf,'FM9,999,999,999,999,999,990');
 balance:=to_char(p_member_balance_rwf,'FM9,999,999,999,999,999,990');
 return case p_language
  when 'rw'then 'BuriMunsi: Ubwizigame bwa '||amount||' RWF bwanditswe. Igiteranyo cyawe cyanditswe muri iri tsinda ku '||at_text||': '||balance||' RWF. Ref: '||ref||'.'
  when 'en'then 'BuriMunsi: Savings recorded: '||amount||' RWF. Your recorded savings in this group at '||at_text||': '||balance||' RWF. Ref: '||ref||'.'
  when 'fr'then 'BuriMunsi: Épargne enregistrée: '||amount||' RWF. Votre épargne enregistrée dans ce groupe au '||at_text||': '||balance||' RWF. Réf: '||ref||'.'end;
end$_$;


ALTER FUNCTION collect_receipt_policy.render_v2(p_amount_rwf bigint, p_member_balance_rwf bigint, p_recorded_at timestamp with time zone, p_reference text, p_language text) OWNER TO postgres;

--
-- Name: snapshot_is_eligible(collect_hybrid.momo_balance_snapshots); Type: FUNCTION; Schema: collect_receipt_policy; Owner: postgres
--

CREATE FUNCTION collect_receipt_policy.snapshot_is_eligible(p_snapshot collect_hybrid.momo_balance_snapshots) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 select exists(select 1 from public.payments p
 join public.collections c on c.id=p.collection_id
 join collect_hybrid.member_records m on m.id=p.member_record_id
 join collect_hybrid.momo_journal_entries j on j.id=p_snapshot.journal_entry_id
 join public.payment_provider_confirmations pc on pc.payment_id=p.id
 where p.id=p_snapshot.payment_id and p.status='posted'and p.currency='RWF'
  and p.amount_rwf>0 and p_snapshot.event_type='receipt'
  and p.collection_id=p_snapshot.collection_id and p.member_record_id=p_snapshot.member_record_id
  and p_snapshot.delta_rwf=p.amount_rwf and p_snapshot.member_balance_after_rwf is not null
  and isfinite(p_snapshot.captured_at)
  and c.collection_type='ikimina'and c.archived_at is null
  and m.lifecycle='active'and not collect_hybrid.member_record_has_account(m.id)
  and exists(select 1 from public.collection_members cm where cm.collection_id=p.collection_id
   and cm.member_record_id=p.member_record_id and cm.status='active')
  and collect_ops.payment_scope(p.id)
  and(p.parsed_event_id is null or collect_ops.transaction_sms_id('payment',p.id)is not null)
  and pc.provider_network=p.provider_network and upper(btrim(pc.transaction_id))=upper(btrim(p.transaction_id))
  and pc.receiver_momo_number_hash=p.receiver_momo_number_hash and pc.amount_rwf=p.amount_rwf and pc.currency='RWF'
  and j.payment_id=p.id and j.collection_id=p.collection_id and j.member_record_id=p.member_record_id
  and j.entry_type='receipt'and j.amount_rwf=p.amount_rwf
  and not exists(select 1 from collect_hybrid.momo_journal_entries r where r.payment_id=p.id and r.entry_type='reversal')
  and(select count(*)=2 and count(*)filter(where l.account_code='momo_receiving_asset:RWF'and l.direction='debit')=1
   and count(*)filter(where l.account_code='member_savings_liability:RWF'and l.direction='credit')=1
   and min(l.amount_rwf)=p.amount_rwf and max(l.amount_rwf)=p.amount_rwf
   from collect_hybrid.momo_journal_lines l where l.journal_entry_id=j.id))
$$;


ALTER FUNCTION collect_receipt_policy.snapshot_is_eligible(p_snapshot collect_hybrid.momo_balance_snapshots) OWNER TO postgres;

