    CONSTRAINT payments_provider_network_check CHECK ((provider_network = ANY (ARRAY['mtn_momo'::text, 'airtel_money'::text, 'unknown'::text]))),
    CONSTRAINT payments_source_check CHECK ((source = ANY (ARRAY['sms_auto'::text, 'manual_sms_paste'::text, 'manual_admin'::text, 'import'::text]))),
