ALTER FUNCTION collect_security.runtime_control_spec(p_family text) OWNER TO postgres;

--
-- Name: runtime_control_v2_deadline(timestamp with time zone, boolean); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_v2_deadline(p_expires_at timestamp with time zone, p_initial boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$declare at_time timestamptz:=clock_timestamp();begin
 if p_expires_at is null or not isfinite(p_expires_at) or p_expires_at<=at_time
  or p_initial and p_expires_at>at_time+interval '120 seconds' then
  raise exception 'runtime_control_request_expired' using errcode='22023';end if;
 if current_setting('transaction_isolation')<>'read committed' then
  raise exception 'runtime_control_read_committed_required' using errcode='25001';end if;
end$$;


ALTER FUNCTION collect_security.runtime_control_v2_deadline(p_expires_at timestamp with time zone, p_initial boolean) OWNER TO postgres;

--
-- Name: runtime_control_v2_fingerprint(uuid, text, jsonb, text, bigint, text, timestamp with time zone); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_v2_fingerprint(p_request_id uuid, p_family text, p_identity jsonb, p_patch_json text, p_expected_revision bigint, p_reason_sha256 text, p_expires_at timestamp with time zone) RETURNS text
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare spec jsonb:=collect_security.runtime_control_v2_spec(p_family);lines text[];field text;begin
 perform collect_security.runtime_control_check_identity(p_family,p_identity);
 lines:=array['collect-runtime-control-request-v2',p_request_id::text,p_family];
 for field in select jsonb_array_elements_text(spec->'identity') loop lines:=array_append(lines,field||'='||(p_identity->>field));end loop;
 lines:=lines||array[p_expected_revision::text,collect_security.runtime_control_v2_utc(p_expires_at),
  encode(extensions.digest(convert_to(p_patch_json,'UTF8'),'sha256'),'hex'),p_reason_sha256];
 return encode(extensions.digest(convert_to(array_to_string(lines,E'\n'),'UTF8'),'sha256'),'hex');
end$$;


ALTER FUNCTION collect_security.runtime_control_v2_fingerprint(p_request_id uuid, p_family text, p_identity jsonb, p_patch_json text, p_expected_revision bigint, p_reason_sha256 text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: runtime_control_v2_observe(text, boolean); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_v2_observe(p_family text, p_audit boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare spec jsonb:=collect_security.runtime_control_v2_spec(p_family);sid uuid;u auth.users;s auth.sessions;
 role_uuid uuid;mode_value text;approval_time timestamptz;approval_expiry timestamptz;permission text;required text[];manage text[];can_manage boolean:=true;
begin
 if current_setting('transaction_isolation')<>'read committed' then raise exception 'runtime_control_read_committed_required' using errcode='25001';end if;
 if not pg_try_advisory_xact_lock_shared(193517,141) then raise exception 'runtime_control_authority_unavailable' using errcode='42501';end if;
 begin
  lock table collect_admin_access.operator_auth_policy,collect_admin_access.email_approvals,collect_admin_access.whatsapp_approvals,
   public.admin_user_roles,public.admin_roles,public.admin_role_permissions,public.admin_permissions in share mode nowait;
 exception when lock_not_available then raise exception 'runtime_control_authority_unavailable' using errcode='42501';end;
 sid:=public._lock_notification_registration_session();
 required:=array[case when p_audit then 'audit.read' else spec->>'read_permission' end];
 manage:=array[spec->>'permission'];
 if spec ? 'additional_permission' then manage:=array_append(manage,spec->>'additional_permission');end if;
 if exists(select 1 from unnest(required||manage)n where n is null or n !~ '^[a-z_]+(\.[a-z_]+)+$')
  or exists(select 1 from unnest(required||manage)n where not exists(select 1 from public.admin_permissions p where p.name=n)) then
  raise exception 'runtime_control_registry_invalid' using errcode='55000';end if;
 select mode into mode_value from collect_admin_access.operator_auth_policy where id for share;
 if mode_value is null or mode_value not in('email','transition') then raise exception 'runtime_control_authority_invalid' using errcode='55000';end if;
 select * into u from auth.users where id=auth.uid() for share;
 select * into s from auth.sessions where id=sid and user_id=auth.uid() for share;
 if u.id is null or s.id is null or s.created_at is null or not isfinite(s.created_at)
  or s.created_at>clock_timestamp() or s.aal::text not in('aal1','aal2') or s.aal is null
  or s.not_after is not null and (not isfinite(s.not_after) or s.not_after<=clock_timestamp())
  or u.deleted_at is not null or coalesce(u.is_anonymous,false) or u.banned_until>clock_timestamp() then
  raise exception 'runtime_control_session_required' using errcode='42501';end if;
 if u.email_confirmed_at is not null then
  select approved_at,expires_at into approval_time,approval_expiry from collect_admin_access.email_approvals a
   where a.user_id=auth.uid() and a.email=lower(btrim(u.email)) and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>clock_timestamp()) for share;
 end if;
 if approval_time is null and mode_value='transition' and u.phone_confirmed_at is not null
  and not exists(select 1 from collect_admin_access.email_approvals where user_id=auth.uid()) then
  select approved_at,expires_at into approval_time,approval_expiry from collect_admin_access.whatsapp_approvals a
   where a.user_id=auth.uid() and a.phone_e164='+'||ltrim(u.phone,'+') and a.revoked_at is null
    and (a.expires_at is null or a.expires_at>clock_timestamp()) for share;
 end if;
 select r.id into role_uuid from public.admin_user_roles ur join public.admin_roles r on r.id=ur.role_id and r.name='platform_owner'
  where ur.user_id=auth.uid() and ur.revoked_at is null and s.created_at>=ur.created_at
   and approval_time is not null and s.created_at>=approval_time order by ur.created_at for share of ur,r;
 if role_uuid is null then raise exception 'runtime_control_permission_required' using errcode='42501';end if;
 for permission in select distinct n from unnest(required||manage)n order by n loop
  perform 1 from public.admin_role_permissions where role_id=role_uuid and permission_name=permission for share;
  if not found then
   if permission=any(required) then raise exception 'runtime_control_permission_required' using errcode='42501';end if;
   can_manage:=false;
  end if;
 end loop;
 -- Authority times can elapse during a real row wait. Revalidate every clock
 -- predicate after the last permission lock, preserving the locked evidence.
 if approval_expiry is not null and approval_expiry<=clock_timestamp()
  or not public._notification_session_is_live(sid,auth.uid())
  or not collect_admin_access.approved_identity(auth.uid()) then raise exception 'runtime_control_session_required' using errcode='42501';end if;
 return jsonb_build_object('session_id',sid,'can_manage',can_manage);
end$_$;


ALTER FUNCTION collect_security.runtime_control_v2_observe(p_family text, p_audit boolean) OWNER TO postgres;

--
-- Name: runtime_control_v2_project(text, jsonb); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_v2_project(p_family text, p_value jsonb) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO ''
    AS $$
 select case when p_value is null or p_value='null'::jsonb then null else
 (select coalesce(jsonb_object_agg(k,v),'{}'::jsonb) from jsonb_each(p_value)e(k,v)
  where (collect_security.runtime_control_spec(p_family)->'identity')?k or (collect_security.runtime_control_spec(p_family)->'writable')?k) end
$$;


ALTER FUNCTION collect_security.runtime_control_v2_project(p_family text, p_value jsonb) OWNER TO postgres;

--
-- Name: runtime_control_v2_spec(text); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_v2_spec(p_family text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$declare spec jsonb:=collect_security.runtime_control_spec(p_family);begin
 if p_family is null or not p_family=any(array['account_request_reason_options','admin_navigation_items','admin_queue_filter_options','admin_queue_signals','admin_queue_sla_policies','admin_queue_specs','brand_entities','collection_category_subtypes','collection_purpose_templates','collection_type_catalog','collection_type_country_rules','feature_flags','notification_channels','notification_event_types','notification_template_versions','notification_templates','otp_policy','payment_entrypoints','policy_document_sections','policy_documents','roster_resource_policy','sms_receipt_member_consents','sms_receipt_policies','support_channels','system_settings'])
  or spec is null or coalesce((spec->>'user_owned')::boolean,false) then
  raise exception 'runtime_control_family_invalid' using errcode='22023';end if;
 return spec;
end$$;


ALTER FUNCTION collect_security.runtime_control_v2_spec(p_family text) OWNER TO postgres;

--
-- Name: runtime_control_v2_utc(timestamp with time zone); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_v2_utc(p_at timestamp with time zone) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    SET search_path TO ''
    AS $$
 select to_char(p_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
$$;


ALTER FUNCTION collect_security.runtime_control_v2_utc(p_at timestamp with time zone) OWNER TO postgres;

--
-- Name: runtime_control_validate(text, jsonb, jsonb); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.runtime_control_validate(p_family text, p_new jsonb, p_old jsonb DEFAULT NULL::jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare spec jsonb:=collect_security.runtime_control_spec(p_family); field record; typ text; value_type text; clean text; limit_chars integer;
 parent public.policy_documents; amount_text text;
begin
 if spec is null or p_new is null or jsonb_typeof(p_new)<>'object' then raise exception 'runtime_control_invalid' using errcode='22023';end if;
 perform collect_security.runtime_control_check_values(p_family,case when p_old is null then p_new else
  coalesce((select jsonb_object_agg(key,value) from jsonb_each(p_new) where p_old->key is distinct from value),'{}'::jsonb) end);
 if p_old is not null and exists(select 1 from jsonb_array_elements_text(spec->'immutable_after_create') k where p_new->k is distinct from p_old->k) then
  raise exception 'runtime_control_wiring_immutable' using errcode='55000';end if;
 if p_family='support_channels' then
  if p_new->>'channel_type' in ('phone','whatsapp') and (char_length(p_new->>'value') not between 8 and 16 or p_new->>'value' !~ '^\+?[1-9][0-9]+$')
   or p_new->>'channel_type'='email' and (char_length(p_new->>'value')>254 or p_new->>'value' !~ '^[A-Za-z0-9.!#$%&''*+/=?^_`{|}~-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,63}$')
   or p_new->>'channel_type'='url' and not collect_security.runtime_control_https(p_new->>'value') then raise exception 'runtime_control_invalid_support' using errcode='22023';end if;
 end if;
 if p_family='payment_entrypoints' and (p_new->>'is_active')::boolean then
  if p_new->>'country_code' is distinct from 'RW' or p_new->>'currency' is distinct from 'RWF' or p_new->>'network' is distinct from 'mtn_momo'
    or p_new->>'code' is null or p_new->>'code' !~ '^\*182\*8\*1\*41258\*[1-9][0-9]{0,8}#$' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
  amount_text:=split_part(p_new->>'code','*',6);amount_text:=replace(amount_text,'#','');
  if p_new->'metadata'->>'amount_rwf' is distinct from amount_text then raise exception 'runtime_control_payment_amount_mismatch' using errcode='22023';end if;
 end if;
 if p_family='collection_type_country_rules' and (p_new->>'enabled')::boolean and p_new->>'country_code' is distinct from 'RW' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
 if p_family='feature_flags' and (p_new->>'enabled')::boolean and p_new->>'key' ~* '(bank_transfer|stripe|diaspora|international|foreign)' then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
 if p_family='system_settings' then
  if p_new->>'key' ~* '(secret|password|credential|api[_-]?key|token|private[_-]?key)' then raise exception 'runtime_control_sensitive_field' using errcode='22023';end if;
  if p_new->>'key'='payments.mode' and p_new->'value' is distinct from '{"rwanda":{"provider":"momo_ussd_sms","currency":"RWF"}}'::jsonb then raise exception 'runtime_control_rwanda_route_required' using errcode='22023';end if;
  if p_new->>'key'='sms.parser.schema_version' and p_new->'value' is distinct from '"collect.sms_parser.v1"'::jsonb then raise exception 'runtime_control_unsupported_parser' using errcode='22023';end if;
 end if;
 if p_old is not null and p_family in ('policy_documents','notification_template_versions') and (p_old->>'status'<>'draft' or p_old->>'published_at' is not null) then
  if (p_new-array['status','updated_at','updated_by','updated_reason']) is distinct from (p_old-array['status','updated_at','updated_by','updated_reason'])
    or p_new->>'status' not in ('published','archived') or (p_old->>'status'='archived' and p_new->>'status'<>'archived') then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 end if;
 if p_family='policy_document_sections' then
  select * into parent from public.policy_documents where id=(p_new->>'policy_document_id')::uuid;
  if parent.id is null or parent.status<>'draft' or parent.published_at is not null then raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 end if;
 if p_family='notification_templates' and p_old is not null and exists(select 1 from public.notification_template_versions where template_key=p_old->>'key' and (status<>'draft' or published_at is not null))
  and (p_new-array['enabled','updated_at','updated_by','updated_reason']) is distinct from (p_old-array['enabled','updated_at','updated_by','updated_reason']) then
  raise exception 'runtime_control_published_immutable' using errcode='55000';end if;
 if p_family='policy_documents' and p_new->>'status'='published' and (p_old is null or p_old->>'status'='draft') then
  if not exists(select 1 from public.policy_document_sections where policy_document_id=(p_new->>'id')::uuid) then raise exception 'runtime_control_policy_sections_required' using errcode='22023';end if;
 end if;
 if p_family='sms_receipt_policies' and not exists(select 1 from public.collections c where c.id=(p_new->>'collection_id')::uuid and c.collection_type='ikimina' and c.archived_at is null) then raise exception 'runtime_control_collection_required' using errcode='22023';end if;
 if p_family='sms_receipt_member_consents' and not exists(select 1 from collect_hybrid.member_records m join collect_hybrid.member_momo_identities i on i.member_id=m.id where m.id=(p_new->>'member_record_id')::uuid and m.lifecycle='active' and m.linked_user_id is null) then raise exception 'runtime_control_member_required' using errcode='22023';end if;
 if p_family='roster_resource_policy' and ((p_new->>'actor_active')::integer>(p_new->>'global_active')::integer
   or (p_new->>'actor_daily_requests')::integer>(p_new->>'global_daily_requests')::integer
   or (p_new->>'actor_daily_bytes')::bigint>(p_new->>'global_daily_bytes')::bigint
   or (p_new->>'actor_daily_cost_units')::bigint>(p_new->>'global_daily_cost_units')::bigint
   or (p_new->>'ai_attempt_cost_units')::bigint>(p_new->>'actor_daily_cost_units')::bigint) then raise exception 'runtime_control_quota_order_invalid' using errcode='22023';end if;
 if p_family='otp_policy' and (p_new->>'global_hourly_limit')::integer>(p_new->>'global_daily_limit')::integer then raise exception 'runtime_control_quota_order_invalid' using errcode='22023';end if;
end $_$;


ALTER FUNCTION collect_security.runtime_control_validate(p_family text, p_new jsonb, p_old jsonb) OWNER TO postgres;

--
-- Name: rwanda_sms_scope(uuid); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.rwanda_sms_scope(p_sms_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $_$
 select exists(
  select 1 from public.raw_payment_sms sms
  left join public.parsed_payment_events e on e.raw_sms_id=sms.id
  where sms.id=p_sms_id
   and (e.id is null or (e.is_mobile_money_payment and e.currency='RWF'
    and e.network in ('mtn_momo','airtel_money') and e.direction='incoming'
    and e.receiver_user_id=sms.receiver_user_id
    and (e.receiver_phone_hash is null or e.receiver_phone_hash=sms.receiver_momo_number_hash)))
   and (exists(select 1 from public.collection_receivers r
     where r.collection_id=sms.collection_id and r.receiver_user_id=sms.receiver_user_id
      and r.momo_number_hash=sms.receiver_momo_number_hash
      and (e.id is null or e.network=r.network)
      and ((r.network='mtn_momo' and r.momo_number ~ '^(\+250|0)7[89][0-9]{7}$')
       or (r.network='airtel_money' and r.momo_number ~ '^(\+250|0)7[23][0-9]{7}$')))
    or exists(select 1 from public.profiles profile where profile.id=sms.receiver_user_id
     and profile.country_code='RW' and profile.currency_code='RWF'
     and profile.momo_number_verified_at is not null
     and profile.momo_number_hash=sms.receiver_momo_number_hash
     and (e.id is null or e.network=profile.momo_provider)
     and ((profile.momo_provider='mtn_momo' and profile.momo_number ~ '^(\+250|0)7[89][0-9]{7}$')
      or (profile.momo_provider='airtel_money' and profile.momo_number ~ '^(\+250|0)7[23][0-9]{7}$'))))
 )
$_$;


ALTER FUNCTION collect_security.rwanda_sms_scope(p_sms_id uuid) OWNER TO postgres;

--
-- Name: shadow_run_json(uuid, timestamp with time zone); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.shadow_run_json(p_run_id uuid, p_observed_at timestamp with time zone DEFAULT clock_timestamp()) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare r collect_security.shadow_supervisor_runs;
  s collect_security.shadow_supervisor_samples;
begin
  select * into r from collect_security.shadow_supervisor_runs where id=p_run_id;
  if r.id is null then return null;end if;
  select * into s from collect_security.shadow_supervisor_samples where run_id=r.id;
  if s.id is not null and s.content_sha256 is distinct from
    encode(extensions.digest(convert_to(s.body::text,'UTF8'),'sha256'),'hex') then
    raise exception 'shadow_integrity_unavailable' using errcode='55000';end if;
  return jsonb_build_object('run_id',r.id,'request_id',r.request_id,
    'fence_version',r.fence_version,'status',case when r.status='running'
      and r.lease_expires_at<=p_observed_at then 'expired' else r.status end,
    'started_at',r.started_at,'lease_expires_at',r.lease_expires_at,
    'sampled_at',s.checked_at,'completed_at',r.completed_at,'summary',s.body->'summary');
end $$;


ALTER FUNCTION collect_security.shadow_run_json(p_run_id uuid, p_observed_at timestamp with time zone) OWNER TO postgres;

--
-- Name: transaction_lifecycle(uuid, boolean); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.transaction_lifecycle(p_sms_id uuid, p_notifications boolean) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
 with evidence as (
  select sms.id,sms.parse_status,e.allocation_status,p.id payment_id,p.status,
   p.amount_rwf,p.collection_id,p.member_record_id,
   pc.id confirmation_id,pr.payment_id rejection_id,
   pc.amount_rwf confirmation_amount,pc.provider_network confirmation_network,
   p.provider_network,pc.transaction_id confirmation_reference,p.transaction_id,
   exists(select 1 from collect_hybrid.momo_journal_entries j
    join collect_hybrid.momo_balance_snapshots s on s.journal_entry_id=j.id
    where j.payment_id=p.id and j.entry_type='receipt' and j.amount_rwf=p.amount_rwf
     and j.collection_id=p.collection_id and j.member_record_id is not distinct from p.member_record_id
     and s.payment_id=p.id and s.collection_id=p.collection_id
     and s.member_record_id is not distinct from p.member_record_id
     and s.event_type='receipt' and s.delta_rwf=p.amount_rwf
     and (select count(*)=2 and count(*) filter(where
      (l.account_code='momo_receiving_asset:RWF' and l.direction='debit') or
      (l.account_code='member_savings_liability:RWF' and l.direction='credit'))=2
      and min(l.amount_rwf)=p.amount_rwf and max(l.amount_rwf)=p.amount_rwf
      from collect_hybrid.momo_journal_lines l where l.journal_entry_id=j.id)) receipt_posted,
   exists(select 1 from collect_hybrid.momo_journal_entries j
    join collect_hybrid.momo_balance_snapshots s on s.journal_entry_id=j.id
    where j.payment_id=p.id and j.entry_type='reversal' and j.amount_rwf=p.amount_rwf
     and j.collection_id=p.collection_id and j.member_record_id is not distinct from p.member_record_id
     and s.payment_id=p.id and s.collection_id=p.collection_id
     and s.member_record_id is not distinct from p.member_record_id
     and s.event_type='reversal' and s.delta_rwf=-p.amount_rwf
     and (select count(*)=2 and count(*) filter(where
      (l.account_code='momo_receiving_asset:RWF' and l.direction='credit') or
      (l.account_code='member_savings_liability:RWF' and l.direction='debit'))=2
      and min(l.amount_rwf)=p.amount_rwf and max(l.amount_rwf)=p.amount_rwf
      from collect_hybrid.momo_journal_lines l where l.journal_entry_id=j.id)) reversal_posted,
   case when p_notifications then (select o.state from collect_hybrid.sms_notification_outbox o
    where o.payment_id=p.id and o.template_key='buri_munsi.payment_received') else null end notification
  from public.raw_payment_sms sms
  left join public.parsed_payment_events e on e.raw_sms_id=sms.id
  left join public.payments p on p.parsed_event_id=e.id
  left join public.payment_provider_confirmations pc on pc.payment_id=p.id
  left join collect_hybrid.payment_provider_rejections pr on pr.payment_id=p.id
  where sms.id=p_sms_id
 ) select jsonb_build_object('contract_version',1,
  'verification',case
   when confirmation_id is not null and (rejection_id is not null or confirmation_amount<>amount_rwf
    or confirmation_network is distinct from provider_network
    or upper(btrim(confirmation_reference)) is distinct from upper(btrim(transaction_id))) then 'evidence_conflict'
   when rejection_id is not null then 'rejection_recorded'
   when confirmation_id is not null then 'confirmation_recorded' else 'pending' end,
  'allocation',coalesce(allocation_status::text,case parse_status
   when 'pending' then 'pending_parse' when 'failed' then 'parse_failed' else 'unavailable' end),
  'ledger',case when status='reversed' and receipt_posted and reversal_posted then 'reversed'
   when status='posted' and receipt_posted and not reversal_posted then 'posted'
   when status in ('posted','reversed') or receipt_posted or reversal_posted then 'evidence_missing'
   else 'not_posted' end,
  'notification',case when not p_notifications then 'access_required'
   else coalesce(notification,'not_created') end,
  'evidence_limit','confirmation_record_is_not_external_settlement_proof') from evidence
$$;


ALTER FUNCTION collect_security.transaction_lifecycle(p_sms_id uuid, p_notifications boolean) OWNER TO postgres;

--
-- Name: transaction_read_authority(text); Type: FUNCTION; Schema: collect_security; Owner: postgres
--

CREATE FUNCTION collect_security.transaction_read_authority(p_permission text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;
begin
 if p_permission not in ('payments.read','notifications.read') or p_permission is null then
  raise exception 'transaction_permission_invalid' using errcode='22023';end if;
 sid:=public._lock_notification_registration_session();
 perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
 -- Match installed Admin authority: approved current platform_owner only.
 -- Lock Auth, approval, grant, role and permission proof rows against revoke.
 begin
  perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,
   'platform_owner',array[p_permission]);
  return true;
 exception when sqlstate '42501' then return false;end;
end $$;


ALTER FUNCTION collect_security.transaction_read_authority(p_permission text) OWNER TO postgres;

--
-- Name: change_identity(uuid, uuid, text, text); Type: FUNCTION; Schema: collect_supervisor; Owner: postgres
--

CREATE FUNCTION collect_supervisor.change_identity(p_principal uuid, p_request uuid, p_expected_key text, p_action text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare sid uuid;item collect_supervisor.identities;prior jsonb;input jsonb;result jsonb;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();
 if p_principal is null or p_request is null or p_expected_key is null
  or p_expected_key !~ '^[0-9a-f]{64}$'or p_action not in('activate','revoke')then
  raise exception 'supervisor_action_invalid'using errcode='22023';end if;
 input:=jsonb_build_array(p_principal,p_expected_key);
 perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request::text,0));
 prior:=collect_supervisor.owner_replay(p_request,auth.uid(),p_action,input);
 if prior is not null then return prior;end if;
 select * into item from collect_supervisor.identities where id=p_principal for update;
 if item.id is null or item.key_sha256<>p_expected_key then
  raise exception 'supervisor_identity_unavailable'using errcode='42501';end if;
 t:=clock_timestamp();
 if p_action='activate'then
  if item.state<>'pending'or item.expires_at<=t then
   raise exception 'supervisor_activation_unavailable'using errcode='55000';end if;
  if not exists(select 1 from collect_supervisor.requests where principal_id=item.id and action='prove_key'
   and recorded_at>=t-interval '120 seconds'and issued_at>=t-interval '120 seconds'
   and issued_at<=t+interval '30 seconds')then
   raise exception 'supervisor_key_possession_required'using errcode='55000';end if;
  update collect_supervisor.identities set state='active',activated_at=t where id=item.id;
 else
  if item.state='revoked'then raise exception 'supervisor_already_revoked'using errcode='55000';end if;
  update collect_supervisor.identities set state='revoked',revoked_at=t where id=item.id;
 end if;
 result:=jsonb_build_object('contract_version',1,'principal_id',item.id,'request_id',p_request,
  'state_at_action',case p_action when 'activate'then 'active'else 'revoked'end,
  'scope',item.scope,'key_sha256',item.key_sha256,'expires_at',collect_gateway.utc(item.expires_at),
  'recorded_at',collect_gateway.utc(t));
 insert into collect_supervisor.owner_requests values(p_request,auth.uid(),sid,p_action,input,result,t);
 perform public.create_audit_log('supervisor.identity.'||p_action,'receipt_supervisor',item.id,
  jsonb_build_object('request_id',p_request,'scope',item.scope),null);
 return result;
end$_$;


ALTER FUNCTION collect_supervisor.change_identity(p_principal uuid, p_request uuid, p_expected_key text, p_action text) OWNER TO postgres;

--
-- Name: distinct_identity_key(); Type: FUNCTION; Schema: collect_supervisor; Owner: postgres
--

CREATE FUNCTION collect_supervisor.distinct_identity_key() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 if current_setting('transaction_isolation')<>'read committed'then
  raise exception 'supervisor_snapshot_retry'using errcode='40001';end if;
 perform pg_advisory_xact_lock(hashtextextended('collect-dedicated-key:'||new.key_sha256,0));
 if (tg_table_schema='collect_gateway'and exists(
  select 1 from collect_supervisor.identities where key_sha256=new.key_sha256))
  or(tg_table_schema='collect_supervisor'and exists(
  select 1 from collect_gateway.devices where key_sha256=new.key_sha256))then
  raise exception 'supervisor_key_scope_conflict'using errcode='22023';end if;
 return new;
end$$;


ALTER FUNCTION collect_supervisor.distinct_identity_key() OWNER TO postgres;

--
-- Name: guard_identity(); Type: FUNCTION; Schema: collect_supervisor; Owner: postgres
--

CREATE FUNCTION collect_supervisor.guard_identity() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin
 if tg_op='DELETE'then raise exception 'supervisor_identity_retained'using errcode='55000';end if;
 if (to_jsonb(new)-array['state','activated_at','revoked_at'])is distinct from
  (to_jsonb(old)-array['state','activated_at','revoked_at'])or old.state='revoked'
  or(old.state='active'and new.state not in('active','revoked'))
  or(old.activated_at is not null and new.activated_at is distinct from old.activated_at)then
  raise exception 'supervisor_identity_immutable'using errcode='55000';end if;
 return new;
end$$;


ALTER FUNCTION collect_supervisor.guard_identity() OWNER TO postgres;

