CREATE FUNCTION collect_supervisor.immutable_evidence() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
begin raise exception 'supervisor_evidence_immutable'using errcode='55000';end$$;


