--
-- Name: _authenticated_momo_phone_hash(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._authenticated_momo_phone_hash(p_user_id uuid) RETURNS text
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public', 'auth', 'extensions'
    AS $_$
declare
  profile_digits text;
  auth_digits text;
  canonical_profile_phone text;
  canonical_auth_phone text;
  auth_phone_confirmed_at timestamptz;
begin
  select
    regexp_replace(coalesce(profile.momo_number, ''), '[^0-9]', '', 'g'),
    regexp_replace(coalesce(auth_user.phone, ''), '[^0-9]', '', 'g'),
    auth_user.phone_confirmed_at
    into profile_digits, auth_digits, auth_phone_confirmed_at
  from public.profiles profile
  join auth.users auth_user on auth_user.id = profile.id
  where profile.id = p_user_id
    and auth_user.deleted_at is null
    and profile.country_code = 'RW';

  if profile_digits ~ '^250[0-9]{9}$' then
    canonical_profile_phone := '+' || profile_digits;
  elsif profile_digits ~ '^0[0-9]{9}$' then
    canonical_profile_phone := '+250' || substr(profile_digits, 2);
  elsif profile_digits ~ '^[0-9]{9}$' then
    canonical_profile_phone := '+250' || profile_digits;
  else
    return null;
  end if;

  if auth_digits ~ '^250[0-9]{9}$' then
    canonical_auth_phone := '+' || auth_digits;
  elsif auth_digits ~ '^0[0-9]{9}$' then
    canonical_auth_phone := '+250' || substr(auth_digits, 2);
  elsif auth_digits ~ '^[0-9]{9}$' then
    canonical_auth_phone := '+250' || auth_digits;
  else
    return null;
  end if;

  if auth_phone_confirmed_at is null
     or canonical_profile_phone <> canonical_auth_phone then
    return null;
  end if;

  return encode(extensions.digest(canonical_auth_phone, 'sha256'), 'hex');
end;
$_$;


ALTER FUNCTION public._authenticated_momo_phone_hash(p_user_id uuid) OWNER TO postgres;

--
-- Name: _create_roster_import_source_v142(uuid, uuid, uuid, text, text, bigint, text, text, text, text, bigint, boolean, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._create_roster_import_source_v142(p_actor_id uuid, p_session_id uuid, p_request_id uuid, p_source_kind text, p_original_sha256 text, p_original_size bigint, p_client_filename text, p_declared_mime text, p_detected_type text, p_derived_sha256 text, p_derived_size bigint, p_ai_consent boolean, p_consent_version text, p_ai_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
   begin perform collect_hybrid.guard_roster_service_recovery((select id from collect_hybrid.roster_import_sources where request_id=p_request_id)); return collect_hybrid._create_roster_import_source_v142_guarded_149(p_actor_id,p_session_id,p_request_id,p_source_kind,p_original_sha256,p_original_size,p_client_filename,p_declared_mime,p_detected_type,p_derived_sha256,p_derived_size,p_ai_consent,p_consent_version,p_ai_metadata); end $$;


