--
-- Name: _lock_notification_registration_session(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._lock_notification_registration_session() RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare session_text text:=auth.jwt()->>'session_id'; session_id uuid; begin
  perform public._lock_notification_session_gate();
  if auth.role() is distinct from 'authenticated' or auth.uid() is null
    or session_text is null or session_text !~* '^[0-9a-f]{8}(-[0-9a-f]{4}){3}-[0-9a-f]{12}$' then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  session_id:=session_text::uuid;
  -- SHARE blocks both deletion and non-key revocation updates before we lock
  -- a token. A late registration sees the deletion after waiting and refuses.
  perform 1 from auth.sessions s where s.id=session_id and s.user_id=auth.uid() for share;
  if not found or not public._notification_session_is_live(session_id,auth.uid()) then
    raise exception 'notification_registration_session_required' using errcode='42501';
  end if;
  return session_id;
end $_$;


ALTER FUNCTION public._lock_notification_registration_session() OWNER TO postgres;

--
-- Name: _lock_notification_session_gate(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public._lock_notification_session_gate() RETURNS void
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO ''
    AS $$
  select pg_catalog.pg_advisory_xact_lock_shared(193517,141);
$$;


ALTER FUNCTION public._lock_notification_session_gate() OWNER TO postgres;

--
-- Name: profiles; Type: TABLE; Schema: public; Owner: postgres
--

CREATE TABLE public.profiles (
    id uuid NOT NULL,
    public_id character(6) NOT NULL,
    display_name text,
    avatar_url text,
    whatsapp_phone text,
    momo_number text,
    momo_number_hash text,
    anonymity_default text DEFAULT 'anonymous'::text NOT NULL,
    is_platform_admin boolean DEFAULT false NOT NULL,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    momo_pay_code text,
    country_code text,
    currency_code text,
    revolut_name text,
    momo_provider text,
    momo_number_verified_at timestamp with time zone,
    revolut_link text,
    revolut_account text,
    CONSTRAINT profiles_anonymity_default_check CHECK ((anonymity_default = ANY (ARRAY['anonymous'::text, 'public_id'::text, 'display_name'::text]))),
    CONSTRAINT profiles_country_code_format CHECK (((country_code IS NULL) OR (country_code ~ '^[A-Z]{2}$'::text))),
    CONSTRAINT profiles_currency_code_format CHECK (((currency_code IS NULL) OR (currency_code ~ '^[A-Z]{3}$'::text))),
    CONSTRAINT profiles_momo_number_hash_matches CHECK (((momo_number_hash IS NULL) OR ((momo_number ~ '^07[2389][0-9]{7}$'::text) AND (momo_number_hash = encode(extensions.digest(('+250'::text || substr(momo_number, 2)), 'sha256'::text), 'hex'::text))) OR ((momo_number ~ '^\\+2507[2389][0-9]{7}$'::text) AND (momo_number_hash = encode(extensions.digest(momo_number, 'sha256'::text), 'hex'::text))))),
    CONSTRAINT profiles_momo_number_rw_format CHECK (((momo_number IS NULL) OR (momo_number ~ '^07[2389][0-9]{7}$'::text) OR (momo_number ~ '^\+2507[2389][0-9]{7}$'::text))),
    CONSTRAINT profiles_momo_pay_code_format CHECK (((momo_pay_code IS NULL) OR (momo_pay_code ~ '^[0-9]{4,9}$'::text))),
    CONSTRAINT profiles_momo_provider_check CHECK (((momo_provider IS NULL) OR (momo_provider = ANY (ARRAY['mtn_momo'::text, 'airtel_money'::text])))),
    CONSTRAINT profiles_momo_provider_number_match CHECK (((momo_provider IS NULL) OR (momo_number IS NULL) OR ((momo_provider = 'mtn_momo'::text) AND (momo_number ~ '^(\+250|0)7[89][0-9]{7}$'::text)) OR ((momo_provider = 'airtel_money'::text) AND (momo_number ~ '^(\+250|0)7[23][0-9]{7}$'::text)))),
    CONSTRAINT profiles_public_id_digits CHECK ((public_id ~ '^[0-9]{6}$'::text)),
    CONSTRAINT profiles_revolut_account_length CHECK (((revolut_account IS NULL) OR ((char_length(btrim(revolut_account)) >= 4) AND (char_length(btrim(revolut_account)) <= 120)))),
    CONSTRAINT profiles_revolut_link_format CHECK (((revolut_link IS NULL) OR (revolut_link ~ '^https://([a-z0-9-]+\.)?revolut\.me/[A-Za-z0-9._~-]+/?$'::text))),
    CONSTRAINT profiles_revolut_name_length CHECK (((revolut_name IS NULL) OR ((char_length(TRIM(BOTH FROM revolut_name)) >= 2) AND (char_length(TRIM(BOTH FROM revolut_name)) <= 100))))
);


