--
-- Name: admin_activate_receipt_operations_identity_v2(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_activate_receipt_operations_identity_v2(p_principal_id uuid, p_request_id uuid, p_expected_key_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare sid uuid;prior jsonb;input jsonb;r collect_supervisor.identities;result jsonb;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();
 if p_principal_id is null or p_request_id is null or p_expected_key_sha256 is null or p_expected_key_sha256!~'^[0-9a-f]{64}$'then raise exception 'operations_identity_input_invalid'using errcode='22023';end if;
 input:=jsonb_build_array(p_principal_id,p_expected_key_sha256);perform pg_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0));
 prior:=collect_receipt_operations.owner_replay(p_request_id,'activate',input);if prior is not null then return prior;end if;
 select * into r from collect_supervisor.identities where id=p_principal_id for update;t:=clock_timestamp();
 if r.id is null or r.scope<>'rw_receipt_operations'or r.key_sha256<>p_expected_key_sha256 or r.state<>'pending'or r.expires_at<=t then raise exception 'operations_identity_unavailable'using errcode='42501';end if;
 if not exists(select 1 from collect_receipt_operations.requests where principal_id=r.id and action='prove_key'and recorded_at>=t-interval '120 seconds')then raise exception 'operations_key_possession_required'using errcode='55000';end if;
 update collect_supervisor.identities set state='active',activated_at=t where id=r.id;
 result:=jsonb_build_object('contract_version',2,'principal_id',r.id,'request_id',p_request_id,'state_at_action','active','scope','rw_receipt_operations','recorded_at',collect_gateway.utc(t));
 insert into collect_receipt_operations.owner_requests values(p_request_id,auth.uid(),sid,'activate',input,result,t,null);
 perform public.create_audit_log('supervisor.operations.activate','receipt_supervisor',r.id,jsonb_build_object('request_id',p_request_id),auth.uid());return result;end$_$;


ALTER FUNCTION public.admin_activate_receipt_operations_identity_v2(p_principal_id uuid, p_request_id uuid, p_expected_key_sha256 text) OWNER TO postgres;

--
-- Name: admin_activate_receipt_operations_identity_v3(uuid, uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_activate_receipt_operations_identity_v3(p_principal_id uuid, p_request_id uuid, p_expected_key_sha256 text, p_request_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare sid uuid;prior collect_receipt_operations.enrollment_workflow_requests;input jsonb;
 legacy jsonb;item collect_supervisor.identities;result jsonb;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_principal_id is null or p_request_id is null or p_expected_key_sha256 is null or p_expected_key_sha256!~'^[0-9a-f]{64}$'
  or p_request_expires_at is null or not isfinite(p_request_expires_at)
  or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_input_invalid'using errcode='22023';end if;
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 input:=jsonb_build_array(p_principal_id,p_expected_key_sha256,p_request_expires_at);
 perform pg_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0));
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request_id::text,0));
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 select * into prior from collect_receipt_operations.enrollment_workflow_requests where request_id=p_request_id;
 if prior.request_id is not null then
  if prior.actor_id<>auth.uid()or prior.action<>'activate'or prior.input is distinct from input
   or prior.request_expires_at<>p_request_expires_at then raise exception 'operations_enrollment_request_conflict'using errcode='22023';end if;
  return prior.result;
 end if;
 if exists(select 1 from collect_receipt_operations.owner_requests where request_id=p_request_id)
  or exists(select 1 from collect_supervisor.owner_requests where request_id=p_request_id)
  then raise exception 'operations_enrollment_legacy_request_conflict'using errcode='22023';end if;
 select * into item from collect_supervisor.identities where id=p_principal_id for update;
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 if item.id is null or item.owner_actor_id<>auth.uid()or item.key_sha256<>p_expected_key_sha256
  or item.scope<>'rw_receipt_operations'or item.state<>'pending'or item.expires_at<=t
  then raise exception 'operations_identity_unavailable'using errcode='42501';end if;
 legacy:=public.admin_activate_receipt_operations_identity_v2(p_principal_id,p_request_id,p_expected_key_sha256);
 select * into item from collect_supervisor.identities where id=p_principal_id for share;
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 if item.id is null or item.owner_actor_id<>auth.uid()or item.key_sha256<>p_expected_key_sha256 or item.scope<>'rw_receipt_operations'
  or item.state<>'active'or item.expires_at<=t or legacy->>'principal_id'<>p_principal_id::text
  then raise exception 'operations_enrollment_binding_invalid'using errcode='55000';end if;
 result:=jsonb_build_object('contract_version',3,'action','activate','request_id',p_request_id,'principal_id',item.id,
  'state_at_action','active','scope','rw_receipt_operations','key_sha256',item.key_sha256,
  'identity_expires_at',collect_gateway.utc(item.expires_at),'recorded_at',collect_gateway.utc(t),
  'request_expires_at',collect_gateway.utc(p_request_expires_at));
 insert into collect_receipt_operations.enrollment_workflow_requests values(p_request_id,auth.uid(),sid,'activate',input,p_request_expires_at,result,t);
 return result;end$_$;


ALTER FUNCTION public.admin_activate_receipt_operations_identity_v3(p_principal_id uuid, p_request_id uuid, p_expected_key_sha256 text, p_request_expires_at timestamp with time zone) OWNER TO postgres;

