--
-- Name: admin_configure_receipt_operations_v2(uuid, bigint, text, boolean, uuid[], uuid[], uuid[], jsonb, boolean, integer, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_configure_receipt_operations_v2(p_request_id uuid, p_expected_revision bigint, p_mode text, p_emergency_stop boolean, p_principal_ids uuid[], p_collection_ids uuid[], p_device_ids uuid[], p_caps jsonb, p_catchup_enabled boolean, p_catchup_hours integer, p_reason text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;r collect_receipt_operations.policy;input jsonb;prior jsonb;result jsonb;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();
 if p_request_id is null or p_expected_revision is null or p_mode is null or p_mode not in('Shadow','Dry-run','Live-limited','Live','Paused')
  or p_emergency_stop is null or(p_mode='Paused'and not p_emergency_stop)or p_principal_ids is null or p_collection_ids is null or p_device_ids is null
  or cardinality(p_principal_ids)not between 1 and 10 or cardinality(p_collection_ids)not between 1 and 100 or cardinality(p_device_ids)>10
  or array_ndims(p_principal_ids)<>1 or array_ndims(p_collection_ids)<>1 or coalesce(array_ndims(p_device_ids),1)<>1
  or array_position(p_principal_ids,null)is not null or array_position(p_collection_ids,null)is not null or array_position(p_device_ids,null)is not null
  or cardinality(p_principal_ids)<>(select count(distinct x)from unnest(p_principal_ids)x)
  or cardinality(p_collection_ids)<>(select count(distinct x)from unnest(p_collection_ids)x)
  or cardinality(p_device_ids)<>(select count(distinct x)from unnest(p_device_ids)x)
  or not collect_receipt_operations.caps_valid(p_caps)or p_catchup_enabled is null or p_catchup_hours is null or p_catchup_hours not between 1 and 168
  or p_reason is null or char_length(btrim(p_reason))not between 8 and 500
  or p_expires_at is null or not isfinite(p_expires_at)or p_expires_at>clock_timestamp()+interval '120 seconds' then raise exception 'operations_policy_input_invalid'using errcode='22023';end if;
 if p_expires_at<=clock_timestamp()then raise exception 'operations_owner_request_expired'using errcode='55000';end if;
 if p_mode='Live-limited'and((p_caps->>'run_actions')::integer>10 or(p_caps->>'run_sms_segments')::integer>20)then raise exception 'operations_pilot_caps_exceeded'using errcode='22023';end if;
 input:=jsonb_build_array(p_expected_revision,p_mode,p_emergency_stop,p_principal_ids,p_collection_ids,p_device_ids,p_caps,p_catchup_enabled,p_catchup_hours,btrim(p_reason),p_expires_at);
 perform pg_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0));
 prior:=collect_receipt_operations.owner_replay(p_request_id,'configure',input);if prior is not null then return prior;end if;
 select * into r from collect_receipt_operations.policy where singleton for update;perform collect_supervisor.owner_actor();
 if r.revision<>p_expected_revision or r.revision=1000000000 then raise exception 'operations_policy_source_changed'using errcode='55000';end if;
 if exists(select 1 from unnest(p_principal_ids)x left join collect_supervisor.identities i on i.id=x where i.id is null or i.scope<>'rw_receipt_operations'or i.state<>'active'or i.expires_at<=clock_timestamp())
  or exists(select 1 from unnest(p_collection_ids)x left join public.collections c on c.id=x where c.id is null or c.collection_type<>'ikimina'or c.archived_at is not null)
  or exists(select 1 from unnest(p_device_ids)x left join collect_gateway.devices d on d.id=x where d.id is null or d.state<>'active')
  or(p_mode in('Live','Live-limited')and cardinality(p_device_ids)=0)then raise exception 'operations_scope_unavailable'using errcode='42501';end if;
 t:=clock_timestamp();if p_expires_at<=t then raise exception 'operations_owner_request_expired'using errcode='55000';end if;
 update collect_receipt_operations.policy set revision=r.revision+1,mode=p_mode,emergency_stop=p_emergency_stop,
 principal_ids=p_principal_ids,collection_ids=p_collection_ids,device_ids=p_device_ids,caps=p_caps,catchup_enabled=p_catchup_enabled,catchup_hours=p_catchup_hours,updated_at=t,updated_by=auth.uid()where singleton;
 result:=jsonb_build_object('contract_version',2,'request_id',p_request_id,'revision',r.revision+1,'mode',p_mode,'emergency_stop',p_emergency_stop,'recorded_at',collect_gateway.utc(t),'expires_at',collect_gateway.utc(p_expires_at));
 insert into collect_receipt_operations.owner_requests values(p_request_id,auth.uid(),sid,'configure',input,result,t,p_expires_at);
 perform public.create_audit_log('supervisor.operations.configure','receipt_operations_policy',null,
  jsonb_build_object('request_id',p_request_id,'revision',r.revision+1,'mode',p_mode,'emergency_stop',p_emergency_stop,'collection_ids',p_collection_ids,'device_ids',p_device_ids,'caps',p_caps,'catchup_enabled',p_catchup_enabled,'catchup_hours',p_catchup_hours,'reason',btrim(p_reason)),auth.uid());return result;end$$;


ALTER FUNCTION public.admin_configure_receipt_operations_v2(p_request_id uuid, p_expected_revision bigint, p_mode text, p_emergency_stop boolean, p_principal_ids uuid[], p_collection_ids uuid[], p_device_ids uuid[], p_caps jsonb, p_catchup_enabled boolean, p_catchup_hours integer, p_reason text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: admin_configure_unattended_operating_policy_v1(uuid, bigint, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_configure_unattended_operating_policy_v1(p_request_id uuid, p_expected_revision bigint, p_mode text, p_emergency_stop boolean, p_reason_code text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;bridge uuid;revision bigint;begin
 result:=public.collect_operations_legacy_configure_policy_v1(p_request_id,p_expected_revision,p_mode,p_emergency_stop,p_reason_code);
 if p_emergency_stop then
  bridge:=extensions.uuid_generate_v5('a1363b67-d8c0-45d2-9e0d-3ca9d35df59d','collect-v1-stop:'||p_request_id::text);
  if not exists(select 1 from collect_receipt_operations.owner_requests where request_id=bridge and actor_id=auth.uid()and action='stop')then
   select p.revision into revision from collect_receipt_operations.policy p where singleton for update;
   perform public.admin_stop_receipt_operations_v2(bridge,revision,'Inherited current operator emergency stop from v1 policy',clock_timestamp()+interval '120 seconds');
  end if;
 end if;return result;end$$;


