--
-- Name: admin_create_collect_payee(uuid, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_create_collect_payee(p_collection_id uuid, p_label text, p_momo_code text, p_network text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  collection_row public.collections;
  receiver_id uuid;
  clean_label text := btrim(coalesce(p_label, ''));
  clean_code text := regexp_replace(coalesce(p_momo_code, ''), '[^0-9]', '', 'g');
  clean_network text := lower(btrim(coalesce(p_network, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
begin
  perform public.assert_admin_permission('receivers.manage');
  if char_length(clean_label) not between 2 and 120 then
    raise exception 'Official payee name must be between 2 and 120 characters';
  end if;
  if clean_code !~ '^[0-9]{4,12}$' then
    raise exception 'MoMo number or code must contain 4 to 12 digits';
  end if;
  if clean_network not in ('mtn_momo', 'airtel_money') then
    raise exception 'Unsupported MoMo provider';
  end if;
  if char_length(clean_reason) < 8 then
    raise exception 'Creation reason must be at least 8 characters';
  end if;

  select collection.*
  into collection_row
  from public.collections collection
  where collection.id = p_collection_id
    and collection.is_platform_sponsored
    and collection.public_status = 'public_approved'
    and collection.archived_at is null
  for update;

  if collection_row.id is null then
    raise exception 'Eligible platform-sponsored public group not found';
  end if;
  if exists (
    select 1
    from public.collection_receivers receiver
    where receiver.collection_id = p_collection_id
  ) then
    raise exception 'This group already has an immutable payee route; reactivate it instead';
  end if;

  insert into public.collection_receivers (
    collection_id,
    receiver_user_id,
    momo_number,
    momo_number_hash,
    network,
    label,
    is_active
  ) values (
    p_collection_id,
    collection_row.creator_user_id,
    clean_code,
    encode(extensions.digest(clean_code, 'sha256'), 'hex'),
    clean_network,
    clean_label,
    true
  )
  returning id into receiver_id;

  update public.collections
  set receiver_display_label = clean_label,
      updated_at = now()
  where id = p_collection_id;

  perform public.create_audit_log(
    'payee.official.created',
    'collection_receiver',
    receiver_id,
    jsonb_build_object(
      'reason', clean_reason,
      'collection_id', p_collection_id,
      'label', clean_label,
      'provider', clean_network,
      'route_immutable', true
    )
  );

  return jsonb_build_object(
    'ok', true,
    'payee_id', receiver_id,
    'status', 'active',
    'route_immutable', true
  );
end;
$_$;


ALTER FUNCTION public.admin_create_collect_payee(p_collection_id uuid, p_label text, p_momo_code text, p_network text, p_reason text) OWNER TO postgres;

--
-- Name: FUNCTION admin_create_collect_payee(p_collection_id uuid, p_label text, p_momo_code text, p_network text, p_reason text); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.admin_create_collect_payee(p_collection_id uuid, p_label text, p_momo_code text, p_network text, p_reason text) IS 'Creates an official platform payee. The MoMo number or code and provider are immutable after insert.';


--
-- Name: admin_create_platform_public_group(text, text, text, text, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_create_platform_public_group(p_title text, p_description text, p_collection_type text, p_category_subtype text, p_purpose_label text, p_receiver_label text, p_momo_code text, p_network text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'extensions'
    AS $_$
declare
  clean_title text := btrim(coalesce(p_title, ''));
  clean_description text := btrim(coalesce(p_description, ''));
  clean_type text := lower(btrim(coalesce(p_collection_type, '')));
  clean_subtype text := nullif(btrim(coalesce(p_category_subtype, '')), '');
  clean_purpose text := btrim(coalesce(p_purpose_label, ''));
  clean_receiver text := btrim(coalesce(p_receiver_label, ''));
  clean_code text := regexp_replace(coalesce(p_momo_code, ''), '[^0-9]', '', 'g');
  clean_network text := lower(btrim(coalesce(p_network, '')));
  clean_reason text := btrim(coalesce(p_reason, ''));
  base_slug text;
  final_slug text;
  created_group_id uuid;
  created_receiver_id uuid;
begin
  perform public.assert_admin_permission('collections.moderate');
  perform public.assert_admin_permission('receivers.manage');

  if char_length(clean_title) not between 3 and 120 then
    raise exception 'Group name must be between 3 and 120 characters';
  end if;
  if char_length(clean_description) > 1000 then
    raise exception 'Group description must be 1000 characters or fewer';
  end if;
  if clean_type not in ('ikimina', 'sport', 'church', 'wedding', 'other') then
    raise exception 'Unsupported collection type';
  end if;
  if char_length(clean_purpose) not between 2 and 120 then
    raise exception 'Purpose label must be between 2 and 120 characters';
  end if;
  if char_length(clean_receiver) not between 2 and 120 then
    raise exception 'Official payee name must be between 2 and 120 characters';
  end if;
  if clean_code !~ '^[0-9]{4,12}$' then
    raise exception 'MoMo number or code must contain 4 to 12 digits';
  end if;
  if clean_network not in ('mtn_momo', 'airtel_money') then
    raise exception 'Unsupported MoMo provider';
  end if;
  if char_length(clean_reason) < 8 then
    raise exception 'Creation reason must be at least 8 characters';
  end if;
  if not exists (select 1 from public.profiles profile where profile.id = auth.uid()) then
    raise exception 'The signed-in admin does not have a Collect profile';
  end if;

  base_slug := public.normalize_slug(clean_title);
  if base_slug = '' then base_slug := 'group'; end if;
  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12);

  insert into public.collections (
    slug,
    creator_user_id,
    title,
    description,
    category,
    currency,
    visibility,
    public_status,
    is_recurring,
    allow_anonymous,
    contribution_visibility,
    allow_public_comments,
    receiver_display_label,
    collection_type,
    category_subtype,
    purpose_label,
    moderation_status,
    diaspora_enabled,
    diaspora_regions,
    is_platform_sponsored,
    archived_at
  ) values (
    final_slug,
    auth.uid(),
    clean_title,
    clean_description,
    case clean_type
      when 'sport' then 'Sports team'
      when 'church' then 'Church'
      when 'wedding' then 'Wedding'
      when 'ikimina' then 'Family / friends'
      else 'Other'
    end,
    'RWF',
    'public_approved',
    'public_approved',
    false,
    true,
    'public_safe',
    false,
    clean_receiver,
    clean_type,
    clean_subtype,
    clean_purpose,
    'approved',
    false,
    '{}'::text[],
    true,
    null
  ) returning id into created_group_id;

  insert into public.collection_members (collection_id, user_id, role, status)
  values (created_group_id, auth.uid(), 'owner', 'active');

  insert into public.collection_receivers (
    collection_id,
    receiver_user_id,
    momo_number,
    momo_number_hash,
    network,
    label,
    is_active
  ) values (
    created_group_id,
    auth.uid(),
    clean_code,
    encode(extensions.digest(clean_code, 'sha256'), 'hex'),
    clean_network,
    clean_receiver,
    true
  ) returning id into created_receiver_id;

  perform public.create_audit_log(
    'collection.platform_public.created',
    'collection',
    created_group_id,
    jsonb_build_object(
      'reason', clean_reason,
      'title', clean_title,
      'collection_type', clean_type,
      'category_subtype', clean_subtype,
      'purpose_label', clean_purpose,
      'receiver_id', created_receiver_id,
      'provider', clean_network,
      'route_immutable', true
    )
  );

  perform public.create_audit_log(
    'payee.official.created',
    'collection_receiver',
    created_receiver_id,
    jsonb_build_object(
      'reason', clean_reason,
      'collection_id', created_group_id,
      'label', clean_receiver,
      'provider', clean_network,
      'route_immutable', true
    )
  );

  return jsonb_build_object(
    'ok', true,
    'collection_id', created_group_id,
    'payee_id', created_receiver_id,
    'status', 'active',
    'visibility', 'public_approved',
    'route_immutable', true
  );
end;
$_$;


