--
-- Name: admin_enroll_gateway_device_v1(uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_enroll_gateway_device_v1(p_request_id uuid, p_installation_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_signing_certificate_sha256 text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare actor uuid;der bytea;i jsonb;r jsonb;d uuid;t timestamptz;
 x numeric:=0;y numeric:=0;point_byte integer;
 prime numeric:=115792089210356248762697446949407573530086143415290314195533631308867097853951;
 curve_b numeric:=41058363725152142129326129780047268409114441015993725554835256314039467401291;
begin
 actor:=collect_gateway.owner_actor();
 if p_request_id is null or p_installation_id is null or p_key_sha256 is null or p_key_sha256 !~ '^[0-9a-f]{64}$'
  or p_signing_certificate_sha256 is null or p_signing_certificate_sha256 !~ '^[0-9a-f]{64}$'
  or p_public_key_spki_base64 is null or p_public_key_spki_base64 !~ '^[A-Za-z0-9+/]{122}==$' then
  raise exception 'gateway_enrollment_invalid' using errcode='22023';end if;
 der:=decode(p_public_key_spki_base64,'base64');
 if octet_length(der)<>91 or encode(substring(der from 1 for 27),'hex')<>'3059301306072a8648ce3d020106082a8648ce3d03010703420004'
  or replace(encode(der,'base64'),E'\n','')<>p_public_key_spki_base64
  or encode(extensions.digest(der,'sha256'),'hex')<>p_key_sha256 then
  raise exception 'gateway_enrollment_invalid' using errcode='22023';end if;
 for point_byte in 0..31 loop
  x:=x*256+get_byte(der,27+point_byte);y:=y*256+get_byte(der,59+point_byte);
 end loop;
 if x>=prime or y>=prime or mod(y*y-(x*x*x-3*x+curve_b),prime)<>0 then
  raise exception 'gateway_enrollment_invalid' using errcode='22023';end if;
 -- DER, SHA and the actual P-256 curve point are checked here. Recent key
 -- possession still depends on the separately verified Edge signature.
 i:=jsonb_build_array(p_installation_id,p_public_key_spki_base64,p_key_sha256,p_signing_certificate_sha256);
 r:=collect_gateway.owner_replay(actor,p_request_id,'enroll',i);if r is not null then return r;end if;
 if exists(select 1 from collect_gateway.devices where installation_id=p_installation_id or key_sha256=p_key_sha256) then
  raise exception 'gateway_installation_already_enrolled' using errcode='22023';end if;
 t:=clock_timestamp();
 insert into collect_gateway.devices(enrollment_request_id,owner_actor_id,owner_session_id,installation_id,public_key_spki_base64,key_sha256,signing_certificate_sha256,created_at)
 values(p_request_id,actor,(auth.jwt()->>'session_id')::uuid,p_installation_id,p_public_key_spki_base64,p_key_sha256,p_signing_certificate_sha256,t) returning id into d;
 r:=jsonb_build_object('device_id',d,'request_id',p_request_id,'state_at_action','pending','recorded_at',collect_gateway.utc(t),'replay',false);
 insert into collect_gateway.admin_requests(request_id,actor_id,action,input,result,recorded_at) values(p_request_id,actor,'enroll',i,r,t);
 return r;
end$_$;


ALTER FUNCTION public.admin_enroll_gateway_device_v1(p_request_id uuid, p_installation_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_signing_certificate_sha256 text) OWNER TO postgres;

--
-- Name: admin_enroll_receipt_operations_identity_v2(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_enroll_receipt_operations_identity_v2(p_request_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;prior jsonb;input jsonb;result jsonb;principal uuid;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();
 if p_request_id is null or p_expires_at is null or not isfinite(p_expires_at)then raise exception 'operations_enrollment_invalid'using errcode='22023';end if;
 perform collect_supervisor.validate_key(p_public_key_spki_base64,p_key_sha256);
 input:=jsonb_build_array(p_public_key_spki_base64,p_key_sha256,p_expires_at);
 perform pg_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0));
 prior:=collect_receipt_operations.owner_replay(p_request_id,'enroll',input);if prior is not null then return prior;end if;
 t:=clock_timestamp();if p_expires_at<t+interval '10 minutes'or p_expires_at>t+interval '30 days'then raise exception 'operations_enrollment_invalid'using errcode='22023';end if;
 insert into collect_supervisor.identities(enrollment_request_id,owner_actor_id,owner_session_id,public_key_spki_base64,key_sha256,scope,created_at,expires_at)
 values(p_request_id,auth.uid(),sid,p_public_key_spki_base64,p_key_sha256,'rw_receipt_operations',t,p_expires_at)returning id into principal;
 result:=jsonb_build_object('contract_version',2,'principal_id',principal,'request_id',p_request_id,'state_at_action','pending','scope','rw_receipt_operations','key_sha256',p_key_sha256,'expires_at',collect_gateway.utc(p_expires_at),'recorded_at',collect_gateway.utc(t));
 insert into collect_receipt_operations.owner_requests values(p_request_id,auth.uid(),sid,'enroll',input,result,t,null);
 perform public.create_audit_log('supervisor.operations.enroll','receipt_supervisor',principal,jsonb_build_object('request_id',p_request_id,'scope','rw_receipt_operations'),auth.uid());
 return result;end$$;


ALTER FUNCTION public.admin_enroll_receipt_operations_identity_v2(p_request_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: admin_enroll_receipt_operations_identity_v3(uuid, text, text, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_enroll_receipt_operations_identity_v3(p_request_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_identity_expires_at timestamp with time zone, p_request_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;prior collect_receipt_operations.enrollment_workflow_requests;input jsonb;
 legacy jsonb;item collect_supervisor.identities;result jsonb;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_id is null or p_identity_expires_at is null or not isfinite(p_identity_expires_at)
  or p_request_expires_at is null or not isfinite(p_request_expires_at)
  or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_input_invalid'using errcode='22023';end if;
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 perform collect_supervisor.validate_key(p_public_key_spki_base64,p_key_sha256);
 input:=jsonb_build_array(p_public_key_spki_base64,p_key_sha256,p_identity_expires_at,p_request_expires_at);
 perform pg_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0));
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request_id::text,0));
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 select * into prior from collect_receipt_operations.enrollment_workflow_requests where request_id=p_request_id;
 if prior.request_id is not null then
  if prior.actor_id<>auth.uid()or prior.action<>'enroll'or prior.input is distinct from input
   or prior.request_expires_at<>p_request_expires_at then raise exception 'operations_enrollment_request_conflict'using errcode='22023';end if;
  return prior.result;
 end if;
 if exists(select 1 from collect_receipt_operations.owner_requests where request_id=p_request_id)
  or exists(select 1 from collect_supervisor.owner_requests where request_id=p_request_id)
  then raise exception 'operations_enrollment_legacy_request_conflict'using errcode='22023';end if;
 legacy:=public.admin_enroll_receipt_operations_identity_v2(p_request_id,p_public_key_spki_base64,p_key_sha256,p_identity_expires_at);
 select * into item from collect_supervisor.identities where id=(legacy->>'principal_id')::uuid for share;
 sid:=collect_supervisor.owner_actor();t:=clock_timestamp();
 if p_request_expires_at<=t or p_request_expires_at>t+interval '120 seconds'then raise exception 'operations_enrollment_request_expired'using errcode='55000';end if;
 if item.id is null or item.enrollment_request_id<>p_request_id or item.owner_actor_id<>auth.uid()
  or item.key_sha256<>p_key_sha256 or item.expires_at<>p_identity_expires_at or item.scope<>'rw_receipt_operations'
  or item.state<>'pending'or item.expires_at<=t then raise exception 'operations_enrollment_binding_invalid'using errcode='55000';end if;
 result:=jsonb_build_object('contract_version',3,'action','enroll','request_id',p_request_id,'principal_id',item.id,
  'state_at_action','pending','scope','rw_receipt_operations','key_sha256',item.key_sha256,
  'identity_expires_at',collect_gateway.utc(item.expires_at),'recorded_at',collect_gateway.utc(t),
  'request_expires_at',collect_gateway.utc(p_request_expires_at));
 insert into collect_receipt_operations.enrollment_workflow_requests values(p_request_id,auth.uid(),sid,'enroll',input,p_request_expires_at,result,t);
 return result;end$$;


ALTER FUNCTION public.admin_enroll_receipt_operations_identity_v3(p_request_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_identity_expires_at timestamp with time zone, p_request_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: admin_enroll_receipt_supervisor_v1(uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_enroll_receipt_supervisor_v1(p_request_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;prior jsonb;input jsonb;result jsonb;principal uuid;t timestamptz;begin
 sid:=collect_supervisor.owner_actor();
 if p_request_id is null or p_expires_at is null or not isfinite(p_expires_at)then
  raise exception 'supervisor_enrollment_invalid'using errcode='22023';end if;
 perform collect_supervisor.validate_key(p_public_key_spki_base64,p_key_sha256);
 input:=jsonb_build_array(p_public_key_spki_base64,p_key_sha256,p_expires_at);
 perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request_id::text,0));
 prior:=collect_supervisor.owner_replay(p_request_id,auth.uid(),'enroll',input);
 if prior is not null then return prior;end if;
 t:=clock_timestamp();
 if p_expires_at<t+interval '10 minutes'or p_expires_at>t+interval '30 days'
  or exists(select 1 from collect_gateway.devices where key_sha256=p_key_sha256)then
  raise exception 'supervisor_enrollment_invalid'using errcode='22023';end if;
 insert into collect_supervisor.identities(enrollment_request_id,owner_actor_id,owner_session_id,
  public_key_spki_base64,key_sha256,created_at,expires_at)
 values(p_request_id,auth.uid(),sid,p_public_key_spki_base64,p_key_sha256,t,p_expires_at)returning identities.id into principal;
 result:=jsonb_build_object('contract_version',1,'principal_id',principal,'request_id',p_request_id,
  'state_at_action','pending','scope','rw_receipt_shadow','key_sha256',p_key_sha256,
  'expires_at',collect_gateway.utc(p_expires_at),'recorded_at',collect_gateway.utc(t));
 insert into collect_supervisor.owner_requests values(p_request_id,auth.uid(),sid,'enroll',input,result,t);
 perform public.create_audit_log('supervisor.identity.enroll','receipt_supervisor',principal,
  jsonb_build_object('request_id',p_request_id,'scope','rw_receipt_shadow','expires_at',p_expires_at),null);
 return result;
end$$;


ALTER FUNCTION public.admin_enroll_receipt_supervisor_v1(p_request_id uuid, p_public_key_spki_base64 text, p_key_sha256 text, p_expires_at timestamp with time zone) OWNER TO postgres;

