--
-- Name: admin_get_collect_investigation_v1(text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_collect_investigation_v1(p_kind text, p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare payment_access boolean; receipt_access boolean; result jsonb; checked timestamptz;
begin
 if p_kind is null or p_kind not in ('transaction','receipt') or p_id is null then
  raise exception 'investigation_target_invalid' using errcode='22023';end if;
 payment_access:=collect_security.transaction_read_authority('payments.read');
 receipt_access:=collect_security.transaction_read_authority('notifications.read');
 if (p_kind='transaction' and not payment_access) or (p_kind='receipt' and not receipt_access) then
  raise exception 'investigation_permission_required' using errcode='42501';end if;

 -- Every section shares one statement snapshot. checked_at is captured after
 -- this read; it is measurement time, never a substituted business timestamp.
 with target as (
  select sms.id sms_id,e.id event_id,p.id payment_id,
   coalesce(p.collection_id,e.collection_id,sms.collection_id) collection_id,
   p.member_record_id,o.id outbox_id,
   collect_security.rwanda_sms_scope(sms.id) supported
  from public.raw_payment_sms sms
  left join public.parsed_payment_events e on e.raw_sms_id=sms.id
  left join public.payments p on p.parsed_event_id=e.id
  left join collect_hybrid.sms_notification_outbox o on o.payment_id=p.id
   and o.template_key='buri_munsi.payment_received'
  where p_kind='transaction' and sms.id=p_id
  union all
  select sms.id,e.id,p.id,o.collection_id,o.member_record_id,o.id,
   coalesce(collect_security.rwanda_sms_scope(sms.id),false)
  from collect_hybrid.sms_notification_outbox o
  join public.payments p on p.id=o.payment_id
  left join public.parsed_payment_events e on e.id=p.parsed_event_id
  left join public.raw_payment_sms sms on sms.id=e.raw_sms_id
  where p_kind='receipt' and o.id=p_id
 ), payment_section as (
  select jsonb_build_object(
   'payment_id',t.payment_id,'raw_sms_id',t.sms_id,'event_id',t.event_id,
   'collection_id',t.collection_id,'member_record_id',t.member_record_id,
   'lifecycle',case when t.sms_id is not null then
    collect_security.transaction_lifecycle(t.sms_id,receipt_access) else null end,
   'times',jsonb_build_object('received_at_device',sms.received_at_device,
    'ingested_at',sms.ingested_at,'parsed_recorded_at',e.created_at,
    'allocation_recorded_at',a.created_at,'provider_confirmed_at',pc.confirmed_at,
    'confirmation_recorded_at',pc.recorded_at,'rejection_occurred_at',pr.occurred_at,
    'rejection_recorded_at',pr.recorded_at,
    'payment_posted_at',case when p.status in ('posted','reversed') then p.posted_at else null end),
   'journals',coalesce((select jsonb_agg(jsonb_build_object(
    'id',j.id,'entry_type',j.entry_type,'amount_rwf',j.amount_rwf::text,'posted_at',j.posted_at,
    'snapshot',case when s.id is null then null else jsonb_build_object(
     'id',s.id,'captured_at',s.captured_at,'delta_rwf',s.delta_rwf::text,
     'member_balance_rwf',s.member_balance_after_rwf::text,
     'group_balance_rwf',s.group_balance_after_rwf::text) end)
    order by j.posted_at,j.id) from collect_hybrid.momo_journal_entries j
    left join collect_hybrid.momo_balance_snapshots s on s.journal_entry_id=j.id
    where j.payment_id=t.payment_id),'[]'::jsonb),
   'current_balances',jsonb_build_object(
    'member_rwf',mb.confirmed_rwf::text,'member_updated_at',mb.updated_at,
    'group_rwf',gb.confirmed_rwf::text,'group_updated_at',gb.updated_at)) value
  from target t left join public.raw_payment_sms sms on sms.id=t.sms_id
  left join public.parsed_payment_events e on e.id=t.event_id
  left join public.payments p on p.id=t.payment_id
  left join public.payment_allocations a on a.payment_id=t.payment_id
   and a.parsed_event_id=t.event_id
  left join public.payment_provider_confirmations pc on pc.payment_id=t.payment_id
  left join collect_hybrid.payment_provider_rejections pr on pr.payment_id=t.payment_id
  left join collect_hybrid.member_balances mb on mb.collection_id=t.collection_id
   and mb.member_record_id=t.member_record_id
  left join collect_hybrid.collection_balances gb on gb.collection_id=t.collection_id
  where payment_access and t.supported
 ), receipt_section as (
  select jsonb_build_object('id',o.id,'payment_id',o.payment_id,'snapshot_id',o.snapshot_id,
   'collection_id',o.collection_id,'member_record_id',o.member_record_id,'state',o.state,
   'template_key',o.template_key,'template_version',o.template_version,
   'created_at',o.created_at,'updated_at',o.updated_at,'observed_sent_at',o.observed_sent_at,
   'masked_destination','+250•••'||right(o.destination_e164,3),
   'amount_rwf',o.amount_rwf::text,'member_balance_rwf',o.member_balance_rwf::text,
   'group_balance_rwf',o.group_balance_rwf::text,
   'snapshot_captured_at',s.captured_at,
   'preview_source',case when s.id is not null then 'immutable_posting_snapshot' else 'snapshot_unavailable' end,
   'masked_snapshot_preview',case when s.id is not null then
    collect_receipt_policy.render_snapshot(s,o.template_version,'snapshot-'||right(s.id::text,8),collect_receipt_policy.language_for_job(o)) else null end,
   'approvals',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,
    'approved_at',c.approved_at,'expires_at',c.expires_at,'consumed_at',c.consumed_at)
    order by c.approved_at desc,c.id desc) from (select *
     from collect_hybrid.sms_notification_confirmations where outbox_id=o.id
     order by approved_at desc,id desc limit 50)c),'[]'::jsonb),
   'approval_total',(select count(*) from collect_hybrid.sms_notification_confirmations where outbox_id=o.id),
   'attempts',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,
    'attempt_number',a.attempt_number,'state',a.state,'send_started_at',a.send_started_at,
    'outcome_at',a.outcome_at) order by a.attempt_number desc) from
     (select * from collect_hybrid.sms_notification_attempts where outbox_id=o.id
      order by attempt_number desc limit 50)a),'[]'::jsonb),
   'attempt_total',(select count(*) from collect_hybrid.sms_notification_attempts where outbox_id=o.id)) value
  from target t join collect_hybrid.sms_notification_outbox o on o.id=t.outbox_id
  -- Reconstruction is allowed only from the matching immutable receipt snapshot.
  left join collect_hybrid.momo_balance_snapshots s on s.id=o.snapshot_id
   and s.payment_id=o.payment_id and s.collection_id=o.collection_id
   and s.member_record_id=o.member_record_id and s.event_type='receipt'
   and s.delta_rwf=o.amount_rwf and s.member_balance_after_rwf=o.member_balance_rwf
   and s.group_balance_after_rwf=o.group_balance_rwf
   and exists(select 1 from collect_hybrid.momo_journal_entries j
    where j.id=s.journal_entry_id and j.payment_id=o.payment_id
     and j.collection_id=o.collection_id and j.member_record_id=o.member_record_id
     and j.entry_type='receipt' and j.amount_rwf=o.amount_rwf)
  where receipt_access and t.supported
 ) select jsonb_build_object(
  'contract_version',1,'scope',case when exists(select 1 from target where supported)
   then 'rwanda_momo' else 'unclassified' end,'kind',p_kind,'target_id',p_id,'history_limit',50,
  'payment_state',case when not payment_access then 'denied'
   when not exists(select 1 from target) then 'missing'
   when not exists(select 1 from target where supported) then 'unsupported' else 'available' end,
  'payment',(select value from payment_section limit 1),
  'receipt_state',case when not receipt_access then 'denied'
   when exists(select 1 from target) and not exists(select 1 from target where supported) then 'unsupported'
   when exists(select 1 from receipt_section) then 'available' else 'missing' end,
  'receipt',(select value from receipt_section limit 1)) into result;
 checked:=clock_timestamp();
 return result||jsonb_build_object('checked_at',checked,'sample_valid_until',checked+interval '60 seconds');
end $$;


ALTER FUNCTION public.admin_get_collect_investigation_v1(p_kind text, p_id uuid) OWNER TO postgres;

--
-- Name: admin_get_collect_transaction(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_collect_transaction(p_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  rail text := split_part(coalesce(p_id, ''), ':', 1);
  record_text text := split_part(coalesce(p_id, ''), ':', 2);
  record_id uuid;
  result jsonb;
begin
  perform public.assert_admin_permission('payments.read');
  if record_text !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' then
    return '{}'::jsonb;
  end if;
  record_id := record_text::uuid;

  if rail = 'momo' then
    select jsonb_build_object(
      'id', 'momo:' || sms.id::text,
      'transaction_id', coalesce(event.transaction_id, 'Receipt ' || right(sms.body_hash, 8)),
      'payment_route', 'Rwanda MoMo USSD + receipt SMS',
      'rail', 'rw_momo',
      'raw_sms_id', sms.id,
      'sms_sender', public.collect_admin_mask_sender(sms.raw_sender),
      'parse_status', sms.parse_status,
      'sender_name', public.collect_admin_mask_name(event.sender_name),
      'network', case event.network
        when 'mtn_momo' then 'MTN MoMo'
        when 'airtel_money' then 'Airtel Money'
        else 'Unknown MoMo provider' end,
      'reference', event.transaction_id,
      'amount', case when event.amount_rwf is null then null
        else 'RWF ' || to_char(event.amount_rwf, 'FM999G999G999G999') end,
      'payee', coalesce(receiver.label, 'MoMo payee') || ' · ' ||
        coalesce(public.mask_phone(receiver.momo_number), 'number unavailable'),
      'group_name', collection.title,
      'allocation_status', coalesce(event.allocation_status::text, sms.parse_status),
      'received_at', coalesce(sms.received_at_device, sms.ingested_at),
      'created_at', sms.created_at
    ) into result
    from public.raw_payment_sms sms
    left join public.parsed_payment_events event on event.raw_sms_id = sms.id
    left join public.payments payment on payment.parsed_event_id = event.id
    left join public.collections collection
      on collection.id = coalesce(payment.collection_id, event.collection_id, sms.collection_id)
    left join lateral (
      select route.* from public.collection_receivers route
      where route.collection_id = collection.id and route.is_active
      order by route.created_at desc limit 1
    ) receiver on true
    where sms.id = record_id;
  elsif rail = 'diaspora' then
    select jsonb_build_object(
      'id', 'diaspora:' || evidence.id::text,
      'transaction_id', coalesce(bank_transaction.bank_transaction_id,
        event.transfer_reference, 'Account receipt ' || right(evidence.body_hash, 8)),
      'payment_route', 'Diaspora bank / Revolut account transfer',
      'rail', 'diaspora_account',
      'raw_bank_event_id', event.id,
      'sms_sender', public.collect_admin_mask_sender(evidence.raw_sender),
      'source', upper(evidence.channel),
      'parse_status', evidence.parse_status,
      'payer_name', public.collect_admin_mask_name(
        coalesce(bank_transaction.payer_name, event.payer_name)),
      'provider', coalesce(destination.bank_name, 'Diaspora account'),
      'reference', coalesce(bank_transaction.transfer_reference, event.transfer_reference),
      'amount', case when coalesce(bank_transaction.amount_minor, event.amount_minor) is null then null
        else coalesce(bank_transaction.currency, event.currency, 'EUR') || ' ' ||
          to_char(coalesce(bank_transaction.amount_minor, event.amount_minor)::numeric / 100,
            'FM999G999G999D00') end,
      'payee', coalesce(destination.beneficiary_name, 'Diaspora payee') || ' · ' ||
        coalesce(public.mask_iban(destination.iban), 'account unavailable'),
      'group_name', collection.title,
      'allocation_status', coalesce(event.allocation_status,
        bank_transaction.status, evidence.parse_status),
      'received_at', evidence.received_at,
      'created_at', evidence.created_at
    ) into result
    from public.raw_payment_evidence evidence
    left join public.bank_evidence_events event on event.raw_evidence_id = evidence.id
    left join public.payment_evidence_links evidence_link
      on evidence_link.evidence_event_id = event.id
    left join public.bank_transactions bank_transaction
      on bank_transaction.id = evidence_link.bank_transaction_id
    left join public.bank_transaction_allocations allocation
      on allocation.bank_transaction_id = bank_transaction.id
    left join public.collections collection on collection.id = allocation.collection_id
    left join public.bank_transfer_destinations destination
      on destination.id = bank_transaction.destination_id
    where evidence.id = record_id;
  else
    return '{}'::jsonb;
  end if;
  return coalesce(result, '{}'::jsonb);
end;
$_$;


ALTER FUNCTION public.admin_get_collect_transaction(p_id text) OWNER TO postgres;

--
-- Name: admin_get_collection(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_collection(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
 perform public.assert_admin_permission('collections.read');
 return coalesce((select jsonb_build_object(
  'id',collection.id,'slug',collection.slug,'title',collection.title,'description',collection.description,
  'creator_user_id',collection.creator_user_id,'creator_label','Collect ID '||profile.public_id,
  'collection_type',collection.collection_type,'category_subtype',collection.category_subtype,'purpose_label',collection.purpose_label,
  'receiver_display_label',receiver.label,'receiver_momo_code',receiver.momo_number,'receiver_network',receiver.network,
  'is_platform_sponsored',collection.is_platform_sponsored,'visibility',collection.visibility,'public_status',collection.public_status,
  'status',case when collection.archived_at is not null then 'archived' else collection.public_status::text end,
  'creation_origin',collection.creation_origin,'archived_at',collection.archived_at,'currency',collection.currency,'diaspora_enabled',collection.diaspora_enabled,
  'active_receivers',(select count(*) from public.collection_receivers route where route.collection_id=collection.id and route.is_active),
  'active_members',(select count(*) from public.collection_members member where member.collection_id=collection.id and member.status='active'),
  'pending_payment_intents',(select count(*) from public.payment_intents intent where intent.collection_id=collection.id and intent.status='pending'),
  'created_at',collection.created_at,'updated_at',collection.updated_at)
 from public.collections collection left join public.profiles profile on profile.id=collection.creator_user_id
 left join lateral (select route.label,route.momo_number,route.network from public.collection_receivers route
  where route.collection_id=collection.id and route.is_active order by route.created_at limit 1) receiver on true
 where collection.id=p_id),'{}'::jsonb);
end $$;


ALTER FUNCTION public.admin_get_collection(p_id uuid) OWNER TO postgres;

--
-- Name: admin_get_exception_entity_audit_v2(uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_exception_entity_audit_v2(p_exception_id uuid, p_limit integer DEFAULT 20, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare sample timestamptz;result jsonb;begin
 perform collect_operator_audit.exception_actor_v2(true);
 if p_exception_id is null or p_limit is null or p_limit not between 1 and 25
  or(p_before_at is null)is distinct from(p_before_event_id is null)
  or(p_before_at is not null and(not isfinite(p_before_at)
   or p_before_at<'0001-01-01T00:00:00Z'::timestamptz
   or p_before_at>='10000-01-01T00:00:00Z'::timestamptz))then
  raise exception 'exception_audit_input_invalid'using errcode='22023';end if;
 sample:=clock_timestamp();
 with scope as materialized(select exists(select 1 from collect_ops.exceptions e where e.id=p_exception_id
  and collect_operator_audit.exception_scope_v2(e.source_kind,e.source_id))available),
 events as not materialized(
  (select collect_operator_audit.exception_event_id('exception_action',r.request_id)event_id,
   'exception_action'::text source,r.request_id source_record_id,'exception.'||r.action action,r.recorded_at,
   'operator'::text actor_kind,r.actor_id,r.request_id,r.expected_revision revision,null::bigint workflow_revision,
   null::uuid escalation_id,r.reason_code,'immutable_request'::text origin,null::uuid assignee_id,null::timestamptz due_at
   from collect_ops.exception_actions r where r.exception_id=p_exception_id
    and r.recorded_at>='0001-01-01T00:00:00Z'::timestamptz and r.recorded_at<=sample
    and(p_before_at is null or(r.recorded_at,collect_operator_audit.exception_event_id('exception_action',r.request_id))<(p_before_at,p_before_event_id))
   order by r.recorded_at desc,collect_operator_audit.exception_event_id('exception_action',r.request_id)desc limit p_limit+1)
  union all (select collect_operator_audit.exception_event_id('exception_workflow_request',r.request_id),
   'exception_workflow_request',r.request_id,'exception.workflow.'||r.action,r.recorded_at,'operator',r.actor_id,r.request_id,
   r.expected_source_revision,(r.result->>'workflow_revision')::bigint,
   case when r.action='escalate'then collect_operator_audit.safe_uuid(r.result->>'escalation_id')end,r.reason_code,
   'immutable_request',case when r.action='assign'then r.assignee_id end,case when r.action='assign'then r.due_at end
   from collect_ops.exception_workflow_requests r where r.exception_id=p_exception_id
    and r.recorded_at>='0001-01-01T00:00:00Z'::timestamptz and r.recorded_at<=sample
    and(p_before_at is null or(r.recorded_at,collect_operator_audit.exception_event_id('exception_workflow_request',r.request_id))<(p_before_at,p_before_event_id))
   order by r.recorded_at desc,collect_operator_audit.exception_event_id('exception_workflow_request',r.request_id)desc limit p_limit+1)
  union all (select collect_operator_audit.exception_event_id('exception_escalation_event',r.id),
   'exception_escalation_event',r.id,'exception.escalation.'||r.action,r.recorded_at,r.actor_kind,r.actor_id,null::uuid,
   r.source_revision,null::bigint,r.escalation_id,e.reason_code,r.origin,null::uuid,null::timestamptz
   from collect_ops.exception_escalation_events r join collect_ops.exception_escalations e on e.id=r.escalation_id
   where r.exception_id=p_exception_id
    and r.recorded_at>='0001-01-01T00:00:00Z'::timestamptz and r.recorded_at<=sample
    and(p_before_at is null or(r.recorded_at,collect_operator_audit.exception_event_id('exception_escalation_event',r.id))<(p_before_at,p_before_event_id))
   order by r.recorded_at desc,collect_operator_audit.exception_event_id('exception_escalation_event',r.id)desc limit p_limit+1)
 ),page as materialized(select * from events where(select available from scope)
  and recorded_at>='0001-01-01T00:00:00Z'::timestamptz and recorded_at<=sample
  and(p_before_at is null or(recorded_at,event_id)<(p_before_at,p_before_event_id))
  order by recorded_at desc,event_id desc limit p_limit+1),
 shown as materialized(select * from page order by recorded_at desc,event_id desc limit p_limit)
 select jsonb_build_object('contract_version',2,'scope','rw_operator_entity_audit','entity_kind','exception',
  'entity_id',p_exception_id,'status',case when(select available from scope)then 'available'else 'unavailable'end,
  'checked_at',collect_ops.utc(sample),'sample_valid_until',collect_ops.utc(sample+interval '60 seconds'),
  'limit',p_limit,'history_complete',false,'financial_action',false,'send_action',false,
  'rows',coalesce((select jsonb_agg(jsonb_build_object('event_id',event_id,'source',source,
   'source_record_id',source_record_id,'action',action,'recorded_at',collect_ops.utc(recorded_at),
   'actor_kind',actor_kind,'actor_id',actor_id,'request_id',request_id,'revision',revision,
   'workflow_revision',workflow_revision,'escalation_id',escalation_id,'reason_code',reason_code,
   'origin',origin,'assignee_id',assignee_id,'due_at',collect_ops.utc(due_at))order by recorded_at desc,event_id desc)from shown),'[]'::jsonb),
  'next_cursor',case when(select count(*)from page)>p_limit then
   (select jsonb_build_object('recorded_at',collect_ops.utc(recorded_at),'event_id',event_id)
    from shown order by recorded_at,event_id limit 1)else null end)into result;
 perform collect_operator_audit.exception_actor_v2(true);
 return result;
exception when lock_not_available then raise exception 'exception_audit_authority_busy'using errcode='55P03';end$$;


ALTER FUNCTION public.admin_get_exception_entity_audit_v2(p_exception_id uuid, p_limit integer, p_before_at timestamp with time zone, p_before_event_id uuid) OWNER TO postgres;

--
-- Name: admin_get_exception_workflow_request_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_exception_workflow_request_v1(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare prior collect_ops.exception_workflow_requests;acquired boolean;at timestamptz;begin
 perform collect_ops.actor(false);
 if p_request_id is null then raise exception 'exception_workflow_input_invalid'using errcode='22023';end if;
 acquired:=pg_try_advisory_xact_lock(hashtextextended('collect-ops-workflow-request:'||p_request_id::text,0));
 select * into prior from collect_ops.exception_workflow_requests where acquired and request_id=p_request_id and actor_id=auth.uid();
 at:=clock_timestamp();return jsonb_build_object('contract_version',1,'request_id',p_request_id,
  'checked_at',collect_ops.utc(at),'sample_valid_until',collect_ops.utc(at+interval '60 seconds'),
  'status',case when not acquired then 'in_progress'when prior.request_id is null then 'not_recorded'else 'recorded'end,'receipt',prior.result);
end$$;


ALTER FUNCTION public.admin_get_exception_workflow_request_v1(p_request_id uuid) OWNER TO postgres;

--
-- Name: admin_get_exception_workflow_request_v2(uuid, text, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_exception_workflow_request_v2(p_request_id uuid, p_request_fingerprint text, p_expires_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $_$
declare prior collect_ops.exception_workflow_requests;acquired boolean;at timestamptz;
 fingerprint text;receipt jsonb;
begin
 perform collect_ops.followup_v2_actor(false);
 if p_request_id is null or p_request_fingerprint is null or p_request_fingerprint!~'^[0-9a-f]{64}$'
  or p_expires_at is null or not isfinite(p_expires_at)
  or p_expires_at<'0001-01-01T00:00:00Z'::timestamptz
  or p_expires_at>='10000-01-01T00:00:00Z'::timestamptz then
  raise exception 'exception_followup_lookup_input_invalid' using errcode='22023';
 end if;
 acquired:=pg_try_advisory_xact_lock(hashtextextended('collect-ops-workflow-request:'||p_request_id::text,0));
 select * into prior from collect_ops.exception_workflow_requests
  where acquired and request_id=p_request_id and actor_id=auth.uid();
 if prior.request_id is not null then
  fingerprint:=collect_ops.followup_v2_fingerprint(prior.request_id,prior.exception_id,
   prior.expected_source_revision,prior.expected_workflow_revision,prior.action,
   prior.assignee_id,prior.due_at,prior.reason_code,prior.expires_at);
  if fingerprint is distinct from p_request_fingerprint or prior.expires_at is distinct from p_expires_at then
   raise exception 'exception_followup_request_conflict' using errcode='22023';
  end if;
  receipt:=prior.result||jsonb_build_object('contract_version',2,'request_fingerprint',fingerprint);
 end if;
 perform collect_ops.followup_v2_actor(false);
 at:=clock_timestamp();
 return jsonb_build_object('contract_version',2,'request_id',p_request_id,
  'request_fingerprint',p_request_fingerprint,'expires_at',collect_ops.utc(p_expires_at),
  'checked_at',collect_ops.utc(at),'sample_valid_until',collect_ops.utc(at+interval '60 seconds'),
  'status',case when not acquired then 'in_progress' when prior.request_id is null then 'not_recorded' else 'recorded' end,
  'receipt',receipt);
exception when lock_not_available then
 raise exception 'exception_followup_authority_busy' using errcode='55P03';
end $_$;


ALTER FUNCTION public.admin_get_exception_workflow_request_v2(p_request_id uuid, p_request_fingerprint text, p_expires_at timestamp with time zone) OWNER TO postgres;

--
-- Name: admin_get_exception_workflow_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_exception_workflow_v1(p_exception_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare at timestamptz;result jsonb;begin
 perform collect_ops.actor(false);
 if p_exception_id is null then raise exception 'exception_workflow_input_invalid'using errcode='22023';end if;
 at:=clock_timestamp();result:=collect_ops.workflow_projection(p_exception_id);
 if result is null then raise exception 'exception_workflow_unavailable'using errcode='22023';end if;
 return result||jsonb_build_object('checked_at',collect_ops.utc(at),'sample_valid_until',collect_ops.utc(at+interval '60 seconds'));
end$$;


ALTER FUNCTION public.admin_get_exception_workflow_v1(p_exception_id uuid) OWNER TO postgres;

--
-- Name: admin_get_gateway_owner_request_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_gateway_owner_request_v1(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare actor uuid;result jsonb;
begin
 actor:=collect_gateway.read_actor();
 if p_request_id is null then raise exception 'gateway_owner_request_invalid' using errcode='22023';end if;
 -- Original-actor reconciliation only. An absent or other-actor request is
 -- unknown, never an instruction to retry an uncertain mutation. Identity
 -- fields are public immutable pairing data; original key bytes stay private.
 with read_time as materialized(select clock_timestamp() checked_at),
 evidence as materialized(
  select r.action,r.result,d.* from collect_gateway.admin_requests r
  join collect_gateway.devices d on r.result->>'device_id'=d.id::text
  where r.request_id=p_request_id and r.actor_id=actor
 )
 select jsonb_build_object('contract_version',1,'scope','platform_global',
  'checked_at',collect_gateway.utc(t.checked_at),
  'sample_valid_until',collect_gateway.utc(t.checked_at+interval '60 seconds'),
  'request_id',p_request_id,'outcome',case when e.id is null then 'unknown' else 'recorded' end,
  'action',e.action,'receipt',case when e.id is null then null else collect_gateway.public_owner_receipt(e.result) end,
  'identity',case when e.id is null then null else
   jsonb_build_object('device_id',e.id,'installation_id',e.installation_id,
    'key_sha256',e.key_sha256,'signing_certificate_sha256',e.signing_certificate_sha256) end)
 into result from read_time t left join evidence e on true;
 return result;
end$$;


ALTER FUNCTION public.admin_get_gateway_owner_request_v1(p_request_id uuid) OWNER TO postgres;

--
-- Name: admin_get_gateway_receipt_attempt_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_gateway_receipt_attempt_v2(p_receipt_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare sid uuid;a collect_gateway_dispatch.attempts;o collect_hybrid.sms_notification_outbox;t timestamptz;data jsonb;begin
 perform collect_gateway.read_actor();
 if p_receipt_id is null then raise exception 'gateway_receipt_id_invalid'using errcode='22023';end if;
 select * into o from collect_hybrid.sms_notification_outbox where id=p_receipt_id for share;
 if o.id is null or not collect_receipt_actions.rwanda_source(o)then raise exception 'gateway_receipt_unavailable'using errcode='42501';end if;
 select * into a from collect_gateway_dispatch.attempts where outbox_id=o.id;t:=clock_timestamp();
 if a.id is not null then data:=collect_gateway_dispatch.status(a.id)||jsonb_build_object('device_id',a.device_id,'run_id',a.run_id,'policy_revision',a.policy_revision,'issued_at',collect_gateway.utc(a.issued_at),'expires_at',collect_gateway.utc(a.expires_at));end if;
 return jsonb_build_object('contract_version',2,'receipt_id',p_receipt_id,'checked_at',collect_gateway.utc(t),'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'),'automatic_attempt',data);
end$$;


ALTER FUNCTION public.admin_get_gateway_receipt_attempt_v2(p_receipt_id uuid) OWNER TO postgres;

--
-- Name: admin_get_gateway_receipt_investigation_v3(uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_gateway_receipt_investigation_v3(p_receipt_id uuid, p_limit integer DEFAULT 20, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_request_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t timestamptz;answer jsonb;
begin
 perform collect_gateway.read_actor();
 t:=clock_timestamp();
 if p_receipt_id is null or p_limit is null or p_limit not between 1 and 25
  or (p_before_at is null)<>(p_before_request_id is null)
  or p_before_at is not null and not isfinite(p_before_at) then
  raise exception 'gateway_investigation_input_invalid' using errcode='22023';end if;
 -- All evidence below is read in one statement snapshot. Framework callbacks
 -- and archival recording never establish carrier delivery or send authority.
 with source as materialized (
  select o.* from collect_hybrid.sms_notification_outbox o
  where o.id=p_receipt_id and collect_receipt_actions.rwanda_source(o)
 ), attempt as materialized (
  select a.* from collect_gateway_dispatch.attempts a join source o on o.id=a.outbox_id
 ), arm as materialized (
  select r.* from collect_gateway_dispatch.arms r join attempt a on a.id=r.attempt_id
 ), bindings as materialized (
  select b.callback_id,b.segment_index,b.callback_kind,
   first_value.request_id is not null as has_observation,
   first_value.request_id is not null and
    (first_value.result_code,coalesce(first_value.tp_status,-1))=
    (last_value.result_code,coalesce(last_value.tp_status,-1)) as consistent,
   first_value.result_code,first_value.tp_status
  from collect_gateway_dispatch.callback_bindings b join attempt a on a.id=b.attempt_id
  left join lateral (
   select c.request_id,c.result_code,c.tp_status from collect_gateway_dispatch.callbacks c
   where c.attempt_id=b.attempt_id and c.callback_id=b.callback_id
   order by c.result_code,coalesce(c.tp_status,-1) limit 1
  ) first_value on true
  left join lateral (
   select c.result_code,c.tp_status from collect_gateway_dispatch.callbacks c
   where c.attempt_id=b.attempt_id and c.callback_id=b.callback_id
   order by c.result_code desc,coalesce(c.tp_status,-1) desc limit 1
  ) last_value on true
 ), ack as materialized (
  select k.* from collect_gateway_archive.acknowledgements k join attempt a on a.id=k.attempt_id
 ), dispatch_history as materialized (
  select r.request_id,r.recorded_at,r.action,
   case when r.action='dispatch_grant' then 'grant' else 'arm' end as source,
   r.result->>'code' as code,null::uuid as callback_id,null::integer as segment_index,
   null::text as callback_kind,null::integer as result_code,null::integer as tp_status,
   null::timestamptz as occurred_at
  from collect_gateway_dispatch.requests r join attempt a on
   r.request_id=a.grant_request_id or r.request_id=(select request_id from arm)
  where p_before_at is null or (r.recorded_at,r.request_id)<(p_before_at,p_before_request_id)
  order by r.recorded_at desc,r.request_id desc limit p_limit+1
 ), callback_history as materialized (
  select c.request_id,c.recorded_at,'callback'::text as action,'callback'::text as source,
   null::text as code,c.callback_id,c.segment_index,c.callback_kind,c.result_code,c.tp_status,c.occurred_at
  from attempt a cross join lateral (
   select c.* from collect_gateway_dispatch.callbacks c where c.attempt_id=a.id
    and (p_before_at is null or (c.recorded_at,c.request_id)<(p_before_at,p_before_request_id))
   order by c.recorded_at desc,c.request_id desc limit p_limit+1
  ) c
 ), archive_history as materialized (
  select r.request_id,r.recorded_at,'archive_attempt'::text as action,'archive'::text as source,
   r.result->>'code' as code,null::uuid as callback_id,null::integer as segment_index,
   null::text as callback_kind,null::integer as result_code,null::integer as tp_status,
   null::timestamptz as occurred_at
  from attempt a cross join lateral (
   select r.* from collect_gateway_archive.requests r where r.payload->>'attempt_id'=a.id::text
    and (p_before_at is null or (r.recorded_at,r.request_id)<(p_before_at,p_before_request_id))
   order by r.recorded_at desc,r.request_id desc limit p_limit+1
  ) r
 ), bounded_history as materialized (
  select * from (
   select * from dispatch_history union all select * from callback_history union all select * from archive_history
  ) h order by recorded_at desc,request_id desc limit p_limit+1
 ), page as materialized (
  select * from bounded_history order by recorded_at desc,request_id desc limit p_limit
 )
 select jsonb_build_object('contract_version',3,'scope','rw_automatic_gateway_evidence',
  'receipt_id',p_receipt_id,
  'status',case when not exists(select 1 from source) then 'unavailable'
   when not exists(select 1 from attempt) then 'no_automatic_attempt' else 'available' end,
  'checked_at',collect_gateway.utc(t),'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'),
  'limit',p_limit,'attempt',(select collect_gateway_dispatch.admin_attempt_projection(a) from attempt a),
  'arm',(select jsonb_build_object('request_id',r.request_id,'health_observation_id',r.health_observation_id,
   'armed_at',collect_gateway.utc(r.armed_at),'expires_at',collect_gateway.utc(r.expires_at)) from arm r),
  'expected_callbacks',coalesce((select jsonb_agg(jsonb_build_object('callback_id',b.callback_id,
   'segment_index',b.segment_index,'callback_kind',b.callback_kind,'has_observation',b.has_observation,
   'consistent',b.consistent,'result_code',b.result_code,'tp_status',b.tp_status)
   order by b.segment_index,b.callback_kind) from bindings b),'[]'::jsonb),
  'archive_ack',(select jsonb_build_object('acknowledgement_id',k.id,'request_id',k.request_id,
   'recorded_at',collect_gateway.utc(k.recorded_at),'evidence_kind','complete_framework_callback_observations') from ack k),
  'history_complete',false,
  'rows',coalesce((select jsonb_agg(jsonb_build_object('request_id',h.request_id,'source',h.source,
   'action',h.action,'recorded_at',collect_gateway.utc(h.recorded_at),'code',h.code,
   'callback_id',h.callback_id,'segment_index',h.segment_index,'callback_kind',h.callback_kind,
   'result_code',h.result_code,'tp_status',h.tp_status,
   'occurred_at',case when h.occurred_at is not null then collect_gateway.utc(h.occurred_at) end)
   order by h.recorded_at desc,h.request_id desc) from page h),'[]'::jsonb),
  'next_cursor',case when (select count(*) from bounded_history)>p_limit then
   (select jsonb_build_object('recorded_at',collect_gateway.utc(h.recorded_at),'request_id',h.request_id)
    from page h order by h.recorded_at,h.request_id limit 1) else null end,
  'carrier_proof',false,'delivery_proven',false,'send_authority',false) into answer;
 perform collect_gateway.read_actor();
 if clock_timestamp()>=t+interval '60 seconds' then
  raise exception 'gateway_investigation_sample_expired' using errcode='55000';end if;
 return answer;
end$$;


ALTER FUNCTION public.admin_get_gateway_receipt_investigation_v3(p_receipt_id uuid, p_limit integer, p_before_at timestamp with time zone, p_before_request_id uuid) OWNER TO postgres;

--
-- Name: admin_get_hybrid_sms_receipt(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_hybrid_sms_receipt(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.assert_admin_permission('notifications.read');
  return coalesce((
    select jsonb_build_object(
      'id', outbox.id,
      'state', outbox.state,
      'channel', 'Assisted SMS operator',
      'member_collect_id', member.collect_id,
      'collection_id', outbox.collection_id,
      'collection_title', collection.title,
      'destination_masked', left(outbox.destination_e164, 4) || '•••'
        || right(outbox.destination_e164, 3),
      'amount_rwf', outbox.amount_rwf,
      'member_balance_rwf', outbox.member_balance_rwf,
      'group_balance_rwf', outbox.group_balance_rwf,
      'reference', outbox.reference,
      'template_key', outbox.template_key,
      'template_version', outbox.template_version,
      'consent_revision', outbox.consent_revision,
      'authorization_current',
        collect_hybrid.sms_receipt_job_is_current(outbox.id),
      'body_sha256', outbox.body_sha256,
      'message_body', 'Hidden until a current fenced operator claim',
      'attempt_count', outbox.attempt_count,
      'claim_expires_at', outbox.claim_expires_at,
      'suppression_reason', outbox.suppression_reason,
      'created_at', outbox.created_at,
      'observed_sent_at', outbox.observed_sent_at,
      'latest_attempt_state', (
        select attempt.state
        from collect_hybrid.sms_notification_attempts attempt
        where attempt.outbox_id = outbox.id
        order by attempt.attempt_number desc
        limit 1
      ),
      'delivery_claim',
        'Observed sent is operator-recorded UI evidence, not handset delivery'
    )
    from collect_hybrid.sms_notification_outbox outbox
    join public.collections collection on collection.id = outbox.collection_id
    join collect_hybrid.member_records member on member.id = outbox.member_record_id
    where outbox.id = p_id
  ), '{}'::jsonb);
end;
$$;


ALTER FUNCTION public.admin_get_hybrid_sms_receipt(p_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION admin_get_hybrid_sms_receipt(p_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.admin_get_hybrid_sms_receipt(p_id uuid) IS 'Admin-safe SMS receipt metadata; exact destination and body remain available only through a current fenced operator claim.';


--
-- Name: admin_get_interrupted_roster_commit_status(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_interrupted_roster_commit_status(p_import_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; c collect_hybrid.roster_import_commits; begin
 sid:=collect_hybrid.require_roster_caller();
 select * into s from collect_hybrid.roster_import_sources where id=p_import_id;
 if s.id is null or s.actor_id<>auth.uid() then raise exception 'roster_import_unavailable' using errcode='42501'; end if;
 select * into c from collect_hybrid.roster_import_commits where import_id=s.id;
 -- Current authority permits only reading an immutable outcome, no old editor.
 return jsonb_build_object('contract_version',1,'ok',true,'import_id',s.id,'state',case when c.request_id is null then 'missing' else 'committed' end,
  'commit',c.response);
end $$;


ALTER FUNCTION public.admin_get_interrupted_roster_commit_status(p_import_id uuid) OWNER TO postgres;

--
-- Name: admin_get_journal_entry(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_journal_entry(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('bank_reconciliation.read');
  select to_jsonb(entry) || jsonb_build_object(
    'lines', coalesce((select jsonb_agg(to_jsonb(line) order by line.direction, line.account_code)
      from public.journal_lines line where line.journal_entry_id = entry.id), '[]'::jsonb),
    'balanced', coalesce((select sum(case when line.direction = 'debit' then line.amount_minor else -line.amount_minor end)
      from public.journal_lines line where line.journal_entry_id = entry.id), 1) = 0
  ) into result from public.journal_entries entry where entry.id = p_id;
  return coalesce(result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION public.admin_get_journal_entry(p_id uuid) OWNER TO postgres;

--
-- Name: admin_get_member_record(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_member_record(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public.assert_admin_permission('users.read');
  return coalesce((
    select jsonb_build_object(
      'id', member.id,
      'collect_id', member.collect_id,
      'member_name', coalesce(identity.member_name, profile.display_name),
      'momo_registered_name', identity.momo_name,
      'momo_masked', public.mask_phone(identity.momo_number),
      'whatsapp_masked', case when profile.id is null then null
        else public.mask_phone(profile.whatsapp_phone) end,
      'account_state', case
        when member.linked_user_id is not null then 'app'
        when claim.user_id is not null then 'app_claimed'
        else 'feature_phone'
      end,
      'origin', member.origin,
      'lifecycle', member.lifecycle,
      'active_groups', (
        select count(distinct membership.collection_id)
        from public.collection_members membership
        join public.collections collection
          on collection.id = membership.collection_id
        where membership.member_record_id = member.id
          and membership.status = 'active'
          and collection.archived_at is null
      ),
      'created_at', member.created_at
    )
    from collect_hybrid.member_records member
    left join collect_hybrid.member_account_claims claim
      on claim.member_record_id = member.id and claim.user_id is not null
    left join public.profiles profile
      on profile.id = coalesce(member.linked_user_id, claim.user_id)
    left join collect_hybrid.member_momo_identities identity
      on identity.member_id = member.id
    where member.id = p_id
  ), '{}'::jsonb);
end;
$$;


ALTER FUNCTION public.admin_get_member_record(p_id uuid) OWNER TO postgres;

--
-- Name: FUNCTION admin_get_member_record(p_id uuid); Type: COMMENT; Schema: public; Owner: postgres
--

COMMENT ON FUNCTION public.admin_get_member_record(p_id uuid) IS 'Authorized combined app/feature-phone member detail. MoMo and WhatsApp numbers are masked; raw receipt evidence remains separately controlled.';


--
-- Name: admin_get_notification(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_notification(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform public._lock_notification_session_gate();
  perform public.assert_admin_permission('notifications.read');
  return coalesce((
    select jsonb_build_object(
      'id', event.id,
      'type', event.type,
      'title', event.title,
      'status', event.status,
      'collect_id', profile.public_id,
      'collection_id', event.collection_id,
      'deep_link', event.deep_link,
      'delivery_statuses', coalesce((
        select string_agg(count_rows.status || ': ' || count_rows.delivery_count::text, ', ' order by count_rows.status)
        from (
          select status, count(*) as delivery_count
          from public.notification_deliveries
          where event_id = event.id
          group by status
        ) count_rows
      ), 'No registered delivery'),
      'retryable_count', (
        select count(*)
        from public.notification_deliveries delivery
        join public.notification_device_tokens device on device.id = delivery.device_id
        where delivery.event_id = event.id
          and delivery.status = 'failed'
          and public._notification_session_is_live(device.registration_session_id,device.user_id)
          and device.enabled
          and device.user_id = event.user_id
          and device.provider in ('apns', 'fcm')
          and device.token is not null
          and (delivery.claim_expires_at is null
            or delivery.claim_expires_at <= clock_timestamp())
      ),
      'cumulative_attempt_count', coalesce((
        select sum(delivery.prior_attempt_count + delivery.attempt_count)
        from public.notification_deliveries delivery
        where delivery.event_id = event.id
      ), 0),
      'last_error_code', event.last_error_code,
      'created_at', event.created_at,
      'sent_at', event.sent_at,
      'read_at', event.read_at
    )
    from public.notification_events event
    join public.profiles profile on profile.id = event.user_id
    where event.id = p_id
  ), '{}'::jsonb);
end;
$$;


ALTER FUNCTION public.admin_get_notification(p_id uuid) OWNER TO postgres;

--
-- Name: admin_get_operational_exception_action_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_operational_exception_action_v1(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare prior collect_ops.exception_actions;
begin
 perform collect_ops.actor(false);
 if p_request_id is null then raise exception 'operational_exception_action_invalid' using errcode='22023';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('collect-ops-action:'||p_request_id::text,0))then
  return jsonb_build_object('contract_version',1,'request_id',p_request_id,'status','in_progress','receipt',null);end if;
 select * into prior from collect_ops.exception_actions where request_id=p_request_id and actor_id=auth.uid();
 return jsonb_build_object('contract_version',1,'request_id',p_request_id,
  'status',case when prior.request_id is null then 'not_recorded' else 'recorded' end,'receipt',prior.result);
end$$;


ALTER FUNCTION public.admin_get_operational_exception_action_v1(p_request_id uuid) OWNER TO postgres;

--
-- Name: admin_get_operational_exception_action_v2(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_operational_exception_action_v2(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare result jsonb;acquired boolean;
begin
 -- The original action holds the roster authority lock until commit. Timeout
 -- means current authority could not be established, without outcome leakage.
 perform collect_ops.actor(false);
 if p_request_id is null then raise exception 'operational_exception_action_invalid' using errcode='22023';end if;
 acquired:=pg_try_advisory_xact_lock(hashtextextended('collect-ops-action:'||p_request_id::text,0));
 with sample as materialized(select clock_timestamp() at),
 prior as materialized(select a.* from collect_ops.exception_actions a
  where acquired and a.request_id=p_request_id and a.actor_id=auth.uid())
 select jsonb_build_object('contract_version',2,'scope','platform_global',
  'checked_at',collect_ops.utc(sample.at),'sample_valid_until',collect_ops.utc(sample.at+interval '60 seconds'),
  'request_id',p_request_id,'status',case when not acquired then 'in_progress'
   when exists(select 1 from prior)then 'recorded'else 'not_recorded'end,
  'receipt',(select collect_ops.public_action_receipt(p)from prior p))
 into result from sample;
 return result;
exception when lock_not_available then
 raise exception 'operational_exception_authority_busy' using errcode='55P03';
end$$;


ALTER FUNCTION public.admin_get_operational_exception_action_v2(p_request_id uuid) OWNER TO postgres;

--
-- Name: admin_get_operator_approval_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_operator_approval_v1(p_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid;target auth.users;e collect_admin_access.email_approvals;w collect_admin_access.whatsapp_approvals;
 state jsonb;provider text;status_value text;mode_value text;masked text;
begin
 sid:=public._lock_notification_registration_session();
 perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,'platform_owner',array['admin_users.read']);
 select * into target from auth.users where id=p_user_id for share;
 if target.id is null or not exists(select 1 from public.profiles where id=p_user_id) then
  raise exception 'operator_account_unavailable' using errcode='22023';end if;
 select * into e from collect_admin_access.email_approvals where user_id=p_user_id for share;
 select * into w from collect_admin_access.whatsapp_approvals where user_id=p_user_id for share;
 select mode into mode_value from collect_admin_access.operator_auth_policy where id;
 state:=collect_admin_access.account_state(p_user_id);status_value:=state->>'status';
 if e.user_id is not null or (w.user_id is null and nullif(btrim(target.email),'') is not null) then
  provider:='email';
  masked:=case when nullif(btrim(target.email),'') is not null then left(lower(btrim(target.email)),1)||'***@***' end;
  if e.user_id is not null and e.revoked_at is null and (e.expires_at is null or e.expires_at>clock_timestamp())
   and target.email_confirmed_at is null and lower(btrim(target.email))=e.email then status_value:='pending_verification';end if;
 elsif w.user_id is not null then
  provider:='whatsapp';masked:=state->>'phone_masked';
  if mode_value='email' and status_value='identity_changed' then status_value:='legacy_disabled';end if;
 else provider:='unapproved';masked:=null;end if;
 return jsonb_build_object('contract_version',1,'user_id',p_user_id,'provider',provider,'mode',mode_value,
  'identity_masked',masked,'approved_at',state->'approved_at','expires_at',state->'expires_at',
  'status',status_value,'approved',state->'approved','role_granted',state->'role_granted',
  'admin_access',state->'admin_access','access_status',state->'access_status');
end $$;


ALTER FUNCTION public.admin_get_operator_approval_v1(p_user_id uuid) OWNER TO postgres;

--
-- Name: admin_get_operator_entity_audit_v1(text, uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_operator_entity_audit_v1(p_entity_kind text, p_entity_id uuid, p_limit integer DEFAULT 20, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_event_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare available boolean;result jsonb;sample timestamptz;begin
 perform collect_operator_audit.actor(p_entity_kind);
 if p_entity_kind is null or p_entity_kind not in('shadow_run','gateway_device','exception','supervisor_identity','receipt')
  or p_entity_id is null or p_limit is null or p_limit not between 1 and 50
  or(p_before_at is null)is distinct from(p_before_event_id is null)
  or(p_before_at is not null and not isfinite(p_before_at))then
  raise exception 'operator_audit_input_invalid'using errcode='22023';end if;
 available:=case p_entity_kind
  when 'shadow_run'then exists(select 1 from collect_security.shadow_supervisor_runs where id=p_entity_id)
  when 'gateway_device'then exists(select 1 from collect_gateway.devices where id=p_entity_id)
  when 'supervisor_identity'then exists(select 1 from collect_supervisor.identities where id=p_entity_id)
  when 'receipt'then exists(select 1 from collect_hybrid.sms_notification_outbox j
   where j.id=p_entity_id and collect_operator_audit.payment_scope(j.payment_id))
  when 'exception'then exists(select 1 from collect_ops.exceptions e where e.id=p_entity_id and
   case e.source_kind
    when 'gateway'then exists(select 1 from collect_gateway.devices d where d.id=e.source_id)
    when 'receipt'then exists(select 1 from collect_hybrid.sms_notification_outbox j
     where j.id=e.source_id and collect_operator_audit.payment_scope(j.payment_id))
    when 'payment'then collect_operator_audit.payment_scope(e.source_id)
    when 'raw_sms'then collect_ops.transaction_sms_id('raw_sms',e.source_id) is not null
    when 'allocation'then collect_ops.transaction_sms_id('allocation',e.source_id) is not null
    else false end)
  else false end;
 sample:=clock_timestamp();
 -- Permit cursor predicates to reach the entity/order indexes rather than
 -- materializing an entity's entire retained history before selecting a page.
 with events as not materialized(
  select e.event_id,'shadow_audit_event'::text source,e.action,e.recorded_at,e.actor_id,e.request_id,
   null::bigint revision,e.fence_version,null::text reason_code
   from collect_operator_audit.shadow_events e where p_entity_kind='shadow_run'and e.run_id=p_entity_id
  union all
  select e.request_id,'gateway_admin_request','gateway.'||e.action,e.recorded_at,e.actor_id,e.request_id,
   null::bigint,null::bigint,null::text from collect_gateway.admin_requests e
   where p_entity_kind='gateway_device'and collect_operator_audit.safe_uuid(e.result->>'device_id')=p_entity_id
  union all
  select e.request_id,'supervisor_owner_request','supervisor.'||e.action,e.recorded_at,e.actor_id,e.request_id,
   null::bigint,null::bigint,null::text from collect_supervisor.owner_requests e
   where p_entity_kind='supervisor_identity'and collect_operator_audit.safe_uuid(e.result->>'principal_id')=p_entity_id
  union all
  select e.request_id,'exception_action','exception.'||e.action,e.recorded_at,e.actor_id,e.request_id,
   e.expected_revision,null::bigint,e.reason_code from collect_ops.exception_actions e
   where p_entity_kind='exception'and e.exception_id=p_entity_id
  union all
  select e.request_id,'receipt_cancellation','receipt.cancel_unstarted',e.recorded_at,e.actor_id,e.request_id,
   e.revision,null::bigint,e.reason_code from collect_receipt_actions.cancellations e
   where p_entity_kind='receipt'and e.outbox_id=p_entity_id
 ), page as materialized(
  select * from events where available and isfinite(recorded_at)and recorded_at<=sample
   and(p_before_at is null or(recorded_at,event_id)<(p_before_at,p_before_event_id))
   order by recorded_at desc,event_id desc limit p_limit+1
 ), shown as materialized(select * from page order by recorded_at desc,event_id desc limit p_limit)
 select jsonb_build_object('contract_version',1,'scope','rw_operator_entity_audit',
  'entity_kind',p_entity_kind,'entity_id',p_entity_id,'status',case when available then 'available'else 'unavailable'end,
  'checked_at',collect_ops.utc(sample),'sample_valid_until',collect_ops.utc(sample+interval '60 seconds'),
  'limit',p_limit,'history_complete',false,'historical_shadow_audit_backfilled',false,
  'financial_action',false,'send_action',false,
  'rows',coalesce((select jsonb_agg(jsonb_build_object('event_id',event_id,'source',source,'action',action,
   'recorded_at',collect_ops.utc(recorded_at),'actor_id',actor_id,'request_id',request_id,
   'revision',revision,'fence_version',fence_version,'reason_code',reason_code)
   order by recorded_at desc,event_id desc)from shown),'[]'::jsonb),
  'next_cursor',case when(select count(*)from page)>p_limit then
   (select jsonb_build_object('recorded_at',collect_ops.utc(recorded_at),'event_id',event_id)
    from shown order by recorded_at,event_id limit 1)else null end)into result;
 -- Natural expiry remains relevant even while row locks prevent revocation.
 perform collect_operator_audit.actor(p_entity_kind);
 return result;
exception when lock_not_available then raise exception 'operator_audit_authority_busy'using errcode='55P03';end$$;


ALTER FUNCTION public.admin_get_operator_entity_audit_v1(p_entity_kind text, p_entity_id uuid, p_limit integer, p_before_at timestamp with time zone, p_before_event_id uuid) OWNER TO postgres;

