--

COMMENT ON FUNCTION public.admin_get_queue_sla(p_queue_key text) IS 'Returns permission-gated operational SLA guidance for every current Admin queue.';


--
-- Name: admin_get_receipt_deferral_exception_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_receipt_deferral_exception_v1(p_exception_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '200ms'
    AS $$
declare e collect_ops.exceptions;current jsonb;t timestamptz;begin
 perform collect_ops.actor(false);perform pg_advisory_xact_lock(hashtext('collect-ops-workflow'));
 select * into e from collect_ops.exceptions where id=p_exception_id and source_kind in('receipt_event','receipt_backlog');
 if e.id is null then raise exception 'receipt_exception_unavailable'using errcode='22023';end if;
 perform collect_ops.refresh_source(e.source_kind,e.source_id);select * into e from collect_ops.exceptions where id=p_exception_id;
 current:=collect_ops.receipt_exception_source(e.source_kind,e.source_id);perform collect_ops.actor(false);t:=clock_timestamp();
 return jsonb_build_object('contract_version',1,'exception_id',e.id,'source_kind',e.source_kind,'source_id',e.source_id,
  'source_version',current->'source_version','event_kind',current->'event_kind','reason_code',e.reason_code,'revision',e.revision,'active',e.active,
  'disposition',current->'disposition','original_code',current->'original_code','current_code',current->'current_code',
  'business_handled',current->'business_handled','receipt_id',current->'receipt_id','checked_at',collect_ops.utc(t),
  'sample_valid_until',collect_ops.utc(t+interval '60 seconds'),'financial_action',false,'send_action',false);end$$;


ALTER FUNCTION public.admin_get_receipt_deferral_exception_v1(p_exception_id uuid) OWNER TO postgres;

--
-- Name: admin_get_receipt_exception_worker_health_v1(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_receipt_exception_worker_health_v1() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare c collect_ops.receipt_worker_configuration;j collect_ops.receipt_worker_jobs;r collect_ops.receipt_worker_receipts;
 t timestamptz;state text;alerts jsonb:='[]'::jsonb;pending bigint;refused integer;transport_ready boolean:=false;
 day_count integer;scan_reserved integer;escalation_reserved integer;begin
 perform collect_ops.actor(false);t:=clock_timestamp();select * into c from collect_ops.receipt_worker_configuration where singleton;
 select * into j from collect_ops.receipt_worker_jobs order by created_at desc,request_id desc limit 1;
 select * into r from collect_ops.receipt_worker_receipts order by recorded_at desc,request_id desc limit 1;
 state:=case when not c.enabled then 'inactive'when j.request_id is null then 'unobserved'
  when exists(select 1 from collect_ops.receipt_worker_receipts where request_id=j.request_id)then 'observed'
  when exists(select 1 from collect_ops.receipt_worker_expirations where request_id=j.request_id)then 'expired_without_receipt'
  when j.expires_at<=t then 'unknown'else 'pending'end;
 select count(*)into pending from collect_ops.receipt_exception_work where processed_at is null;
 select count(*),coalesce(sum(scan_limit),0),coalesce(sum(escalation_limit),0)into day_count,scan_reserved,escalation_reserved
  from collect_ops.receipt_worker_jobs where reserved_day=(t at time zone 'UTC')::date;
 begin perform collect_ops.receipt_worker_transport();transport_ready:=true;
 exception when object_not_in_prerequisite_state then transport_ready:=false;end;
 refused:=coalesce((r.result->'scan'->>'refused')::integer,0);
 if c.enabled and(r.recorded_at is null or r.recorded_at<t-interval '180 seconds')then alerts:=alerts||jsonb_build_array('WORKER_STALE');end if;
 if state='unknown'then alerts:=alerts||jsonb_build_array('ORIGINAL_OUTCOME_UNKNOWN');end if;
 if state='expired_without_receipt'then alerts:=alerts||jsonb_build_array('ORIGINAL_EXPIRED_UNHANDLED');end if;
 if pending>c.scan_limit*10 then alerts:=alerts||jsonb_build_array('DEFERRAL_BACKLOG');end if;
 if refused>0 then alerts:=alerts||jsonb_build_array('SOURCE_REFUSALS');end if;
 if c.enabled and not transport_ready then alerts:=alerts||jsonb_build_array('TRANSPORT_UNCONFIGURED');end if;
 if c.enabled and(day_count>=c.day_jobs or scan_reserved+c.scan_limit>c.day_scan_sources or escalation_reserved+c.escalation_limit>c.day_escalations)
  then alerts:=alerts||jsonb_build_array('WORKER_QUOTA_EXHAUSTED');end if;
 return jsonb_build_object('contract_version',1,'checked_at',collect_ops.utc(t),'sample_valid_until',collect_ops.utc(t+interval '60 seconds'),
  'configuration_revision',c.revision,'enabled',c.enabled,'state',state,'last_request_id',j.request_id,'last_created_at',collect_ops.utc(j.created_at),
  'last_expires_at',collect_ops.utc(j.expires_at),'last_recorded_at',collect_ops.utc(r.recorded_at),'last_outcome',r.result->'status',
  'pending_sources',pending,'alerts',alerts,'transport_configured',transport_ready,
  'day_jobs_reserved',day_count,'day_scan_sources_reserved',scan_reserved,'day_escalations_reserved',escalation_reserved,
  'day_jobs_cap',c.day_jobs,'day_scan_sources_cap',c.day_scan_sources,'day_escalations_cap',c.day_escalations,
  'source_scan_complete',false,'financial_action',false,'send_action',false,'external_send',false);
end$$;


ALTER FUNCTION public.admin_get_receipt_exception_worker_health_v1() OWNER TO postgres;

--
-- Name: admin_get_receipt_operations_enrollment_request_v3(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_receipt_operations_enrollment_request_v3(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_receipt_operations.enrollment_workflow_requests;t timestamptz;status text;begin
 perform collect_supervisor.owner_actor();
 if p_request_id is null then raise exception 'operations_enrollment_input_invalid'using errcode='22023';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0))then status:='in_progress';
 else
  perform collect_supervisor.owner_actor();
  if not pg_try_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request_id::text,0))then status:='in_progress';
  else
   perform collect_supervisor.owner_actor();
   select * into r from collect_receipt_operations.enrollment_workflow_requests where request_id=p_request_id and actor_id=auth.uid();
   if r.request_id is null and(exists(select 1 from collect_receipt_operations.owner_requests where request_id=p_request_id and actor_id=auth.uid())
    or exists(select 1 from collect_supervisor.owner_requests where request_id=p_request_id and actor_id=auth.uid()))
    then raise exception 'operations_enrollment_legacy_request_conflict'using errcode='22023';end if;
   status:=case when r.request_id is null then 'not_recorded'else 'recorded'end;
  end if;
 end if;
 perform collect_supervisor.owner_actor();t:=clock_timestamp();
 return jsonb_build_object('contract_version',3,'request_id',p_request_id,'action',r.action,'status',status,
  'checked_at',collect_gateway.utc(t),'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'),
  'request_expires_at',case when r.request_id is null then null else collect_gateway.utc(r.request_expires_at)end,
  'receipt',case when status='recorded'then r.result else null end);end$$;


ALTER FUNCTION public.admin_get_receipt_operations_enrollment_request_v3(p_request_id uuid) OWNER TO postgres;

--
-- Name: admin_get_receipt_operations_identity_v3(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_get_receipt_operations_identity_v3(p_principal_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_supervisor.identities;t timestamptz;begin
 perform collect_supervisor.owner_actor();
 if p_principal_id is null then raise exception 'operations_enrollment_input_invalid'using errcode='22023';end if;
 select * into r from collect_supervisor.identities where id=p_principal_id and owner_actor_id=auth.uid()and scope='rw_receipt_operations'for share;
 perform collect_supervisor.owner_actor();t:=clock_timestamp();
 return jsonb_build_object('contract_version',3,'checked_at',collect_gateway.utc(t),
  'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'),'found',r.id is not null,
  'identity',case when r.id is null then null else collect_receipt_operations.enrollment_identity_row(r)end);end$$;


ALTER FUNCTION public.admin_get_receipt_operations_identity_v3(p_principal_id uuid) OWNER TO postgres;

