CREATE FUNCTION public.admin_get_receipt_operations_owner_request_v2(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare r collect_receipt_operations.owner_requests;t timestamptz;status text;begin
 perform collect_supervisor.owner_actor();
 if p_request_id is null then raise exception 'operations_owner_request_input_invalid'using errcode='22023';end if;
 if not pg_try_advisory_xact_lock(hashtextextended('collect-operations-owner:'||p_request_id::text,0))then status:='in_progress';
 else
  select * into r from collect_receipt_operations.owner_requests where request_id=p_request_id and actor_id=auth.uid()and action in('configure','stop');
  status:=case when r.request_id is null then 'not_recorded'else 'recorded'end;
 end if;
 t:=clock_timestamp();return jsonb_build_object('contract_version',2,'request_id',p_request_id,
  'checked_at',collect_gateway.utc(t),'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'),
  'status',status,'expires_at',case when r.request_id is null then null else collect_gateway.utc(r.expires_at)end,
  'receipt',case when status='recorded'then r.result else null end);end$$;


