--

CREATE FUNCTION public.admin_list_bank_transfer_intents(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('bank_transactions.read');
  with filtered as (
    select intent.*, collection.title as collection_title
    from public.bank_transfer_intents intent
    join public.collections collection on collection.id = intent.collection_id
    where (p_status is null or intent.status = p_status)
      and (
        p_search is null
        or intent.transfer_reference ilike '%' || p_search || '%'
        or collection.title ilike '%' || p_search || '%'
      )
  ), counted as (
    select count(*) over () as total_count, filtered.*
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      case when p_sort = 'amount_asc' then amount_minor end asc nulls last,
      case when p_sort = 'amount_desc' then amount_minor end desc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      id, transfer_reference, collection_title, status,
      currency || ' ' || to_char(amount_minor::numeric / 100, 'FM999G999G999D00'),
      created_at,
      jsonb_build_object('collection_id', collection_id)
    ) order by created_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


ALTER FUNCTION public.admin_list_bank_transfer_intents(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_collect_ledgers(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_collect_ledgers(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('ledger.read');
  with unified as (
    select
      'momo:' || entry.id::text as id,
      entry.external_reference as title,
      case when entry.entry_type = 'reversal'
        then 'Rwanda · compensating MoMo reversal'
        else 'Rwanda · provider-confirmed MoMo receipt' end as subtitle,
      case when entry.entry_type = 'reversal'
        then 'reversed' else 'balanced' end as status,
      ('RWF ' || case when entry.entry_type = 'reversal' then '-' else '' end
        || to_char(entry.amount_rwf, 'FM999G999G999G999') || ' =') as amount,
      entry.created_at,
      jsonb_build_object(
        'rail', 'rw_momo',
        'payment_id', entry.payment_id,
        'journal_entry_id', entry.id,
        'collection_id', entry.collection_id,
        'debit_total', totals.debit_total,
        'credit_total', totals.credit_total,
        'currency', 'RWF',
        'line_count', totals.line_count,
        'entry_type', entry.entry_type
      ) as extra
    from collect_hybrid.momo_journal_entries entry
    join lateral (
      select
        coalesce(sum(line.amount_rwf) filter (
          where line.direction = 'debit'
        ), 0)::bigint as debit_total,
        coalesce(sum(line.amount_rwf) filter (
          where line.direction = 'credit'
        ), 0)::bigint as credit_total,
        count(*)::bigint as line_count
      from collect_hybrid.momo_journal_lines line
      where line.journal_entry_id = entry.id
    ) totals on true
    union all
    select
      'diaspora:' || journal.id::text,
      coalesce(journal.external_reference, 'Diaspora journal ' || right(journal.id::text, 8)),
      'Diaspora · ' || journal.description,
      case when totals.debit_total = totals.credit_total and totals.debit_total > 0
        then 'balanced' else 'unbalanced' end,
      journal.currency || ' '
        || to_char(totals.debit_total::numeric / 100, 'FM999G999G999D00') || ' =',
      journal.posted_at,
      jsonb_build_object(
        'rail', 'diaspora_account',
        'journal_entry_id', journal.id,
        'transaction_id', journal.bank_transaction_id,
        'collection_id', journal.collection_id,
        'debit_total', totals.debit_total,
        'credit_total', totals.credit_total,
        'currency', journal.currency,
        'line_count', totals.line_count
      )
    from public.journal_entries journal
    join lateral (
      select
        coalesce(sum(line.amount_minor) filter (
          where line.direction = 'debit'
        ), 0)::bigint as debit_total,
        coalesce(sum(line.amount_minor) filter (
          where line.direction = 'credit'
        ), 0)::bigint as credit_total,
        count(*)::bigint as line_count
      from public.journal_lines line
      where line.journal_entry_id = journal.id
    ) totals on true
  ), filtered as (
    select * from unified
    where (nullif(btrim(coalesce(p_status, '')), '') is null
        or status = btrim(p_status))
      and (nullif(btrim(coalesce(p_search, '')), '') is null
        or title ilike '%' || btrim(p_search) || '%'
        or subtitle ilike '%' || btrim(p_search) || '%')
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(jsonb_build_object(
      'id', id,
      'title', title,
      'subtitle', subtitle,
      'status', status,
      'amount', amount,
      'created_at', created_at
    ) || extra order by created_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result
  from counted;
  return result;
end;
$$;


