ALTER FUNCTION public.admin_list_collections(p_search text, p_status text) OWNER TO postgres;

--
-- Name: admin_list_collections(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_collections(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('collections.read');

  with base as (
    select
      collection.id,
      collection.title,
      coalesce(collection.purpose_label, collection.category, 'Community group') as subtitle,
      case
        when collection.archived_at is not null then 'archived'
        when collection.public_status = 'public_approved' then 'public_approved'
        else 'private'
      end as status,
      collection.created_at,
      collection.updated_at,
      coalesce(member_count.active_members, 0)::integer as active_members,
      jsonb_build_object(
        'slug', collection.slug,
        'collection_type', collection.collection_type,
        'category_subtype', collection.category_subtype,
        'purpose_label', collection.purpose_label,
        'visibility', case
          when collection.public_status = 'public_approved' then 'public'
          else 'private'
        end,
        'is_platform_sponsored', collection.is_platform_sponsored,
        'creator_label', case
          when collection.is_platform_sponsored then 'Collect platform'
          else 'Collect ID ' || coalesce(profile.public_id, 'unavailable')
        end,
        'active_members', coalesce(member_count.active_members, 0),
        'receiver_label', receiver.label,
        'receiver_network', receiver.network,
        'momo_identifier', case
          when receiver.momo_number is null then null
          when collection.is_platform_sponsored then receiver.momo_number
          else public.mask_phone(receiver.momo_number)
        end,
        'route_ready', receiver.momo_number is not null,
        'updated_at', collection.updated_at
      ) as extra
    from public.collections collection
    left join public.profiles profile on profile.id = collection.creator_user_id
    left join lateral (
      select route.label, route.momo_number, route.network
      from public.collection_receivers route
      where route.collection_id = collection.id and route.is_active
      order by route.created_at desc
      limit 1
    ) receiver on true
    left join lateral (
      select count(*) as active_members
      from public.collection_members member
      where member.collection_id = collection.id and member.status = 'active'
    ) member_count on true
  ), filtered as (
    select * from base
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or subtitle ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'slug', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'creator_label', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'receiver_label', '') ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', active_members::text || ' members',
        'created_at', created_at
      ) || extra order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


ALTER FUNCTION public.admin_list_collections(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_country_scoped(text, text, text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_country_scoped(p_rpc_name text, p_country text, p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  v_allowed_rpcs constant text[] := array[
    'admin_list_collections',
    'admin_list_users',
    'admin_list_members',
    'admin_list_non_member_users',
    'admin_list_collect_payees',
    'admin_list_collect_transactions',
    'admin_list_collect_reconciliations',
    'admin_list_collect_ledgers',
    'admin_list_notifications'
  ];
  v_country text := upper(btrim(coalesce(p_country, '')));
  v_page_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_page_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_source_offset integer := 0;
  v_source_total integer := 0;
  v_batch jsonb;
  v_all_rows jsonb := '[]'::jsonb;
  v_result jsonb;
begin
  if not (p_rpc_name = any(v_allowed_rpcs)) then
    raise exception 'Unsupported country-scoped Admin list';
  end if;
  if v_country not in ('RW', 'MT', 'OTHER') then
    raise exception 'Country scope must be RW, MT, or OTHER';
  end if;

  loop
    v_batch := case p_rpc_name
      when 'admin_list_collections' then public.admin_list_collections(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_users' then public.admin_list_users(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_members' then public.admin_list_members(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_non_member_users' then public.admin_list_non_member_users(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_payees' then public.admin_list_collect_payees(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_transactions' then public.admin_list_collect_transactions(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_reconciliations' then public.admin_list_collect_reconciliations(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_collect_ledgers' then public.admin_list_collect_ledgers(
        p_search, p_status, 100, v_source_offset, p_sort)
      when 'admin_list_notifications' then public.admin_list_notifications(
        p_search, p_status, 100, v_source_offset, p_sort)
    end;

    v_source_total := greatest(
      v_source_total,
      coalesce(nullif(v_batch ->> 'total', '')::integer, 0)
    );
    v_all_rows := v_all_rows || coalesce(v_batch -> 'rows', '[]'::jsonb);
    exit when jsonb_array_length(coalesce(v_batch -> 'rows', '[]'::jsonb)) = 0
      or v_source_offset + 100 >= v_source_total;
    v_source_offset := v_source_offset + 100;
  end loop;

  with enriched as (
    select
      source.ordinality,
      source.value || jsonb_build_object(
        'country_code',
        private.collect_admin_country_for_row(p_rpc_name, source.value)
      ) as row
    from jsonb_array_elements(v_all_rows) with ordinality as source(value, ordinality)
  ), filtered as (
    select enriched.*
    from enriched
    where case v_country
      when 'RW' then enriched.row ->> 'country_code' = 'RW'
      when 'MT' then enriched.row ->> 'country_code' = 'MT'
      else enriched.row ->> 'country_code' not in ('RW', 'MT')
    end
  ), paged as (
    select filtered.*
    from filtered
    order by filtered.ordinality
    limit v_page_limit offset v_page_offset
  )
  select jsonb_build_object(
    'rows', coalesce(
      (select jsonb_agg(paged.row order by paged.ordinality) from paged),
      '[]'::jsonb
    ),
    'total', (select count(*) from filtered)
  ) into v_result;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


ALTER FUNCTION public.admin_list_country_scoped(p_rpc_name text, p_country text, p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

