--
-- Name: admin_list_exception_escalation_inbox_v1(integer); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_exception_escalation_inbox_v1(p_limit integer DEFAULT 20) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare at timestamptz;rows jsonb;begin
 perform collect_ops.actor(false);
 if p_limit is null or p_limit not between 1 and 50 then raise exception 'exception_escalation_limit_invalid'using errcode='22023';end if;
 at:=clock_timestamp();
 select coalesce(jsonb_agg(jsonb_build_object('escalation_id',d.escalation_id,'exception_id',s.exception_id,
  'source_revision',s.source_revision,'reason_code',s.reason_code,'source_active',e.active,
  'current_source_revision',e.revision,'delivered_at',collect_ops.utc(d.delivered_at),'read_at',collect_ops.utc(r.read_at))
  order by d.delivered_at desc,d.escalation_id desc),'[]'::jsonb)into rows
 from(select * from collect_ops.exception_inbox_deliveries where recipient_id=auth.uid()
  order by delivered_at desc,escalation_id desc limit p_limit)d
 join collect_ops.exception_escalations s on s.id=d.escalation_id
 join collect_ops.exceptions e on e.id=s.exception_id
 left join collect_ops.exception_inbox_reads r on r.escalation_id=d.escalation_id;
 return jsonb_build_object('contract_version',1,'channel','admin_inbox','checked_at',collect_ops.utc(at),
  'sample_valid_until',collect_ops.utc(at+interval '60 seconds'),'rows',rows);
end$$;


ALTER FUNCTION public.admin_list_exception_escalation_inbox_v1(p_limit integer) OWNER TO postgres;

--
-- Name: admin_list_exception_escalation_inbox_v2(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_exception_escalation_inbox_v2(p_limit integer DEFAULT 20, p_before_delivered_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_escalation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare sample timestamptz;result jsonb;begin
 perform collect_operator_audit.exception_actor_v2(false);
 if p_limit is null or p_limit not between 1 and 25
  or(p_before_delivered_at is null)is distinct from(p_before_escalation_id is null)
  or(p_before_delivered_at is not null and(not isfinite(p_before_delivered_at)
   or p_before_delivered_at<'0001-01-01T00:00:00Z'::timestamptz
   or p_before_delivered_at>='10000-01-01T00:00:00Z'::timestamptz))then
  raise exception 'exception_inbox_input_invalid'using errcode='22023';end if;
 sample:=clock_timestamp();
 with page as materialized(select d.escalation_id,e.id exception_id,s.source_revision,s.reason_code,
  e.active source_active,e.revision current_source_revision,d.delivered_at,r.read_at
  from collect_ops.exception_inbox_deliveries d join collect_ops.exception_escalations s on s.id=d.escalation_id
  join collect_ops.exceptions e on e.id=s.exception_id
  left join collect_ops.exception_inbox_reads r on r.escalation_id=d.escalation_id and r.recipient_id=auth.uid()
  where d.recipient_id=auth.uid()and s.recipient_id=d.recipient_id
   and d.delivered_at>='0001-01-01T00:00:00Z'::timestamptz and d.delivered_at<=sample
   and(p_before_delivered_at is null or(d.delivered_at,d.escalation_id)<(p_before_delivered_at,p_before_escalation_id))
  order by d.delivered_at desc,d.escalation_id desc limit p_limit+1),
 shown as materialized(select * from page order by delivered_at desc,escalation_id desc limit p_limit)
 select jsonb_build_object('contract_version',2,'channel','admin_inbox','scope','current_operator','recipient_id',auth.uid(),
  'checked_at',collect_ops.utc(sample),'sample_valid_until',collect_ops.utc(sample+interval '60 seconds'),'limit',p_limit,
  'rows',coalesce((select jsonb_agg(jsonb_build_object('escalation_id',escalation_id,'exception_id',exception_id,
   'source_revision',source_revision,'reason_code',reason_code,'source_active',source_active,
   'current_source_revision',current_source_revision,'delivered_at',collect_ops.utc(delivered_at),'read_at',collect_ops.utc(read_at))
   order by delivered_at desc,escalation_id desc)from shown),'[]'::jsonb),
  'next_cursor',case when(select count(*)from page)>p_limit then
   (select jsonb_build_object('delivered_at',collect_ops.utc(delivered_at),'escalation_id',escalation_id)
    from shown order by delivered_at,escalation_id limit 1)else null end)into result;
 perform collect_operator_audit.exception_actor_v2(false);
 return result;
exception when lock_not_available then raise exception 'exception_inbox_authority_busy'using errcode='55P03';end$$;


ALTER FUNCTION public.admin_list_exception_escalation_inbox_v2(p_limit integer, p_before_delivered_at timestamp with time zone, p_before_escalation_id uuid) OWNER TO postgres;

--
-- Name: admin_list_exception_followup_operators_v2(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_exception_followup_operators_v2(p_limit integer DEFAULT 25, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_operator_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET lock_timeout TO '100ms'
    AS $$
declare at timestamptz;rows jsonb;cursor_value jsonb;
begin
 perform collect_ops.followup_v2_actor(false);
 if p_limit is null or p_limit not between 1 and 25
  or (p_before_created_at is null)<>(p_before_operator_id is null)
  or (p_before_created_at is not null and (not isfinite(p_before_created_at)
   or p_before_created_at<'0001-01-01T00:00:00Z'::timestamptz
   or p_before_created_at>='10000-01-01T00:00:00Z'::timestamptz)) then
  raise exception 'exception_followup_directory_input_invalid' using errcode='22023';
 end if;
 at:=clock_timestamp();
 with candidates as materialized (
  select p.id,p.public_id,p.created_at from public.profiles p
  where isfinite(p.created_at) and p.created_at>='0001-01-01T00:00:00Z'::timestamptz
   and p.created_at<=at and collect_ops.recipient_available(p.id)
   and exists(select 1 from collect_admin_access.email_approvals a where a.user_id=p.id
    and a.revoked_at is null and (a.expires_at is null or a.expires_at>at))
   and (p_before_created_at is null or (p.created_at,p.id)<(p_before_created_at,p_before_operator_id))
  order by p.created_at desc,p.id desc limit p_limit+1
 ), numbered as (select *,row_number()over(order by created_at desc,id desc) n from candidates)
 select coalesce(jsonb_agg(jsonb_build_object('operator_id',id,
   'display_label','Collect ID '||public_id,'created_at',collect_ops.utc(created_at))
   order by created_at desc,id desc)filter(where n<=p_limit),'[]'::jsonb),
  case when max(n)>p_limit then (select jsonb_build_object('created_at',collect_ops.utc(x.created_at),
   'operator_id',x.id) from numbered x where x.n=p_limit) else null end
 into rows,cursor_value from numbered;
 perform collect_ops.followup_v2_actor(false);
 return jsonb_build_object('contract_version',2,'scope','platform_global','checked_at',collect_ops.utc(at),
  'sample_valid_until',collect_ops.utc(at+interval '60 seconds'),'limit',p_limit,
  'rows',rows,'next_cursor',cursor_value);
exception when lock_not_available then
 raise exception 'exception_followup_authority_busy' using errcode='55P03';
end $$;


ALTER FUNCTION public.admin_list_exception_followup_operators_v2(p_limit integer, p_before_created_at timestamp with time zone, p_before_operator_id uuid) OWNER TO postgres;

--
-- Name: admin_list_feature_flags(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_feature_flags(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
 perform collect_security.runtime_control_actor('feature_flags',true);
 if char_length(coalesce(p_search,''))>200 or p_status is not null and p_status not in ('enabled','disabled') then raise exception 'runtime_control_query_invalid' using errcode='22023';end if;
 return jsonb_build_object('rows',coalesce((select jsonb_agg(public._admin_row(md5('collect.runtime-control.row.v1:feature_flags:'||flag.key)::uuid,flag.key,flag.description,case when flag.enabled then 'enabled' else 'disabled' end,'',flag.updated_at)||jsonb_build_object('extra',jsonb_build_object('runtime_revision',head.revision)) order by flag.key)
 from public.feature_flags flag join collect_security.runtime_control_heads head on head.family='feature_flags' and head.identity=jsonb_build_object('key',flag.key)
 where (p_search is null or flag.key ilike '%'||p_search||'%' or flag.description ilike '%'||p_search||'%') and (p_status is null or p_status='enabled' and flag.enabled or p_status='disabled' and not flag.enabled)),'[]'::jsonb));
end $$;


ALTER FUNCTION public.admin_list_feature_flags(p_search text, p_status text) OWNER TO postgres;

--
-- Name: admin_list_gateway_device_attempts_v3(uuid, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_gateway_device_attempts_v3(p_device_id uuid, p_limit integer DEFAULT 20, p_before_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_attempt_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare t timestamptz;answer jsonb;
begin
 perform collect_gateway.read_actor();t:=clock_timestamp();
 if p_device_id is null or p_limit is null or p_limit not between 1 and 25
  or (p_before_at is null)<>(p_before_attempt_id is null)
  or p_before_at is not null and not isfinite(p_before_at) then
  raise exception 'gateway_investigation_input_invalid' using errcode='22023';end if;
 with device as materialized (
  select d.id from collect_gateway.devices d where d.id=p_device_id
 ), candidates as materialized (
  select a.* from device d cross join lateral (
   select a.* from collect_gateway_dispatch.attempts a where a.device_id=d.id
    and (p_before_at is null or (a.issued_at,a.id)<(p_before_at,p_before_attempt_id))
   order by a.issued_at desc,a.id desc limit p_limit+1
  ) a
 ), scanned_page as materialized (
  select * from candidates order by issued_at desc,id desc limit p_limit
 ), page as materialized (
  select a.* from scanned_page a join collect_hybrid.sms_notification_outbox o on o.id=a.outbox_id
  where collect_receipt_actions.rwanda_source(o)
 ) select jsonb_build_object('contract_version',3,'scope','rw_automatic_gateway_evidence',
  'device_id',p_device_id,'status',case when exists(select 1 from device) then 'available' else 'unavailable' end,
  'checked_at',collect_gateway.utc(t),'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'),
  'limit',p_limit,'scanned_count',(select count(*) from scanned_page),
  'rows',coalesce((select jsonb_agg(collect_gateway_dispatch.admin_attempt_projection(a)
   order by a.issued_at desc,a.id desc) from page a),'[]'::jsonb),
  'next_cursor',case when (select count(*) from candidates)>p_limit then
   (select jsonb_build_object('issued_at',collect_gateway.utc(a.issued_at),'attempt_id',a.id)
    from scanned_page a order by a.issued_at,a.id limit 1) else null end,
  'carrier_proof',false,'delivery_proven',false,'send_authority',false) into answer;
 perform collect_gateway.read_actor();
 if clock_timestamp()>=t+interval '60 seconds' then
  raise exception 'gateway_investigation_sample_expired' using errcode='55000';end if;
 return answer;
end$$;


ALTER FUNCTION public.admin_list_gateway_device_attempts_v3(p_device_id uuid, p_limit integer, p_before_at timestamp with time zone, p_before_attempt_id uuid) OWNER TO postgres;

--
-- Name: admin_list_gateway_devices_v1(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_gateway_devices_v1(p_limit integer DEFAULT 20, p_before_enrolled_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_device_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 perform collect_gateway.read_actor();
 if p_limit is null or p_limit not between 1 and 50
  or ((p_before_enrolled_at is null)<>(p_before_device_id is null))
  or (p_before_enrolled_at is not null and not isfinite(p_before_enrolled_at)) then
  raise exception 'gateway_read_query_invalid' using errcode='22023';end if;
 -- One Read Committed statement sees a coherent committed source snapshot.
 -- Capture its clock inside that statement, after its snapshot is acquired;
 -- a concurrently committed heartbeat/action cannot be newer than this clock
 -- yet visible in only one of the separate projections.
 with read_time as materialized(select clock_timestamp() checked_at),
 candidates as materialized(
  select d.* from collect_gateway.devices d
  where p_before_enrolled_at is null or (d.created_at,d.id)<(p_before_enrolled_at,p_before_device_id)
  order by d.created_at desc,d.id desc limit p_limit+1
 ),page as materialized(select * from candidates order by created_at desc,id desc limit p_limit),
 projected as (
  select d.created_at,d.id,
   collect_gateway.public_identity(d::collect_gateway.devices)||jsonb_build_object(
    'state',d.state,'enrolled_at',collect_gateway.utc(d.created_at),
    'activated_at',collect_gateway.utc(d.activated_at),'revoked_at',collect_gateway.utc(d.revoked_at),
    'dispatch_authority','pending','dispatch_available',false,
    'health',case when h.id is null then null else jsonb_build_object(
     'observation_id',h.id,'reported_at',collect_gateway.utc(h.reported_at),
     'ingested_at',collect_gateway.utc(h.ingested_at),
     'observation_valid_until',collect_gateway.utc(least(h.reported_at,h.ingested_at)+interval '120 seconds'),
     'freshness',case when t.checked_at<least(h.reported_at,h.ingested_at)+interval '120 seconds'
       then 'fresh' else 'stale' end,
     'sms_permission',h.sms_permission,'network',h.network,'telephony',h.telephony,
     'sim_selected',h.sim_selected,'local_pause',h.local_pause,'carrier_proof',false) end,
    'callback_observations',jsonb_build_object('total',collect_gateway.read_count(cb.total),
     'sent',collect_gateway.read_count(cb.sent),'delivery',collect_gateway.read_count(cb.delivery)),
    'last_owner_action',case when a.request_id is null then null else
     jsonb_build_object('action',a.action,'receipt',collect_gateway.public_owner_receipt(a.result)) end) value
  from page d cross join read_time t
  left join lateral(select o.* from collect_gateway.health_observations o where o.device_id=d.id
    order by o.ingested_at desc,o.id desc limit 1)h on true
  left join lateral(select r.action,r.request_id,r.result from collect_gateway.admin_requests r
    where r.result->>'device_id'=d.id::text order by r.recorded_at desc,r.request_id desc limit 1)a on true
  cross join lateral(select count(*) total,count(*) filter(where c.callback_kind='sent')sent,
    count(*) filter(where c.callback_kind='delivery')delivery
    from collect_gateway.segment_callbacks c where c.device_id=d.id)cb
 )
 select jsonb_build_object('contract_version',1,'scope','platform_global',
  'checked_at',collect_gateway.utc(t.checked_at),
  'sample_valid_until',collect_gateway.utc(t.checked_at+interval '60 seconds'),
  'limit',p_limit,'total',collect_gateway.read_count((select count(*) from collect_gateway.devices)),
  'next_cursor',case when (select count(*) from candidates)>p_limit then
   (select jsonb_build_object('enrolled_at',collect_gateway.utc(p.created_at),'device_id',p.id)
    from page p order by p.created_at,p.id limit 1) else null end,
  'rows',coalesce((select jsonb_agg(p.value order by p.created_at desc,p.id desc)from projected p),'[]'::jsonb))
 into result from read_time t;
 return result;
end$$;


ALTER FUNCTION public.admin_list_gateway_devices_v1(p_limit integer, p_before_enrolled_at timestamp with time zone, p_before_device_id uuid) OWNER TO postgres;

--
-- Name: admin_list_hybrid_sms_receipts(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_hybrid_sms_receipts(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  bounded_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  bounded_offset integer := greatest(coalesce(p_offset, 0), 0);
  result jsonb;
begin
  perform public.assert_admin_permission('notifications.read');
  with filtered as (
    select
      outbox.*,
      collection.title as collection_title,
      member.collect_id
    from collect_hybrid.sms_notification_outbox outbox
    join public.collections collection on collection.id = outbox.collection_id
    join collect_hybrid.member_records member on member.id = outbox.member_record_id
    where (nullif(btrim(coalesce(p_status, '')), '') is null
        or outbox.state = btrim(p_status))
      and (
        nullif(btrim(coalesce(p_search, '')), '') is null
        or collection.title ilike '%' || btrim(p_search) || '%'
        or member.collect_id = btrim(p_search)
        or outbox.reference ilike '%' || btrim(p_search) || '%'
        or right(outbox.destination_e164, 3) = btrim(p_search)
      )
  ), ordered as (
    select filtered.*,
      row_number() over (
        order by
          case when coalesce(p_sort, 'created_at_desc') = 'created_at_asc'
            then filtered.created_at end asc nulls last,
          filtered.created_at desc,
          filtered.id
      ) as admin_rank
    from filtered
    order by
      case when coalesce(p_sort, 'created_at_desc') = 'created_at_asc'
        then filtered.created_at end asc nulls last,
      filtered.created_at desc,
      filtered.id
    limit bounded_limit offset bounded_offset
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      ordered.id,
      ordered.collection_title || ' receipt',
      'Collect ID ' || ordered.collect_id || ' • '
        || left(ordered.destination_e164, 4) || '•••'
        || right(ordered.destination_e164, 3),
      ordered.state,
      'RWF ' || to_char(ordered.amount_rwf, 'FM999,999,999,999,999,990'),
      ordered.created_at,
      jsonb_build_object(
        'collection_id', ordered.collection_id,
        'member_collect_id', ordered.collect_id,
        'reference', ordered.reference,
        'destination_masked', left(ordered.destination_e164, 4) || '•••'
          || right(ordered.destination_e164, 3),
        'template_key', ordered.template_key,
        'template_version', ordered.template_version,
        'consent_revision', ordered.consent_revision,
        'authorization_current',
          collect_hybrid.sms_receipt_job_is_current(ordered.id),
        'attempt_count', ordered.attempt_count,
        'claim_expires_at', ordered.claim_expires_at,
        'channel', 'assisted_sms',
        'country_code', 'RW'
      )
    ) order by ordered.admin_rank), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into result
  from ordered;
  return coalesce(result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


ALTER FUNCTION public.admin_list_hybrid_sms_receipts(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_interrupted_roster_imports(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_interrupted_roster_imports() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare sid uuid; s collect_hybrid.roster_import_sources; answer jsonb:='[]'; begin
 sid:=collect_hybrid.require_fresh_roster_auth();
 -- A bounded authenticated server lookup; browser references confer no access.
 for s in select * from collect_hybrid.roster_import_sources where actor_id=auth.uid() and session_id<>sid
  and expires_at>clock_timestamp() and not exists(select 1 from collect_hybrid.roster_recovery_transfers where from_import_id=id)
  order by created_at desc,id limit 100 loop
  begin
   if exists(select 1 from collect_hybrid.roster_import_commits where import_id=s.id) then
    answer:=answer||jsonb_build_array(jsonb_build_object('import_id',s.id,'source_sha256',s.source_sha256,
     'source_kind',s.source_kind,'created_at',s.created_at,'expires_at',s.expires_at,'state','committed','etag',null));
   else
    perform collect_hybrid.require_interrupted_roster(s.id,sid);
    answer:=answer||jsonb_build_array(jsonb_build_object('import_id',s.id,'source_sha256',s.source_sha256,
     'source_kind',s.source_kind,'created_at',s.created_at,'expires_at',s.expires_at,'state','interrupted',
     'etag',collect_hybrid.roster_interrupted_etag(s.id,sid)));
   end if;
  exception when sqlstate '42501' or sqlstate '55000' then null;
  end;
 end loop;
 return jsonb_build_object('contract_version',1,'ok',true,'actor_id',auth.uid(),'destination_session_id',sid,'items',answer);
end $$;


ALTER FUNCTION public.admin_list_interrupted_roster_imports() OWNER TO postgres;

--
-- Name: admin_list_journal_entries(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_journal_entries(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('bank_reconciliation.read');
  with filtered as (
    select entry.*,
      coalesce((select sum(line.amount_minor) from public.journal_lines line
        where line.journal_entry_id = entry.id and line.direction = 'debit'), 0) amount_minor
    from public.journal_entries entry
    where (p_status is null or entry.entry_type = p_status)
      and (p_search is null or entry.external_reference ilike '%' || p_search || '%'
        or entry.description ilike '%' || p_search || '%')
  ), counted as (
    select count(*) over () total_count, filtered.* from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(public._admin_row(
      id, external_reference, description, entry_type,
      currency || ' ' || to_char(amount_minor::numeric / 100, 'FM999G999G999D00'),
      created_at, jsonb_build_object('collection_id', collection_id)
    ) order by created_at desc), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


ALTER FUNCTION public.admin_list_journal_entries(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

