--
-- Name: admin_list_notifications(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_notifications(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_result jsonb;
begin
  perform public.assert_admin_permission('notifications.read');

  with page as materialized (
    select event.id, event.type, event.status, event.created_at,
      profile.public_id
    from public.notification_events event
    join public.profiles profile on profile.id = event.user_id
    where (p_status is null or event.status = p_status)
      and (
        p_search is null
        or event.type ilike '%' || p_search || '%'
        or profile.public_id = p_search
      )
    order by
      case when coalesce(p_sort, 'created_at_desc') = 'created_at_asc'
        then event.created_at end asc nulls last,
      event.created_at desc,
      event.id
    limit v_limit offset v_offset
  ), enriched as (
    select page.*,
      delivery_counts.delivery_count,
      delivery_counts.failed_count
    from page
    left join lateral (
      select count(*)::bigint as delivery_count,
        count(*) filter (where delivery.status = 'failed')::bigint
          as failed_count
      from public.notification_deliveries delivery
      where delivery.event_id = page.id
    ) delivery_counts on true
  )
  select jsonb_build_object(
    'rows', coalesce((
      select jsonb_agg(
        public._admin_row(
          row.id,
          replace(initcap(replace(row.type, '_', ' ')), 'Momo', 'MoMo'),
          'Collect ID ' || row.public_id || ' • ' ||
            row.delivery_count || ' deliveries',
          row.status,
          case when row.failed_count > 0
            then row.failed_count || ' failed' else '' end,
          row.created_at,
          jsonb_build_object('failed_deliveries', row.failed_count)
        )
        order by
          case when coalesce(p_sort, 'created_at_desc') = 'created_at_asc'
            then row.created_at end asc nulls last,
          row.created_at desc,
          row.id
      )
      from enriched row
    ), '[]'::jsonb),
    'total', (
      select count(*)
      from public.notification_events event
      join public.profiles profile on profile.id = event.user_id
      where (p_status is null or event.status = p_status)
        and (
          p_search is null
          or event.type ilike '%' || p_search || '%'
          or profile.public_id = p_search
        )
    )
  ) into v_result;

  return coalesce(v_result,
    jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


ALTER FUNCTION public.admin_list_notifications(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_operational_exceptions_v1(boolean, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_operational_exceptions_v1(p_active boolean DEFAULT true, p_limit integer DEFAULT 20, p_before_changed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare rows jsonb;last jsonb;more boolean;
begin
 perform collect_ops.actor(false);
 if p_active is null or p_limit is null or p_limit not between 1 and 50
  or((p_before_changed_at is null)<>(p_before_id is null))
  or(p_before_changed_at is not null and not isfinite(p_before_changed_at)) then
  raise exception 'operational_exception_query_invalid' using errcode='22023';end if;
 select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'source_kind',e.source_kind,'source_id',e.source_id,
  'reason_code',e.reason_code,'active',e.active,'revision',e.revision,'source_sha256',e.source_sha256,
  'first_observed_at',collect_ops.utc(e.first_observed_at),'last_changed_at',collect_ops.utc(e.last_changed_at),
  'acknowledged',exists(select 1 from collect_ops.exception_actions a where a.exception_id=e.id and a.expected_revision=e.revision and a.action='acknowledge'),
  'escalation_requested',exists(select 1 from collect_ops.exception_actions a where a.exception_id=e.id and a.expected_revision=e.revision and a.action='escalate'))
  order by e.last_changed_at desc,e.id desc),'[]'::jsonb) into rows
 from(select * from collect_ops.exceptions where active=p_active and
  (p_before_changed_at is null or(last_changed_at,id)<(p_before_changed_at,p_before_id))
  order by last_changed_at desc,id desc limit p_limit+1)e;
 more:=jsonb_array_length(rows)>p_limit;if more then rows:=rows-(jsonb_array_length(rows)-1);end if;
 last:=rows->(jsonb_array_length(rows)-1);
 return jsonb_build_object('contract_version',1,'checked_at',collect_ops.utc(clock_timestamp()),
  'rows',rows,'active',p_active,'limit',p_limit,
  'next_cursor',case when more then jsonb_build_object('changed_at',last->'last_changed_at','id',last->'id')else null end,
  'escalation_delivery_verified',false,'source_scan_complete',false);
end$$;


ALTER FUNCTION public.admin_list_operational_exceptions_v1(p_active boolean, p_limit integer, p_before_changed_at timestamp with time zone, p_before_id uuid) OWNER TO postgres;

--
-- Name: admin_list_operational_exceptions_v2(boolean, integer, timestamp with time zone, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_operational_exceptions_v2(p_active boolean DEFAULT true, p_limit integer DEFAULT 20, p_before_changed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_id uuid DEFAULT NULL::uuid, p_source_kind text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare result jsonb;
begin
 perform collect_ops.actor(false);
 if p_active is null or p_limit is null or p_limit not between 1 and 50
  or((p_before_changed_at is null)<>(p_before_id is null))
  or(p_before_changed_at is not null and not isfinite(p_before_changed_at))
  or(p_source_kind is not null and p_source_kind not in('raw_sms','allocation','payment','receipt','gateway','receipt_event','receipt_backlog')) then
  raise exception 'operational_exception_query_invalid' using errcode='22023';end if;
 -- One committed statement supplies time, category, page and review flags.
 -- Read freshness is independent of the retained source observation's age.
 with sample as materialized(select clock_timestamp() at),
 candidates as materialized(select e.* from collect_ops.exceptions e
  where e.active=p_active and(p_source_kind is null or e.source_kind=p_source_kind)
   and(p_before_changed_at is null or(e.last_changed_at,e.id)<(p_before_changed_at,p_before_id))
  order by e.last_changed_at desc,e.id desc limit p_limit+1),
 page as materialized(select * from candidates order by last_changed_at desc,id desc limit p_limit),
 projected as(select e.last_changed_at,e.id,jsonb_build_object('id',e.id,
  'source_kind',e.source_kind,'source_id',e.source_id,'reason_code',e.reason_code,
  'active',e.active,'revision',e.revision,'source_sha256',e.source_sha256,
  'first_observed_at',collect_ops.utc(e.first_observed_at),
  'last_changed_at',collect_ops.utc(e.last_changed_at),
  'transaction_sms_id',collect_ops.transaction_sms_id(e.source_kind,e.source_id),
  'acknowledged',exists(select 1 from collect_ops.exception_actions a
   where a.exception_id=e.id and a.expected_revision=e.revision and a.action='acknowledge'),
  'escalation_requested',exists(select 1 from collect_ops.exception_actions a
   where a.exception_id=e.id and a.expected_revision=e.revision and a.action='escalate'))value from page e)
 select jsonb_build_object('contract_version',2,'scope','platform_global',
  'checked_at',collect_ops.utc(sample.at),'sample_valid_until',collect_ops.utc(sample.at+interval '60 seconds'),
  'active',p_active,'source_kind',p_source_kind,'limit',p_limit,
  'rows',coalesce((select jsonb_agg(value order by last_changed_at desc,id desc)from projected),'[]'::jsonb),
  'next_cursor',case when(select count(*)from candidates)>p_limit then
   (select jsonb_build_object('changed_at',collect_ops.utc(last_changed_at),'id',id)
    from page order by last_changed_at,id limit 1)else null end,
  'escalation_delivery_verified',false,'source_scan_complete',false)
 into result from sample;
 return result;
end$$;


ALTER FUNCTION public.admin_list_operational_exceptions_v2(p_active boolean, p_limit integer, p_before_changed_at timestamp with time zone, p_before_id uuid, p_source_kind text) OWNER TO postgres;

--
-- Name: admin_list_payment_events(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_payment_events(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sort text := coalesce(nullif(p_sort, ''), 'created_at_desc');
  v_result jsonb;
begin
  perform assert_admin_permission('payment_events.read');
  if v_sort not in (
    'created_at_desc',
    'created_at_asc',
    'amount_desc',
    'amount_asc'
  ) then
    v_sort := 'created_at_desc';
  end if;

  with filtered as (
    select e.*
    from parsed_payment_events e
    where (p_status is null or e.allocation_status::text = p_status)
      and (p_search is null or e.transaction_id ilike '%' || p_search || '%')
  ),
  ordered as (
    select
      filtered.*,
      row_number() over (
        order by
          case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
          case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
          case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,
          case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,
          filtered.created_at desc nulls last,
          filtered.id
      ) as admin_rank
    from filtered
    order by
      case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
      case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
      case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,
      case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,
      filtered.created_at desc nulls last,
      filtered.id
    limit v_limit
    offset v_offset
  )
  select jsonb_build_object(
    'rows',
    coalesce(
      jsonb_agg(
        _admin_row(
          ordered.id,
          coalesce(ordered.transaction_id, 'Payment event'),
          'MoMo SMS',
          ordered.allocation_status::text,
          coalesce(ordered.amount_rwf::text || ' RWF', ''),
          ordered.created_at,
          jsonb_build_object('collection_id', ordered.collection_id)
        )
        order by ordered.admin_rank
      ),
      '[]'::jsonb
    ),
    'total',
    (select count(*) from filtered)
  )
  into v_result
  from ordered;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


ALTER FUNCTION public.admin_list_payment_events(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_payment_intents(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_payment_intents(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sort text := coalesce(nullif(p_sort, ''), 'created_at_desc');
  v_result jsonb;
begin
  perform public.assert_admin_permission('payments.read');
  if v_sort not in ('created_at_desc', 'created_at_asc', 'amount_desc', 'amount_asc') then
    v_sort := 'created_at_desc';
  end if;

  with filtered as (
    select intent.*
    from public.payment_intents intent
    where (p_status is null or intent.status::text = p_status)
      and (
        p_search is null
        or intent.contribution_code ilike '%' || p_search || '%'
        or intent.reported_transaction_id ilike '%' || p_search || '%'
      )
  ), ordered as (
    select filtered.*,
      row_number() over (
        order by
          case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
          case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
          case when v_sort = 'amount_asc' then filtered.expected_amount_rwf end asc nulls last,
          case when v_sort = 'amount_desc' then filtered.expected_amount_rwf end desc nulls last,
          filtered.created_at desc,
          filtered.id
      ) as admin_rank
    from filtered
    order by
      case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
      case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
      case when v_sort = 'amount_asc' then filtered.expected_amount_rwf end asc nulls last,
      case when v_sort = 'amount_desc' then filtered.expected_amount_rwf end desc nulls last,
      filtered.created_at desc,
      filtered.id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      public._admin_row(
        ordered.id,
        'Intent ' || ordered.contribution_code,
        'Group ' || left(ordered.collection_id::text, 8),
        ordered.status::text,
        coalesce(ordered.expected_amount_rwf::text || ' RWF', 'Amount not fixed'),
        ordered.created_at,
        jsonb_build_object('expires_at', ordered.expires_at)
      ) order by ordered.admin_rank
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result
  from ordered;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


