CREATE FUNCTION public.admin_list_payments(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  perform assert_admin_permission('payments.read');
  return jsonb_build_object('rows', coalesce((
    select jsonb_agg(_admin_row(p.id, coalesce(p.transaction_id, 'Payment'), p.source, p.status, p.amount_rwf::text || ' RWF', p.created_at) order by p.created_at desc)
    from payments p
    where (p_status is null or p.status = p_status)
      and (p_search is null or p.transaction_id ilike '%' || p_search || '%')
  ), '[]'::jsonb));
end;
$$;


ALTER FUNCTION public.admin_list_payments(p_search text, p_status text) OWNER TO postgres;

--
-- Name: admin_list_payments(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_payments(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);
  v_offset integer := greatest(coalesce(p_offset, 0), 0);
  v_sort text := coalesce(nullif(p_sort, ''), 'created_at_desc');
  v_result jsonb;
begin
  perform public.assert_admin_permission('payments.read');
  if v_sort not in ('created_at_desc', 'created_at_asc', 'amount_desc', 'amount_asc') then
    v_sort := 'created_at_desc';
  end if;

  with filtered as (
    select payment.*
    from public.payments payment
    where (p_status is null or payment.status = p_status)
      and (p_search is null or payment.transaction_id ilike '%' || p_search || '%')
  ), ordered as (
    select filtered.*,
      row_number() over (
        order by
          case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
          case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
          case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,
          case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,
          filtered.created_at desc,
          filtered.id
      ) as admin_rank
    from filtered
    order by
      case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,
      case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,
      case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,
      case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,
      filtered.created_at desc,
      filtered.id
    limit v_limit offset v_offset
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      public._admin_row(
        ordered.id,
        coalesce(ordered.transaction_id, 'Posted transaction'),
        ordered.source,
        ordered.status,
        ordered.amount_rwf::text || ' RWF',
        ordered.created_at,
        jsonb_build_object('payment_intent_id', ordered.payment_intent_id)
      ) order by ordered.admin_rank
    ), '[]'::jsonb),
    'total', (select count(*) from filtered)
  ) into v_result
  from ordered;

  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));
end;
$$;


ALTER FUNCTION public.admin_list_payments(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_platform_payee_candidates(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_platform_payee_candidates(p_search text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 25, p_offset integer DEFAULT 0, p_sort text DEFAULT 'created_at_desc'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('receivers.manage');

  with candidates as (
    select
      collection.id::text as id,
      collection.title,
      'Platform-sponsored public group with no payee route'::text as subtitle,
      'eligible'::text as status,
      'Rwanda · MoMo USSD'::text as amount,
      collection.created_at
    from public.collections collection
    where collection.is_platform_sponsored
      and collection.public_status = 'public_approved'
      and collection.archived_at is null
      and not exists (
        select 1
        from public.collection_receivers receiver
        where receiver.collection_id = collection.id
      )
  ), filtered as (
    select *
    from candidates
    where (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', amount,
        'created_at', created_at
      )
      order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  )
  into result
  from counted;

  return result;
end;
$$;


ALTER FUNCTION public.admin_list_platform_payee_candidates(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_list_receipt_operations_identities_v3(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_receipt_operations_identities_v3(p_limit integer DEFAULT 25, p_before_created_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_principal_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare data jsonb;t timestamptz;begin
 perform collect_supervisor.owner_actor();
 if p_limit is null or p_limit not between 1 and 25 or(p_before_created_at is null)is distinct from(p_before_principal_id is null)
  or(p_before_created_at is not null and not isfinite(p_before_created_at))
  then raise exception 'operations_enrollment_input_invalid'using errcode='22023';end if;
 with page as materialized(
  select i as identity,i.created_at,i.id from collect_supervisor.identities i
  where i.owner_actor_id=auth.uid()and i.scope='rw_receipt_operations'
   and(p_before_created_at is null or(i.created_at,i.id)<(p_before_created_at,p_before_principal_id))
  order by i.created_at desc,i.id desc limit p_limit+1 for share
 ),shown as materialized(select * from page order by created_at desc,id desc limit p_limit)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(collect_receipt_operations.enrollment_identity_row(s.identity)
   order by s.created_at desc,s.id desc)from shown s),'[]'::jsonb),
  'next_cursor',case when(select count(*)from page)>p_limit then
   (select jsonb_build_object('created_at',collect_gateway.utc(created_at),'principal_id',id)
    from shown order by created_at,id limit 1)else null end)into data;
 perform collect_supervisor.owner_actor();t:=clock_timestamp();
 return jsonb_build_object('contract_version',3,'checked_at',collect_gateway.utc(t),
  'sample_valid_until',collect_gateway.utc(t+interval '60 seconds'))||data;end$$;


ALTER FUNCTION public.admin_list_receipt_operations_identities_v3(p_limit integer, p_before_created_at timestamp with time zone, p_before_principal_id uuid) OWNER TO postgres;

