--
-- Name: admin_list_users(text, text, integer, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_list_users(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare result jsonb;
begin
  perform public.assert_admin_permission('users.read');

  with base as (
    select
      profile.id,
      'Collect ID ' || profile.public_id as title,
      public.mask_phone(profile.whatsapp_phone) as subtitle,
      case when profile.is_platform_admin then 'admin' else 'active' end as status,
      profile.created_at,
      profile.updated_at,
      coalesce(member_count.active_groups, 0)::integer as active_groups,
      jsonb_build_object(
        'public_id', profile.public_id,
        'display_name', profile.display_name,
        'whatsapp_masked', public.mask_phone(profile.whatsapp_phone),
        'country_code', coalesce(profile.country_code, 'RW'),
        'currency_code', coalesce(profile.currency_code, 'RWF'),
        'momo_provider', profile.momo_provider,
        'momo_masked', public.mask_phone(profile.momo_number),
        'has_revolut_profile',
          profile.revolut_link is not null and profile.revolut_account is not null,
        'account_last4', case
          when profile.revolut_account is null then null
          else right(regexp_replace(profile.revolut_account, '[^A-Za-z0-9]', '', 'g'), 4)
        end,
        'active_groups', coalesce(member_count.active_groups, 0),
        'is_platform_admin', profile.is_platform_admin,
        'updated_at', profile.updated_at
      ) as extra
    from public.profiles profile
    left join lateral (
      select count(distinct member.collection_id) as active_groups
      from public.collection_members member
      where member.user_id = profile.id and member.status = 'active'
    ) member_count on true
  ), filtered as (
    select * from base
    where (
      nullif(btrim(coalesce(p_status, '')), '') is null
      or status = btrim(p_status)
    ) and (
      nullif(btrim(coalesce(p_search, '')), '') is null
      or title ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'display_name', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'whatsapp_masked', '') ilike '%' || btrim(p_search) || '%'
      or coalesce(extra ->> 'country_code', '') ilike '%' || btrim(p_search) || '%'
    )
  ), counted as (
    select filtered.*, count(*) over () as total_count
    from filtered
    order by
      case when p_sort = 'created_at_asc' then created_at end asc nulls last,
      created_at desc
    limit least(greatest(coalesce(p_limit, 25), 1), 100)
    offset greatest(coalesce(p_offset, 0), 0)
  )
  select jsonb_build_object(
    'rows', coalesce(jsonb_agg(
      jsonb_build_object(
        'id', id,
        'title', title,
        'subtitle', subtitle,
        'status', status,
        'amount', active_groups::text || ' groups',
        'created_at', created_at
      ) || extra order by created_at desc
    ), '[]'::jsonb),
    'total', coalesce(max(total_count), 0)
  ) into result from counted;
  return result;
end;
$$;


ALTER FUNCTION public.admin_list_users(p_search text, p_status text, p_limit integer, p_offset integer, p_sort text) OWNER TO postgres;

--
-- Name: admin_manual_allocate_payment(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_manual_allocate_payment(p_event_id uuid, p_collection_id uuid, p_payment_intent_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  event_row public.parsed_payment_events%rowtype;
  intent_row public.payment_intents%rowtype;
  receiver_hash text;
  payment_id uuid;
begin
  perform public.assert_admin_permission('payments.allocate');
  if p_payment_intent_id is null then
    raise exception 'A verified payment intent is required';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Allocation reason must be at least 8 characters';
  end if;

  select * into event_row from public.parsed_payment_events
  where id = p_event_id for update;
  select * into intent_row from public.payment_intents
  where id = p_payment_intent_id for update;
  if event_row.id is null or intent_row.id is null then
    raise exception 'Payment event and intent are required';
  end if;
  if intent_row.collection_id <> p_collection_id then
    raise exception 'Payment intent does not belong to the selected group';
  end if;

  if event_row.receiver_phone_hash is null then
    select receiver.momo_number_hash into receiver_hash
    from public.collection_receivers receiver
    where receiver.collection_id = p_collection_id
      and receiver.receiver_user_id = event_row.receiver_user_id
      and receiver.momo_number_hash = intent_row.receiver_momo_number_hash
      and receiver.is_active
    order by receiver.created_at desc limit 1;
    if receiver_hash is null then
      raise exception 'SMS receiver is not an active payee for the selected group';
    end if;
    update public.parsed_payment_events
    set receiver_phone_hash = receiver_hash,
        collection_id = p_collection_id
    where id = p_event_id;
  end if;

  payment_id := public.post_payment_from_event(
    p_event_id,
    p_payment_intent_id,
    p_collection_id,
    'Admin verified allocation: ' || btrim(p_reason)
  );
  perform public.create_audit_log(
    'payment.allocated.admin_verified', 'payment', payment_id,
    jsonb_build_object(
      'parsed_event_id', p_event_id,
      'payment_intent_id', p_payment_intent_id,
      'collection_id', p_collection_id,
      'reason', btrim(p_reason)
    )
  );
  return jsonb_build_object('status', 'allocated', 'payment_id', payment_id);
end;
$$;


ALTER FUNCTION public.admin_manual_allocate_payment(p_event_id uuid, p_collection_id uuid, p_payment_intent_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: admin_overview(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_overview() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare
  review_count bigint;
  unallocated_count bigint;
  balanced_count bigint;
  payee_count bigint;
begin
  perform public.assert_admin_permission('overview.read');
  review_count := (public.admin_list_collect_reconciliations(null,null,1,0,'created_at_desc')->>'total')::bigint;
  unallocated_count := (public.admin_list_collect_transactions(null,'unallocated',1,0,'created_at_desc')->>'total')::bigint;
  balanced_count := (public.admin_list_collect_ledgers(null,'balanced',1,0,'created_at_desc')->>'total')::bigint;
  payee_count := (public.admin_list_collect_payees(null,'active',1,0,'created_at_desc')->>'total')::bigint;
  return jsonb_build_object('metrics', jsonb_build_array(
    jsonb_build_object('label','Open reconciliations','value',review_count,
      'status',case when review_count>0 then 'needs_review' else 'active' end),
    jsonb_build_object('label','Unallocated transactions','value',unallocated_count,
      'status',case when unallocated_count>0 then 'needs_review' else 'active' end),
    jsonb_build_object('label','Balanced ledgers','value',balanced_count,'status','active'),
    jsonb_build_object('label','Active payees','value',payee_count,'status','active')
  ));
end;
$$;


