--
-- Name: admin_preview_receipt_backlog_v1(integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_preview_receipt_backlog_v1(p_limit integer DEFAULT 20, p_before_captured_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_before_snapshot_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare rows jsonb; last_row jsonb; more boolean;
begin
  perform collect_hybrid.require_receipt_monitor_actor();
  if p_limit is null or p_limit not between 1 and 50
    or ((p_before_captured_at is null)<>(p_before_snapshot_id is null))
    or (p_before_captured_at is not null and not isfinite(p_before_captured_at)) then
    raise exception 'receipt_monitor_request_invalid' using errcode='22023';end if;
  select coalesce(jsonb_agg(collect_hybrid.receipt_backlog_preview_row(s.id) order by s.captured_at desc,s.id desc),'[]'::jsonb)
    into rows from (select snapshot.* from collect_hybrid.momo_balance_snapshots snapshot
      where snapshot.event_type='receipt' and not exists(select 1 from collect_hybrid.sms_notification_outbox o
        where o.payment_id=snapshot.payment_id and o.template_key='buri_munsi.payment_received')
      and (p_before_captured_at is null or (snapshot.captured_at,snapshot.id)<(p_before_captured_at,p_before_snapshot_id))
      order by snapshot.captured_at desc,snapshot.id desc limit p_limit+1) s;
  more:=jsonb_array_length(rows)>p_limit;
  if more then rows:=rows-(jsonb_array_length(rows)-1);end if;
  last_row:=rows->(jsonb_array_length(rows)-1);
  return jsonb_build_object('contract_version',1,'checked_at',clock_timestamp(),'scope','collect_platform',
    'catch_up','policy_pending','historical_enqueue_enabled',false,'rows',rows,'limit',p_limit,
    'next_cursor',case when more then jsonb_build_object('captured_at',last_row->'captured_at','snapshot_id',last_row->'snapshot_id') else null end);
end $$;


ALTER FUNCTION public.admin_preview_receipt_backlog_v1(p_limit integer, p_before_captured_at timestamp with time zone, p_before_snapshot_id uuid) OWNER TO postgres;

--
-- Name: admin_propose_bank_allocation(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_propose_bank_allocation(p_bank_transaction_id uuid, p_bank_transfer_intent_id uuid, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  request public.bank_allocation_change_requests%rowtype;
  transaction_row public.bank_transactions%rowtype;
  intent public.bank_transfer_intents%rowtype;
begin
  perform public.assert_admin_permission('bank_allocations.propose');
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Allocation reason must be at least 8 characters';
  end if;
  select * into transaction_row
  from public.bank_transactions
  where id = p_bank_transaction_id
  for update;
  select * into intent
  from public.bank_transfer_intents
  where id = p_bank_transfer_intent_id
  for update;
  if transaction_row.id is null or intent.id is null then
    raise exception 'Bank transaction and transfer intent are required';
  end if;
  if transaction_row.currency <> intent.currency
     or transaction_row.amount_minor <> intent.amount_minor then
    raise exception 'Manual allocation requires an exact amount and currency match';
  end if;
  if transaction_row.status in ('reconciled', 'returned')
     or intent.status in ('reconciled', 'returned', 'cancelled', 'expired') then
    raise exception 'The transaction or transfer intent is no longer allocatable';
  end if;
  if exists (
    select 1 from public.bank_transaction_allocations allocation
    where allocation.bank_transaction_id = transaction_row.id
       or allocation.bank_transfer_intent_id = intent.id
  ) then
    raise exception 'The transaction or transfer intent is already allocated';
  end if;
  insert into public.bank_allocation_change_requests (
    bank_transaction_id, bank_transfer_intent_id, reason, proposed_by
  ) values (
    transaction_row.id, intent.id, btrim(p_reason), auth.uid()
  ) returning * into request;
  perform public.create_audit_log(
    'bank_allocation.proposed',
    'bank_allocation_change_request',
    request.id,
    jsonb_build_object(
      'bank_transaction_id', transaction_row.id,
      'bank_transfer_intent_id', intent.id,
      'reason', request.reason
    )
  );
  return to_jsonb(request);
end;
$$;


ALTER FUNCTION public.admin_propose_bank_allocation(p_bank_transaction_id uuid, p_bank_transfer_intent_id uuid, p_reason text) OWNER TO postgres;

--
-- Name: admin_propose_bank_destination(text, text, text, text, boolean, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_propose_bank_destination(p_beneficiary_name text, p_iban text, p_bic text, p_bank_name text, p_supports_instant boolean, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  request public.bank_destination_change_requests%rowtype;
  clean_iban text := public.normalize_iban(p_iban);
  clean_bic text := upper(regexp_replace(coalesce(p_bic, ''), '[^A-Za-z0-9]', '', 'g'));
begin
  perform public.assert_admin_permission('bank_details.propose');
  if clean_iban !~ '^[A-Z]{2}[0-9]{2}[A-Z0-9]{11,30}$'
     or clean_iban like 'XX00%'
     or clean_iban like '%PLACEHOLDER%' then
    raise exception 'A valid non-placeholder IBAN is required';
  end if;
  if clean_bic !~ '^[A-Z0-9]{8}([A-Z0-9]{3})?$'
     or clean_bic like 'PLACEH%' then
    raise exception 'A valid non-placeholder BIC is required';
  end if;
  if char_length(btrim(coalesce(p_beneficiary_name, ''))) < 3
     or char_length(btrim(coalesce(p_bank_name, ''))) < 2 then
    raise exception 'Beneficiary and bank names are required';
  end if;
  if char_length(btrim(coalesce(p_reason, ''))) < 8 then
    raise exception 'Change reason must be at least 8 characters';
  end if;

  insert into public.bank_destination_change_requests (
    beneficiary_name, iban, bic, bank_name, currency,
    supports_instant, status, reason, proposed_by
  ) values (
    btrim(p_beneficiary_name), clean_iban, clean_bic, btrim(p_bank_name),
    'EUR', coalesce(p_supports_instant, true), 'pending', btrim(p_reason), auth.uid()
  ) returning * into request;

  perform public.create_audit_log(
    'bank_destination.change_proposed',
    'bank_destination_change_request',
    request.id,
    jsonb_build_object(
      'beneficiary_name', request.beneficiary_name,
      'iban_masked', public.mask_iban(request.iban),
      'bic', request.bic,
      'bank_name', request.bank_name,
      'supports_instant', request.supports_instant,
      'reason', request.reason
    )
  );
  return to_jsonb(request) - 'iban' || jsonb_build_object('iban_masked', public.mask_iban(request.iban));
end;
$_$;


ALTER FUNCTION public.admin_propose_bank_destination(p_beneficiary_name text, p_iban text, p_bic text, p_bank_name text, p_supports_instant boolean, p_reason text) OWNER TO postgres;

--
-- Name: admin_read_exception_escalation_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_read_exception_escalation_v1(p_escalation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d collect_ops.exception_inbox_deliveries;r collect_ops.exception_inbox_reads;begin
 perform collect_ops.actor(false);
 select * into d from collect_ops.exception_inbox_deliveries where escalation_id=p_escalation_id and recipient_id=auth.uid();
 if d.escalation_id is null then raise exception 'exception_escalation_delivery_unavailable'using errcode='42501';end if;
 insert into collect_ops.exception_inbox_reads values(d.escalation_id,auth.uid(),clock_timestamp())on conflict do nothing;
 select * into r from collect_ops.exception_inbox_reads where escalation_id=d.escalation_id;
 return jsonb_build_object('contract_version',1,'escalation_id',r.escalation_id,'read_at',collect_ops.utc(r.read_at),'source_resolved',false);
end$$;


ALTER FUNCTION public.admin_read_exception_escalation_v1(p_escalation_id uuid) OWNER TO postgres;

