--
-- Name: admin_receipt_overview_v1(text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_receipt_overview_v1(p_country text DEFAULT 'RW'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare session_id uuid; t timestamptz; day_start timestamptz; day_end timestamptz;
  posted jsonb; receipts jsonb; receipt_access boolean;
begin
  session_id:=public._lock_notification_registration_session();
  perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));
  if not collect_hybrid.admin_overview_authorized(auth.uid(),session_id,'overview.read') then
    raise exception 'overview_permission_required' using errcode='42501';
  end if;
  if coalesce(upper(btrim(p_country)),'RW')<>'RW' then
    raise exception 'overview_country_invalid' using errcode='22023';
  end if;
  receipt_access:=collect_hybrid.admin_overview_authorized(auth.uid(),session_id,'notifications.read');
  t:=clock_timestamp();
  day_start:=date_trunc('day',t at time zone 'Africa/Kigali') at time zone 'Africa/Kigali';
  day_end:=day_start+interval '24 hours';
  -- public.payments is the canonical Rwanda RWF posting source. Reversed
  -- payments are excluded; this is currently-posted value, not gross turnover,
  -- a wallet balance or bank/diaspora rail aggregation.
  -- Both subqueries use the same SQL statement snapshot. The read timestamp
  -- is captured after evaluation; crossing midnight fails closed for refresh.
  select
    (select jsonb_build_object('count',count(*),
      'value_rwf',coalesce(sum(p.amount_rwf),0)::text)
     from public.payments p where p.status='posted' and p.currency='RWF'
       and p.provider_network in ('mtn_momo','airtel_money')
       and p.posted_at>=day_start and p.posted_at<day_end and p.posted_at<=t),
    case when receipt_access then
      (select jsonb_build_object('queued',count(*) filter(where state='queued'),
        'awaiting_confirmation',count(*) filter(where state='awaiting_confirmation'),
        'oldest_pending_at',min(created_at) filter(where state in ('queued','awaiting_confirmation')),
        'failed_no_send',count(*) filter(where state='failed_no_send'),
        'uncertain',count(*) filter(where state='uncertain'),
        'send_started',count(*) filter(where state='send_started'))
       from collect_hybrid.sms_notification_outbox)
      else null end into posted,receipts;
  t:=clock_timestamp();
  if t>=day_end then
    raise exception 'overview_day_changed' using errcode='40001';
  end if;
  return jsonb_build_object('contract_version',1,'scope','rwanda_momo','country_code','RW',
    'timezone','Africa/Kigali','checked_at',t,'sample_valid_until',t+interval '60 seconds',
    'day_start',day_start,'day_end',day_end,'posted',posted,
    'receipts_state',case when receipt_access then 'available' else 'denied' end,
    'receipts',receipts);
end $$;


ALTER FUNCTION public.admin_receipt_overview_v1(p_country text) OWNER TO postgres;

--
-- Name: admin_reconcile_receipt_backlog_v1(uuid, uuid[], text[]); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_reconcile_receipt_backlog_v1(p_request_id uuid, p_snapshot_ids uuid[], p_review_versions text[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
begin
  perform collect_hybrid.require_receipt_monitor_actor();
  if p_request_id is null or p_snapshot_ids is null or p_review_versions is null
    or cardinality(p_snapshot_ids) not between 1 and 25
    or cardinality(p_review_versions)<>cardinality(p_snapshot_ids)
    or array_position(p_snapshot_ids,null) is not null
    or exists(select 1 from unnest(p_review_versions) v where v is null or v !~ '^[a-f0-9]{64}$') then
    raise exception 'receipt_monitor_request_invalid' using errcode='22023';end if;
  -- Historical consent/contact snapshots cannot be reconstructed from current
  -- revisions. No approved policy exists: refuse without enqueue or mutation.
  return jsonb_build_object('contract_version',1,'ok',false,'code','CATCHUP_POLICY_PENDING',
    'request_id',p_request_id,'queued',0,'historical_enqueue_enabled',false);
end $_$;


ALTER FUNCTION public.admin_reconcile_receipt_backlog_v1(p_request_id uuid, p_snapshot_ids uuid[], p_review_versions text[]) OWNER TO postgres;

--
-- Name: admin_record_operator_note(text, uuid, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.admin_record_operator_note(p_entity_type text, p_entity_id uuid, p_body text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  note_id uuid;
  normalized_entity_type text := trim(coalesce(p_entity_type, ''));
  normalized_body text := trim(coalesce(p_body, ''));
begin
  if normalized_body = '' then
    raise exception 'Note body is required';
  end if;

  case normalized_entity_type
    when 'collection' then perform assert_admin_permission('collections.read');
    when 'profile' then perform assert_admin_permission('users.read');
    when 'payment_intent' then perform assert_admin_permission('payments.read');
    when 'parsed_payment_event' then perform assert_admin_permission('payment_events.read');
    when 'payment_receiver' then perform assert_admin_permission('collections.read');
    when 'raw_payment_sms' then perform assert_admin_permission('sms.metadata.read');
    else raise exception 'Unsupported admin note entity type: %', normalized_entity_type;
  end case;

  insert into admin_notes (entity_type, entity_id, body, created_by)
  values (normalized_entity_type, p_entity_id, normalized_body, auth.uid())
  returning id into note_id;

  perform create_audit_log(
    'admin.operator_note.recorded',
    normalized_entity_type,
    p_entity_id,
    jsonb_build_object('note_id', note_id)
  );

  return jsonb_build_object('ok', true, 'note_id', note_id);
end;
$$;


ALTER FUNCTION public.admin_record_operator_note(p_entity_type text, p_entity_id uuid, p_body text) OWNER TO postgres;

