--

CREATE FUNCTION public.audit_admin_runtime_metadata_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  metadata_key text;
begin
  metadata_key := case
    when tg_op = 'DELETE' then coalesce(
      to_jsonb(old)->>'key',
      to_jsonb(old)->>'rpc_name',
      to_jsonb(old)->>'id'
    )
    else coalesce(
      to_jsonb(new)->>'key',
      to_jsonb(new)->>'rpc_name',
      to_jsonb(new)->>'id'
    )
  end;

  if auth.uid() is not null then
    perform create_audit_log(
      'admin_runtime_metadata.' || lower(tg_op),
      tg_table_name,
      null,
      jsonb_build_object('key', metadata_key)
    );
  end if;

  if tg_op = 'DELETE' then
    return old;
  end if;
  return new;
end;
$$;


ALTER FUNCTION public.audit_admin_runtime_metadata_change() OWNER TO postgres;

