--
-- Name: create_private_group_with_owner_attested(text, text, text, text, text, text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_private_group_with_owner_attested(group_name text, group_description text, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text, group_collection_type text, group_category_subtype text, group_purpose_label text, native_capability uuid) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  created_group_id uuid;
  profile_provider text;
begin
  perform collect_profile_access.assert_ready('rwanda');
  select profile.momo_provider into profile_provider
  from public.profiles profile
  where profile.id = auth.uid() and profile.country_code = 'RW';
  if profile_provider not in ('mtn_momo', 'airtel_money') then
    raise exception 'Complete the Rwanda MoMo profile before creating a group';
  end if;

  created_group_id := public.create_group_with_owner_attested(
    group_name,
    group_description,
    receiver_momo_number,
    receiver_momo_number_hash,
    receiver_label,
    group_collection_type,
    group_category_subtype,
    group_purpose_label,
    false,
    native_capability
  );
  update public.collection_receivers
  set network = profile_provider
  where collection_id = created_group_id
    and receiver_user_id = auth.uid();
  return created_group_id;
end;
$$;


ALTER FUNCTION public.create_private_group_with_owner_attested(group_name text, group_description text, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text, group_collection_type text, group_category_subtype text, group_purpose_label text, native_capability uuid) OWNER TO postgres;

--
-- Name: create_private_group_with_owner_media_attested(text, text, text, text, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.create_private_group_with_owner_media_attested(group_name text, group_description text, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text, group_collection_type text, group_category_subtype text, group_purpose_label text, native_capability uuid, group_image_url text DEFAULT NULL::text, group_accent_color_hex text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
declare
  created_group_id uuid;
begin
  if auth.uid() is null then raise exception 'Authentication required'; end if;
  if group_accent_color_hex is not null and group_accent_color_hex !~ '^#[0-9A-Fa-f]{6}$' then
    raise exception 'Invalid group colour' using errcode = '22023';
  end if;
  if octet_length(coalesce(group_image_url, '')) > 7340032 then
    raise exception 'Choose a smaller group photo' using errcode = '22023';
  end if;
  created_group_id := public.create_private_group_with_owner_attested(
    group_name, group_description, receiver_momo_number,
    receiver_momo_number_hash, receiver_label, group_collection_type,
    group_category_subtype, group_purpose_label, native_capability
  );
  update public.collections
  set cover_image_url = nullif(trim(group_image_url), ''),
      accent_color_hex = nullif(trim(group_accent_color_hex), '')
  where id = created_group_id and creator_user_id = auth.uid();
  if not found then raise exception 'Group owner could not be verified'; end if;
  return created_group_id;
end;
$_$;


ALTER FUNCTION public.create_private_group_with_owner_media_attested(group_name text, group_description text, receiver_momo_number text, receiver_momo_number_hash text, receiver_label text, group_collection_type text, group_category_subtype text, group_purpose_label text, native_capability uuid, group_image_url text, group_accent_color_hex text) OWNER TO postgres;

