--
-- Name: gateway_archive_attempt_v3(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_archive_attempt_v3(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare a collect_gateway_dispatch.attempts;arm collect_gateway_dispatch.arms;prior collect_gateway_archive.requests;
 refs jsonb;x jsonb;cb collect_gateway_dispatch.callbacks;r collect_gateway_dispatch.requests;
 t timestamptz;idx integer:=0;n integer;reason text;ack uuid;result jsonb;ref_callback uuid;ref_request uuid;digest text;begin
 perform collect_gateway_archive.require_request(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['attempt_id','fence_version','body_sha256','destination_sha256','callback_requests']);
 if not pg_try_advisory_xact_lock(hashtextextended('gateway-dispatch-request:'||p_request_id::text,0))then raise exception 'gateway_archive_request_busy'using errcode='55000';end if;
 if exists(select 1 from collect_gateway.requests where request_id=p_request_id)or exists(select 1 from collect_gateway_dispatch.requests where request_id=p_request_id)then raise exception 'gateway_archive_request_conflict'using errcode='22023';end if;
 refs:=p_payload->'callback_requests';
 if jsonb_typeof(refs)is distinct from 'array'or jsonb_array_length(refs)not between 2 and 20
  or jsonb_typeof(p_payload->'body_sha256')is distinct from 'string'or(p_payload->>'body_sha256')!~'^[0-9a-f]{64}$'
  or jsonb_typeof(p_payload->'destination_sha256')is distinct from 'string'or(p_payload->>'destination_sha256')!~'^[0-9a-f]{64}$'then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
 select * into a from collect_gateway_dispatch.attempts where id=collect_gateway.payload_uuid(p_payload,'attempt_id')and device_id=p_device_id;
 if a.id is null or a.fence_version<>collect_gateway.payload_int(p_payload,'fence_version',1,1000000000)then raise exception 'gateway_dispatch_attempt_unavailable'using errcode='42501';end if;
 -- Callback folds use this receipt -> attempt order. Pause/revocation never
 -- reopens dispatch, but must not discard already signed prior-arm evidence.
 perform 1 from collect_hybrid.sms_notification_outbox where id=a.outbox_id for update;
 select * into a from collect_gateway_dispatch.attempts where id=a.id for update;
 perform 1 from collect_gateway.devices where id=p_device_id for share;
 select * into prior from collect_gateway_archive.requests where request_id=p_request_id;
 if prior.request_id is not null then
  if prior.device_id<>p_device_id or prior.request_sha256<>p_request_sha256 or prior.payload is distinct from p_payload then raise exception 'gateway_archive_request_conflict'using errcode='22023';end if;
  return prior.result||jsonb_build_object('replay',true);
 end if;
 select * into arm from collect_gateway_dispatch.arms where attempt_id=a.id;
 if arm.attempt_id is null or a.body_sha256 is distinct from(p_payload->>'body_sha256')or a.destination_sha256 is distinct from(p_payload->>'destination_sha256')
  or jsonb_array_length(refs)<>a.segment_count*2 then raise exception 'gateway_archive_binding_invalid'using errcode='22023';end if;
 for x in select value from jsonb_array_elements(refs)loop
  perform collect_gateway.payload_keys(x,array['callback_id','request_id','request_sha256']);
  ref_callback:=collect_gateway.payload_uuid(x,'callback_id');ref_request:=collect_gateway.payload_uuid(x,'request_id');digest:=x->>'request_sha256';
  if jsonb_typeof(x->'request_sha256')is distinct from 'string'or digest!~'^[0-9a-f]{64}$'or ref_request=p_request_id
   or ref_callback is distinct from((arm.callback_plan->(idx/2))->>case when idx%2=0 then 'sent_callback_id'else 'delivery_callback_id'end)::uuid then raise exception 'gateway_archive_binding_invalid'using errcode='22023';end if;
  select * into r from collect_gateway_dispatch.requests where request_id=ref_request and device_id=p_device_id and action='callback';
  select * into cb from collect_gateway_dispatch.callbacks where request_id=ref_request and attempt_id=a.id and callback_id=ref_callback;
  if r.request_id is null or cb.request_id is null then reason:=coalesce(reason,'CALLBACK_EVIDENCE_INCOMPLETE');
  elsif r.request_sha256<>digest or cb.segment_index<>idx/2 or cb.callback_kind<>(case when idx%2=0 then 'sent'else 'delivery'end) then raise exception 'gateway_archive_binding_invalid'using errcode='22023';
  end if;idx:=idx+1;
 end loop;
 if(select count(distinct value->>'request_id')from jsonb_array_elements(refs))<>jsonb_array_length(refs)then raise exception 'gateway_archive_binding_invalid'using errcode='22023';end if;
 select count(*)into n from collect_gateway_dispatch.callback_bindings b where b.attempt_id=a.id;
 if n<>a.segment_count*2 then reason:='CALLBACK_EVIDENCE_INCOMPLETE';end if;
 if a.state='uncertain'or exists(select 1 from collect_gateway_dispatch.callbacks where attempt_id=a.id and result_code<>-1)
  or exists(select 1 from collect_gateway_dispatch.callbacks where attempt_id=a.id group by callback_id having count(distinct jsonb_build_array(result_code,tp_status))>1)then reason:='CALLBACK_EVIDENCE_UNCERTAIN';
 elsif a.state<>'observed_sent'or(select count(distinct callback_id)from collect_gateway_dispatch.callbacks where attempt_id=a.id)<>a.segment_count*2 then reason:=coalesce(reason,'CALLBACK_EVIDENCE_INCOMPLETE');end if;
 if exists(select 1 from collect_gateway_archive.acknowledgements where attempt_id=a.id)then reason:='ATTEMPT_ALREADY_ACKNOWLEDGED';end if;
 t:=clock_timestamp();
 if reason is null then
  ack:=gen_random_uuid();insert into collect_gateway_archive.acknowledgements values(ack,a.id,p_request_id,p_device_id,refs,t);
 end if;
 result:=jsonb_build_object('request_id',p_request_id,'device_id',p_device_id,'attempt_id',a.id,'fence_version',a.fence_version,
  'ok',reason is null,'code',reason,'archive_ack_id',ack,'receipt_id',case when reason is null then a.outbox_id end,
  'body_sha256',a.body_sha256,'destination_sha256',a.destination_sha256,'segment_count',a.segment_count,
  'callback_requests',case when reason is null then refs end,'recorded_at',collect_gateway.utc(t),'replay',false,
  'evidence_kind',case when reason is null then 'complete_framework_callback_observations'end,
  'carrier_proof',false,'delivery_proven',false,'send_authority',false);
 insert into collect_gateway_archive.requests values(p_request_id,p_device_id,p_request_sha256,p_payload,result,t);return result;
end$_$;


ALTER FUNCTION public.gateway_archive_attempt_v3(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_archive_lookup_v3(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_archive_lookup_v3(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare target uuid;r collect_gateway_archive.requests;begin
 perform collect_gateway_archive.require_request(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['target_request_id']);target:=collect_gateway.payload_uuid(p_payload,'target_request_id');
 if target=p_request_id then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
 select * into r from collect_gateway_archive.requests where request_id=target and device_id=p_device_id;
 return jsonb_build_object('target_request_id',target,'outcome',case when r.request_id is null then 'unknown'else 'recorded'end,'recorded_result',r.result);
end$$;


ALTER FUNCTION public.gateway_archive_lookup_v3(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_arm_dispatch_v2(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_arm_dispatch_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare a collect_gateway_dispatch.attempts;r collect_receipt_operations.runs;o collect_hybrid.sms_notification_outbox;h collect_gateway.health_observations;
 prior jsonb;cb jsonb;idx integer;seen uuid[]:='{}';sid uuid;did uuid;t timestamptz;result jsonb;attempt uuid;fence integer;begin
 perform collect_gateway_dispatch.request_lock(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['attempt_id','fence_version','body_sha256','destination_sha256','callbacks','reservation_sha256']);
 attempt:=collect_gateway.payload_uuid(p_payload,'attempt_id');fence:=collect_gateway.payload_int(p_payload,'fence_version',1,1000000000);
 if jsonb_typeof(p_payload->'callbacks')is distinct from 'array'or jsonb_array_length(p_payload->'callbacks')not between 1 and 10 then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
 foreach did in array array[attempt,p_request_id]loop seen:=array_append(seen,did);end loop;
 idx:=0;for cb in select value from jsonb_array_elements(p_payload->'callbacks')loop
  perform collect_gateway.payload_keys(cb,array['segment_index','sent_callback_id','delivery_callback_id']);
  if collect_gateway.payload_int(cb,'segment_index',0,9)<>idx then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
  sid:=collect_gateway.payload_uuid(cb,'sent_callback_id');did:=collect_gateway.payload_uuid(cb,'delivery_callback_id');
  if sid=any(seen)or did=any(seen)or sid=did then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
  seen:=seen||array[sid,did];idx:=idx+1;
 end loop;
 if jsonb_typeof(p_payload->'reservation_sha256')is distinct from 'string'or(p_payload->>'reservation_sha256')!~'^[0-9a-f]{64}$'
  or jsonb_typeof(p_payload->'body_sha256')is distinct from 'string'or jsonb_typeof(p_payload->'destination_sha256')is distinct from 'string'then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
 select * into a from collect_gateway_dispatch.attempts where id=attempt;
 if a.id is null or a.device_id<>p_device_id or a.fence_version<>fence then raise exception 'gateway_dispatch_attempt_unavailable'using errcode='42501';end if;
 r:=collect_receipt_operations.require_run(a.run_id,a.fence_version,a.principal_id);
 select * into o from collect_hybrid.sms_notification_outbox where id=a.outbox_id for update;
 select * into a from collect_gateway_dispatch.attempts where id=attempt for update;
 h:=collect_gateway_dispatch.ready_health(p_device_id);prior:=collect_gateway_dispatch.replay(p_device_id,p_request_id,'arm_dispatch',p_request_sha256,p_payload);
 if prior is not null then return prior;end if;
 if a.state<>'granted'or a.expires_at<=clock_timestamp()or o.state<>'queued'or a.policy_revision<>r.policy_revision
  or a.body_sha256 is distinct from(p_payload->>'body_sha256')or a.destination_sha256 is distinct from(p_payload->>'destination_sha256')
  or idx<>a.segment_count or h.id is null or h.sim_revision_sha256 is distinct from a.sim_revision_sha256
  or exists(select 1 from collect_hybrid.sms_notification_attempts where outbox_id=o.id)
  or exists(select 1 from collect_hybrid.sms_notification_claim_requests where outbox_id=o.id)
  or exists(select 1 from collect_hybrid.sms_notification_confirmations where outbox_id=o.id)
  then raise exception 'gateway_dispatch_arm_fenced'using errcode='55000';end if;
 perform collect_gateway_dispatch.lock_source(o.id);t:=clock_timestamp();
 if t>=a.expires_at or t>=r.expires_at then raise exception 'gateway_dispatch_expired'using errcode='55000';end if;
 insert into collect_gateway_dispatch.arms values(a.id,p_request_id,p_payload->>'reservation_sha256',p_payload->'callbacks',h.id,t,a.expires_at);
 insert into collect_gateway_dispatch.callback_bindings
 select (x.value->>'sent_callback_id')::uuid,a.id,(x.value->>'segment_index')::integer,'sent'from jsonb_array_elements(p_payload->'callbacks')x
 union all select (x.value->>'delivery_callback_id')::uuid,a.id,(x.value->>'segment_index')::integer,'delivery'from jsonb_array_elements(p_payload->'callbacks')x;
 update collect_gateway_dispatch.attempts set state='send_started' ,updated_at=t where id=a.id;
 update collect_hybrid.sms_notification_outbox set state='send_started',fence_version=a.fence_version,attempt_count=1,updated_at=t where id=o.id;
 result:=jsonb_build_object('ok',true,'code','DISPATCH_ARMED','device_id',p_device_id,'request_id',p_request_id,'attempt_id',a.id,'fence_version',a.fence_version,
  'reservation_sha256',p_payload->>'reservation_sha256','armed_at',collect_gateway.utc(t),'expires_at',collect_gateway.utc(a.expires_at),'replay',false,'carrier_proof',false);
 perform collect_gateway_dispatch.store(p_device_id,p_request_id,'arm_dispatch',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'ORIGINAL_REQUEST_RECORDED',true));return result;
end$_$;


ALTER FUNCTION public.gateway_arm_dispatch_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_attempt_status_v2(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_attempt_status_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare a collect_gateway_dispatch.attempts;begin
 perform collect_gateway.require_service(p_device_id,p_request_id,p_request_sha256);
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'gateway_dispatch_snapshot_retry'using errcode='40001';end if;
 perform collect_gateway.payload_keys(p_payload,array['attempt_id','fence_version']);
 select * into a from collect_gateway_dispatch.attempts where id=collect_gateway.payload_uuid(p_payload,'attempt_id')and device_id=p_device_id;
 if a.id is null or a.fence_version<>collect_gateway.payload_int(p_payload,'fence_version',1,1000000000)then raise exception 'gateway_dispatch_attempt_unavailable'using errcode='42501';end if;
 -- Serialize against arm/callback; revoked devices may read their prior facts.
 perform 1 from collect_hybrid.sms_notification_outbox where id=a.outbox_id for share;
 return collect_gateway_dispatch.status(a.id);
end$$;


ALTER FUNCTION public.gateway_attempt_status_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_callback_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_callback_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d collect_gateway.devices;r jsonb;arm collect_gateway.dispatch_arms;cb uuid;attempt uuid;
 fence integer;idx integer;segments integer;rc integer;tp integer;t timestamptz;occurred timestamptz;
begin
 perform collect_gateway.require_service(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['callback_id','attempt_id','fence_version','segment_index','segment_count','body_sha256','destination_sha256','callback_kind','result_code','tp_status','occurred_at']);
 cb:=collect_gateway.payload_uuid(p_payload,'callback_id');attempt:=collect_gateway.payload_uuid(p_payload,'attempt_id');
 if cb=p_request_id then raise exception 'gateway_callback_id_invalid' using errcode='22023';end if;
 fence:=collect_gateway.payload_int(p_payload,'fence_version',1,1000000000);
 idx:=collect_gateway.payload_int(p_payload,'segment_index',0,9);segments:=collect_gateway.payload_int(p_payload,'segment_count',1,10);
 rc:=collect_gateway.payload_int(p_payload,'result_code',-1,200);
 if jsonb_typeof(p_payload->'tp_status') is distinct from 'null' then tp:=collect_gateway.payload_int(p_payload,'tp_status',0,255);end if;
 if jsonb_typeof(p_payload->'body_sha256') is distinct from 'string' or coalesce(p_payload->>'body_sha256','') !~ '^[0-9a-f]{64}$'
  or jsonb_typeof(p_payload->'destination_sha256') is distinct from 'string' or coalesce(p_payload->>'destination_sha256','') !~ '^[0-9a-f]{64}$'
  or coalesce(p_payload->>'callback_kind','') not in('sent','delivery') then raise exception 'gateway_payload_invalid' using errcode='22023';end if;
 occurred:=collect_gateway.payload_time(p_payload,'occurred_at');
 select * into d from collect_gateway.devices where id=p_device_id for update;
 if d.id is null then raise exception 'gateway_device_not_found' using errcode='22023';end if;
 r:=collect_gateway.replay(d.id,p_request_id,'callback',p_request_sha256,p_payload);if r is not null then return r;end if;
 select * into arm from collect_gateway.dispatch_arms where device_id=d.id and attempt_id=attempt for share;
 if arm.id is null or arm.fence_version<>fence or arm.body_sha256<>p_payload->>'body_sha256'
  or arm.destination_sha256<>p_payload->>'destination_sha256' or arm.segment_count<>segments or idx>=segments then
  raise exception 'gateway_prior_arm_required' using errcode='42501';end if;
 t:=clock_timestamp();if occurred<arm.armed_at-interval '120 seconds' or occurred>t+interval '30 seconds' then raise exception 'gateway_callback_time_invalid' using errcode='22023';end if;
 if exists(select 1 from collect_gateway.segment_callbacks where callback_id=cb or (arm_id=arm.id and segment_index=idx and callback_kind=p_payload->>'callback_kind')) then
  raise exception 'gateway_callback_conflict' using errcode='22023';end if;
 r:=jsonb_build_object('callback_id',cb,'recorded_at',collect_gateway.utc(t),'replay',false,'carrier_proof',false);
 insert into collect_gateway.requests(request_id,device_id,action,request_sha256,payload,result,recorded_at) values(p_request_id,d.id,'callback',p_request_sha256,p_payload,r,t);
 insert into collect_gateway.segment_callbacks(callback_id,request_id,arm_id,device_id,segment_index,callback_kind,result_code,tp_status,occurred_at,recorded_at)
 values(cb,p_request_id,arm.id,d.id,idx,p_payload->>'callback_kind',rc,tp,occurred,t);
 return r;
end$_$;


ALTER FUNCTION public.gateway_callback_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_callback_v2(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_callback_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare a collect_gateway_dispatch.attempts;arm collect_gateway_dispatch.arms;o collect_hybrid.sms_notification_outbox;
 cb uuid;idx integer;n integer;code integer;tp integer;occurred timestamptz;t timestamptz;prior jsonb;fold jsonb;newstate text;result jsonb;begin
 perform collect_gateway_dispatch.request_lock(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['callback_id','attempt_id','fence_version','segment_index','segment_count','body_sha256','destination_sha256','callback_kind','result_code','tp_status','occurred_at']);
 cb:=collect_gateway.payload_uuid(p_payload,'callback_id');if cb=p_request_id then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
 idx:=collect_gateway.payload_int(p_payload,'segment_index',0,9);n:=collect_gateway.payload_int(p_payload,'segment_count',1,10);
 code:=collect_gateway.payload_int(p_payload,'result_code',-1,200);occurred:=collect_gateway.payload_time(p_payload,'occurred_at');
 if jsonb_typeof(p_payload->'tp_status')is distinct from 'null'then tp:=collect_gateway.payload_int(p_payload,'tp_status',0,255);end if;
 if jsonb_typeof(p_payload->'callback_kind')is distinct from 'string'or coalesce(p_payload->>'callback_kind','')not in('sent','delivery')or jsonb_typeof(p_payload->'body_sha256')is distinct from 'string'
  or jsonb_typeof(p_payload->'destination_sha256')is distinct from 'string'then raise exception 'gateway_payload_invalid'using errcode='22023';end if;
 select * into a from collect_gateway_dispatch.attempts where id=collect_gateway.payload_uuid(p_payload,'attempt_id');
 if a.id is null or a.device_id<>p_device_id then raise exception 'gateway_dispatch_attempt_unavailable'using errcode='42501';end if;
 -- Same receipt lock as arm, without reopening current mode/run authority.
 select * into o from collect_hybrid.sms_notification_outbox where id=a.outbox_id for update;
 select * into a from collect_gateway_dispatch.attempts where id=a.id for update;
 perform 1 from collect_gateway.devices where id=p_device_id for share;
 prior:=collect_gateway_dispatch.replay(p_device_id,p_request_id,'callback',p_request_sha256,p_payload);if prior is not null then return prior;end if;
 select * into arm from collect_gateway_dispatch.arms where attempt_id=a.id;t:=clock_timestamp();
 if arm.attempt_id is null or a.fence_version<>collect_gateway.payload_int(p_payload,'fence_version',1,1000000000)
  or a.body_sha256 is distinct from(p_payload->>'body_sha256')or a.destination_sha256 is distinct from(p_payload->>'destination_sha256')
  or n<>a.segment_count or idx>=n or cb is distinct from((arm.callback_plan->idx)->>case p_payload->>'callback_kind'when 'sent'then 'sent_callback_id'else 'delivery_callback_id'end)::uuid
  or occurred<arm.armed_at-interval '120 seconds'or occurred>t+interval '30 seconds'then raise exception 'gateway_dispatch_callback_binding_invalid'using errcode='22023';end if;
 -- Changed signed observations are retained under a new request UUID and fold
 -- to uncertainty; original callback identities remain fixed by the arm plan.
 insert into collect_gateway_dispatch.callbacks values(p_request_id,cb,a.id,idx,p_payload->>'callback_kind',code,tp,occurred,t);
 fold:=collect_gateway_dispatch.status(a.id);
 newstate:=case when a.state='uncertain'or(fold->>'conflicting_observations')::boolean
   or exists(select 1 from collect_gateway_dispatch.callbacks where attempt_id=a.id and callback_kind='sent'and result_code<>-1)then 'uncertain'
  when(fold->>'sent_observations')::integer=a.segment_count then 'observed_sent'else 'send_started'end;
 update collect_gateway_dispatch.attempts set state=newstate,updated_at=t where id=a.id;
 update collect_hybrid.sms_notification_outbox set state=newstate,observed_sent_at=case when newstate='observed_sent'then coalesce(observed_sent_at,t)else observed_sent_at end,updated_at=t where id=o.id;
 result:=jsonb_build_object('callback_id',cb,'recorded_at',collect_gateway.utc(t),'replay',false,'carrier_proof',false,'state',newstate,
  'sent_observations',fold->'sent_observations','delivery_observations',fold->'delivery_observations','conflicting_observations',fold->'conflicting_observations');
 perform collect_gateway_dispatch.store(p_device_id,p_request_id,'callback',p_request_sha256,p_payload,result);return result;
end$$;


ALTER FUNCTION public.gateway_callback_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_device_key_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_device_key_v1(p_device_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d collect_gateway.devices;begin
 if auth.role() is distinct from 'service_role' then raise exception 'gateway_service_required' using errcode='42501';end if;
 select * into d from collect_gateway.devices where id=p_device_id;
 if d.id is null then raise exception 'gateway_device_not_found' using errcode='22023';end if;
 return jsonb_build_object('device_id',d.id,'state',d.state,'public_key_spki_base64',d.public_key_spki_base64,'key_sha256',d.key_sha256,'installation_id',d.installation_id,'signing_certificate_sha256',d.signing_certificate_sha256);
end$$;


ALTER FUNCTION public.gateway_device_key_v1(p_device_id uuid) OWNER TO postgres;

--
-- Name: gateway_dispatch_grant_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_dispatch_grant_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare d collect_gateway.devices;r jsonb;t timestamptz;begin
 perform collect_gateway.require_service(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array[]::text[]);
 select * into d from collect_gateway.devices where id=p_device_id for update;
 if d.id is null then raise exception 'gateway_device_not_found' using errcode='22023';end if;
 if d.state='revoked' then raise exception 'gateway_device_revoked' using errcode='42501';end if;
 r:=collect_gateway.replay(d.id,p_request_id,'dispatch_grant',p_request_sha256,p_payload);if r is not null then return r;end if;
 t:=clock_timestamp();r:=jsonb_build_object('ok',false,'code','GATEWAY_DISPATCH_AUTHORITY_PENDING','device_id',d.id,'request_id',p_request_id,'replay',false);
 insert into collect_gateway.requests(request_id,device_id,action,request_sha256,payload,result,recorded_at) values(p_request_id,d.id,'dispatch_grant',p_request_sha256,p_payload,r,t);
 return r;
end$$;


ALTER FUNCTION public.gateway_dispatch_grant_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_dispatch_grant_v2(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_dispatch_grant_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare p collect_receipt_operations.policy;r collect_receipt_operations.runs;o collect_hybrid.sms_notification_outbox;
 h collect_gateway.health_observations;a collect_gateway_dispatch.attempts;prior jsonb;result jsonb;reservation uuid;t timestamptz;expiry timestamptz;n integer;begin
 perform collect_gateway_dispatch.request_lock(p_device_id,p_request_id,p_request_sha256);perform collect_gateway.payload_keys(p_payload,array[]::text[]);
 -- Lock current policy before any run/outbox/device authority, matching quota.
 select * into p from collect_receipt_operations.policy where singleton for update;
 if not exists(select 1 from collect_gateway.devices where id=p_device_id and state='active')then raise exception 'gateway_device_not_active'using errcode='42501';end if;
 prior:=collect_gateway_dispatch.replay(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload);if prior is not null then return prior;end if;
 if p.emergency_stop or p.mode not in('Live-limited','Live')then return collect_gateway_dispatch.store(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'OPERATIONS_PAUSED'));end if;
 select * into r from collect_receipt_operations.runs where device_id=p_device_id and completed_at is null and expires_at>clock_timestamp()
  and policy_revision=p.revision and mode in('Live-limited','Live')order by fence_version desc limit 1;
 if r.id is null then return collect_gateway_dispatch.store(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'NO_CURRENT_RUN'));end if;
 r:=collect_receipt_operations.require_run(r.id,r.fence_version,r.principal_id);
 select * into o from collect_hybrid.sms_notification_outbox j where state='queued'and template_version=2 and collection_id=any(r.collection_ids)
  and fence_version=0 and attempt_count=0 and claim_token is null and claimed_by is null and claim_expires_at is null
  and suppression_reason is null and observed_sent_at is null
  and not exists(select 1 from collect_gateway_dispatch.attempts automatic where automatic.outbox_id=j.id)
  and not exists(select 1 from collect_hybrid.sms_notification_attempts assisted where assisted.outbox_id=j.id)
  and not exists(select 1 from collect_hybrid.sms_notification_claim_requests c where c.outbox_id=j.id)
  and not exists(select 1 from collect_hybrid.sms_notification_confirmations c where c.outbox_id=j.id)
  order by created_at,id limit 1 for update skip locked;
 if o.id is null then return collect_gateway_dispatch.store(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'NO_ELIGIBLE_RECEIPT'));end if;
 perform collect_gateway_dispatch.lock_source(o.id);h:=collect_gateway_dispatch.ready_health(p_device_id);
 if h.id is null then return collect_gateway_dispatch.store(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'DEVICE_NOT_READY'));end if;
 n:=collect_gateway_dispatch.segment_count(o.message_body);reservation:=gen_random_uuid();
 result:=collect_receipt_operations.reserve_dispatch(r.id,r.fence_version,reservation,o.id,p_device_id,n);
 if not(result->>'ok')::boolean then return collect_gateway_dispatch.store(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'QUOTA_EXHAUSTED'));end if;
 t:=clock_timestamp();expiry:=least(r.expires_at,t+interval '30 seconds',least(h.reported_at,h.ingested_at)+interval '120 seconds',(date_trunc('day',t at time zone 'UTC')at time zone 'UTC')+interval '1 day');
 if expiry<=t then raise exception 'gateway_dispatch_expired'using errcode='55000';end if;
 insert into collect_gateway_dispatch.attempts(outbox_id,device_id,run_id,principal_id,fence_version,policy_revision,grant_request_id,reservation_id,body_sha256,destination_sha256,segment_count,health_observation_id,sim_revision_sha256,issued_at,expires_at,updated_at)
 values(o.id,p_device_id,r.id,r.principal_id,r.fence_version,r.policy_revision,p_request_id,reservation,o.body_sha256,o.destination_sha256,n,h.id,h.sim_revision_sha256,t,expiry,t) returning * into a;
 result:=jsonb_build_object('ok',true,'code','DISPATCH_GRANTED','device_id',p_device_id,'request_id',p_request_id,'attempt_id',a.id,'receipt_id',o.id,'run_id',r.id,
  'fence_version',r.fence_version,'policy_revision',r.policy_revision,'issued_at',collect_gateway.utc(t),'expires_at',collect_gateway.utc(expiry),'segment_count',n,
  'body',o.message_body,'destination_e164',o.destination_e164,'body_sha256',o.body_sha256,'destination_sha256',o.destination_sha256,'sim_revision_sha256',h.sim_revision_sha256,'replay',false);
 -- Durable request result is redacted; lost initial response never releases a
 -- reusable body/grant. Request lookup only reconciles recording, not sending.
 perform collect_gateway_dispatch.store(p_device_id,p_request_id,'dispatch_grant',p_request_sha256,p_payload,collect_gateway_dispatch.refusal(p_device_id,p_request_id,'ORIGINAL_REQUEST_RECORDED',true));return result;
end$$;


ALTER FUNCTION public.gateway_dispatch_grant_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_heartbeat_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_heartbeat_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $_$
declare d collect_gateway.devices;r jsonb;t timestamptz;observed timestamptz;h uuid;
begin
 perform collect_gateway.require_service(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['sms_permission','network','telephony','sim_selected','sim_revision_sha256','local_pause','reported_at']);
 if jsonb_typeof(p_payload->'sms_permission') is distinct from 'boolean'
  or jsonb_typeof(p_payload->'sim_selected') is distinct from 'boolean'
  or jsonb_typeof(p_payload->'local_pause') is distinct from 'boolean'
  or coalesce(p_payload->>'network','') not in('validated','unvalidated','offline','unknown')
  or coalesce(p_payload->>'telephony','') not in('ready','unavailable','unknown')
  or ((p_payload->>'sim_selected')::boolean and (jsonb_typeof(p_payload->'sim_revision_sha256') is distinct from 'string' or coalesce(p_payload->>'sim_revision_sha256','') !~ '^[0-9a-f]{64}$'))
  or (not(p_payload->>'sim_selected')::boolean and jsonb_typeof(p_payload->'sim_revision_sha256') is distinct from 'null') then
  raise exception 'gateway_payload_invalid' using errcode='22023';end if;
 observed:=collect_gateway.payload_time(p_payload,'reported_at');
 select * into d from collect_gateway.devices where id=p_device_id for update;
 if d.id is null then raise exception 'gateway_device_not_found' using errcode='22023';end if;
 if d.state='revoked' then raise exception 'gateway_device_revoked' using errcode='42501';end if;
 r:=collect_gateway.replay(d.id,p_request_id,'heartbeat',p_request_sha256,p_payload);if r is not null then return r;end if;
 t:=clock_timestamp();if observed<t-interval '120 seconds' or observed>t+interval '30 seconds' then
  raise exception 'gateway_report_time_invalid' using errcode='22023';end if;
 h:=gen_random_uuid();r:=jsonb_build_object('observation_id',h,'ingested_at',collect_gateway.utc(t),'replay',false,'carrier_proof',false);
 insert into collect_gateway.requests(request_id,device_id,action,request_sha256,payload,result,recorded_at) values(p_request_id,d.id,'heartbeat',p_request_sha256,p_payload,r,t);
 insert into collect_gateway.health_observations(id,device_id,request_id,reported_at,ingested_at,sms_permission,network,telephony,sim_selected,sim_revision_sha256,local_pause)
 values(h,d.id,p_request_id,observed,t,(p_payload->>'sms_permission')::boolean,p_payload->>'network',p_payload->>'telephony',(p_payload->>'sim_selected')::boolean,p_payload->>'sim_revision_sha256',(p_payload->>'local_pause')::boolean);
 return r;
end$_$;


ALTER FUNCTION public.gateway_heartbeat_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_reconcile_v1(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_reconcile_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare target uuid;r collect_gateway.requests;begin
 perform collect_gateway.require_service(p_device_id,p_request_id,p_request_sha256);
 perform collect_gateway.payload_keys(p_payload,array['target_request_id']);target:=collect_gateway.payload_uuid(p_payload,'target_request_id');
 if not exists(select 1 from collect_gateway.devices where id=p_device_id) then raise exception 'gateway_device_not_found' using errcode='22023';end if;
 select * into r from collect_gateway.requests where device_id=p_device_id and request_id=target;
 return jsonb_build_object('target_request_id',target,'outcome',case when r.request_id is null then 'unknown' else 'recorded' end,'recorded_action',r.action,'recorded_result',r.result);
end$$;


ALTER FUNCTION public.gateway_reconcile_v1(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: gateway_reconcile_v2(uuid, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.gateway_reconcile_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$declare target uuid;r collect_gateway_dispatch.requests;begin
 perform collect_gateway.require_service(p_device_id,p_request_id,p_request_sha256);
 if current_setting('transaction_isolation')<>'read committed'then raise exception 'gateway_dispatch_snapshot_retry'using errcode='40001';end if;
 perform collect_gateway.payload_keys(p_payload,array['target_request_id']);target:=collect_gateway.payload_uuid(p_payload,'target_request_id');
 if not exists(select 1 from collect_gateway.devices where id=p_device_id)then raise exception 'gateway_device_not_found'using errcode='22023';end if;
 select * into r from collect_gateway_dispatch.requests where request_id=target and device_id=p_device_id;
 return jsonb_build_object('target_request_id',target,'outcome',case when r.request_id is null then 'unknown'else 'recorded'end,'recorded_action',r.action,'recorded_result',case when r.action in('dispatch_grant','arm_dispatch')then collect_gateway_dispatch.refusal(p_device_id,r.request_id,'ORIGINAL_REQUEST_RECORDED',true)else r.result end);
end$$;


ALTER FUNCTION public.gateway_reconcile_v2(p_device_id uuid, p_request_id uuid, p_request_sha256 text, p_payload jsonb) OWNER TO postgres;

--
-- Name: generate_contribution_code(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_contribution_code() RETURNS text
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
declare
  candidate text;
begin
  loop
    candidate := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));
    exit when not exists (select 1 from payment_intents where contribution_code = candidate);
  end loop;
  return candidate;
end;
$$;


ALTER FUNCTION public.generate_contribution_code() OWNER TO postgres;

--
-- Name: generate_public_id(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.generate_public_id() RETURNS character
    LANGUAGE plpgsql
    SET search_path TO ''
    AS $$
declare candidate char(6); attempts integer := 0;
begin
  perform pg_advisory_xact_lock(hashtextextended('collect-numeric-member-id', 0));
  loop
    candidate := lpad(floor(random() * 1000000)::int::text, 6, '0')::char(6);
    if not exists(select 1 from public.profiles where public_id = candidate)
       and not exists(select 1 from collect_hybrid.member_records where collect_id = candidate) then
      return candidate;
    end if;
    attempts := attempts + 1;
    if attempts >= 1000 then raise exception 'Collect ID allocation requires review'; end if;
  end loop;
end; $$;


ALTER FUNCTION public.generate_public_id() OWNER TO postgres;

--
-- Name: get_active_policy_document(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_active_policy_document(p_kind text, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  with selected_document as (
    select pd.*
    from policy_documents pd
    where pd.kind = lower(trim(p_kind))
      and pd.locale in (coalesce(nullif(trim(p_locale), ''), 'en'), 'en')
      and pd.status = 'published'
      and pd.effective_at <= now()
    order by
      case when pd.locale = coalesce(nullif(trim(p_locale), ''), 'en') then 0 else 1 end,
      pd.effective_at desc,
      pd.version desc
    limit 1
  )
  select coalesce(
    (
      select jsonb_build_object(
        'id', sd.id,
        'kind', sd.kind,
        'locale', sd.locale,
        'version', sd.version,
        'title', sd.title,
        'summary', sd.summary,
        'effective_at', sd.effective_at,
        'sections', coalesce((
          select jsonb_agg(
            jsonb_build_object(
              'key', pds.section_key,
              'title', pds.title,
              'body', pds.body,
              'display_order', pds.display_order
            )
            order by pds.display_order, pds.section_key
          )
          from policy_document_sections pds
          where pds.policy_document_id = sd.id
        ), '[]'::jsonb)
      )
      from selected_document sd
    ),
    '{}'::jsonb
  );
$$;


ALTER FUNCTION public.get_active_policy_document(p_kind text, p_locale text) OWNER TO postgres;

--
-- Name: get_bank_transfer_destination(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_transfer_destination() RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  destination public.bank_transfer_destinations%rowtype;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;

  select * into destination
  from public.bank_transfer_destinations
  where currency = 'EUR'
  order by (status = 'active') desc, version desc
  limit 1;

  if destination.id is null then
    return '{}'::jsonb;
  end if;
  return public.bank_transfer_destination_json(destination);
end;
$$;


ALTER FUNCTION public.get_bank_transfer_destination() OWNER TO postgres;

--
-- Name: get_bank_transfer_intent(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_bank_transfer_intent(p_id uuid) RETURNS jsonb
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  result jsonb;
begin
  if auth.uid() is null then
    raise exception 'Authentication required';
  end if;
  select to_jsonb(intent) || jsonb_build_object(
    'destination', intent.destination_snapshot,
    'collection_title', collection.title
  ) into result
  from public.bank_transfer_intents intent
  join public.collections collection on collection.id = intent.collection_id
  where intent.id = p_id
    and intent.contributor_user_id = auth.uid();
  return coalesce(result, '{}'::jsonb);
end;
$$;


ALTER FUNCTION public.get_bank_transfer_intent(p_id uuid) OWNER TO postgres;

--
-- Name: get_collect_shadow_run_v1(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_collect_shadow_run_v1(p_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
declare r collect_security.shadow_supervisor_runs;
begin
  perform collect_security.require_shadow_actor();
  if p_request_id is null then raise exception 'shadow_request_invalid' using errcode='22023';end if;
  -- Read-only reconciliation after normal reauthentication never resumes the
  -- previous session's lease. Only the original actor sees this request lookup.
  select * into r from collect_security.shadow_supervisor_runs
    where request_id=p_request_id and actor_id=auth.uid();
  return jsonb_build_object('contract_version',1,'mode','shadow','scope','collect_platform',
    'found',r.id is not null,'run',collect_security.shadow_run_json(r.id));
end $$;


ALTER FUNCTION public.get_collect_shadow_run_v1(p_request_id uuid) OWNER TO postgres;

--
-- Name: get_collection_type_catalog(text, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.get_collection_type_catalog(p_country_code text DEFAULT 'RW'::text, p_locale text DEFAULT 'en'::text) RETURNS jsonb
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  select jsonb_build_object(
    'country_code', upper(coalesce(nullif(trim(p_country_code), ''), 'RW')),
    'locale', coalesce(nullif(trim(p_locale), ''), 'en'),
    'types', coalesce((
      select jsonb_agg(
        jsonb_build_object(
          'key', ctc.key,
          'label', ctc.label,
          'short_purpose', ctc.short_purpose,
          'icon_key', ctc.icon_key,
          'default_category_subtype', ctc.default_category_subtype,
          'default_purpose_template_key', ctc.default_purpose_template_key,
          'display_order', ctc.display_order,
          'subtypes', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'key', ccs.key,
                'label', ccs.label,
                'display_order', ccs.display_order
              )
              order by ccs.display_order, ccs.key
            )
            from collection_category_subtypes ccs
            where ccs.collection_type_key = ctc.key
              and ccs.enabled
          ), '[]'::jsonb),
          'purpose_templates', coalesce((
            select jsonb_agg(
              jsonb_build_object(
                'key', cpt.key,
                'label', cpt.label,
                'display_order', cpt.display_order
              )
              order by cpt.display_order, cpt.key
            )
            from collection_purpose_templates cpt
            where cpt.collection_type_key = ctc.key
              and cpt.enabled
          ), '[]'::jsonb)
        )
        order by ctc.display_order, ctc.key
      )
      from collection_type_catalog ctc
      where ctc.enabled
        and exists (
          select 1
          from collection_type_country_rules ctcr
          where ctcr.collection_type_key = ctc.key
            and ctcr.enabled
            and ctcr.country_code = upper(coalesce(nullif(trim(p_country_code), ''), 'RW'))
        )
    ), '[]'::jsonb)
  );
$$;


ALTER FUNCTION public.get_collection_type_catalog(p_country_code text, p_locale text) OWNER TO postgres;

