CREATE FUNCTION public.lock_notification_auth_activity() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  perform public._lock_notification_session_gate();
  return null;
end $$;


ALTER FUNCTION public.lock_notification_auth_activity() OWNER TO postgres;

--
-- Name: lock_notification_auth_revocation(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.lock_notification_auth_revocation() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
begin
  -- A multi-statement Auth transaction may already hold a shared activity
  -- gate. Never wait while upgrading that lock: another shared reader could
  -- be waiting for this transaction's Auth row. Abort atomically for a whole
  -- transaction retry instead of forming an upgrade deadlock.
  if exists(select 1 from pg_catalog.pg_locks where locktype='advisory'
      and pid=pg_catalog.pg_backend_pid() and classid=193517 and objid=141
      and objsubid=2 and mode='ShareLock' and granted)
    and not exists(select 1 from pg_catalog.pg_locks where locktype='advisory'
      and pid=pg_catalog.pg_backend_pid() and classid=193517 and objid=141
      and objsubid=2 and mode='ExclusiveLock' and granted) then
    if not pg_catalog.pg_try_advisory_xact_lock(193517,141) then
      raise exception 'notification_auth_revocation_retry' using errcode='40001';
    end if;
  else
    perform pg_catalog.pg_advisory_xact_lock(193517,141);
  end if;
  return null;
end $$;


ALTER FUNCTION public.lock_notification_auth_revocation() OWNER TO postgres;

--
-- Name: mark_bank_transfer_handoff_opened(uuid); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.mark_bank_transfer_handoff_opened(p_intent_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
declare
  intent public.bank_transfer_intents%rowtype;
begin
  update public.bank_transfer_intents
  set status = case when status = 'awaiting_transfer' then 'handoff_opened' else status end,
      handoff_opened_at = coalesce(handoff_opened_at, now()),
      updated_at = now()
  where id = p_intent_id
    and contributor_user_id = auth.uid()
    and status in ('awaiting_transfer', 'handoff_opened', 'awaiting_bank_evidence')
    and expires_at > now()
  returning * into intent;
  if intent.id is null then
    raise exception 'Active bank transfer request not found';
  end if;
  return to_jsonb(intent);
end;
$$;


ALTER FUNCTION public.mark_bank_transfer_handoff_opened(p_intent_id uuid) OWNER TO postgres;

