--
-- Name: member_collection_summary_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.member_collection_summary_view WITH (security_invoker='true') AS
 SELECT id AS collection_id,
    title,
    creator_user_id,
    ( SELECT (COALESCE(sum(le.amount_rwf) FILTER (WHERE (le.entry_type = 'collection_credit'::text)), (0)::numeric))::bigint AS "coalesce"
           FROM public.ledger_entries le
          WHERE (le.collection_id = c.id)) AS amount_raised_rwf,
    ( SELECT count(DISTINCT COALESCE((p.contributor_user_id)::text, (p.contributor_public_id)::text, (p.id)::text)) AS count
           FROM public.payments p
          WHERE ((p.collection_id = c.id) AND (p.status = 'posted'::text))) AS supporter_count,
    ( SELECT count(pi.id) AS count
           FROM public.payment_intents pi
          WHERE ((pi.collection_id = c.id) AND (pi.status = 'pending'::public.payment_intent_status))) AS pending_intent_count,
    ( SELECT count(DISTINCT ppe.id) AS count
           FROM (public.collection_receivers cr
             JOIN public.parsed_payment_events ppe ON (((ppe.receiver_user_id = cr.receiver_user_id) AND ((ppe.collection_id = c.id) OR ((ppe.collection_id IS NULL) AND (ppe.receiver_phone_hash = cr.momo_number_hash))))))
          WHERE ((cr.collection_id = c.id) AND (ppe.allocation_status = ANY (ARRAY['unallocated'::public.allocation_status, 'ambiguous'::public.allocation_status, 'needs_review'::public.allocation_status])))) AS exception_event_count,
    created_at,
    updated_at
   FROM public.collections c
  WHERE public.user_can_read_collection(id, auth.uid());


ALTER VIEW public.member_collection_summary_view OWNER TO postgres;

--
-- Name: member_collections_view; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.member_collections_view WITH (security_invoker='true') AS
 SELECT collection.id,
    collection.slug,
    collection.creator_user_id,
    collection.title,
    collection.description,
    collection.currency,
    collection.collection_type,
    collection.category_subtype,
    collection.purpose_label,
    collection.suggested_amount_rwf,
    false AS diaspora_enabled,
    '{}'::text[] AS diaspora_regions,
        CASE
            WHEN (collection.archived_at IS NOT NULL) THEN 'archived'::text
            ELSE collection.moderation_status
        END AS moderation_status,
        CASE
            WHEN (public.user_is_collection_admin(collection.id, auth.uid()) OR (EXISTS ( SELECT 1
               FROM public.collection_receivers receiver_check
              WHERE ((receiver_check.collection_id = collection.id) AND (receiver_check.receiver_user_id = auth.uid()) AND receiver_check.is_active)))) THEN receiver.momo_number
            ELSE NULL::text
        END AS receiver_momo_number,
    receiver.label AS receiver_display_label,
    receiver.network AS receiver_network,
    collection.created_at,
    collection.updated_at,
    collection.archived_at,
    collection.accent_color_hex,
    collection.recurring_cadence,
    (collection.public_status = 'public_approved'::public.collection_visibility) AS is_public,
    ((collection.creator_user_id = auth.uid()) OR (EXISTS ( SELECT 1
           FROM public.collection_members member_check
          WHERE ((member_check.collection_id = collection.id) AND (member_check.user_id = auth.uid()) AND (member_check.status = 'active'::public.member_status))))) AS is_member,
    collection.is_recurring,
    (collection.public_status)::text AS visibility_status,
    collection.is_platform_sponsored
   FROM (public.collections collection
     LEFT JOIN LATERAL ( SELECT route.momo_number,
            route.label,
            route.network
           FROM public.collection_receivers route
          WHERE ((route.collection_id = collection.id) AND route.is_active)
          ORDER BY route.created_at
         LIMIT 1) receiver ON (true))
  WHERE (public.user_can_read_collection(collection.id, auth.uid()) AND (collection.currency = 'RWF'::text) AND (NOT collection.diaspora_enabled));


ALTER VIEW public.member_collections_view OWNER TO postgres;

