202605230001	collect_baseline	{"create extension if not exists pgcrypto;\n\ncreate type collection_visibility as enum ('private', 'public_requested', 'public_approved', 'public_rejected', 'archived');\ncreate type member_role as enum ('owner', 'admin', 'receiver', 'member', 'contributor', 'viewer');\ncreate type member_status as enum ('invited', 'active', 'removed', 'left');\ncreate type payment_intent_status as enum ('pending', 'matched', 'expired', 'cancelled');\ncreate type allocation_status as enum ('unallocated', 'allocated', 'ambiguous', 'needs_review', 'ignored');\n\ncreate table profiles (\n  id uuid primary key references auth.users(id) on delete cascade,\n  public_id char(6) unique not null,\n  display_name text,\n  avatar_url text,\n  whatsapp_phone text unique,\n  momo_number text,\n  momo_number_hash text,\n  anonymity_default text not null default 'anonymous' check (anonymity_default in ('anonymous', 'public_id', 'display_name')),\n  is_platform_admin boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  constraint profiles_public_id_digits check (public_id ~ '^[0-9]{6}$')\n);\n\ncreate table collections (\n  id uuid primary key default gen_random_uuid(),\n  slug text unique not null,\n  creator_user_id uuid not null references profiles(id) on delete restrict,\n  title text not null check (char_length(trim(title)) between 3 and 120),\n  description text not null default '',\n  category text not null check (category in (\n    'Church',\n    'Artist / Creator',\n    'Sports team',\n    'Wedding',\n    'Funeral',\n    'Medical support',\n    'School / education',\n    'Community event',\n    'Public figure / fan support',\n    'Family / friends',\n    'Other'\n  )),\n  cover_image_url text,\n  currency text not null default 'RWF' check (currency = 'RWF'),\n  target_amount_rwf bigint check (target_amount_rwf is null or target_amount_rwf > 0),\n  deadline_at timestamptz,\n  visibility collection_visibility not null default 'private',\n  public_status collection_visibility not null default 'private',\n  is_recurring boolean not null default false,\n  recurring_rule jsonb,\n  allow_anonymous boolean not null default true,\n  contribution_visibility text not null default 'public_safe' check (contribution_visibility in ('private', 'members', 'public_safe')),\n  allow_public_comments boolean not null default false,\n  receiver_display_label text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  archived_at timestamptz,\n  constraint collections_visibility_consistency check (\n    public_status in ('private', 'public_requested', 'public_approved', 'public_rejected', 'archived')\n  )\n);\n\ncreate table collection_members (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  user_id uuid references profiles(id) on delete cascade,\n  invited_phone_hash text,\n  role member_role not null default 'member',\n  status member_status not null default 'invited',\n  created_at timestamptz not null default now(),\n  unique (collection_id, user_id, role)\n);\n\ncreate table collection_receivers (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  receiver_user_id uuid not null references profiles(id) on delete restrict,\n  momo_number text not null,\n  momo_number_hash text not null,\n  network text not null default 'unknown' check (network in ('mtn_momo', 'airtel_money', 'unknown')),\n  label text not null default 'Collection receiver',\n  is_active boolean not null default true,\n  created_at timestamptz not null default now()\n);\n\ncreate table payment_instruction_templates (\n  id uuid primary key default gen_random_uuid(),\n  country_code text not null default 'RW' check (country_code = 'RW'),\n  currency text not null default 'RWF' check (currency = 'RWF'),\n  network text not null default 'unknown' check (network in ('mtn_momo', 'airtel_money', 'unknown')),\n  title text not null,\n  body_template text not null,\n  is_active boolean not null default true,\n  created_at timestamptz not null default now()\n);\n\ncreate table collection_invites (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  invite_token_hash text unique not null,\n  invited_by uuid not null references profiles(id) on delete restrict,\n  invited_phone_hash text,\n  role member_role not null default 'member',\n  expires_at timestamptz not null default (now() + interval '14 days'),\n  used_at timestamptz,\n  created_at timestamptz not null default now()\n);\n\ncreate table payment_intents (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  contributor_user_id uuid references profiles(id) on delete set null,\n  contribution_code text unique not null,\n  expected_amount_rwf bigint check (expected_amount_rwf is null or expected_amount_rwf > 0),\n  receiver_momo_number_hash text not null,\n  sender_phone_hash text,\n  reported_transaction_id text,\n  status payment_intent_status not null default 'pending',\n  anonymity_choice text not null default 'anonymous' check (anonymity_choice in ('anonymous', 'public_id', 'display_name')),\n  created_at timestamptz not null default now(),\n  expires_at timestamptz not null default (now() + interval '24 hours')\n);\n\ncreate table raw_payment_sms (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid references collections(id) on delete set null,\n  receiver_user_id uuid not null references profiles(id) on delete restrict,\n  raw_sender text not null,\n  raw_body text not null,\n  body_hash text unique not null,\n  receiver_momo_number_hash text,\n  received_at_device timestamptz,\n  ingested_at timestamptz not null default now(),\n  parse_status text not null default 'pending' check (parse_status in ('pending', 'parsed', 'failed', 'ignored')),\n  created_at timestamptz not null default now()\n);\n\ncreate table parsed_payment_events (\n  id uuid primary key default gen_random_uuid(),\n  raw_sms_id uuid unique references raw_payment_sms(id) on delete cascade,\n  collection_id uuid references collections(id) on delete set null,\n  receiver_user_id uuid not null references profiles(id) on delete restrict,\n  is_mobile_money_payment boolean not null default false,\n  network text not null default 'unknown' check (network in ('mtn_momo', 'airtel_money', 'unknown')),\n  direction text not null default 'unknown' check (direction in ('incoming', 'outgoing', 'unknown')),\n  amount_rwf bigint,\n  currency text not null default 'unknown' check (currency in ('RWF', 'unknown')),\n  transaction_id text,\n  sender_name text,\n  sender_phone_hash text,\n  receiver_phone_hash text,\n  transaction_time timestamptz,\n  detected_collection_code text,\n  detected_user_public_id text,\n  confidence numeric not null default 0 check (confidence >= 0 and confidence <= 1),\n  parser_model text,\n  parser_schema_version text not null default 'collect.sms_parser.v1',\n  parsed_json jsonb not null default '{}'::jsonb,\n  allocation_status allocation_status not null default 'unallocated',\n  review_reason text,\n  created_at timestamptz not null default now()\n);\n\ncreate table payments (\n  id uuid primary key default gen_random_uuid(),\n  parsed_event_id uuid unique references parsed_payment_events(id) on delete restrict,\n  payment_intent_id uuid references payment_intents(id) on delete set null,\n  collection_id uuid not null references collections(id) on delete restrict,\n  contributor_user_id uuid references profiles(id) on delete set null,\n  contributor_public_id char(6),\n  receiver_user_id uuid not null references profiles(id) on delete restrict,\n  receiver_momo_number_hash text not null,\n  amount_rwf bigint not null check (amount_rwf > 0),\n  currency text not null default 'RWF' check (currency = 'RWF'),\n  transaction_id text unique,\n  source text not null check (source in ('sms_auto', 'manual_sms_paste', 'manual_admin', 'import')),\n  status text not null default 'posted' check (status in ('posted', 'reversed', 'review')),\n  anonymity_choice text not null default 'anonymous' check (anonymity_choice in ('anonymous', 'public_id', 'display_name')),\n  posted_at timestamptz not null default now(),\n  created_at timestamptz not null default now()\n);\n\ncreate table payment_allocations (\n  id uuid primary key default gen_random_uuid(),\n  payment_id uuid not null references payments(id) on delete restrict,\n  parsed_event_id uuid references parsed_payment_events(id) on delete restrict,\n  collection_id uuid not null references collections(id) on delete restrict,\n  payment_intent_id uuid references payment_intents(id) on delete set null,\n  allocated_by uuid references profiles(id) on delete set null,\n  allocation_method text not null check (allocation_method in ('auto_exact_txn', 'auto_code', 'auto_phone_amount_time', 'auto_unique_amount_time', 'manual')),\n  confidence numeric not null default 1 check (confidence >= 0 and confidence <= 1),\n  reason text not null,\n  created_at timestamptz not null default now(),\n  unique (parsed_event_id)\n);\n\ncreate table ledger_entries (\n  id uuid primary key default gen_random_uuid(),\n  payment_id uuid not null references payments(id) on delete restrict,\n  collection_id uuid not null references collections(id) on delete restrict,\n  user_id uuid references profiles(id) on delete set null,\n  entry_type text not null check (entry_type in ('collection_credit', 'member_credit')),\n  amount_rwf bigint not null check (amount_rwf <> 0),\n  currency text not null default 'RWF' check (currency = 'RWF'),\n  visibility text not null default 'public_safe' check (visibility in ('private', 'members', 'public_safe')),\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\n\ncreate table recurring_periods (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  period_start date not null,\n  period_end date not null,\n  expected_amount_rwf bigint check (expected_amount_rwf is null or expected_amount_rwf > 0),\n  status text not null default 'open' check (status in ('open', 'closed', 'cancelled')),\n  created_at timestamptz not null default now(),\n  unique (collection_id, period_start, period_end)\n);\n\ncreate table member_obligations (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  recurring_period_id uuid not null references recurring_periods(id) on delete cascade,\n  user_id uuid not null references profiles(id) on delete cascade,\n  expected_amount_rwf bigint not null check (expected_amount_rwf >= 0),\n  paid_amount_rwf bigint not null default 0 check (paid_amount_rwf >= 0),\n  status text not null default 'overdue' check (status in ('paid', 'partial', 'overdue', 'waived')),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (recurring_period_id, user_id)\n);\n\ncreate table public_collection_requests (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  requested_by uuid not null references profiles(id) on delete restrict,\n  status text not null default 'pending' check (status in ('pending', 'approved', 'rejected')),\n  admin_user_id uuid references profiles(id) on delete set null,\n  admin_note text,\n  requested_at timestamptz not null default now(),\n  reviewed_at timestamptz\n);\n\ncreate table collection_reports (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete cascade,\n  reporter_user_id uuid references profiles(id) on delete set null,\n  reason text not null,\n  status text not null default 'open' check (status in ('open', 'reviewing', 'resolved', 'dismissed')),\n  admin_note text,\n  created_at timestamptz not null default now(),\n  reviewed_at timestamptz\n);\n\ncreate table receiver_mode_consents (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references profiles(id) on delete cascade,\n  enabled boolean not null,\n  momo_number_hash text,\n  build_channel text not null,\n  device_label text,\n  created_at timestamptz not null default now()\n);\n\ncreate table otp_rate_limits (\n  id uuid primary key default gen_random_uuid(),\n  phone_hash text not null,\n  ip_hash text,\n  requested_at timestamptz not null default now()\n);\n\ncreate table audit_logs (\n  id uuid primary key default gen_random_uuid(),\n  actor_user_id uuid references profiles(id) on delete set null,\n  action text not null,\n  entity_type text not null,\n  entity_id uuid,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\n\ninsert into payment_instruction_templates (network, title, body_template)\nvalues\n  (\n    'mtn_momo',\n    'MTN MOMO USSD',\n    'Dial *182# or use the MTN MoMo menu, send {{amount}} to {{receiver_number}}, and enter {{code}} in the reason/reference field when available.'\n  ),\n  (\n    'airtel_money',\n    'Airtel Money USSD',\n    'Use the Airtel Money USSD menu, send {{amount}} to {{receiver_number}}, and include {{code}} as the reference when the menu supports it.'\n  ),\n  (\n    'unknown',\n    'Mobile money USSD',\n    'Use your mobile-money USSD menu, send {{amount}} to {{receiver_number}}, and include {{code}} as the reason/reference when supported.'\n  );\n\ncreate index collections_creator_idx on collections (creator_user_id);\ncreate index collections_public_idx on collections (public_status, category, created_at desc);\ncreate index collection_members_user_idx on collection_members (user_id, status);\ncreate index payment_intents_match_idx on payment_intents (status, receiver_momo_number_hash, expected_amount_rwf, sender_phone_hash, created_at);\ncreate index payment_intents_code_idx on payment_intents (contribution_code);\ncreate index raw_sms_receiver_idx on raw_payment_sms (receiver_user_id, ingested_at desc);\ncreate index parsed_events_review_idx on parsed_payment_events (allocation_status, created_at desc);\ncreate index parsed_events_txn_idx on parsed_payment_events (transaction_id);\ncreate index payments_collection_idx on payments (collection_id, posted_at desc);\ncreate index ledger_collection_idx on ledger_entries (collection_id, created_at desc);\n\ncreate or replace function touch_updated_at()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  new.updated_at = now();\n  return new;\nend;\n$$;\n\ncreate trigger profiles_touch_updated_at before update on profiles\nfor each row execute function touch_updated_at();\n\ncreate or replace function prevent_client_admin_escalation()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  if auth.role() <> 'service_role' and new.is_platform_admin is distinct from old.is_platform_admin then\n    raise exception 'Platform admin flag cannot be changed by clients';\n  end if;\n  return new;\nend;\n$$;\n\ncreate trigger profiles_prevent_client_admin_escalation before update on profiles\nfor each row execute function prevent_client_admin_escalation();\n\ncreate trigger collections_touch_updated_at before update on collections\nfor each row execute function touch_updated_at();\n\ncreate trigger obligations_touch_updated_at before update on member_obligations\nfor each row execute function touch_updated_at();\n\ncreate or replace function normalize_slug(value text)\nreturns text\nlanguage sql\nimmutable\nas $$\n  select trim(both '-' from regexp_replace(lower(coalesce(value, 'collection')), '[^a-z0-9]+', '-', 'g'));\n$$;\n\ncreate or replace function generate_public_id()\nreturns char(6)\nlanguage plpgsql\nas $$\ndeclare\n  candidate char(6);\nbegin\n  loop\n    candidate := lpad(floor(random() * 1000000)::int::text, 6, '0')::char(6);\n    exit when not exists (select 1 from profiles where public_id = candidate);\n  end loop;\n  return candidate;\nend;\n$$;\n\ncreate or replace function create_profile_for_auth_user()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into profiles (id, public_id, whatsapp_phone, display_name)\n  values (\n    new.id,\n    generate_public_id(),\n    nullif(new.phone, ''),\n    coalesce(nullif(new.raw_user_meta_data->>'display_name', ''), null)\n  )\n  on conflict (id) do nothing;\n  return new;\nend;\n$$;\n\ndrop trigger if exists on_auth_user_created_collect_profile on auth.users;\ncreate trigger on_auth_user_created_collect_profile\nafter insert on auth.users\nfor each row execute function create_profile_for_auth_user();\n\ncreate or replace function get_current_profile()\nreturns profiles\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select *\n  from profiles\n  where id = auth.uid();\n$$;\n\ncreate or replace function public.current_user_is_platform_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce((select is_platform_admin from profiles where id = auth.uid()), false);\n$$;\n\ncreate or replace function public.user_is_collection_admin(collection uuid, user_uuid uuid default auth.uid())\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce(public.current_user_is_platform_admin(), false)\n    or exists (\n      select 1\n      from collections c\n      where c.id = collection and c.creator_user_id = user_uuid\n    )\n    or exists (\n      select 1\n      from collection_members m\n      where m.collection_id = collection\n        and m.user_id = user_uuid\n        and m.status = 'active'\n        and m.role in ('owner', 'admin', 'receiver')\n    );\n$$;\n\ncreate or replace function public.user_can_read_collection(collection uuid, user_uuid uuid default auth.uid())\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1\n    from collections c\n    where c.id = collection\n      and (\n        c.public_status = 'public_approved'\n        or c.creator_user_id = user_uuid\n        or public.current_user_is_platform_admin()\n        or exists (\n          select 1\n          from collection_members m\n          where m.collection_id = c.id\n            and m.user_id = user_uuid\n            and m.status = 'active'\n        )\n      )\n  );\n$$;\n\ncreate or replace function public.user_can_ingest_receiver_sms(\n  receiver_hash text default null,\n  collection uuid default null,\n  user_uuid uuid default auth.uid()\n)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select exists (\n    select 1\n    from collection_receivers cr\n    where cr.is_active\n      and (collection is null or cr.collection_id = collection)\n      and (receiver_hash is null or cr.momo_number_hash = receiver_hash)\n      and (\n        cr.receiver_user_id = user_uuid\n        or public.user_is_collection_admin(cr.collection_id, user_uuid)\n      )\n  );\n$$;\n\ncreate or replace function create_collection_with_owner(\n  title text,\n  description text,\n  category text,\n  target_amount_rwf bigint default null,\n  receiver_momo_number text default null,\n  receiver_momo_number_hash text default null,\n  receiver_label text default 'Primary MOMO receiver',\n  cover_image_url text default null,\n  is_recurring boolean default false,\n  recurring_rule jsonb default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  created_collection_id uuid;\n  base_slug text;\n  final_slug text;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  base_slug := normalize_slug(title);\n  if base_slug = '' then\n    base_slug := 'collection';\n  end if;\n  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);\n\n  insert into collections (\n    slug,\n    creator_user_id,\n    title,\n    description,\n    category,\n    cover_image_url,\n    target_amount_rwf,\n    receiver_display_label,\n    is_recurring,\n    recurring_rule\n  )\n  values (\n    final_slug,\n    auth.uid(),\n    title,\n    coalesce(description, ''),\n    category,\n    nullif(cover_image_url, ''),\n    target_amount_rwf,\n    receiver_label,\n    coalesce(is_recurring, false),\n    recurring_rule\n  )\n  returning id into created_collection_id;\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values (created_collection_id, auth.uid(), 'owner', 'active');\n\n  if receiver_momo_number is not null and receiver_momo_number_hash is not null then\n    insert into collection_receivers (collection_id, receiver_user_id, momo_number, momo_number_hash, label)\n    values (created_collection_id, auth.uid(), receiver_momo_number, receiver_momo_number_hash, receiver_label);\n  end if;\n\n  if coalesce(is_recurring, false) then\n    insert into recurring_periods (\n      collection_id,\n      period_start,\n      period_end,\n      expected_amount_rwf,\n      status\n    )\n    values (\n      created_collection_id,\n      current_date,\n      current_date + interval '1 month' - interval '1 day',\n      target_amount_rwf,\n      'open'\n    );\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id)\n  values (auth.uid(), 'collection.created', 'collection', created_collection_id);\n\n  return created_collection_id;\nend;\n$$;\n\ncreate or replace function generate_contribution_code()\nreturns text\nlanguage plpgsql\nas $$\ndeclare\n  candidate text;\nbegin\n  loop\n    candidate := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 6));\n    exit when not exists (select 1 from payment_intents where contribution_code = candidate);\n  end loop;\n  return candidate;\nend;\n$$;\n\ncreate or replace function create_collection_invite(\n  collection uuid,\n  target_phone_hash text default null,\n  target_public_id text default null,\n  invite_role member_role default 'member'\n)\nreturns table (\n  id uuid,\n  invite_token text,\n  invite_token_hash text,\n  expires_at timestamptz,\n  role member_role\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  plain_token text;\n  hashed_token text;\n  invite_id uuid;\n  target_user_id uuid;\n  invite_expires_at timestamptz;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  if not public.user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can invite members';\n  end if;\n\n  if invite_role = 'owner' then\n    raise exception 'Owner role cannot be granted by invite';\n  end if;\n\n  if target_phone_hash is null and target_public_id is null then\n    raise exception 'Invite requires a phone number or Collect public ID';\n  end if;\n\n  if target_public_id is not null then\n    if target_public_id !~ '^[0-9]{6}$' then\n      raise exception 'Collect public ID must be 6 digits';\n    end if;\n\n    select p.id into target_user_id\n    from profiles p\n    where p.public_id::text = target_public_id;\n  end if;\n\n  plain_token := encode(gen_random_bytes(18), 'hex');\n  hashed_token := encode(digest(plain_token, 'sha256'), 'hex');\n\n  insert into collection_invites (\n    collection_id,\n    invite_token_hash,\n    invited_by,\n    invited_phone_hash,\n    role\n  )\n  values (\n    collection,\n    hashed_token,\n    auth.uid(),\n    target_phone_hash,\n    invite_role\n  )\n  returning collection_invites.id, collection_invites.expires_at\n    into invite_id, invite_expires_at;\n\n  if target_user_id is not null then\n    insert into collection_members (collection_id, user_id, role, status)\n    values (collection, target_user_id, invite_role, 'invited')\n    on conflict on constraint collection_members_collection_id_user_id_role_key do update\n      set status = 'invited';\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.invite_created',\n    'collection',\n    collection,\n    jsonb_build_object(\n      'role', invite_role,\n      'target_public_id_present', target_public_id is not null,\n      'target_phone_hash_present', target_phone_hash is not null\n    )\n  );\n\n  return query select\n    invite_id,\n    plain_token,\n    hashed_token,\n    invite_expires_at,\n    invite_role;\nend;\n$$;\n\ncreate or replace function create_payment_intent(\n  collection uuid,\n  expected_amount_rwf bigint default null,\n  sender_phone_hash text default null,\n  anonymity_choice text default 'anonymous'\n)\nreturns payment_intents\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  receiver_hash text;\n  intent payment_intents;\nbegin\n  if not public.user_can_read_collection(collection, auth.uid()) then\n    raise exception 'Collection is not available';\n  end if;\n\n  select cr.momo_number_hash\n    into receiver_hash\n  from collection_receivers cr\n  where cr.collection_id = collection and cr.is_active\n  order by cr.created_at\n  limit 1;\n\n  if receiver_hash is null then\n    raise exception 'Collection has no active receiver';\n  end if;\n\n  insert into payment_intents (\n    collection_id,\n    contributor_user_id,\n    contribution_code,\n    expected_amount_rwf,\n    receiver_momo_number_hash,\n    sender_phone_hash,\n    anonymity_choice\n  )\n  values (\n    collection,\n    auth.uid(),\n    generate_contribution_code(),\n    expected_amount_rwf,\n    receiver_hash,\n    sender_phone_hash,\n    anonymity_choice\n  )\n  returning * into intent;\n\n  return intent;\nend;\n$$;\n\ncreate or replace function create_payment_intent_with_instructions(\n  collection uuid,\n  p_expected_amount_rwf bigint default null,\n  p_sender_phone_hash text default null,\n  p_anonymity_choice text default 'anonymous'\n)\nreturns table (\n  id uuid,\n  collection_id uuid,\n  contribution_code text,\n  expected_amount_rwf bigint,\n  receiver_momo_number text,\n  receiver_momo_number_hash text,\n  receiver_label text,\n  network text,\n  instruction_title text,\n  instruction_body text,\n  sender_phone_hash text,\n  status payment_intent_status,\n  anonymity_choice text,\n  reported_transaction_id text,\n  created_at timestamptz,\n  expires_at timestamptz\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  receiver_row collection_receivers;\n  intent_row payment_intents;\n  template_row payment_instruction_templates;\nbegin\n  if not public.user_can_read_collection(collection, auth.uid()) then\n    raise exception 'Collection is not available';\n  end if;\n\n  select *\n    into receiver_row\n  from collection_receivers cr\n  where cr.collection_id = collection and cr.is_active\n  order by cr.created_at\n  limit 1;\n\n  if receiver_row.id is null then\n    raise exception 'Collection has no active receiver';\n  end if;\n\n  select *\n    into template_row\n  from payment_instruction_templates pit\n  where pit.is_active\n    and pit.network in (receiver_row.network, 'unknown')\n  order by case when pit.network = receiver_row.network then 0 else 1 end, pit.created_at\n  limit 1;\n\n  insert into payment_intents (\n    collection_id,\n    contributor_user_id,\n    contribution_code,\n    expected_amount_rwf,\n    receiver_momo_number_hash,\n    sender_phone_hash,\n    anonymity_choice\n  )\n  values (\n    collection,\n    auth.uid(),\n    generate_contribution_code(),\n    p_expected_amount_rwf,\n    receiver_row.momo_number_hash,\n    p_sender_phone_hash,\n    p_anonymity_choice\n  )\n  returning * into intent_row;\n\n  return query select\n    intent_row.id,\n    intent_row.collection_id,\n    intent_row.contribution_code,\n    intent_row.expected_amount_rwf,\n    receiver_row.momo_number,\n    intent_row.receiver_momo_number_hash,\n    receiver_row.label,\n    receiver_row.network,\n    coalesce(template_row.title, 'Mobile money USSD'),\n    replace(\n      replace(\n        replace(\n          coalesce(\n            template_row.body_template,\n            'Use your mobile-money USSD menu, send {{amount}} to {{receiver_number}}, and include {{code}} as the reason/reference when supported.'\n          ),\n          '{{amount}}',\n          coalesce(intent_row.expected_amount_rwf::text || ' RWF', 'the selected amount')\n        ),\n        '{{receiver_number}}',\n        receiver_row.momo_number\n      ),\n      '{{code}}',\n      intent_row.contribution_code\n    ),\n    intent_row.sender_phone_hash,\n    intent_row.status,\n    intent_row.anonymity_choice,\n    intent_row.reported_transaction_id,\n    intent_row.created_at,\n    intent_row.expires_at;\nend;\n$$;\n\ncreate or replace function report_payment_intent_paid(\n  intent uuid,\n  transaction_id text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  intent_row payment_intents;\n  cleaned_transaction_id text;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select * into intent_row\n  from payment_intents\n  where id = intent\n  for update;\n\n  if not found then\n    raise exception 'Payment intent not found';\n  end if;\n\n  if intent_row.contributor_user_id is distinct from auth.uid()\n     and not public.user_is_collection_admin(intent_row.collection_id, auth.uid()) then\n    raise exception 'Not authorized to report this payment intent';\n  end if;\n\n  if intent_row.status <> 'pending' then\n    raise exception 'Only pending payment intents can be reported paid';\n  end if;\n\n  cleaned_transaction_id := nullif(upper(trim(coalesce(transaction_id, ''))), '');\n\n  update payment_intents\n    set reported_transaction_id = cleaned_transaction_id\n    where id = intent;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'payment_intent.reported_paid',\n    'payment_intent',\n    intent,\n    jsonb_build_object('transaction_id_present', cleaned_transaction_id is not null)\n  );\nend;\n$$;\n\ncreate or replace function post_payment_from_event(\n  event_id uuid,\n  intent_id uuid,\n  target_collection_id uuid,\n  method text,\n  allocation_reason text,\n  actor uuid default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  event_row parsed_payment_events;\n  intent_row payment_intents;\n  receiver_id uuid;\n  contributor_id uuid;\n  contributor_pid char(6);\n  anonymity text := 'anonymous';\n  payment_id uuid;\nbegin\n  select * into event_row from parsed_payment_events where id = event_id for update;\n  if not found then\n    raise exception 'Parsed event not found';\n  end if;\n\n  if event_row.allocation_status = 'allocated' then\n    select p.id into payment_id from payments p where p.parsed_event_id = event_id;\n    return payment_id;\n  end if;\n\n  if event_row.transaction_id is not null and exists (select 1 from payments where transaction_id = event_row.transaction_id) then\n    update parsed_payment_events\n      set allocation_status = 'allocated', review_reason = 'Duplicate transaction already posted'\n      where id = event_id;\n    select p.id into payment_id from payments p where p.transaction_id = event_row.transaction_id;\n    return payment_id;\n  end if;\n\n  if intent_id is not null then\n    select * into intent_row from payment_intents where id = intent_id for update;\n    if not found then\n      raise exception 'Payment intent not found';\n    end if;\n    if intent_row.collection_id <> target_collection_id then\n      raise exception 'Payment intent does not belong to target collection';\n    end if;\n    contributor_id := intent_row.contributor_user_id;\n    anonymity := intent_row.anonymity_choice;\n  end if;\n\n  if not exists (\n    select 1\n    from collection_receivers cr\n    where cr.collection_id = target_collection_id\n      and cr.is_active\n      and cr.receiver_user_id = event_row.receiver_user_id\n      and (\n        event_row.receiver_phone_hash is null\n        or cr.momo_number_hash = event_row.receiver_phone_hash\n      )\n  ) then\n    raise exception 'Parsed event receiver is not configured for target collection';\n  end if;\n\n  select cr.receiver_user_id\n    into receiver_id\n  from collection_receivers cr\n  where cr.collection_id = target_collection_id\n    and cr.momo_number_hash = coalesce(event_row.receiver_phone_hash, event_row.parsed_json->>'receiver_momo_number_hash', intent_row.receiver_momo_number_hash)\n  order by cr.created_at\n  limit 1;\n\n  receiver_id := coalesce(receiver_id, event_row.receiver_user_id);\n\n  if contributor_id is not null then\n    select public_id into contributor_pid from profiles where id = contributor_id;\n  elsif event_row.detected_user_public_id is not null then\n    select id, public_id into contributor_id, contributor_pid\n    from profiles\n    where public_id = event_row.detected_user_public_id::char(6);\n  end if;\n\n  insert into payments (\n    parsed_event_id,\n    payment_intent_id,\n    collection_id,\n    contributor_user_id,\n    contributor_public_id,\n    receiver_user_id,\n    receiver_momo_number_hash,\n    amount_rwf,\n    transaction_id,\n    source,\n    anonymity_choice\n  )\n  values (\n    event_id,\n    intent_id,\n    target_collection_id,\n    contributor_id,\n    contributor_pid,\n    receiver_id,\n    coalesce(event_row.receiver_phone_hash, intent_row.receiver_momo_number_hash, 'unknown'),\n    event_row.amount_rwf,\n    event_row.transaction_id,\n    case when actor is null then 'sms_auto' else 'manual_admin' end,\n    anonymity\n  )\n  returning id into payment_id;\n\n  insert into payment_allocations (\n    payment_id,\n    parsed_event_id,\n    collection_id,\n    payment_intent_id,\n    allocated_by,\n    allocation_method,\n    confidence,\n    reason\n  )\n  values (\n    payment_id,\n    event_id,\n    target_collection_id,\n    intent_id,\n    actor,\n    method,\n    event_row.confidence,\n    allocation_reason\n  );\n\n  insert into ledger_entries (\n    payment_id,\n    collection_id,\n    user_id,\n    entry_type,\n    amount_rwf,\n    visibility,\n    metadata\n  )\n  values (\n    payment_id,\n    target_collection_id,\n    contributor_id,\n    'collection_credit',\n    event_row.amount_rwf,\n    'public_safe',\n    jsonb_build_object('allocation_method', method, 'parsed_event_id', event_id)\n  );\n\n  update parsed_payment_events\n    set allocation_status = 'allocated', review_reason = allocation_reason\n    where id = event_id;\n\n  if intent_id is not null then\n    update payment_intents set status = 'matched' where id = intent_id;\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    actor,\n    case when actor is null then 'payment.allocated.auto' else 'payment.allocated.manual' end,\n    'payment',\n    payment_id,\n    jsonb_build_object('parsed_event_id', event_id, 'method', method)\n  );\n\n  return payment_id;\nend;\n$$;\n\ncreate or replace function allocate_parsed_payment_event(event_id uuid)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  event_row parsed_payment_events;\n  match_intent_id uuid;\n  match_collection_id uuid;\n  possible_count int;\nbegin\n  select * into event_row from parsed_payment_events where id = event_id for update;\n  if not found then\n    raise exception 'Parsed event not found';\n  end if;\n\n  if event_row.allocation_status = 'allocated' then\n    return 'already_allocated';\n  end if;\n\n  if not event_row.is_mobile_money_payment\n     or event_row.direction <> 'incoming'\n     or event_row.currency <> 'RWF'\n     or event_row.amount_rwf is null\n     or event_row.amount_rwf <= 0\n     or event_row.confidence < 0.72 then\n    update parsed_payment_events\n      set allocation_status = 'needs_review',\n          review_reason = 'Parser result is not sufficiently reliable for auto allocation'\n      where id = event_id;\n    return 'needs_review';\n  end if;\n\n  if event_row.transaction_id is not null then\n    select id, collection_id into match_intent_id, match_collection_id\n    from payment_intents\n    where status = 'pending'\n      and reported_transaction_id = event_row.transaction_id\n    order by created_at\n    limit 1;\n    if match_intent_id is not null then\n      perform post_payment_from_event(event_id, match_intent_id, match_collection_id, 'auto_exact_txn', 'Matched by contributor-reported transaction ID');\n      return 'allocated';\n    end if;\n  end if;\n\n  if event_row.detected_collection_code is not null then\n    select id, collection_id into match_intent_id, match_collection_id\n    from payment_intents\n    where status = 'pending'\n      and contribution_code = upper(event_row.detected_collection_code)\n    limit 1;\n    if match_intent_id is not null then\n      perform post_payment_from_event(event_id, match_intent_id, match_collection_id, 'auto_code', 'Matched by contribution code');\n      return 'allocated';\n    end if;\n  end if;\n\n  if event_row.sender_phone_hash is not null and event_row.receiver_phone_hash is not null then\n    select id, collection_id into match_intent_id, match_collection_id\n    from payment_intents\n    where status = 'pending'\n      and receiver_momo_number_hash = event_row.receiver_phone_hash\n      and expected_amount_rwf = event_row.amount_rwf\n      and sender_phone_hash = event_row.sender_phone_hash\n      and event_row.created_at between created_at - interval '15 minutes' and expires_at + interval '2 hours'\n    order by created_at\n    limit 1;\n    if match_intent_id is not null then\n      perform post_payment_from_event(event_id, match_intent_id, match_collection_id, 'auto_phone_amount_time', 'Matched by receiver, amount, sender phone hash, and time window');\n      return 'allocated';\n    end if;\n  end if;\n\n  if event_row.receiver_phone_hash is not null then\n    select\n      count(*),\n      (array_agg(id order by created_at))[1],\n      (array_agg(collection_id order by created_at))[1]\n      into possible_count, match_intent_id, match_collection_id\n    from payment_intents\n    where status = 'pending'\n      and receiver_momo_number_hash = event_row.receiver_phone_hash\n      and expected_amount_rwf = event_row.amount_rwf\n      and event_row.created_at between created_at - interval '15 minutes' and expires_at + interval '2 hours';\n\n    if possible_count = 1 then\n      perform post_payment_from_event(event_id, match_intent_id, match_collection_id, 'auto_unique_amount_time', 'Matched as the only plausible pending intent in time window');\n      return 'allocated';\n    elsif possible_count > 1 then\n      update parsed_payment_events\n        set allocation_status = 'ambiguous', review_reason = 'Multiple plausible payment intents matched receiver, amount, and time window'\n        where id = event_id;\n      return 'ambiguous';\n    end if;\n  end if;\n\n  update parsed_payment_events\n    set allocation_status = 'needs_review', review_reason = 'No deterministic match found'\n    where id = event_id;\n  return 'needs_review';\nend;\n$$;\n\ncreate or replace function manual_allocate_parsed_payment_event(\n  event_id uuid,\n  target_collection_id uuid,\n  target_payment_intent_id uuid default null,\n  reason text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if coalesce(trim(reason), '') = '' then\n    raise exception 'Manual allocation reason is required';\n  end if;\n  if not public.user_is_collection_admin(target_collection_id, auth.uid()) then\n    raise exception 'Only collection admins can allocate payments';\n  end if;\n  return post_payment_from_event(event_id, target_payment_intent_id, target_collection_id, 'manual', reason, auth.uid());\nend;\n$$;\n\ncreate or replace function request_public_collection(collection uuid)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  request_id uuid;\nbegin\n  if not public.user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can request public listing';\n  end if;\n\n  update collections\n    set public_status = 'public_requested', visibility = 'public_requested'\n    where id = collection;\n\n  insert into public_collection_requests (collection_id, requested_by)\n  values (collection, auth.uid())\n  returning id into request_id;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id)\n  values (auth.uid(), 'collection.public_requested', 'collection', collection);\n\n  return request_id;\nend;\n$$;\n\ncreate or replace function review_public_collection(\n  request_id uuid,\n  approved boolean,\n  p_admin_note text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  request_row public_collection_requests;\nbegin\n  if not public.current_user_is_platform_admin() then\n    raise exception 'Platform admin required';\n  end if;\n\n  select * into request_row\n  from public_collection_requests\n  where id = request_id\n  for update;\n\n  if not found then\n    raise exception 'Public collection request not found';\n  end if;\n\n  update public_collection_requests\n    set status = case when approved then 'approved' else 'rejected' end,\n        admin_user_id = auth.uid(),\n        admin_note = p_admin_note,\n        reviewed_at = now()\n    where id = request_id;\n\n  update collections\n    set public_status = case when approved then 'public_approved'::collection_visibility else 'public_rejected'::collection_visibility end,\n        visibility = case when approved then 'public_approved'::collection_visibility else 'private'::collection_visibility end\n    where id = request_row.collection_id;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    case when approved then 'collection.public_approved' else 'collection.public_rejected' end,\n    'collection',\n    request_row.collection_id,\n    jsonb_build_object('request_id', request_id, 'admin_note', p_admin_note)\n  );\nend;\n$$;\n\ncreate or replace function prevent_ledger_mutation()\nreturns trigger\nlanguage plpgsql\nas $$\nbegin\n  raise exception 'Ledger entries are immutable';\nend;\n$$;\n\ncreate trigger ledger_entries_prevent_update before update on ledger_entries\nfor each row execute function prevent_ledger_mutation();\n\ncreate trigger ledger_entries_prevent_delete before delete on ledger_entries\nfor each row execute function prevent_ledger_mutation();\n\ncreate view public_profiles_view\nas\nselect\n  id,\n  public_id,\n  case\n    when anonymity_default = 'display_name' and nullif(display_name, '') is not null then display_name\n    when anonymity_default = 'anonymous' then 'Anonymous supporter'\n    else 'User #' || public_id\n  end as display_alias,\n  case when anonymity_default = 'display_name' then avatar_url else null end as avatar_url,\n  created_at\nfrom profiles;\n\ncreate view collection_summary_view\nas\nselect\n  c.id as collection_id,\n  coalesce(sum(le.amount_rwf) filter (where le.entry_type = 'collection_credit'), 0)::bigint as amount_raised_rwf,\n  count(distinct p.id)::bigint as payment_count,\n  count(distinct coalesce(p.contributor_user_id::text, p.transaction_id, p.id::text))::bigint as supporter_count\nfrom collections c\nleft join ledger_entries le on le.collection_id = c.id\nleft join payments p on p.id = le.payment_id\nwhere c.public_status = 'public_approved'\n  and c.archived_at is null\ngroup by c.id;\n\ncreate view public_collections_view\nas\nselect\n  c.id,\n  c.slug,\n  c.title,\n  c.description,\n  c.category,\n  c.cover_image_url,\n  c.target_amount_rwf,\n  c.deadline_at,\n  c.is_recurring,\n  c.created_at,\n  pp.display_alias as creator_display_alias,\n  csv.amount_raised_rwf,\n  csv.supporter_count\nfrom collections c\njoin public_profiles_view pp on pp.id = c.creator_user_id\njoin collection_summary_view csv on csv.collection_id = c.id\nwhere c.public_status = 'public_approved'\n  and c.archived_at is null;\n\ncreate view public_contributions_view\nas\nselect\n  p.collection_id,\n  p.id as payment_id,\n  p.amount_rwf,\n  p.posted_at,\n  case\n    when p.anonymity_choice = 'display_name' and p.contributor_user_id is not null then coalesce(pr.display_name, 'User #' || pr.public_id)\n    when p.anonymity_choice = 'public_id' and p.contributor_public_id is not null then 'User #' || p.contributor_public_id\n    else 'Anonymous supporter'\n  end as supporter_label\nfrom payments p\nleft join profiles pr on pr.id = p.contributor_user_id\njoin collections c on c.id = p.collection_id\nwhere c.public_status = 'public_approved'\n  and p.status = 'posted';\n\ncreate view member_collection_summary_view\nas\nselect\n  c.id as collection_id,\n  c.title,\n  c.category,\n  c.visibility,\n  c.public_status,\n  c.creator_user_id,\n  (\n    select coalesce(sum(le.amount_rwf) filter (where le.entry_type = 'collection_credit'), 0)::bigint\n    from ledger_entries le\n    where le.collection_id = c.id\n  ) as amount_raised_rwf,\n  (\n    select count(distinct coalesce(p.contributor_user_id::text, p.transaction_id, p.id::text))::bigint\n    from payments p\n    where p.collection_id = c.id\n  ) as supporter_count,\n  (\n    select count(pi.id)::bigint\n    from payment_intents pi\n    where pi.collection_id = c.id\n      and pi.status = 'pending'\n  ) as pending_intent_count,\n  (\n    select count(distinct ppe.id)::bigint\n    from collection_receivers cr\n    join parsed_payment_events ppe\n      on ppe.receiver_user_id = cr.receiver_user_id\n     and (\n       ppe.collection_id = c.id\n       or (\n         ppe.collection_id is null\n         and ppe.receiver_phone_hash = cr.momo_number_hash\n       )\n     )\n    where cr.collection_id = c.id\n      and ppe.allocation_status in ('needs_review', 'ambiguous')\n  ) as review_event_count\nfrom collections c\nwhere public.user_can_read_collection(c.id, auth.uid());\n\ncreate view parsed_payment_events_review_view\nas\nselect distinct on (ppe.id, coalesce(ppe.collection_id, cr.collection_id))\n  ppe.id,\n  coalesce(ppe.collection_id, cr.collection_id) as collection_id,\n  ppe.raw_sms_id,\n  ppe.receiver_user_id,\n  ppe.is_mobile_money_payment,\n  ppe.network,\n  ppe.direction,\n  ppe.amount_rwf,\n  ppe.currency,\n  ppe.transaction_id,\n  ppe.sender_name,\n  ppe.transaction_time,\n  ppe.detected_collection_code,\n  ppe.detected_user_public_id,\n  ppe.confidence,\n  ppe.parser_model,\n  ppe.parser_schema_version,\n  ppe.allocation_status,\n  ppe.review_reason,\n  ppe.created_at\nfrom parsed_payment_events ppe\nleft join collection_receivers cr\n  on cr.receiver_user_id = ppe.receiver_user_id\n and cr.is_active\n and ppe.collection_id is null\n and ppe.receiver_phone_hash = cr.momo_number_hash\nwhere (\n  ppe.collection_id is not null\n  and public.user_can_read_collection(ppe.collection_id, auth.uid())\n)\nor (\n  ppe.collection_id is null\n  and cr.collection_id is not null\n  and public.user_can_read_collection(cr.collection_id, auth.uid())\n);\n\nalter table profiles enable row level security;\nalter table collections enable row level security;\nalter table collection_members enable row level security;\nalter table collection_receivers enable row level security;\nalter table payment_instruction_templates enable row level security;\nalter table collection_invites enable row level security;\nalter table payment_intents enable row level security;\nalter table raw_payment_sms enable row level security;\nalter table parsed_payment_events enable row level security;\nalter table payments enable row level security;\nalter table payment_allocations enable row level security;\nalter table ledger_entries enable row level security;\nalter table recurring_periods enable row level security;\nalter table member_obligations enable row level security;\nalter table public_collection_requests enable row level security;\nalter table collection_reports enable row level security;\nalter table receiver_mode_consents enable row level security;\nalter table otp_rate_limits enable row level security;\nalter table audit_logs enable row level security;\n\ncreate policy \\"profiles read safe columns\\" on profiles\nfor select\nusing (true);\n\ncreate policy \\"profiles update own non-admin\\" on profiles\nfor update to authenticated\nusing (id = auth.uid())\nwith check (id = auth.uid());\n\ncreate policy \\"profiles service insert\\" on profiles\nfor insert to service_role\nwith check (true);\n\ncreate policy \\"collections read public or member\\" on collections\nfor select\nusing (public_status = 'public_approved' or public.user_can_read_collection(id, auth.uid()));\n\ncreate policy \\"collections insert authenticated\\" on collections\nfor insert to authenticated\nwith check (creator_user_id = auth.uid() and visibility = 'private');\n\ncreate policy \\"collections update admins\\" on collections\nfor update to authenticated\nusing (public.user_is_collection_admin(id, auth.uid()))\nwith check (public.user_is_collection_admin(id, auth.uid()));\n\ncreate policy \\"members read scoped\\" on collection_members\nfor select to authenticated\nusing (public.user_can_read_collection(collection_id, auth.uid()));\n\ncreate policy \\"members manage admins\\" on collection_members\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()))\nwith check (public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"receivers read collection admins\\" on collection_receivers\nfor select to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()) or receiver_user_id = auth.uid());\n\ncreate policy \\"receivers manage admins\\" on collection_receivers\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()))\nwith check (public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"payment instructions read active\\" on payment_instruction_templates\nfor select\nusing (is_active);\n\ncreate policy \\"payment instructions platform admin manage\\" on payment_instruction_templates\nfor all to authenticated\nusing (public.current_user_is_platform_admin())\nwith check (public.current_user_is_platform_admin());\n\ncreate policy \\"invites read admins\\" on collection_invites\nfor select to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"invites manage admins\\" on collection_invites\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()))\nwith check (public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"payment intents read contributor or admin\\" on payment_intents\nfor select to authenticated\nusing (contributor_user_id = auth.uid() or public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"payment intents create contributor\\" on payment_intents\nfor insert to authenticated\nwith check (contributor_user_id = auth.uid() and public.user_can_read_collection(collection_id, auth.uid()));\n\ncreate policy \\"raw sms service writes\\" on raw_payment_sms\nfor all to service_role\nusing (true)\nwith check (true);\n\ncreate policy \\"raw sms receiver own read\\" on raw_payment_sms\nfor select to authenticated\nusing (receiver_user_id = auth.uid() or public.current_user_is_platform_admin());\n\ncreate policy \\"parsed events receiver or admin read\\" on parsed_payment_events\nfor select to authenticated\nusing (receiver_user_id = auth.uid() or public.current_user_is_platform_admin());\n\ncreate policy \\"parsed events service writes\\" on parsed_payment_events\nfor all to service_role\nusing (true)\nwith check (true);\n\ncreate policy \\"payments read scoped\\" on payments\nfor select to authenticated\nusing (\n  contributor_user_id = auth.uid()\n  or public.user_is_collection_admin(collection_id, auth.uid())\n);\n\ncreate policy \\"payments service writes\\" on payments\nfor all to service_role\nusing (true)\nwith check (true);\n\ncreate policy \\"allocations read collection admins\\" on payment_allocations\nfor select to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()) or public.current_user_is_platform_admin());\n\ncreate policy \\"allocations service writes\\" on payment_allocations\nfor all to service_role\nusing (true)\nwith check (true);\n\ncreate policy \\"ledger read scoped\\" on ledger_entries\nfor select to authenticated\nusing (\n  user_id = auth.uid()\n  or public.user_is_collection_admin(collection_id, auth.uid())\n);\n\ncreate policy \\"ledger service writes\\" on ledger_entries\nfor insert to service_role\nwith check (true);\n\ncreate policy \\"recurring periods read scoped\\" on recurring_periods\nfor select to authenticated\nusing (public.user_can_read_collection(collection_id, auth.uid()));\n\ncreate policy \\"recurring periods manage admins\\" on recurring_periods\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()))\nwith check (public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"obligations read own or admin\\" on member_obligations\nfor select to authenticated\nusing (user_id = auth.uid() or public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"obligations manage admins\\" on member_obligations\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, auth.uid()))\nwith check (public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"public requests read requester or admin\\" on public_collection_requests\nfor select to authenticated\nusing (requested_by = auth.uid() or public.current_user_is_platform_admin() or public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"public requests insert requester\\" on public_collection_requests\nfor insert to authenticated\nwith check (requested_by = auth.uid() and public.user_is_collection_admin(collection_id, auth.uid()));\n\ncreate policy \\"public requests admin update\\" on public_collection_requests\nfor update to authenticated\nusing (public.current_user_is_platform_admin())\nwith check (public.current_user_is_platform_admin());\n\ncreate policy \\"reports read admins\\" on collection_reports\nfor select to authenticated\nusing (public.current_user_is_platform_admin() or public.user_is_collection_admin(collection_id, auth.uid()) or reporter_user_id = auth.uid());\n\ncreate policy \\"reports insert authenticated\\" on collection_reports\nfor insert to authenticated\nwith check (reporter_user_id = auth.uid());\n\ncreate policy \\"reports update platform admin\\" on collection_reports\nfor update to authenticated\nusing (public.current_user_is_platform_admin())\nwith check (public.current_user_is_platform_admin());\n\ncreate policy \\"receiver consents own\\" on receiver_mode_consents\nfor all to authenticated\nusing (user_id = auth.uid())\nwith check (user_id = auth.uid());\n\ncreate policy \\"otp rate limit service only\\" on otp_rate_limits\nfor all to service_role\nusing (true)\nwith check (true);\n\ncreate policy \\"audit logs platform or scoped collection admins\\" on audit_logs\nfor select to authenticated\nusing (\n  public.current_user_is_platform_admin()\n  or (\n    entity_type = 'collection'\n    and entity_id is not null\n    and public.user_is_collection_admin(entity_id, auth.uid())\n  )\n);\n\ncreate policy \\"audit logs service writes\\" on audit_logs\nfor insert to service_role\nwith check (true);\n\nrevoke all on profiles from anon, authenticated;\nrevoke all on payment_intents from anon, authenticated;\nrevoke execute on all functions in schema public from public, anon, authenticated;\ngrant usage on schema public to anon, authenticated;\ngrant update (display_name, avatar_url, momo_number, momo_number_hash, anonymity_default, updated_at) on profiles to authenticated;\ngrant select on payment_intents to authenticated;\ngrant select on public_collections_view, public_contributions_view, collection_summary_view, public_profiles_view to anon, authenticated;\ngrant select on payment_instruction_templates to anon, authenticated;\ngrant select on member_collection_summary_view, parsed_payment_events_review_view to authenticated;\ngrant execute on all functions in schema public to service_role;\ngrant execute on function public.current_user_is_platform_admin() to anon, authenticated;\ngrant execute on function public.user_is_collection_admin(uuid, uuid) to anon, authenticated;\ngrant execute on function public.user_can_read_collection(uuid, uuid) to anon, authenticated;\ngrant execute on function public.user_can_ingest_receiver_sms(text, uuid, uuid) to authenticated;\ngrant execute on function get_current_profile() to authenticated;\ngrant execute on function create_collection_with_owner(text, text, text, bigint, text, text, text, text, boolean, jsonb) to authenticated;\ngrant execute on function create_collection_invite(uuid, text, text, member_role) to authenticated;\ngrant execute on function create_payment_intent(uuid, bigint, text, text) to authenticated;\ngrant execute on function create_payment_intent_with_instructions(uuid, bigint, text, text) to authenticated;\ngrant execute on function report_payment_intent_paid(uuid, text) to authenticated;\ngrant execute on function request_public_collection(uuid) to authenticated;\ngrant execute on function review_public_collection(uuid, boolean, text) to authenticated;\ngrant execute on function manual_allocate_parsed_payment_event(uuid, uuid, uuid, text) to authenticated;\n"}
202605230002	fix_invite_rpc_lint	{"create or replace function create_collection_invite(\n  collection uuid,\n  target_phone_hash text default null,\n  target_public_id text default null,\n  invite_role member_role default 'member'\n)\nreturns table (\n  id uuid,\n  invite_token text,\n  invite_token_hash text,\n  expires_at timestamptz,\n  role member_role\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  plain_token text;\n  hashed_token text;\n  invite_id uuid;\n  target_user_id uuid;\n  invite_expires_at timestamptz;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  if not public.user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can invite members';\n  end if;\n\n  if invite_role = 'owner' then\n    raise exception 'Owner role cannot be granted by invite';\n  end if;\n\n  if target_phone_hash is null and target_public_id is null then\n    raise exception 'Invite requires a phone number or Collect public ID';\n  end if;\n\n  if target_public_id is not null then\n    if target_public_id !~ '^[0-9]{6}$' then\n      raise exception 'Collect public ID must be 6 digits';\n    end if;\n\n    select p.id into target_user_id\n    from profiles p\n    where p.public_id::text = target_public_id;\n  end if;\n\n  plain_token := encode(gen_random_bytes(18), 'hex');\n  hashed_token := encode(digest(plain_token, 'sha256'), 'hex');\n\n  insert into collection_invites (\n    collection_id,\n    invite_token_hash,\n    invited_by,\n    invited_phone_hash,\n    role\n  )\n  values (\n    collection,\n    hashed_token,\n    auth.uid(),\n    target_phone_hash,\n    invite_role\n  )\n  returning collection_invites.id, collection_invites.expires_at\n    into invite_id, invite_expires_at;\n\n  if target_user_id is not null then\n    insert into collection_members (collection_id, user_id, role, status)\n    values (collection, target_user_id, invite_role, 'invited')\n    on conflict on constraint collection_members_collection_id_user_id_role_key do update\n      set status = 'invited';\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.invite_created',\n    'collection',\n    collection,\n    jsonb_build_object(\n      'role', invite_role,\n      'target_public_id_present', target_public_id is not null,\n      'target_phone_hash_present', target_phone_hash is not null\n    )\n  );\n\n  return query select\n    invite_id,\n    plain_token,\n    hashed_token,\n    invite_expires_at,\n    invite_role;\nend;\n$$;\n"}
202605230003	harden_rls_indexes	{"create index if not exists audit_logs_collection_entity_idx\n  on audit_logs (entity_id, created_at desc)\n  where entity_type = 'collection';\n\ncreate index if not exists collection_invites_collection_idx\n  on collection_invites (collection_id, created_at desc);\n\ncreate index if not exists collection_members_collection_status_idx\n  on collection_members (collection_id, status);\n\ncreate index if not exists collection_receivers_collection_idx\n  on collection_receivers (collection_id, is_active);\n\ncreate index if not exists collection_receivers_receiver_idx\n  on collection_receivers (receiver_user_id, is_active);\n\ncreate index if not exists collection_reports_collection_idx\n  on collection_reports (collection_id, created_at desc);\n\ncreate index if not exists collection_reports_reporter_idx\n  on collection_reports (reporter_user_id, created_at desc);\n\ncreate index if not exists member_obligations_collection_user_idx\n  on member_obligations (collection_id, user_id, status);\n\ncreate index if not exists parsed_events_receiver_idx\n  on parsed_payment_events (receiver_user_id, created_at desc);\n\ncreate index if not exists payment_allocations_collection_idx\n  on payment_allocations (collection_id, created_at desc);\n\ncreate index if not exists payment_intents_collection_status_idx\n  on payment_intents (collection_id, status, created_at desc);\n\ncreate index if not exists payment_intents_contributor_idx\n  on payment_intents (contributor_user_id, created_at desc);\n\ncreate index if not exists payments_contributor_idx\n  on payments (contributor_user_id, posted_at desc);\n\ncreate index if not exists public_collection_requests_collection_idx\n  on public_collection_requests (collection_id, status, requested_at desc);\n\ncreate index if not exists public_collection_requests_requester_idx\n  on public_collection_requests (requested_by, requested_at desc);\n\ncreate index if not exists receiver_mode_consents_user_idx\n  on receiver_mode_consents (user_id, created_at desc);\n\ncreate index if not exists recurring_periods_collection_status_idx\n  on recurring_periods (collection_id, status, period_start desc);\n\ndrop policy if exists \\"profiles update own non-admin\\" on profiles;\ncreate policy \\"profiles update own non-admin\\" on profiles\nfor update to authenticated\nusing (id = (select auth.uid()))\nwith check (id = (select auth.uid()));\n\ndrop policy if exists \\"collections read public or member\\" on collections;\ncreate policy \\"collections read public or member\\" on collections\nfor select\nusing (\n  public_status = 'public_approved'\n  or public.user_can_read_collection(id, (select auth.uid()))\n);\n\ndrop policy if exists \\"collections insert authenticated\\" on collections;\ncreate policy \\"collections insert authenticated\\" on collections\nfor insert to authenticated\nwith check (\n  creator_user_id = (select auth.uid())\n  and visibility = 'private'\n);\n\ndrop policy if exists \\"collections update admins\\" on collections;\ncreate policy \\"collections update admins\\" on collections\nfor update to authenticated\nusing (public.user_is_collection_admin(id, (select auth.uid())))\nwith check (public.user_is_collection_admin(id, (select auth.uid())));\n\ndrop policy if exists \\"members read scoped\\" on collection_members;\ncreate policy \\"members read scoped\\" on collection_members\nfor select to authenticated\nusing (public.user_can_read_collection(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"members manage admins\\" on collection_members;\ncreate policy \\"members manage admins\\" on collection_members\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"receivers read collection admins\\" on collection_receivers;\ncreate policy \\"receivers read collection admins\\" on collection_receivers\nfor select to authenticated\nusing (\n  public.user_is_collection_admin(collection_id, (select auth.uid()))\n  or receiver_user_id = (select auth.uid())\n);\n\ndrop policy if exists \\"receivers manage admins\\" on collection_receivers;\ncreate policy \\"receivers manage admins\\" on collection_receivers\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"payment instructions platform admin manage\\" on payment_instruction_templates;\ncreate policy \\"payment instructions platform admin manage\\" on payment_instruction_templates\nfor all to authenticated\nusing ((select public.current_user_is_platform_admin()))\nwith check ((select public.current_user_is_platform_admin()));\n\ndrop policy if exists \\"invites read admins\\" on collection_invites;\ncreate policy \\"invites read admins\\" on collection_invites\nfor select to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"invites manage admins\\" on collection_invites;\ncreate policy \\"invites manage admins\\" on collection_invites\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"payment intents read contributor or admin\\" on payment_intents;\ncreate policy \\"payment intents read contributor or admin\\" on payment_intents\nfor select to authenticated\nusing (\n  contributor_user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"payment intents create contributor\\" on payment_intents;\ncreate policy \\"payment intents create contributor\\" on payment_intents\nfor insert to authenticated\nwith check (\n  contributor_user_id = (select auth.uid())\n  and public.user_can_read_collection(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"payment intents update contributor txn or admin\\" on payment_intents;\ncreate policy \\"payment intents update contributor txn or admin\\" on payment_intents\nfor update to authenticated\nusing (\n  contributor_user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n)\nwith check (\n  contributor_user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"raw sms receiver own read\\" on raw_payment_sms;\ncreate policy \\"raw sms receiver own read\\" on raw_payment_sms\nfor select to authenticated\nusing (\n  receiver_user_id = (select auth.uid())\n  or (select public.current_user_is_platform_admin())\n);\n\ndrop policy if exists \\"parsed events receiver or admin read\\" on parsed_payment_events;\ncreate policy \\"parsed events receiver or admin read\\" on parsed_payment_events\nfor select to authenticated\nusing (\n  receiver_user_id = (select auth.uid())\n  or (select public.current_user_is_platform_admin())\n);\n\ndrop policy if exists \\"payments read scoped\\" on payments;\ncreate policy \\"payments read scoped\\" on payments\nfor select to authenticated\nusing (\n  contributor_user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"allocations read collection admins\\" on payment_allocations;\ncreate policy \\"allocations read collection admins\\" on payment_allocations\nfor select to authenticated\nusing (\n  public.user_is_collection_admin(collection_id, (select auth.uid()))\n  or (select public.current_user_is_platform_admin())\n);\n\ndrop policy if exists \\"ledger read scoped\\" on ledger_entries;\ncreate policy \\"ledger read scoped\\" on ledger_entries\nfor select to authenticated\nusing (\n  user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"recurring periods read scoped\\" on recurring_periods;\ncreate policy \\"recurring periods read scoped\\" on recurring_periods\nfor select to authenticated\nusing (public.user_can_read_collection(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"recurring periods manage admins\\" on recurring_periods;\ncreate policy \\"recurring periods manage admins\\" on recurring_periods\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"obligations read own or admin\\" on member_obligations;\ncreate policy \\"obligations read own or admin\\" on member_obligations\nfor select to authenticated\nusing (\n  user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"obligations manage admins\\" on member_obligations;\ncreate policy \\"obligations manage admins\\" on member_obligations\nfor all to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"public requests read requester or admin\\" on public_collection_requests;\ncreate policy \\"public requests read requester or admin\\" on public_collection_requests\nfor select to authenticated\nusing (\n  requested_by = (select auth.uid())\n  or (select public.current_user_is_platform_admin())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"public requests insert requester\\" on public_collection_requests;\ncreate policy \\"public requests insert requester\\" on public_collection_requests\nfor insert to authenticated\nwith check (\n  requested_by = (select auth.uid())\n  and public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"public requests admin update\\" on public_collection_requests;\ncreate policy \\"public requests admin update\\" on public_collection_requests\nfor update to authenticated\nusing ((select public.current_user_is_platform_admin()))\nwith check ((select public.current_user_is_platform_admin()));\n\ndrop policy if exists \\"reports read admins\\" on collection_reports;\ncreate policy \\"reports read admins\\" on collection_reports\nfor select to authenticated\nusing (\n  (select public.current_user_is_platform_admin())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n  or reporter_user_id = (select auth.uid())\n);\n\ndrop policy if exists \\"reports insert authenticated\\" on collection_reports;\ncreate policy \\"reports insert authenticated\\" on collection_reports\nfor insert to authenticated\nwith check (reporter_user_id = (select auth.uid()));\n\ndrop policy if exists \\"reports update platform admin\\" on collection_reports;\ncreate policy \\"reports update platform admin\\" on collection_reports\nfor update to authenticated\nusing ((select public.current_user_is_platform_admin()))\nwith check ((select public.current_user_is_platform_admin()));\n\ndrop policy if exists \\"receiver consents own\\" on receiver_mode_consents;\ncreate policy \\"receiver consents own\\" on receiver_mode_consents\nfor all to authenticated\nusing (user_id = (select auth.uid()))\nwith check (user_id = (select auth.uid()));\n\ndrop policy if exists \\"audit logs platform or scoped collection admins\\" on audit_logs;\ncreate policy \\"audit logs platform or scoped collection admins\\" on audit_logs\nfor select to authenticated\nusing (\n  (select public.current_user_is_platform_admin())\n  or (\n    entity_type = 'collection'\n    and entity_id is not null\n    and public.user_is_collection_admin(entity_id, (select auth.uid()))\n  )\n);\n"}
202605230004	restore_payment_intent_paid_rpc	{"create or replace function report_payment_intent_paid(\n  intent uuid,\n  transaction_id text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  intent_row payment_intents;\n  cleaned_transaction_id text;\nbegin\n  if (select auth.uid()) is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select * into intent_row\n  from payment_intents\n  where id = intent\n  for update;\n\n  if not found then\n    raise exception 'Payment intent not found';\n  end if;\n\n  if intent_row.contributor_user_id is distinct from (select auth.uid())\n     and not public.user_is_collection_admin(intent_row.collection_id, (select auth.uid())) then\n    raise exception 'Not authorized to report this payment intent';\n  end if;\n\n  if intent_row.status <> 'pending' then\n    raise exception 'Only pending payment intents can be reported paid';\n  end if;\n\n  cleaned_transaction_id := nullif(upper(trim(coalesce(transaction_id, ''))), '');\n\n  update payment_intents\n    set reported_transaction_id = cleaned_transaction_id\n    where id = intent;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    (select auth.uid()),\n    'payment_intent.reported_paid',\n    'payment_intent',\n    intent,\n    jsonb_build_object('transaction_id_present', cleaned_transaction_id is not null)\n  );\nend;\n$$;\n\ngrant execute on function report_payment_intent_paid(uuid, text) to authenticated;\n"}
202605230005	restore_sms_collection_scope	{"alter table raw_payment_sms\n  add column if not exists collection_id uuid references collections(id) on delete set null;\n\nalter table parsed_payment_events\n  add column if not exists collection_id uuid references collections(id) on delete set null;\n\ncreate index if not exists raw_sms_collection_idx\n  on raw_payment_sms (collection_id, ingested_at desc);\n\ncreate index if not exists parsed_events_collection_review_idx\n  on parsed_payment_events (collection_id, allocation_status, created_at desc);\n\ncreate or replace view member_collection_summary_view\nas\nselect\n  c.id as collection_id,\n  c.title,\n  c.category,\n  c.visibility,\n  c.public_status,\n  c.creator_user_id,\n  (\n    select coalesce(sum(le.amount_rwf) filter (where le.entry_type = 'collection_credit'), 0)::bigint\n    from ledger_entries le\n    where le.collection_id = c.id\n  ) as amount_raised_rwf,\n  (\n    select count(distinct coalesce(p.contributor_user_id::text, p.transaction_id, p.id::text))::bigint\n    from payments p\n    where p.collection_id = c.id\n  ) as supporter_count,\n  (\n    select count(pi.id)::bigint\n    from payment_intents pi\n    where pi.collection_id = c.id\n      and pi.status = 'pending'\n  ) as pending_intent_count,\n  (\n    select count(distinct ppe.id)::bigint\n    from collection_receivers cr\n    join parsed_payment_events ppe\n      on ppe.receiver_user_id = cr.receiver_user_id\n     and (\n       ppe.collection_id = c.id\n       or (\n         ppe.collection_id is null\n         and ppe.receiver_phone_hash = cr.momo_number_hash\n       )\n     )\n    where cr.collection_id = c.id\n      and ppe.allocation_status in ('needs_review', 'ambiguous')\n  ) as review_event_count\nfrom collections c\nwhere public.user_can_read_collection(c.id, auth.uid());\n\ncreate or replace view parsed_payment_events_review_view\nas\nselect distinct on (ppe.id, coalesce(ppe.collection_id, cr.collection_id))\n  ppe.id,\n  coalesce(ppe.collection_id, cr.collection_id) as collection_id,\n  ppe.raw_sms_id,\n  ppe.receiver_user_id,\n  ppe.is_mobile_money_payment,\n  ppe.network,\n  ppe.direction,\n  ppe.amount_rwf,\n  ppe.currency,\n  ppe.transaction_id,\n  ppe.sender_name,\n  ppe.transaction_time,\n  ppe.detected_collection_code,\n  ppe.detected_user_public_id,\n  ppe.confidence,\n  ppe.parser_model,\n  ppe.parser_schema_version,\n  ppe.allocation_status,\n  ppe.review_reason,\n  ppe.created_at\nfrom parsed_payment_events ppe\nleft join collection_receivers cr\n  on cr.receiver_user_id = ppe.receiver_user_id\n and cr.is_active\n and ppe.collection_id is null\n and ppe.receiver_phone_hash = cr.momo_number_hash\nwhere (\n  ppe.collection_id is not null\n  and public.user_can_read_collection(ppe.collection_id, auth.uid())\n)\nor (\n  ppe.collection_id is null\n  and cr.collection_id is not null\n  and public.user_can_read_collection(cr.collection_id, auth.uid())\n);\n\ngrant select on member_collection_summary_view, parsed_payment_events_review_view to authenticated;\n"}
202605230006	finalize_payment_intent_hardening	{"drop policy if exists \\"payment intents update contributor txn or admin\\" on payment_intents;\n\nrevoke update on payment_intents from anon, authenticated;\ngrant select on payment_intents to authenticated;\n\ngrant execute on function report_payment_intent_paid(uuid, text) to authenticated;\n"}
202605230007	revoke_public_function_execute	{"set search_path = public;\n\nrevoke execute on all functions in schema public from public;\nalter default privileges in schema public revoke execute on functions from public;\n\ngrant execute on all functions in schema public to service_role;\n\ngrant execute on function public.current_user_is_platform_admin() to anon, authenticated;\ngrant execute on function public.user_is_collection_admin(uuid, uuid) to anon, authenticated;\ngrant execute on function public.user_can_read_collection(uuid, uuid) to anon, authenticated;\ngrant execute on function public.user_can_ingest_receiver_sms(text, uuid, uuid) to authenticated;\n\ngrant execute on function public.get_current_profile() to authenticated;\ngrant execute on function public.create_collection_with_owner(text, text, text, bigint, text, text, text, text, boolean, jsonb) to authenticated;\ngrant execute on function public.create_collection_invite(uuid, text, text, member_role) to authenticated;\ngrant execute on function public.create_payment_intent(uuid, bigint, text, text) to authenticated;\ngrant execute on function public.create_payment_intent_with_instructions(uuid, bigint, text, text) to authenticated;\ngrant execute on function public.report_payment_intent_paid(uuid, text) to authenticated;\ngrant execute on function public.request_public_collection(uuid) to authenticated;\ngrant execute on function public.review_public_collection(uuid, boolean, text) to authenticated;\ngrant execute on function public.manual_allocate_parsed_payment_event(uuid, uuid, uuid, text) to authenticated;\n"}
202605230008	admin_panel	{"create table if not exists admin_roles (\n  id uuid primary key default gen_random_uuid(),\n  name text unique not null check (name ~ '^[a-z_]+$'),\n  description text not null default '',\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists admin_permissions (\n  name text primary key check (name ~ '^[a-z_]+(\\\\.[a-z_]+)+$'),\n  description text not null default '',\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists admin_role_permissions (\n  role_id uuid not null references admin_roles(id) on delete cascade,\n  permission_name text not null references admin_permissions(name) on delete cascade,\n  created_at timestamptz not null default now(),\n  primary key (role_id, permission_name)\n);\n\ncreate table if not exists admin_user_roles (\n  user_id uuid not null references profiles(id) on delete cascade,\n  role_id uuid not null references admin_roles(id) on delete cascade,\n  granted_by uuid references profiles(id) on delete set null,\n  reason text not null,\n  created_at timestamptz not null default now(),\n  revoked_at timestamptz,\n  revoked_by uuid references profiles(id) on delete set null,\n  revoke_reason text,\n  primary key (user_id, role_id, created_at)\n);\n\ncreate table if not exists admin_sensitive_access_logs (\n  id uuid primary key default gen_random_uuid(),\n  actor_user_id uuid not null references profiles(id) on delete restrict,\n  entity_type text not null,\n  entity_id uuid not null,\n  reason text not null,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\n\ncreate table if not exists feature_flags (\n  key text primary key check (key ~ '^[a-z0-9_.-]+$'),\n  enabled boolean not null default false,\n  description text not null default '',\n  metadata jsonb not null default '{}'::jsonb,\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists system_settings (\n  key text primary key check (key ~ '^[a-z0-9_.-]+$'),\n  value jsonb not null default '{}'::jsonb,\n  description text not null default '',\n  is_sensitive boolean not null default false,\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists moderation_flags (\n  id uuid primary key default gen_random_uuid(),\n  entity_type text not null,\n  entity_id uuid not null,\n  status text not null default 'open' check (status in ('open', 'reviewing', 'resolved', 'dismissed')),\n  reason text not null,\n  created_by uuid references profiles(id) on delete set null,\n  resolved_by uuid references profiles(id) on delete set null,\n  resolution_note text,\n  created_at timestamptz not null default now(),\n  resolved_at timestamptz\n);\n\ncreate table if not exists admin_notes (\n  id uuid primary key default gen_random_uuid(),\n  entity_type text not null,\n  entity_id uuid not null,\n  body text not null,\n  created_by uuid not null references profiles(id) on delete restrict,\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists admin_user_roles_user_active_idx on admin_user_roles (user_id, revoked_at);\ncreate index if not exists admin_sensitive_access_actor_idx on admin_sensitive_access_logs (actor_user_id, created_at desc);\ncreate index if not exists moderation_flags_entity_idx on moderation_flags (entity_type, entity_id, status, created_at desc);\ncreate index if not exists admin_notes_entity_idx on admin_notes (entity_type, entity_id, created_at desc);\ncreate index if not exists audit_logs_action_created_idx on audit_logs (action, created_at desc);\ncreate index if not exists raw_sms_ingested_status_idx on raw_payment_sms (parse_status, ingested_at desc);\n\nalter table admin_roles enable row level security;\nalter table admin_permissions enable row level security;\nalter table admin_role_permissions enable row level security;\nalter table admin_user_roles enable row level security;\nalter table admin_sensitive_access_logs enable row level security;\nalter table feature_flags enable row level security;\nalter table system_settings enable row level security;\nalter table moderation_flags enable row level security;\nalter table admin_notes enable row level security;\n\ncreate or replace function mask_phone(value text)\nreturns text\nlanguage sql\nimmutable\nas $$\n  select case\n    when value is null or length(regexp_replace(value, '\\\\D', '', 'g')) < 6 then null\n    else '+***' || right(regexp_replace(value, '\\\\D', '', 'g'), 4)\n  end;\n$$;\n\ninsert into admin_permissions (name, description)\nvalues\n  ('overview.read', 'Read admin overview'),\n  ('public_requests.read', 'Read public listing requests'),\n  ('public_requests.review', 'Approve or reject public listing requests'),\n  ('collections.read', 'Read collection operations data'),\n  ('collections.moderate', 'Moderate collections'),\n  ('users.read', 'Read user operations data'),\n  ('receivers.read', 'Read receiver metadata'),\n  ('sms.metadata.read', 'Read SMS metadata'),\n  ('sms.raw.reveal', 'Reveal raw SMS with reason'),\n  ('payment_events.read', 'Read parsed payment events'),\n  ('payment_events.reparse', 'Reparse payment events'),\n  ('payments.read', 'Read payments'),\n  ('payments.allocate', 'Manually allocate payments'),\n  ('ledger.read', 'Read immutable ledger'),\n  ('audit.read', 'Read audit logs'),\n  ('feature_flags.read', 'Read feature flags'),\n  ('feature_flags.manage', 'Manage feature flags'),\n  ('settings.read', 'Read system settings'),\n  ('settings.manage', 'Manage system settings'),\n  ('system_health.read', 'Read system health'),\n  ('admin_users.read', 'Read admin users and roles'),\n  ('admin_users.manage', 'Manage admin roles')\non conflict (name) do update set description = excluded.description;\n\ninsert into admin_roles (name, description)\nvalues\n  ('platform_owner', 'Full platform administration'),\n  ('compliance_admin', 'Audit, privacy, sensitive access, and compliance review'),\n  ('operations_admin', 'Collection and operational queue management'),\n  ('payments_admin', 'Payment event, allocation, payment, and ledger operations'),\n  ('moderation_admin', 'Public approval and moderation operations'),\n  ('support_admin', 'Read support-oriented users, collections, receivers, and events'),\n  ('read_only_admin', 'Read-only operational visibility')\non conflict (name) do update set description = excluded.description;\n\ninsert into admin_role_permissions (role_id, permission_name)\nselect r.id, p.name\nfrom admin_roles r\ncross join admin_permissions p\nwhere r.name = 'platform_owner'\non conflict do nothing;\n\ninsert into admin_role_permissions (role_id, permission_name)\nselect r.id, p.name\nfrom admin_roles r\njoin admin_permissions p on p.name in (\n  'overview.read', 'public_requests.read', 'public_requests.review',\n  'collections.read', 'collections.moderate', 'users.read', 'receivers.read',\n  'sms.metadata.read', 'payment_events.read', 'payment_events.reparse',\n  'payments.read', 'payments.allocate', 'ledger.read', 'audit.read',\n  'feature_flags.read', 'settings.read', 'system_health.read'\n)\nwhere r.name in ('operations_admin', 'payments_admin', 'moderation_admin', 'support_admin', 'read_only_admin')\non conflict do nothing;\n\ncreate or replace function is_platform_admin(user_uuid uuid default auth.uid())\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select coalesce((select p.is_platform_admin from profiles p where p.id = user_uuid), false)\n    or exists (\n      select 1\n      from admin_user_roles aur\n      join admin_roles ar on ar.id = aur.role_id\n      where aur.user_id = user_uuid\n        and aur.revoked_at is null\n        and ar.name = 'platform_owner'\n    );\n$$;\n\ncreate or replace function has_admin_permission(permission text, user_uuid uuid default auth.uid())\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select public.is_platform_admin(user_uuid)\n    or exists (\n      select 1\n      from admin_user_roles aur\n      join admin_role_permissions arp on arp.role_id = aur.role_id\n      where aur.user_id = user_uuid\n        and aur.revoked_at is null\n        and arp.permission_name = permission\n    );\n$$;\n\ncreate or replace function assert_admin_permission(permission text)\nreturns void\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if not public.has_admin_permission(permission, auth.uid()) then\n    raise exception 'Admin permission % required', permission;\n  end if;\nend;\n$$;\n\ncreate or replace function create_audit_log(\n  p_action text,\n  p_entity_type text,\n  p_entity_id uuid default null,\n  p_metadata jsonb default '{}'::jsonb,\n  p_actor uuid default auth.uid()\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  audit_id uuid;\nbegin\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (p_actor, p_action, p_entity_type, p_entity_id, coalesce(p_metadata, '{}'::jsonb))\n  returning id into audit_id;\n  return audit_id;\nend;\n$$;\n\ncreate or replace function admin_bootstrap_platform_owner(p_user_id uuid, p_reason text)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  owner_role_id uuid;\nbegin\n  if auth.role() <> 'service_role' then\n    raise exception 'Service role required';\n  end if;\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Bootstrap reason is required';\n  end if;\n  select id into owner_role_id from admin_roles where name = 'platform_owner';\n  insert into admin_user_roles (user_id, role_id, reason)\n  values (p_user_id, owner_role_id, p_reason);\n  perform create_audit_log('admin.bootstrap.platform_owner', 'profile', p_user_id, jsonb_build_object('reason', p_reason), p_user_id);\n  return jsonb_build_object('ok', true);\nend;\n$$;\n\ncreate or replace function admin_current_user()\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case\n    when auth.uid() is null then null\n    when not public.has_admin_permission('overview.read', auth.uid()) then null\n    else jsonb_build_object(\n      'user_id', p.id,\n      'display_name', coalesce(nullif(p.display_name, ''), 'Collect admin'),\n      'phone_masked', mask_phone(p.whatsapp_phone),\n      'roles', coalesce((\n        select jsonb_agg(distinct ar.name order by ar.name)\n        from admin_user_roles aur\n        join admin_roles ar on ar.id = aur.role_id\n        where aur.user_id = p.id and aur.revoked_at is null\n      ), case when p.is_platform_admin then '[\\"platform_owner\\"]'::jsonb else '[]'::jsonb end),\n      'permissions', coalesce((\n        select jsonb_agg(distinct arp.permission_name order by arp.permission_name)\n        from admin_user_roles aur\n        join admin_role_permissions arp on arp.role_id = aur.role_id\n        where aur.user_id = p.id and aur.revoked_at is null\n      ), case when p.is_platform_admin then (select jsonb_agg(name order by name) from admin_permissions) else '[]'::jsonb end)\n    )\n  end\n  from profiles p\n  where p.id = auth.uid();\n$$;\n\ncreate or replace function _admin_row(\n  p_id uuid,\n  p_title text,\n  p_subtitle text default '',\n  p_status text default 'unknown',\n  p_amount text default '',\n  p_created_at timestamptz default null,\n  p_extra jsonb default '{}'::jsonb\n)\nreturns jsonb\nlanguage sql\nstable\nas $$\n  select jsonb_build_object(\n    'id', p_id,\n    'title', coalesce(p_title, 'Record'),\n    'subtitle', coalesce(p_subtitle, ''),\n    'status', coalesce(p_status, 'unknown'),\n    'amount', coalesce(p_amount, ''),\n    'created_at', p_created_at\n  ) || coalesce(p_extra, '{}'::jsonb);\n$$;\n\ncreate or replace function admin_overview()\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('overview.read');\n  return jsonb_build_object(\n    'metrics', jsonb_build_array(\n      jsonb_build_object('label', 'Pending public requests', 'value', (select count(*) from public_collection_requests where status = 'pending'), 'status', 'pending'),\n      jsonb_build_object('label', 'Unallocated events', 'value', (select count(*) from parsed_payment_events where allocation_status in ('unallocated', 'ambiguous', 'needs_review')), 'status', 'needs_review'),\n      jsonb_build_object('label', 'Posted payments', 'value', (select count(*) from payments where status = 'posted'), 'status', 'posted'),\n      jsonb_build_object('label', 'Ledger credits RWF', 'value', coalesce((select sum(amount_rwf) from ledger_entries), 0), 'status', 'healthy')\n    )\n  );\nend;\n$$;\n\ncreate or replace function admin_list_public_requests(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('public_requests.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(r.id, c.title, coalesce(p.display_name, mask_phone(p.whatsapp_phone), 'Requester'), r.status, '', r.requested_at, jsonb_build_object('collection_id', r.collection_id)) order by r.requested_at desc)\n    from public_collection_requests r\n    join collections c on c.id = r.collection_id\n    left join profiles p on p.id = r.requested_by\n    where (p_status is null or r.status = p_status)\n      and (p_search is null or c.title ilike '%' || p_search || '%')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_collections(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('collections.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(c.id, c.title, c.category, c.public_status::text, coalesce(c.target_amount_rwf::text || ' RWF', ''), c.created_at) order by c.created_at desc)\n    from collections c\n    where (p_status is null or c.public_status::text = p_status)\n      and (p_search is null or c.title ilike '%' || p_search || '%')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_users(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('users.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(p.id, coalesce(p.display_name, 'User #' || p.public_id), mask_phone(p.whatsapp_phone), case when p.is_platform_admin then 'admin' else 'active' end, '', p.created_at) order by p.created_at desc)\n    from profiles p\n    where (p_search is null or p.display_name ilike '%' || p_search || '%' or p.public_id = p_search)\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_payment_events(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(e.id, coalesce(e.transaction_id, 'Payment event'), coalesce(e.sender_name, 'Unknown sender'), e.allocation_status::text, coalesce(e.amount_rwf::text || ' RWF', ''), e.created_at, jsonb_build_object('collection_id', e.collection_id)) order by e.created_at desc)\n    from parsed_payment_events e\n    where (p_status is null or e.allocation_status::text = p_status)\n      and (p_search is null or e.transaction_id ilike '%' || p_search || '%')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_unallocated(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select admin_list_payment_events(p_search, coalesce(p_status, 'needs_review'));\n$$;\n\ncreate or replace function admin_list_payments(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payments.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(p.id, coalesce(p.transaction_id, 'Payment'), p.source, p.status, p.amount_rwf::text || ' RWF', p.created_at) order by p.created_at desc)\n    from payments p\n    where (p_status is null or p.status = p_status)\n      and (p_search is null or p.transaction_id ilike '%' || p_search || '%')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_ledger(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('ledger.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(le.id, le.entry_type, le.collection_id::text, le.visibility, le.amount_rwf::text || ' RWF', le.created_at) order by le.created_at desc)\n    from ledger_entries le\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_receivers(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('receivers.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(cr.id, cr.label, mask_phone(cr.momo_number), case when cr.is_active then 'active' else 'inactive' end, cr.network, cr.created_at) order by cr.created_at desc)\n    from collection_receivers cr\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_sms_metadata(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('sms.metadata.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(s.id, coalesce(mask_phone(s.raw_sender), 'SMS'), s.body_hash, s.parse_status, '', s.ingested_at) order by s.ingested_at desc)\n    from raw_payment_sms s\n    where (p_status is null or s.parse_status = p_status)\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_audit_logs(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('audit.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(a.id, a.action, a.entity_type, 'logged', '', a.created_at) order by a.created_at desc)\n    from audit_logs a\n    where (p_search is null or a.action ilike '%' || p_search || '%')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_feature_flags(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('feature_flags.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(gen_random_uuid(), key, description, case when enabled then 'enabled' else 'disabled' end, '', updated_at) order by key)\n    from feature_flags\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_settings(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('settings.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(gen_random_uuid(), key, description, case when is_sensitive then 'sensitive' else 'normal' end, '', updated_at) order by key)\n    from system_settings\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_admin_users(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('admin_users.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(p.id, coalesce(p.display_name, 'User #' || p.public_id), ar.name, 'admin', '', aur.created_at) order by aur.created_at desc)\n    from admin_user_roles aur\n    join profiles p on p.id = aur.user_id\n    join admin_roles ar on ar.id = aur.role_id\n    where aur.revoked_at is null\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_get_collection(p_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('collections.read');\n  return coalesce((select to_jsonb(c) from collections c where c.id = p_id), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_get_user(p_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('users.read');\n  return coalesce((select to_jsonb(p) - 'whatsapp_phone' - 'momo_number' || jsonb_build_object('whatsapp_phone', mask_phone(p.whatsapp_phone), 'momo_number', mask_phone(p.momo_number)) from profiles p where p.id = p_id), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_get_payment(p_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('payments.read');\n  return coalesce((select to_jsonb(p) from payments p where p.id = p_id), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_get_payment_event(p_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return coalesce((select to_jsonb(e) from parsed_payment_events e where e.id = p_id), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_get_receiver(p_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('receivers.read');\n  return coalesce((select to_jsonb(cr) - 'momo_number' || jsonb_build_object('momo_number', mask_phone(cr.momo_number)) from collection_receivers cr where cr.id = p_id), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_get_sms_metadata(p_id uuid)\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('sms.metadata.read');\n  return coalesce((\n    select jsonb_build_object(\n      'id', s.id,\n      'collection_id', s.collection_id,\n      'receiver_user_id', s.receiver_user_id,\n      'raw_sender_masked', mask_phone(s.raw_sender),\n      'body_hash', s.body_hash,\n      'masked_body', left(regexp_replace(s.raw_body, '[0-9+]{4,}', '***', 'g'), 240),\n      'parse_status', s.parse_status,\n      'received_at_device', s.received_at_device,\n      'ingested_at', s.ingested_at\n    )\n    from raw_payment_sms s\n    where s.id = p_id\n  ), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_system_health(p_id text default 'system')\nreturns jsonb language plpgsql stable security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('system_health.read');\n  return jsonb_build_object(\n    'database', 'healthy',\n    'auth', 'configured',\n    'parser_pending_sms', (select count(*) from raw_payment_sms where parse_status = 'pending'),\n    'failed_sms_parse', (select count(*) from raw_payment_sms where parse_status = 'failed'),\n    'unallocated_events', (select count(*) from parsed_payment_events where allocation_status in ('unallocated', 'ambiguous', 'needs_review')),\n    'checked_at', now()\n  );\nend;\n$$;\n\ncreate or replace function admin_review_public_request(p_request_id uuid, p_approved boolean, p_reason text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('public_requests.review');\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n  perform review_public_collection(p_request_id, p_approved, p_reason);\n  return jsonb_build_object('ok', true, 'message', 'Public request reviewed');\nend;\n$$;\n\ncreate or replace function admin_moderate_collection(p_collection_id uuid, p_status text, p_reason text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('collections.moderate');\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n  if p_status not in ('private', 'public_rejected', 'archived') then\n    raise exception 'Unsupported moderation status';\n  end if;\n  update collections\n    set public_status = p_status::collection_visibility,\n        visibility = case when p_status = 'archived' then 'archived'::collection_visibility else 'private'::collection_visibility end,\n        archived_at = case when p_status = 'archived' then now() else archived_at end\n    where id = p_collection_id;\n  perform create_audit_log('collection.moderated', 'collection', p_collection_id, jsonb_build_object('status', p_status, 'reason', p_reason));\n  return jsonb_build_object('ok', true);\nend;\n$$;\n\ncreate or replace function admin_manual_allocate_payment(p_event_id uuid, p_collection_id uuid, p_payment_intent_id uuid default null, p_reason text default null)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare\n  payment_id uuid;\nbegin\n  perform assert_admin_permission('payments.allocate');\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n  payment_id := manual_allocate_parsed_payment_event(p_event_id, p_collection_id, p_payment_intent_id, p_reason);\n  return jsonb_build_object('ok', true, 'message', payment_id::text);\nend;\n$$;\n\ncreate or replace function admin_reparse_payment_event(p_event_id uuid, p_reason text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\nbegin\n  perform assert_admin_permission('payment_events.reparse');\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n  update parsed_payment_events\n    set allocation_status = 'needs_review',\n        review_reason = 'Reparse requested: ' || p_reason\n    where id = p_event_id and allocation_status <> 'allocated';\n  perform create_audit_log('payment_event.reparse.requested', 'parsed_payment_event', p_event_id, jsonb_build_object('reason', p_reason));\n  return jsonb_build_object('ok', true, 'message', 'Reparse queued for review');\nend;\n$$;\n\ncreate or replace function admin_reveal_raw_sms(p_sms_id uuid, p_reason text)\nreturns jsonb language plpgsql security definer set search_path = public as $$\ndeclare\n  raw_body text;\nbegin\n  perform assert_admin_permission('sms.raw.reveal');\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n  select s.raw_body into raw_body from raw_payment_sms s where s.id = p_sms_id;\n  if raw_body is null then\n    raise exception 'Raw SMS not found';\n  end if;\n  insert into admin_sensitive_access_logs (actor_user_id, entity_type, entity_id, reason)\n  values (auth.uid(), 'raw_payment_sms', p_sms_id, p_reason);\n  perform create_audit_log('sms.raw.revealed', 'raw_payment_sms', p_sms_id, jsonb_build_object('reason', p_reason));\n  return jsonb_build_object('ok', true, 'message', raw_body);\nend;\n$$;\n\ndrop policy if exists \\"admin roles read admins\\" on admin_roles;\ncreate policy \\"admin roles read admins\\" on admin_roles for select to authenticated using (has_admin_permission('admin_users.read'));\ndrop policy if exists \\"admin permissions read admins\\" on admin_permissions;\ncreate policy \\"admin permissions read admins\\" on admin_permissions for select to authenticated using (has_admin_permission('admin_users.read'));\ndrop policy if exists \\"admin role permissions read admins\\" on admin_role_permissions;\ncreate policy \\"admin role permissions read admins\\" on admin_role_permissions for select to authenticated using (has_admin_permission('admin_users.read'));\ndrop policy if exists \\"admin user roles read admins\\" on admin_user_roles;\ncreate policy \\"admin user roles read admins\\" on admin_user_roles for select to authenticated using (has_admin_permission('admin_users.read') or user_id = auth.uid());\ndrop policy if exists \\"sensitive access logs read compliance\\" on admin_sensitive_access_logs;\ncreate policy \\"sensitive access logs read compliance\\" on admin_sensitive_access_logs for select to authenticated using (has_admin_permission('audit.read'));\ndrop policy if exists \\"feature flags read admins\\" on feature_flags;\ncreate policy \\"feature flags read admins\\" on feature_flags for select to authenticated using (has_admin_permission('feature_flags.read'));\ndrop policy if exists \\"system settings read admins\\" on system_settings;\ncreate policy \\"system settings read admins\\" on system_settings for select to authenticated using (has_admin_permission('settings.read'));\ndrop policy if exists \\"moderation flags read admins\\" on moderation_flags;\ncreate policy \\"moderation flags read admins\\" on moderation_flags for select to authenticated using (has_admin_permission('collections.moderate'));\ndrop policy if exists \\"admin notes read admins\\" on admin_notes;\ncreate policy \\"admin notes read admins\\" on admin_notes for select to authenticated using (has_admin_permission('collections.read') or has_admin_permission('users.read'));\n\ndrop policy if exists \\"raw sms receiver own read\\" on raw_payment_sms;\ndrop policy if exists \\"raw sms metadata scoped read\\" on raw_payment_sms;\ncreate policy \\"raw sms metadata scoped read\\" on raw_payment_sms\nfor select to authenticated\nusing (\n  receiver_user_id = auth.uid()\n  or has_admin_permission('sms.metadata.read')\n);\n\nrevoke all on raw_payment_sms from anon, authenticated;\ngrant select (\n  id,\n  collection_id,\n  receiver_user_id,\n  raw_sender,\n  body_hash,\n  receiver_momo_number_hash,\n  received_at_device,\n  ingested_at,\n  parse_status,\n  created_at\n) on raw_payment_sms to authenticated;\n\nrevoke execute on all functions in schema public from public, anon, authenticated;\ngrant execute on all functions in schema public to service_role;\ngrant execute on function public.current_user_is_platform_admin() to anon, authenticated;\ngrant execute on function public.user_is_collection_admin(uuid, uuid) to anon, authenticated;\ngrant execute on function public.user_can_read_collection(uuid, uuid) to anon, authenticated;\ngrant execute on function public.user_can_ingest_receiver_sms(text, uuid, uuid) to authenticated;\ngrant execute on function get_current_profile() to authenticated;\ngrant execute on function create_collection_with_owner(text, text, text, bigint, text, text, text, text, boolean, jsonb) to authenticated;\ngrant execute on function create_collection_invite(uuid, text, text, member_role) to authenticated;\ngrant execute on function create_payment_intent(uuid, bigint, text, text) to authenticated;\ngrant execute on function create_payment_intent_with_instructions(uuid, bigint, text, text) to authenticated;\ngrant execute on function report_payment_intent_paid(uuid, text) to authenticated;\ngrant execute on function request_public_collection(uuid) to authenticated;\ngrant execute on function review_public_collection(uuid, boolean, text) to authenticated;\ngrant execute on function manual_allocate_parsed_payment_event(uuid, uuid, uuid, text) to authenticated;\ngrant execute on function is_platform_admin(uuid) to authenticated;\ngrant execute on function has_admin_permission(text, uuid) to authenticated;\ngrant execute on function admin_current_user() to authenticated;\ngrant execute on function admin_overview() to authenticated;\ngrant execute on function admin_list_public_requests(text, text) to authenticated;\ngrant execute on function admin_list_collections(text, text) to authenticated;\ngrant execute on function admin_list_users(text, text) to authenticated;\ngrant execute on function admin_list_payment_events(text, text) to authenticated;\ngrant execute on function admin_list_unallocated(text, text) to authenticated;\ngrant execute on function admin_list_payments(text, text) to authenticated;\ngrant execute on function admin_list_ledger(text, text) to authenticated;\ngrant execute on function admin_list_receivers(text, text) to authenticated;\ngrant execute on function admin_list_sms_metadata(text, text) to authenticated;\ngrant execute on function admin_list_audit_logs(text, text) to authenticated;\ngrant execute on function admin_list_feature_flags(text, text) to authenticated;\ngrant execute on function admin_list_settings(text, text) to authenticated;\ngrant execute on function admin_list_admin_users(text, text) to authenticated;\ngrant execute on function admin_get_collection(uuid) to authenticated;\ngrant execute on function admin_get_user(uuid) to authenticated;\ngrant execute on function admin_get_payment(uuid) to authenticated;\ngrant execute on function admin_get_payment_event(uuid) to authenticated;\ngrant execute on function admin_get_receiver(uuid) to authenticated;\ngrant execute on function admin_get_sms_metadata(uuid) to authenticated;\ngrant execute on function admin_system_health(text) to authenticated;\ngrant execute on function admin_review_public_request(uuid, boolean, text) to authenticated;\ngrant execute on function admin_moderate_collection(uuid, text, text) to authenticated;\ngrant execute on function admin_manual_allocate_payment(uuid, uuid, uuid, text) to authenticated;\ngrant execute on function admin_reparse_payment_event(uuid, text) to authenticated;\ngrant execute on function admin_reveal_raw_sms(uuid, text) to authenticated;\n"}
20260930235700	sensitive_reason_whitespace	{"begin;\n\n-- Actual current-bundle probes allowed BOM-only reasons and retained\n-- invisible Unicode padding in reveal/retry audit reasons. Normalize\n-- through235500's private helper before the original1..1000 bounds.\n-- Keep authority, locks, API attributes, audit, retry and ACK semantics.\ndo $$begin\n if to_regprocedure('collect_admin_access.normalized_operator_reason(text)') is null then\n  raise exception 'sensitive_reason_normalizer_required' using errcode='55000';\n end if;\nend$$;\n\nCREATE OR REPLACE FUNCTION public.admin_reveal_raw_sms(p_sms_id uuid, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  raw_body text;\n  reason text := collect_admin_access.normalized_operator_reason(p_reason);\nbegin\n  perform assert_admin_permission('sms.raw.reveal');\n  if char_length(reason) not between 1 and 1000 or reason ~ '^[[:space:]]*$' then\n    raise exception 'Reason is required';\n  end if;\n  select s.raw_body into raw_body from raw_payment_sms s where s.id = p_sms_id;\n  if raw_body is null then\n    raise exception 'Raw SMS not found';\n  end if;\n  insert into admin_sensitive_access_logs (actor_user_id, entity_type, entity_id, reason)\n  values (auth.uid(), 'raw_payment_sms', p_sms_id, reason);\n  perform create_audit_log('sms.raw.revealed', 'raw_payment_sms', p_sms_id, jsonb_build_object('reason', reason));\n  return jsonb_build_object('ok', true, 'message', raw_body);\nend;\n$function$;\n\nCREATE OR REPLACE FUNCTION public.admin_retry_notification(p_event_id uuid, p_reason text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\n SET search_path TO 'public'\nAS $function$\ndeclare\n  reason text := collect_admin_access.normalized_operator_reason(p_reason);\n  device_ids uuid[];\n  session_ids uuid[];\n  retried integer;\nbegin\n  perform public._lock_notification_session_gate();\n  perform public.assert_admin_permission('notifications.manage');\n  if char_length(reason) not between 1 and 1000 or reason ~ '^[[:space:]]*$' then raise exception 'Reason is required'; end if;\n  select array_agg(locked.id) into session_ids from (\n    select s.id from auth.sessions s where exists(select 1 from public.notification_device_tokens device\n      join public.notification_deliveries d on d.device_id=device.id\n      where device.registration_session_id=s.id and d.event_id=p_event_id and d.status='failed')\n    order by s.id for share of s\n  ) locked;\n  select array_agg(locked.id) into device_ids from (\n    select device.id from public.notification_device_tokens device\n    join public.notification_events event on event.user_id = device.user_id and event.id = p_event_id\n    where device.registration_session_id=any(session_ids)\n      and public._notification_session_is_live(device.registration_session_id,device.user_id)\n      and device.enabled and device.provider in ('apns', 'fcm') and device.token is not null\n      and exists (select 1 from public.notification_deliveries d where d.device_id = device.id\n        and d.event_id = p_event_id and d.status = 'failed'\n        and (d.claim_expires_at is null or d.claim_expires_at <= clock_timestamp()))\n    order by device.id for update of device\n  ) locked;\n  update public.notification_deliveries d set status = 'queued',\n    prior_attempt_count = d.prior_attempt_count + d.attempt_count, attempt_count = 0,\n    next_attempt_at = clock_timestamp(), last_attempt_at = null, sent_at = null,\n    provider_message_id = null, last_error_code = null,\n    claim_token = null, claim_expires_at = null, claim_user_id = null, updated_at = clock_timestamp()\n  where d.event_id = p_event_id and d.device_id = any(device_ids) and d.status = 'failed'\n    and (d.claim_expires_at is null or d.claim_expires_at <= clock_timestamp());\n  get diagnostics retried = row_count;\n  if retried = 0 then raise exception 'No retryable failed deliveries'; end if;\n  perform public._refresh_notification_event(p_event_id);\n  perform public.create_audit_log('notification.delivery.retried', 'notification_event', p_event_id,\n    jsonb_build_object('reason', reason, 'delivery_count', retried));\n  return jsonb_build_object('ok', true, 'status', 'queued', 'delivery_count', retried);\nend $function$;\n\nnotify pgrst,'reload schema';\ncommit;\n"}
202605230009	add_client_safe_views	{"set search_path = public;\n\ncreate or replace view member_collections_view\nas\nselect\n  c.id,\n  c.slug,\n  c.creator_user_id,\n  c.title,\n  c.description,\n  c.category,\n  c.cover_image_url,\n  c.currency,\n  c.target_amount_rwf,\n  c.deadline_at,\n  c.visibility,\n  c.public_status,\n  c.is_recurring,\n  c.recurring_rule,\n  c.allow_anonymous,\n  c.contribution_visibility,\n  case\n    when public.user_is_collection_admin(c.id, auth.uid())\n      or exists (\n        select 1\n        from collection_receivers receiver_check\n        where receiver_check.collection_id = c.id\n          and receiver_check.receiver_user_id = auth.uid()\n          and receiver_check.is_active\n      )\n      then cr.momo_number\n    else null\n  end as receiver_momo_number,\n  case\n    when public.user_can_read_collection(c.id, auth.uid()) then cr.label\n    else null\n  end as receiver_display_label,\n  cr.network as receiver_network,\n  c.created_at,\n  c.updated_at,\n  c.archived_at\nfrom collections c\nleft join lateral (\n  select\n    collection_receivers.momo_number,\n    collection_receivers.label,\n    collection_receivers.network\n  from collection_receivers\n  where collection_receivers.collection_id = c.id\n    and collection_receivers.is_active\n  order by collection_receivers.created_at asc\n  limit 1\n) cr on true\nwhere public.user_can_read_collection(c.id, auth.uid());\n\ncreate or replace view member_contributions_view\nas\nselect\n  p.collection_id,\n  p.id as payment_id,\n  p.amount_rwf,\n  p.currency,\n  p.status,\n  p.source,\n  case\n    when p.contributor_user_id = auth.uid()\n      or public.user_is_collection_admin(p.collection_id, auth.uid())\n      then p.transaction_id\n    else null\n  end as transaction_id,\n  p.anonymity_choice,\n  p.posted_at,\n  p.created_at,\n  case\n    when p.contributor_user_id = auth.uid() then 'You'\n    when p.anonymity_choice = 'display_name'\n      and p.contributor_user_id is not null\n      and public.user_is_collection_admin(p.collection_id, auth.uid())\n      then coalesce(pr.display_name, 'User #' || pr.public_id)\n    when p.anonymity_choice = 'public_id'\n      and p.contributor_public_id is not null\n      then 'User #' || p.contributor_public_id\n    else 'Anonymous supporter'\n  end as supporter_label\nfrom payments p\nleft join profiles pr on pr.id = p.contributor_user_id\nwhere p.status = 'posted'\n  and (\n    p.contributor_user_id = auth.uid()\n    or public.user_is_collection_admin(p.collection_id, auth.uid())\n    or exists (\n      select 1\n      from collections c\n      where c.id = p.collection_id\n        and c.public_status = 'public_approved'\n    )\n  );\n\ncreate or replace view member_public_collection_requests_view\nas\nselect\n  pcr.id,\n  pcr.collection_id,\n  c.title as collection_title,\n  pcr.requested_by,\n  pcr.status,\n  pcr.admin_user_id,\n  pcr.admin_note,\n  pcr.requested_at,\n  pcr.reviewed_at\nfrom public_collection_requests pcr\njoin collections c on c.id = pcr.collection_id\nwhere pcr.requested_by = auth.uid()\n  or public.current_user_is_platform_admin()\n  or public.user_is_collection_admin(pcr.collection_id, auth.uid());\n\ncreate or replace function record_receiver_mode_consent(\n  enabled boolean,\n  momo_number_hash text default null,\n  build_channel text default 'internal_receiver',\n  device_label text default 'flutter_app'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  consent_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  insert into receiver_mode_consents (\n    user_id,\n    enabled,\n    momo_number_hash,\n    build_channel,\n    device_label\n  )\n  values (\n    auth.uid(),\n    coalesce(enabled, false),\n    momo_number_hash,\n    nullif(build_channel, ''),\n    nullif(device_label, '')\n  )\n  returning id into consent_id;\n\n  insert into audit_logs (\n    actor_user_id,\n    action,\n    entity_type,\n    entity_id,\n    metadata\n  )\n  values (\n    auth.uid(),\n    case\n      when coalesce(enabled, false) then 'receiver_mode.enabled'\n      else 'receiver_mode.disabled'\n    end,\n    'receiver_mode_consent',\n    consent_id,\n    jsonb_build_object('build_channel', build_channel, 'device_label', device_label)\n  );\n\n  return consent_id;\nend;\n$$;\n\nrevoke execute on function record_receiver_mode_consent(boolean, text, text, text) from public, anon;\ngrant select on member_collections_view to authenticated;\ngrant select on member_contributions_view to authenticated;\ngrant select on member_public_collection_requests_view to authenticated;\ngrant execute on function record_receiver_mode_consent(boolean, text, text, text) to authenticated;\n"}
202605230010	grant_collection_receiver_read	{"set search_path = public;\n\ngrant select on collection_receivers to authenticated;\n"}
202605230011	fix_receiver_consent_execute_grant	{"set search_path = public;\n\nrevoke execute on function record_receiver_mode_consent(boolean, text, text, text) from public, anon;\ngrant execute on function record_receiver_mode_consent(boolean, text, text, text) to authenticated;\n"}
202605230012	admin_rpc_grants	{"grant execute on function admin_current_user() to authenticated;\ngrant execute on function admin_overview() to authenticated;\ngrant execute on function admin_list_public_requests(text, text) to authenticated;\ngrant execute on function admin_list_collections(text, text) to authenticated;\ngrant execute on function admin_list_users(text, text) to authenticated;\ngrant execute on function admin_list_payment_events(text, text) to authenticated;\ngrant execute on function admin_list_unallocated(text, text) to authenticated;\ngrant execute on function admin_list_payments(text, text) to authenticated;\ngrant execute on function admin_list_ledger(text, text) to authenticated;\ngrant execute on function admin_list_receivers(text, text) to authenticated;\ngrant execute on function admin_list_sms_metadata(text, text) to authenticated;\ngrant execute on function admin_list_audit_logs(text, text) to authenticated;\ngrant execute on function admin_get_collection(uuid) to authenticated;\ngrant execute on function admin_get_user(uuid) to authenticated;\ngrant execute on function admin_get_payment(uuid) to authenticated;\ngrant execute on function admin_get_payment_event(uuid) to authenticated;\ngrant execute on function admin_get_receiver(uuid) to authenticated;\ngrant execute on function admin_get_sms_metadata(uuid) to authenticated;\ngrant execute on function admin_system_health(text) to authenticated;\n"}
202605230013	admin_settings_flags	{"insert into feature_flags (key, enabled, description)\nvalues\n  ('enable_android_sms_access', false, 'Android-only SMS app access for consented MoMo SMS ingestion'),\n  ('enable_sms_reader', false, 'Restricted SMS reader integration for approved internal builds'),\n  ('admin_panel_enabled', true, 'Platform admin panel access through Supabase Auth and admin roles')\non conflict (key) do update set description = excluded.description;\n\ninsert into system_settings (key, value, description, is_sensitive)\nvalues\n  ('payments.mode', '{\\"provider\\":\\"payment_intent_momo_ussd\\",\\"country\\":\\"RW\\",\\"currency\\":\\"RWF\\"}'::jsonb, 'Collect payment mode: payment intent, MoMo USSD launch, and automated SMS allocation', false),\n  ('sms.parser.schema_version', '\\"collect.sms_parser.v1\\"'::jsonb, 'Active SMS parser structured output schema version', false)\non conflict (key) do update\nset value = excluded.value,\n    description = excluded.description,\n    is_sensitive = excluded.is_sensitive,\n    updated_at = now();\n"}
202605230014	admin_review_hardening	{"revoke all on raw_payment_sms from anon, authenticated;\ngrant select (\n  id,\n  collection_id,\n  receiver_user_id,\n  raw_sender,\n  body_hash,\n  receiver_momo_number_hash,\n  received_at_device,\n  ingested_at,\n  parse_status,\n  created_at\n) on raw_payment_sms to authenticated;\n\nrevoke execute on function admin_reveal_raw_sms(uuid, text) from public, anon, authenticated;\ngrant execute on function admin_reveal_raw_sms(uuid, text) to authenticated;\n\nrevoke execute on function admin_manual_allocate_payment(uuid, uuid, uuid, text) from public, anon, authenticated;\ngrant execute on function admin_manual_allocate_payment(uuid, uuid, uuid, text) to authenticated;\n\nrevoke execute on function admin_reparse_payment_event(uuid, text) from public, anon, authenticated;\ngrant execute on function admin_reparse_payment_event(uuid, text) to authenticated;\n"}
202605230015	admin_collection_moderation	{"create or replace function admin_moderate_collection(\n  p_collection_id uuid,\n  p_status text,\n  p_reason text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('collections.moderate');\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n  if p_status not in ('private', 'public_rejected', 'archived') then\n    raise exception 'Unsupported moderation status';\n  end if;\n  update collections\n    set public_status = p_status::collection_visibility,\n        visibility = case\n          when p_status = 'archived' then 'archived'::collection_visibility\n          else 'private'::collection_visibility\n        end,\n        archived_at = case\n          when p_status = 'archived' then now()\n          else archived_at\n        end\n    where id = p_collection_id;\n  perform create_audit_log(\n    'collection.moderated',\n    'collection',\n    p_collection_id,\n    jsonb_build_object('status', p_status, 'reason', p_reason)\n  );\n  return jsonb_build_object('ok', true, 'message', 'Collection moderated');\nend;\n$$;\n\nrevoke execute on function admin_moderate_collection(uuid, text, text) from public, anon, authenticated;\ngrant execute on function admin_moderate_collection(uuid, text, text) to authenticated;\n"}
202605230016	drop_unowned_admin_helpers	{"drop function if exists admin_manage_admin_user_roles(uuid, text, boolean, text);\ndrop function if exists admin_manage_feature_flag(text, boolean, text);\ndrop function if exists admin_manage_receiver(uuid, boolean, text, text);\ndrop function if exists admin_manage_system_setting(text, jsonb, text);\ndrop function if exists admin_update_user_status(uuid, text, text);\ndrop function if exists hash_phone(text);\n"}
20261001000100	operational_exception_inbox	{"begin;\n\n-- Derived operational evidence only. No payment, allocation, receipt, sender\n-- or policy action is authorized by acknowledging/escalating an exception.\ncreate schema collect_ops;\nrevoke all on schema collect_ops from public,anon,authenticated,service_role;\ncreate table collect_ops.exceptions(\n id uuid primary key default gen_random_uuid(),\n source_kind text not null check(source_kind in('raw_sms','allocation','payment','receipt','gateway')),\n source_id uuid not null,\n reason_code text not null check(reason_code in('PARSING_FAILED','ALLOCATION_REVIEW',\n  'VERIFICATION_PENDING','VERIFICATION_REJECTED','VERIFICATION_CONFLICT','CONTACT_MISSING',\n  'SEND_UNCERTAIN','SEND_FAILED_NO_SEND','RECEIPT_SUPPRESSED','GATEWAY_UNOBSERVED',\n  'GATEWAY_STALE','GATEWAY_SMS_PERMISSION','GATEWAY_NETWORK','GATEWAY_TELEPHONY','GATEWAY_SIM')),\n active boolean not null,\n source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),\n revision bigint not null check(revision between 1 and 1000000000),\n first_observed_at timestamptz not null default clock_timestamp(),\n last_changed_at timestamptz not null default clock_timestamp(),\n unique(source_kind,source_id,reason_code)\n);\ncreate index operational_exception_inbox_order on collect_ops.exceptions(active,last_changed_at desc,id desc);\ncreate table collect_ops.exception_observations(\n exception_id uuid not null references collect_ops.exceptions(id) on delete restrict,\n revision bigint not null,\n active boolean not null,\n source_sha256 text not null check(source_sha256 ~ '^[a-f0-9]{64}$'),\n observed_at timestamptz not null,\n primary key(exception_id,revision)\n);\ncreate table collect_ops.exception_actions(\n request_id uuid primary key,\n exception_id uuid not null references collect_ops.exceptions(id) on delete restrict,\n expected_revision bigint not null,\n action text not null check(action in('acknowledge','escalate')),\n reason_code text not null check(reason_code in('review_started','owner_review_required',\n  'uncertain_send_review','contact_review')),\n actor_id uuid not null,\n session_id uuid not null,\n recorded_at timestamptz not null default clock_timestamp(),\n result jsonb not null\n);\ndo $$declare t text;begin\n foreach t in array array['exceptions','exception_observations','exception_actions'] loop\n  execute format('alter table collect_ops.%I enable row level security',t);\n  execute format('revoke all on collect_ops.%I from public,anon,authenticated,service_role',t);\n end loop;\nend$$;\ncreate function collect_ops.immutable_evidence() returns trigger language plpgsql set search_path='' as $$\nbegin raise exception 'operational_exception_evidence_immutable' using errcode='55000';end$$;\ncreate trigger immutable_exception_observation before update or delete on collect_ops.exception_observations\n for each row execute function collect_ops.immutable_evidence();\ncreate trigger immutable_exception_action before update or delete on collect_ops.exception_actions\n for each row execute function collect_ops.immutable_evidence();\ncreate trigger retain_exception before delete on collect_ops.exceptions\n for each row execute function collect_ops.immutable_evidence();\ncreate function collect_ops.protect_identity() returns trigger language plpgsql set search_path='' as $$\nbegin\n if(to_jsonb(new)-array['active','source_sha256','revision','last_changed_at'])is distinct from\n   (to_jsonb(old)-array['active','source_sha256','revision','last_changed_at'])\n  or new.revision<>old.revision+1 or new.last_changed_at<old.last_changed_at\n  or(new.active=old.active and new.source_sha256=old.source_sha256) then\n  raise exception 'operational_exception_identity_immutable' using errcode='55000';end if;\n return new;\nend$$;\ncreate trigger protect_exception_identity before update on collect_ops.exceptions\n for each row execute function collect_ops.protect_identity();\n\ncreate function collect_ops.observe(p_kind text,p_source uuid,p_codes text[],p_signature jsonb)\nreturns void language plpgsql security definer set search_path='' as $$\ndeclare code text;digest text;item collect_ops.exceptions;at timestamptz;\nbegin\n if p_kind is null or p_kind not in('raw_sms','allocation','payment','receipt','gateway')\n  or p_source is null or p_codes is null or array_position(p_codes,null) is not null\n  or cardinality(p_codes)>15 or p_signature is null then\n  raise exception 'operational_exception_source_invalid' using errcode='22023';end if;\n digest:=encode(extensions.digest(convert_to(p_signature::text,'UTF8'),'sha256'),'hex');\n -- Source-local lock, not a global commit-order watermark. Triggers never\n -- invoke an external service or depend on Codex availability.\n perform pg_advisory_xact_lock(hashtextextended('collect-ops-source:'||p_kind||':'||p_source::text,0));\n foreach code in array p_codes loop\n  at:=clock_timestamp();\n  insert into collect_ops.exceptions(source_kind,source_id,reason_code,active,source_sha256,revision,\n   first_observed_at,last_changed_at) values(p_kind,p_source,code,true,digest,1,at,at)\n  on conflict(source_kind,source_id,reason_code) do update\n   set active=true,source_sha256=excluded.source_sha256,revision=exceptions.revision+1,\n    last_changed_at=greatest(exceptions.last_changed_at,excluded.last_changed_at)\n   where not exceptions.active or exceptions.source_sha256 is distinct from excluded.source_sha256\n  returning * into item;\n  if item.id is not null then\n   insert into collect_ops.exception_observations(exception_id,revision,active,source_sha256,observed_at)\n    values(item.id,item.revision,item.active,item.source_sha256,item.last_changed_at);\n  end if;\n end loop;\n for item in update collect_ops.exceptions set active=false,source_sha256=digest,\n  revision=revision+1,last_changed_at=greatest(last_changed_at,clock_timestamp())\n  where source_kind=p_kind and source_id=p_source and active and not(reason_code=any(p_codes)) returning * loop\n  insert into collect_ops.exception_observations(exception_id,revision,active,source_sha256,observed_at)\n   values(item.id,item.revision,item.active,item.source_sha256,item.last_changed_at);\n end loop;\nend$$;\n\ncreate function collect_ops.payment_scope(p_payment uuid) returns boolean\nlanguage sql stable security definer set search_path='' as $$\n select exists(select 1 from public.payments p where p.id=p_payment and p.currency='RWF'\n  and p.provider_network in('mtn_momo','airtel_money') and\n  (exists(select 1 from public.parsed_payment_events e join public.raw_payment_sms sms on sms.id=e.raw_sms_id\n    where e.id=p.parsed_event_id and e.network=p.provider_network and e.receiver_user_id=p.receiver_user_id\n    and sms.receiver_momo_number_hash=p.receiver_momo_number_hash and collect_security.rwanda_sms_scope(e.raw_sms_id))\n   or exists(select 1 from public.collection_receivers r where r.collection_id=p.collection_id\n    and r.receiver_user_id=p.receiver_user_id and r.momo_number_hash=p.receiver_momo_number_hash\n    and r.network=p.provider_network and\n    ((r.network='mtn_momo' and r.momo_number ~ '^(\\\\+250|0)7[89][0-9]{7}$')\n     or(r.network='airtel_money' and r.momo_number ~ '^(\\\\+250|0)7[23][0-9]{7}$')))\n   or exists(select 1 from public.profiles r where r.id=p.receiver_user_id\n    and r.country_code='RW' and r.currency_code='RWF' and r.momo_number_verified_at is not null\n    and r.momo_number_hash=p.receiver_momo_number_hash and r.momo_provider=p.provider_network and\n    ((r.momo_provider='mtn_momo' and r.momo_number ~ '^(\\\\+250|0)7[89][0-9]{7}$')\n     or(r.momo_provider='airtel_money' and r.momo_number ~ '^(\\\\+250|0)7[23][0-9]{7}$')))))\n$$;\n\ncreate function collect_ops.refresh_source(p_kind text,p_source uuid) returns void\nlanguage plpgsql security definer set search_path='' as $$\ndeclare sms public.raw_payment_sms;event public.parsed_payment_events;payment public.payments;\n receipt collect_hybrid.sms_notification_outbox;device collect_gateway.devices;\n health collect_gateway.health_observations;codes text[]:='{}';signature jsonb;\n confirmation public.payment_provider_confirmations;rejected boolean;fresh boolean;\nbegin\n if p_source is null then raise exception 'operational_exception_source_invalid' using errcode='22023';end if;\n -- Acquire the source lock before taking its current predicate snapshot.\n -- A refresh queued behind a committed change must not reopen old evidence.\n perform pg_advisory_xact_lock(hashtextextended('collect-ops-source:'||p_kind||':'||p_source::text,0));\n if p_kind='raw_sms' then\n  select * into sms from public.raw_payment_sms where id=p_source;\n  if sms.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;\n  if sms.parse_status='failed' and collect_security.rwanda_sms_scope(sms.id) then codes:=array['PARSING_FAILED'];end if;\n  signature:=jsonb_build_array(sms.parse_status,collect_security.rwanda_sms_scope(sms.id));\n elsif p_kind='allocation' then\n  select * into event from public.parsed_payment_events where id=p_source;\n  if event.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;\n  if event.allocation_status in('unallocated','ambiguous','needs_review') and collect_security.rwanda_sms_scope(event.raw_sms_id) then\n   codes:=array['ALLOCATION_REVIEW'];end if;\n  signature:=jsonb_build_array(event.allocation_status,event.collection_id,collect_security.rwanda_sms_scope(event.raw_sms_id));\n elsif p_kind='payment' then\n  select * into payment from public.payments where id=p_source;\n  if payment.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;\n  select * into confirmation from public.payment_provider_confirmations where payment_id=payment.id;\n  rejected:=exists(select 1 from collect_hybrid.payment_provider_rejections where payment_id=payment.id);\n  if collect_ops.payment_scope(payment.id) then\n   if rejected then codes:=array_append(codes,'VERIFICATION_REJECTED');end if;\n   if confirmation.id is not null and(rejected or confirmation.amount_rwf<>payment.amount_rwf\n    or confirmation.provider_network is distinct from payment.provider_network\n    or confirmation.receiver_momo_number_hash is distinct from payment.receiver_momo_number_hash\n    or upper(btrim(confirmation.transaction_id)) is distinct from upper(btrim(payment.transaction_id))) then\n    codes:=array_append(codes,'VERIFICATION_CONFLICT');\n   elsif payment.status='review' and confirmation.id is null and not rejected then codes:=array_append(codes,'VERIFICATION_PENDING');end if;\n   if payment.status='posted' and not exists(select 1 from collect_hybrid.sms_notification_outbox where payment_id=payment.id)\n    and exists(select 1 from collect_hybrid.member_records m\n     join collect_hybrid.sms_receipt_policies policy on policy.collection_id=payment.collection_id and policy.enabled\n     join collect_hybrid.sms_receipt_member_consents consent on consent.member_record_id=m.id and consent.enabled\n     where m.id=payment.member_record_id and m.lifecycle='active' and m.linked_user_id is null\n      and not exists(select 1 from collect_hybrid.member_momo_identities i where i.member_id=m.id)) then\n    codes:=array_append(codes,'CONTACT_MISSING');end if;\n  end if;\n  signature:=jsonb_build_array(payment.status,confirmation.id,rejected,codes,collect_ops.payment_scope(payment.id));\n elsif p_kind='receipt' then\n  select * into receipt from collect_hybrid.sms_notification_outbox where id=p_source;\n  if receipt.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;\n  if collect_ops.payment_scope(receipt.payment_id) then\n   codes:=case receipt.state when 'uncertain' then array['SEND_UNCERTAIN']\n    when 'failed_no_send' then array['SEND_FAILED_NO_SEND'] when 'suppressed' then array['RECEIPT_SUPPRESSED'] else '{}'::text[] end;\n  end if;\n  signature:=jsonb_build_array(receipt.state,receipt.fence_version,receipt.attempt_count,codes,collect_ops.payment_scope(receipt.payment_id));\n elsif p_kind='gateway' then\n  select * into device from collect_gateway.devices where id=p_source;\n  if device.id is null then raise exception 'operational_exception_source_unavailable' using errcode='22023';end if;\n  select * into health from collect_gateway.health_observations where device_id=device.id order by ingested_at desc,id desc limit 1;\n  fresh:=health.id is not null and clock_timestamp()<least(health.reported_at,health.ingested_at)+interval '120 seconds';\n  if device.state='active' then\n   if health.id is null then codes:=array['GATEWAY_UNOBSERVED'];\n   elsif not fresh then codes:=array['GATEWAY_STALE'];\n   else\n    if not health.sms_permission then codes:=array_append(codes,'GATEWAY_SMS_PERMISSION');end if;\n    if health.network<>'validated' then codes:=array_append(codes,'GATEWAY_NETWORK');end if;\n    if health.telephony<>'ready' then codes:=array_append(codes,'GATEWAY_TELEPHONY');end if;\n    if not health.sim_selected then codes:=array_append(codes,'GATEWAY_SIM');end if;\n   end if;\n  end if;\n  signature:=jsonb_build_array(device.state,health.id,fresh,codes);\n else raise exception 'operational_exception_source_invalid' using errcode='22023';end if;\n perform collect_ops.observe(p_kind,p_source,codes,signature);\nend$$;\n\ncreate function collect_ops.capture_source() returns trigger\nlanguage plpgsql security definer set search_path='' as $$\ndeclare kind text;source uuid;\nbegin\n kind:=case tg_table_name when 'raw_payment_sms' then 'raw_sms' when 'parsed_payment_events' then 'allocation'\n  when 'payments' then 'payment' when 'sms_notification_outbox' then 'receipt' when 'devices' then 'gateway'\n  when 'health_observations' then 'gateway' when 'payment_provider_confirmations' then 'payment'\n  when 'payment_provider_rejections' then 'payment' end;\n if tg_table_name='health_observations' then source:=new.device_id;\n elsif tg_table_name in('payment_provider_confirmations','payment_provider_rejections') then source:=new.payment_id;\n else source:=new.id;end if;\n perform collect_ops.refresh_source(kind,source);return new;\nend$$;\ncreate trigger zzzz_operational_raw after insert or update of parse_status on public.raw_payment_sms\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_allocation after insert or update of allocation_status,collection_id on public.parsed_payment_events\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_payment after insert or update of status on public.payments\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_receipt after insert or update of state on collect_hybrid.sms_notification_outbox\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_device after insert or update of state on collect_gateway.devices\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_health after insert on collect_gateway.health_observations\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_confirmation after insert on public.payment_provider_confirmations\n for each row execute function collect_ops.capture_source();\ncreate trigger zzzz_operational_rejection after insert on collect_hybrid.payment_provider_rejections\n for each row execute function collect_ops.capture_source();\n\ncreate function collect_ops.actor(p_mutation boolean) returns uuid\nlanguage plpgsql volatile security definer set search_path='' as $$\ndeclare sid uuid;permissions text[]:=array['payments.read','notifications.read','system_health.read'];\nbegin\n if current_setting('transaction_isolation')<>'read committed' then\n  raise exception 'operational_exception_snapshot_retry' using errcode='40001';end if;\n sid:=public._lock_notification_registration_session();\n perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));\n if p_mutation then permissions:=array_append(permissions,'notifications.manage');end if;\n perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,'platform_owner',permissions);\n return sid;\nend$$;\ncreate function collect_ops.utc(p_time timestamptz) returns text language sql immutable set search_path='' as $$\n select to_char(p_time at time zone 'UTC','YYYY-MM-DD\\"T\\"HH24:MI:SS.US\\"Z\\"')$$;\n\ncreate function public.refresh_operational_exception_sources_v1(p_source_kind text,p_source_ids uuid[])\nreturns jsonb language plpgsql security definer set search_path='' as $$\ndeclare source uuid;\nbegin\n if auth.role() is distinct from 'service_role' then raise exception 'operational_exception_service_required' using errcode='42501';end if;\n if current_setting('transaction_isolation')<>'read committed' then\n  raise exception 'operational_exception_snapshot_retry' using errcode='40001';end if;\n if p_source_kind is null or p_source_kind not in('raw_sms','allocation','payment','receipt','gateway')\n  or p_source_ids is null or cardinality(p_source_ids) not between 1 and 25\n  or array_position(p_source_ids,null) is not null\n  or(select count(distinct id) from unnest(p_source_ids) id)<>cardinality(p_source_ids) then\n  raise exception 'operational_exception_source_invalid' using errcode='22023';end if;\n for source in select ids.id from unnest(p_source_ids)as ids(id)order by ids.id loop\n  perform collect_ops.refresh_source(p_source_kind,source);end loop;\n return jsonb_build_object('contract_version',1,'source_kind',p_source_kind,'checked',cardinality(p_source_ids),\n  'financial_action',false,'send_action',false);\nend$$;\n\ncreate function public.admin_list_operational_exceptions_v1(p_active boolean default true,p_limit integer default 20,\n p_before_changed_at timestamptz default null,p_before_id uuid default null)\nreturns jsonb language plpgsql volatile security definer set search_path='' as $$\ndeclare rows jsonb;last jsonb;more boolean;\nbegin\n perform collect_ops.actor(false);\n if p_active is null or p_limit is null or p_limit not between 1 and 50\n  or((p_before_changed_at is null)<>(p_before_id is null))\n  or(p_before_changed_at is not null and not isfinite(p_before_changed_at)) then\n  raise exception 'operational_exception_query_invalid' using errcode='22023';end if;\n select coalesce(jsonb_agg(jsonb_build_object('id',e.id,'source_kind',e.source_kind,'source_id',e.source_id,\n  'reason_code',e.reason_code,'active',e.active,'revision',e.revision,'source_sha256',e.source_sha256,\n  'first_observed_at',collect_ops.utc(e.first_observed_at),'last_changed_at',collect_ops.utc(e.last_changed_at),\n  'acknowledged',exists(select 1 from collect_ops.exception_actions a where a.exception_id=e.id and a.expected_revision=e.revision and a.action='acknowledge'),\n  'escalation_requested',exists(select 1 from collect_ops.exception_actions a where a.exception_id=e.id and a.expected_revision=e.revision and a.action='escalate'))\n  order by e.last_changed_at desc,e.id desc),'[]'::jsonb) into rows\n from(select * from collect_ops.exceptions where active=p_active and\n  (p_before_changed_at is null or(last_changed_at,id)<(p_before_changed_at,p_before_id))\n  order by last_changed_at desc,id desc limit p_limit+1)e;\n more:=jsonb_array_length(rows)>p_limit;if more then rows:=rows-(jsonb_array_length(rows)-1);end if;\n last:=rows->(jsonb_array_length(rows)-1);\n return jsonb_build_object('contract_version',1,'checked_at',collect_ops.utc(clock_timestamp()),\n  'rows',rows,'active',p_active,'limit',p_limit,\n  'next_cursor',case when more then jsonb_build_object('changed_at',last->'last_changed_at','id',last->'id')else null end,\n  'escalation_delivery_verified',false,'source_scan_complete',false);\nend$$;\n\ncreate function public.admin_act_operational_exception_v1(p_request_id uuid,p_exception_id uuid,\n p_expected_revision bigint,p_action text,p_reason_code text) returns jsonb\nlanguage plpgsql volatile security definer set search_path='' as $$\ndeclare sid uuid;prior collect_ops.exception_actions;item collect_ops.exceptions;at timestamptz;result jsonb;\nbegin\n sid:=collect_ops.actor(true);\n if p_request_id is null or p_exception_id is null or p_expected_revision is null or p_expected_revision not between 1 and 1000000000\n  or p_action is null or p_action not in('acknowledge','escalate') or p_reason_code is null\n  or p_reason_code not in('review_started','owner_review_required','uncertain_send_review','contact_review') then\n  raise exception 'operational_exception_action_invalid' using errcode='22023';end if;\n perform pg_advisory_xact_lock(hashtextextended('collect-ops-action:'||p_request_id::text,0));\n select * into prior from collect_ops.exception_actions where request_id=p_request_id;\n if prior.request_id is not null then\n  if prior.actor_id<>auth.uid() or prior.exception_id<>p_exception_id or prior.expected_revision<>p_expected_revision\n   or prior.action<>p_action or prior.reason_code<>p_reason_code then\n   raise exception 'operational_exception_request_conflict' using errcode='22023';end if;\n  return prior.result;\n end if;\n select * into item from collect_ops.exceptions where id=p_exception_id;\n if item.id is null then raise exception 'operational_exception_unavailable' using errcode='22023';end if;\n -- Re-check the actual source before recording review. This may update only\n -- derived operational evidence; it cannot clear or retry a financial/send source.\n perform collect_ops.refresh_source(item.source_kind,item.source_id);\n select * into item from collect_ops.exceptions where id=p_exception_id for share;\n if not item.active or item.revision<>p_expected_revision then raise exception 'operational_exception_source_changed' using errcode='55000';end if;\n at:=clock_timestamp();result:=jsonb_build_object('contract_version',1,'request_id',p_request_id,'exception_id',item.id,\n  'revision',item.revision,'action',p_action,'recorded_at',collect_ops.utc(at),'source_resolved',false,\n  'financial_action',false,'send_action',false,'escalation_delivery_verified',false);\n insert into collect_ops.exception_actions(request_id,exception_id,expected_revision,action,reason_code,actor_id,session_id,recorded_at,result)\n  values(p_request_id,item.id,item.revision,p_action,p_reason_code,auth.uid(),sid,at,result);\n perform public.create_audit_log('operations.exception.'||p_action,'operational_exception',item.id,\n  jsonb_build_object('request_id',p_request_id,'revision',item.revision,'reason_code',p_reason_code,\n   'financial_action',false,'send_action',false),null);\n return result;\nend$$;\ncreate function public.admin_get_operational_exception_action_v1(p_request_id uuid) returns jsonb\nlanguage plpgsql volatile security definer set search_path='' as $$\ndeclare prior collect_ops.exception_actions;\nbegin\n perform collect_ops.actor(false);\n if p_request_id is null then raise exception 'operational_exception_action_invalid' using errcode='22023';end if;\n if not pg_try_advisory_xact_lock(hashtextextended('collect-ops-action:'||p_request_id::text,0))then\n  return jsonb_build_object('contract_version',1,'request_id',p_request_id,'status','in_progress','receipt',null);end if;\n select * into prior from collect_ops.exception_actions where request_id=p_request_id and actor_id=auth.uid();\n return jsonb_build_object('contract_version',1,'request_id',p_request_id,\n  'status',case when prior.request_id is null then 'not_recorded' else 'recorded' end,'receipt',prior.result);\nend$$;\nrevoke all on all functions in schema collect_ops from public,anon,authenticated,service_role;\nrevoke all on function public.refresh_operational_exception_sources_v1(text,uuid[]),\n public.admin_list_operational_exceptions_v1(boolean,integer,timestamptz,uuid),\n public.admin_act_operational_exception_v1(uuid,uuid,bigint,text,text),\n public.admin_get_operational_exception_action_v1(uuid) from public,anon,authenticated,service_role;\ngrant execute on function public.refresh_operational_exception_sources_v1(text,uuid[]) to service_role;\ngrant execute on function public.admin_list_operational_exceptions_v1(boolean,integer,timestamptz,uuid),\n public.admin_act_operational_exception_v1(uuid,uuid,bigint,text,text),\n public.admin_get_operational_exception_action_v1(uuid) to authenticated;\ncommit;\n"}
202605230017	admin_list_filter_contracts	{"create or replace function admin_list_users(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('users.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(p.id, coalesce(p.display_name, 'User #' || p.public_id), mask_phone(p.whatsapp_phone), case when p.is_platform_admin then 'admin' else 'active' end, '', p.created_at) order by p.created_at desc)\n    from profiles p\n    where (\n        p_search is null\n        or p.display_name ilike '%' || p_search || '%'\n        or p.public_id = p_search\n      )\n      and (\n        p_status is null\n        or (p_status = 'admin' and p.is_platform_admin)\n        or (p_status = 'active' and not p.is_platform_admin)\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_unallocated(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  return admin_list_payment_events(p_search, coalesce(p_status, 'needs_review'));\nend;\n$$;\n\ncreate or replace function admin_list_ledger(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('ledger.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(le.id, le.entry_type, le.collection_id::text, le.visibility, le.amount_rwf::text || ' RWF', le.created_at) order by le.created_at desc)\n    from ledger_entries le\n    where (\n        p_search is null\n        or le.entry_type ilike '%' || p_search || '%'\n        or le.collection_id::text = p_search\n      )\n      and (\n        p_status is null\n        or le.visibility = p_status\n        or le.entry_type = p_status\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_receivers(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('receivers.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(cr.id, cr.label, mask_phone(cr.momo_number), case when cr.is_active then 'active' else 'inactive' end, cr.network, cr.created_at) order by cr.created_at desc)\n    from collection_receivers cr\n    where (\n        p_search is null\n        or cr.label ilike '%' || p_search || '%'\n        or cr.network ilike '%' || p_search || '%'\n      )\n      and (\n        p_status is null\n        or (p_status = 'active' and cr.is_active)\n        or (p_status = 'inactive' and not cr.is_active)\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_audit_logs(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('audit.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(a.id, a.action, a.entity_type, 'logged', '', a.created_at) order by a.created_at desc)\n    from audit_logs a\n    where (\n        p_search is null\n        or a.action ilike '%' || p_search || '%'\n        or a.entity_type ilike '%' || p_search || '%'\n      )\n      and (p_status is null or p_status = 'logged')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_feature_flags(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('feature_flags.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(gen_random_uuid(), key, description, case when enabled then 'enabled' else 'disabled' end, '', updated_at) order by key)\n    from feature_flags\n    where (\n        p_search is null\n        or key ilike '%' || p_search || '%'\n        or description ilike '%' || p_search || '%'\n      )\n      and (\n        p_status is null\n        or (p_status = 'enabled' and enabled)\n        or (p_status = 'disabled' and not enabled)\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_settings(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('settings.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(gen_random_uuid(), key, description, case when is_sensitive then 'sensitive' else 'normal' end, '', updated_at) order by key)\n    from system_settings\n    where (\n        p_search is null\n        or key ilike '%' || p_search || '%'\n        or description ilike '%' || p_search || '%'\n      )\n      and (\n        p_status is null\n        or (p_status = 'sensitive' and is_sensitive)\n        or (p_status = 'normal' and not is_sensitive)\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_admin_users(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('admin_users.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(_admin_row(p.id, coalesce(p.display_name, 'User #' || p.public_id), ar.name, 'admin', '', aur.created_at) order by aur.created_at desc)\n    from admin_user_roles aur\n    join profiles p on p.id = aur.user_id\n    join admin_roles ar on ar.id = aur.role_id\n    where aur.revoked_at is null\n      and (\n        p_search is null\n        or p.display_name ilike '%' || p_search || '%'\n        or p.public_id = p_search\n        or ar.name ilike '%' || p_search || '%'\n      )\n      and (\n        p_status is null\n        or p_status = 'admin'\n        or ar.name = p_status\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_system_health(p_id text default 'system')\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('system_health.read');\n  return jsonb_build_object(\n    'id', coalesce(nullif(p_id, ''), 'system'),\n    'database', 'healthy',\n    'auth', 'configured',\n    'parser_pending_sms', (select count(*) from raw_payment_sms where parse_status = 'pending'),\n    'failed_sms_parse', (select count(*) from raw_payment_sms where parse_status = 'failed'),\n    'unallocated_events', (select count(*) from parsed_payment_events where allocation_status in ('unallocated', 'ambiguous', 'needs_review')),\n    'checked_at', now()\n  );\nend;\n$$;\n"}
20260523203132	tighten_admin_role_permissions	{"-- Tighten admin RBAC so each seeded role only carries the permissions needed\n-- for its operational lane. The original seed gave several non-owner roles the\n-- same broad permission set and left compliance_admin without permissions.\n\nupdate admin_roles\nset description = case name\n  when 'platform_owner' then 'Full platform administration'\n  when 'compliance_admin' then 'Audit, privacy, sensitive access, and compliance review'\n  when 'operations_admin' then 'Collection and operational queue management'\n  when 'payments_admin' then 'Payment event, allocation, payment, and ledger operations'\n  when 'moderation_admin' then 'Public approval and moderation operations'\n  when 'support_admin' then 'Read support-oriented users, collections, receivers, and events'\n  when 'read_only_admin' then 'Read-only operational visibility'\n  else description\nend\nwhere name in (\n  'platform_owner',\n  'compliance_admin',\n  'operations_admin',\n  'payments_admin',\n  'moderation_admin',\n  'support_admin',\n  'read_only_admin'\n);\n\ndelete from admin_role_permissions arp\nusing admin_roles ar\nwhere arp.role_id = ar.id\n  and ar.name <> 'platform_owner'\n  and ar.name in (\n    'compliance_admin',\n    'operations_admin',\n    'payments_admin',\n    'moderation_admin',\n    'support_admin',\n    'read_only_admin'\n  );\n\nwith desired(role_name, permission_name) as (\n  values\n    ('compliance_admin', 'overview.read'),\n    ('compliance_admin', 'users.read'),\n    ('compliance_admin', 'sms.metadata.read'),\n    ('compliance_admin', 'sms.raw.reveal'),\n    ('compliance_admin', 'payment_events.read'),\n    ('compliance_admin', 'payments.read'),\n    ('compliance_admin', 'ledger.read'),\n    ('compliance_admin', 'audit.read'),\n    ('compliance_admin', 'system_health.read'),\n\n    ('operations_admin', 'overview.read'),\n    ('operations_admin', 'public_requests.read'),\n    ('operations_admin', 'collections.read'),\n    ('operations_admin', 'collections.moderate'),\n    ('operations_admin', 'users.read'),\n    ('operations_admin', 'receivers.read'),\n    ('operations_admin', 'sms.metadata.read'),\n    ('operations_admin', 'payment_events.read'),\n    ('operations_admin', 'payments.read'),\n    ('operations_admin', 'ledger.read'),\n    ('operations_admin', 'audit.read'),\n    ('operations_admin', 'system_health.read'),\n\n    ('payments_admin', 'overview.read'),\n    ('payments_admin', 'collections.read'),\n    ('payments_admin', 'receivers.read'),\n    ('payments_admin', 'sms.metadata.read'),\n    ('payments_admin', 'payment_events.read'),\n    ('payments_admin', 'payment_events.reparse'),\n    ('payments_admin', 'payments.read'),\n    ('payments_admin', 'payments.allocate'),\n    ('payments_admin', 'ledger.read'),\n    ('payments_admin', 'audit.read'),\n    ('payments_admin', 'system_health.read'),\n\n    ('moderation_admin', 'overview.read'),\n    ('moderation_admin', 'public_requests.read'),\n    ('moderation_admin', 'public_requests.review'),\n    ('moderation_admin', 'collections.read'),\n    ('moderation_admin', 'collections.moderate'),\n    ('moderation_admin', 'users.read'),\n    ('moderation_admin', 'audit.read'),\n    ('moderation_admin', 'system_health.read'),\n\n    ('support_admin', 'overview.read'),\n    ('support_admin', 'public_requests.read'),\n    ('support_admin', 'collections.read'),\n    ('support_admin', 'users.read'),\n    ('support_admin', 'receivers.read'),\n    ('support_admin', 'sms.metadata.read'),\n    ('support_admin', 'payment_events.read'),\n    ('support_admin', 'payments.read'),\n    ('support_admin', 'audit.read'),\n    ('support_admin', 'system_health.read'),\n\n    ('read_only_admin', 'overview.read'),\n    ('read_only_admin', 'public_requests.read'),\n    ('read_only_admin', 'collections.read'),\n    ('read_only_admin', 'users.read'),\n    ('read_only_admin', 'receivers.read'),\n    ('read_only_admin', 'sms.metadata.read'),\n    ('read_only_admin', 'payment_events.read'),\n    ('read_only_admin', 'payments.read'),\n    ('read_only_admin', 'ledger.read'),\n    ('read_only_admin', 'audit.read'),\n    ('read_only_admin', 'feature_flags.read'),\n    ('read_only_admin', 'settings.read'),\n    ('read_only_admin', 'system_health.read'),\n    ('read_only_admin', 'admin_users.read')\n)\ninsert into admin_role_permissions (role_id, permission_name)\nselect ar.id, ap.name\nfrom desired d\njoin admin_roles ar on ar.name = d.role_name\njoin admin_permissions ap on ap.name = d.permission_name\non conflict do nothing;\n\ncreate or replace function public.current_user_is_platform_admin()\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select public.is_platform_admin(auth.uid());\n$$;\n\ncreate or replace function review_public_collection(\n  request_id uuid,\n  approved boolean,\n  p_admin_note text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  request_row public_collection_requests;\nbegin\n  if not (\n    public.current_user_is_platform_admin()\n    or public.has_admin_permission('public_requests.review', auth.uid())\n  ) then\n    raise exception 'Admin permission public_requests.review required';\n  end if;\n\n  select * into request_row\n  from public_collection_requests\n  where id = request_id\n  for update;\n\n  if not found then\n    raise exception 'Public collection request not found';\n  end if;\n\n  update public_collection_requests\n    set status = case when approved then 'approved' else 'rejected' end,\n        admin_user_id = auth.uid(),\n        admin_note = p_admin_note,\n        reviewed_at = now()\n    where id = request_id;\n\n  update collections\n    set public_status = case when approved then 'public_approved'::collection_visibility else 'public_rejected'::collection_visibility end,\n        visibility = case when approved then 'public_approved'::collection_visibility else 'private'::collection_visibility end\n    where id = request_row.collection_id;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    case when approved then 'collection.public_approved' else 'collection.public_rejected' end,\n    'collection',\n    request_row.collection_id,\n    jsonb_build_object('request_id', request_id, 'admin_note', p_admin_note)\n  );\nend;\n$$;\n\ncreate or replace function manual_allocate_parsed_payment_event(\n  event_id uuid,\n  target_collection_id uuid,\n  target_payment_intent_id uuid default null,\n  reason text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if coalesce(trim(reason), '') = '' then\n    raise exception 'Manual allocation reason is required';\n  end if;\n  if not (\n    public.user_is_collection_admin(target_collection_id, auth.uid())\n    or public.has_admin_permission('payments.allocate', auth.uid())\n  ) then\n    raise exception 'Admin permission payments.allocate required';\n  end if;\n  return post_payment_from_event(event_id, target_payment_intent_id, target_collection_id, 'manual', reason, auth.uid());\nend;\n$$;\n"}
20260523204235	set_views_security_invoker	{"-- Supabase security advisor 0010: public views should run with the querying\n-- user's privileges/RLS context instead of the view owner's privileges.\n\ngrant select (\n  id,\n  public_id,\n  display_name,\n  avatar_url,\n  anonymity_default,\n  created_at\n) on public.profiles to anon, authenticated;\n\ngrant select (\n  id,\n  slug,\n  creator_user_id,\n  title,\n  description,\n  category,\n  cover_image_url,\n  currency,\n  target_amount_rwf,\n  deadline_at,\n  visibility,\n  public_status,\n  is_recurring,\n  recurring_rule,\n  allow_anonymous,\n  contribution_visibility,\n  receiver_display_label,\n  created_at,\n  updated_at,\n  archived_at\n) on public.collections to anon, authenticated;\n\ngrant select (\n  id,\n  parsed_event_id,\n  payment_intent_id,\n  collection_id,\n  contributor_user_id,\n  contributor_public_id,\n  amount_rwf,\n  currency,\n  transaction_id,\n  source,\n  status,\n  anonymity_choice,\n  posted_at,\n  created_at\n) on public.payments to anon, authenticated;\n\ngrant select (\n  id,\n  payment_id,\n  collection_id,\n  user_id,\n  entry_type,\n  amount_rwf,\n  currency,\n  visibility,\n  created_at\n) on public.ledger_entries to anon, authenticated;\n\ndrop policy if exists \\"payments public posted or scoped\\" on public.payments;\ndrop policy if exists \\"payments read scoped\\" on public.payments;\ncreate policy \\"payments public posted or scoped\\" on public.payments\nfor select\nusing (\n  (\n    status = 'posted'\n    and exists (\n      select 1\n      from public.collections c\n      where c.id = payments.collection_id\n        and c.public_status = 'public_approved'\n        and c.archived_at is null\n    )\n  )\n  or contributor_user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\ndrop policy if exists \\"ledger public collection credit or scoped\\" on public.ledger_entries;\ndrop policy if exists \\"ledger read scoped\\" on public.ledger_entries;\ncreate policy \\"ledger public collection credit or scoped\\" on public.ledger_entries\nfor select\nusing (\n  (\n    entry_type = 'collection_credit'\n    and exists (\n      select 1\n      from public.collections c\n      where c.id = ledger_entries.collection_id\n        and c.public_status = 'public_approved'\n        and c.archived_at is null\n    )\n  )\n  or user_id = (select auth.uid())\n  or public.user_is_collection_admin(collection_id, (select auth.uid()))\n);\n\nalter view public.public_profiles_view set (security_invoker = true);\nalter view public.collection_summary_view set (security_invoker = true);\nalter view public.public_collections_view set (security_invoker = true);\nalter view public.public_contributions_view set (security_invoker = true);\nalter view public.member_collection_summary_view set (security_invoker = true);\nalter view public.parsed_payment_events_review_view set (security_invoker = true);\nalter view public.member_collections_view set (security_invoker = true);\nalter view public.member_contributions_view set (security_invoker = true);\nalter view public.member_public_collection_requests_view set (security_invoker = true);\n"}
20260523205502	set_helper_function_search_paths	{"-- Supabase security advisor 0011: helper/trigger functions should not inherit\n-- caller-controlled search_path.\n\nalter function public.mask_phone(text) set search_path = public;\nalter function public._admin_row(uuid, text, text, text, text, timestamptz, jsonb) set search_path = public;\nalter function public.normalize_slug(text) set search_path = public;\nalter function public.touch_updated_at() set search_path = public;\nalter function public.generate_public_id() set search_path = public;\nalter function public.generate_contribution_code() set search_path = public;\nalter function public.prevent_client_admin_escalation() set search_path = public, auth;\nalter function public.prevent_ledger_mutation() set search_path = public;\n"}
20260523210723	split_permissive_select_policies	{"-- Keep read policies single-purpose so the planner does not evaluate multiple\n-- permissive SELECT policies for the same role/action.\n\nalter policy \\"admin user roles read admins\\" on public.admin_user_roles\n  using ((select public.has_admin_permission('admin_users.read')) or user_id = (select auth.uid()));\n\nalter policy \\"raw sms metadata scoped read\\" on public.raw_payment_sms\n  using (\n    receiver_user_id = (select auth.uid())\n    or (select public.has_admin_permission('sms.metadata.read'))\n  );\n\ndrop policy if exists \\"members manage admins\\" on public.collection_members;\ncreate policy \\"members admin insert\\" on public.collection_members\nfor insert to authenticated\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"members admin update\\" on public.collection_members\nfor update to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"members admin delete\\" on public.collection_members\nfor delete to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"receivers manage admins\\" on public.collection_receivers;\ncreate policy \\"receivers admin insert\\" on public.collection_receivers\nfor insert to authenticated\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"receivers admin update\\" on public.collection_receivers\nfor update to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"receivers admin delete\\" on public.collection_receivers\nfor delete to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"payment instructions platform admin manage\\" on public.payment_instruction_templates;\ncreate policy \\"payment instructions platform admin insert\\" on public.payment_instruction_templates\nfor insert to authenticated\nwith check ((select public.current_user_is_platform_admin()));\ncreate policy \\"payment instructions platform admin update\\" on public.payment_instruction_templates\nfor update to authenticated\nusing ((select public.current_user_is_platform_admin()))\nwith check ((select public.current_user_is_platform_admin()));\ncreate policy \\"payment instructions platform admin delete\\" on public.payment_instruction_templates\nfor delete to authenticated\nusing ((select public.current_user_is_platform_admin()));\n\ndrop policy if exists \\"invites manage admins\\" on public.collection_invites;\ncreate policy \\"invites admin insert\\" on public.collection_invites\nfor insert to authenticated\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"invites admin update\\" on public.collection_invites\nfor update to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"invites admin delete\\" on public.collection_invites\nfor delete to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"recurring periods manage admins\\" on public.recurring_periods;\ncreate policy \\"recurring periods admin insert\\" on public.recurring_periods\nfor insert to authenticated\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"recurring periods admin update\\" on public.recurring_periods\nfor update to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"recurring periods admin delete\\" on public.recurring_periods\nfor delete to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())));\n\ndrop policy if exists \\"obligations manage admins\\" on public.member_obligations;\ncreate policy \\"obligations admin insert\\" on public.member_obligations\nfor insert to authenticated\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"obligations admin update\\" on public.member_obligations\nfor update to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())))\nwith check (public.user_is_collection_admin(collection_id, (select auth.uid())));\ncreate policy \\"obligations admin delete\\" on public.member_obligations\nfor delete to authenticated\nusing (public.user_is_collection_admin(collection_id, (select auth.uid())));\n"}
20260523212244	revoke_anon_platform_admin_helper	{"-- Anonymous readers need collection-scope helper functions for public views,\n-- but they do not need direct RPC access to the platform-admin helper.\nrevoke execute on function public.current_user_is_platform_admin() from anon;\n"}
20260523213113	disable_graphql_introspection	{"-- The app uses REST/RPC APIs only. Keep GraphQL introspection explicitly off\n-- so schema enumeration stays disabled in production even if defaults change.\ncomment on schema public is e'@graphql({\\"introspection\\": false})';\n"}
202605250001	app_realtime_invalidation	{"create table if not exists app_realtime_events (\n  id uuid primary key default gen_random_uuid(),\n  area text not null check (area in (\n    'profiles',\n    'collections',\n    'members',\n    'payment_intents',\n    'payments',\n    'allocations',\n    'ledger',\n    'receivers',\n    'sms_events',\n    'admin_roles',\n    'audit',\n    'feature_flags',\n    'settings',\n    'system_health'\n  )),\n  created_at timestamptz not null default now()\n);\n\nalter table app_realtime_events enable row level security;\n\ndrop policy if exists \\"realtime invalidations read authenticated\\" on app_realtime_events;\ncreate policy \\"realtime invalidations read authenticated\\"\non app_realtime_events\nfor select\nto authenticated\nusing (true);\n\nrevoke all on app_realtime_events from anon, authenticated;\ngrant select on app_realtime_events to authenticated;\n\ncreate or replace function emit_app_realtime_event()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  insert into app_realtime_events (area)\n  values (tg_argv[0]);\n\n  if tg_op = 'DELETE' then\n    return old;\n  end if;\n  return new;\nend;\n$$;\n\nrevoke execute on function emit_app_realtime_event() from public, anon, authenticated;\ngrant execute on function emit_app_realtime_event() to service_role;\n\ncreate or replace function attach_app_realtime_event_trigger(\n  p_table_name text,\n  p_area text\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  execute format('drop trigger if exists %I on %I', 'app_realtime_event_trigger', p_table_name);\n  execute format(\n    'create trigger %I after insert or update or delete on %I for each row execute function emit_app_realtime_event(%L)',\n    'app_realtime_event_trigger',\n    p_table_name,\n    p_area\n  );\nend;\n$$;\n\nselect attach_app_realtime_event_trigger('profiles', 'profiles');\nselect attach_app_realtime_event_trigger('collections', 'collections');\nselect attach_app_realtime_event_trigger('collection_members', 'members');\nselect attach_app_realtime_event_trigger('payment_intents', 'payment_intents');\nselect attach_app_realtime_event_trigger('payments', 'payments');\nselect attach_app_realtime_event_trigger('payment_allocations', 'allocations');\nselect attach_app_realtime_event_trigger('ledger_entries', 'ledger');\nselect attach_app_realtime_event_trigger('collection_receivers', 'receivers');\nselect attach_app_realtime_event_trigger('raw_payment_sms', 'sms_events');\nselect attach_app_realtime_event_trigger('parsed_payment_events', 'sms_events');\nselect attach_app_realtime_event_trigger('admin_user_roles', 'admin_roles');\nselect attach_app_realtime_event_trigger('audit_logs', 'audit');\nselect attach_app_realtime_event_trigger('admin_sensitive_access_logs', 'audit');\nselect attach_app_realtime_event_trigger('feature_flags', 'feature_flags');\nselect attach_app_realtime_event_trigger('system_settings', 'settings');\n\ndrop function attach_app_realtime_event_trigger(text, text);\n\ndo $$\nbegin\n  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')\n    and not exists (\n      select 1\n      from pg_publication_tables\n      where pubname = 'supabase_realtime'\n        and schemaname = 'public'\n        and tablename = 'app_realtime_events'\n    ) then\n    execute 'alter publication supabase_realtime add table public.app_realtime_events';\n  end if;\nend;\n$$;\n"}
202605270001	sms_first_group_payment_intents	{"-- Align Collect with the SMS-first Groups product contract.\n-- Contributions are allocated from pending payment intents and parsed MoMo SMS.\n-- Members do not manually report payment references or choose identities.\n\nalter table payment_intents\n  add column if not exists contributor_public_id char(6);\n\nalter table payment_intents\n  alter column contribution_code drop not null;\n\nalter table collections\n  alter column category set default 'Other';\n\nupdate payment_intents pi\nset contributor_public_id = p.public_id\nfrom profiles p\nwhere pi.contributor_user_id = p.id\n  and pi.contributor_public_id is null;\n\ncreate index if not exists payment_intents_member_sms_match_idx\n  on payment_intents (\n    status,\n    receiver_momo_number_hash,\n    expected_amount_rwf,\n    contributor_public_id,\n    created_at\n  );\n\ndrop function if exists create_payment_intent(uuid, bigint, text, text);\ndrop function if exists create_payment_intent_with_instructions(uuid, bigint, text, text);\ndrop function if exists create_contribution_intent(uuid, bigint, text);\n\nalter table payment_allocations\n  drop constraint if exists payment_allocations_allocation_method_check;\n\nalter table payment_allocations\n  add constraint payment_allocations_allocation_method_check\n  check (\n    allocation_method in (\n      'auto_member_intent',\n      'auto_unique_amount_time',\n      'system_exception'\n    )\n  ) not valid;\n\ncreate or replace function create_group_with_owner(\n  group_name text,\n  group_description text default '',\n  receiver_momo_number text default null,\n  receiver_momo_number_hash text default null,\n  receiver_label text default 'Primary MOMO receiver'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  created_group_id uuid;\n  base_slug text;\n  final_slug text;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  base_slug := normalize_slug(group_name);\n  if base_slug = '' then\n    base_slug := 'group';\n  end if;\n  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);\n\n  insert into collections (\n    slug,\n    creator_user_id,\n    title,\n    description,\n    receiver_display_label\n  )\n  values (\n    final_slug,\n    auth.uid(),\n    group_name,\n    coalesce(group_description, ''),\n    receiver_label\n  )\n  returning id into created_group_id;\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values (created_group_id, auth.uid(), 'owner', 'active');\n\n  if receiver_momo_number is not null and receiver_momo_number_hash is not null then\n    insert into collection_receivers (\n      collection_id,\n      receiver_user_id,\n      momo_number,\n      momo_number_hash,\n      label\n    )\n    values (\n      created_group_id,\n      auth.uid(),\n      receiver_momo_number,\n      receiver_momo_number_hash,\n      receiver_label\n    );\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id)\n  values (auth.uid(), 'group.created', 'collection', created_group_id);\n\n  return created_group_id;\nend;\n$$;\n\ncreate or replace function create_payment_intent(\n  collection uuid,\n  expected_amount_rwf bigint default null,\n  sender_phone_hash text default null\n)\nreturns payment_intents\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  receiver_hash text;\n  member_public_id char(6);\n  intent payment_intents;\nbegin\n  if not public.user_can_read_collection(collection, auth.uid()) then\n    raise exception 'Group is not available';\n  end if;\n\n  if expected_amount_rwf is null or expected_amount_rwf <= 0 then\n    raise exception 'Contribution amount must be above zero';\n  end if;\n\n  select p.public_id into member_public_id\n  from profiles p\n  where p.id = auth.uid();\n\n  if member_public_id is null then\n    raise exception 'Collect ID is required before contributing';\n  end if;\n\n  select cr.momo_number_hash\n    into receiver_hash\n  from collection_receivers cr\n  where cr.collection_id = collection and cr.is_active\n  order by cr.created_at\n  limit 1;\n\n  if receiver_hash is null then\n    raise exception 'Group has no active receiver';\n  end if;\n\n  insert into payment_intents (\n    collection_id,\n    contributor_user_id,\n    contributor_public_id,\n    expected_amount_rwf,\n    receiver_momo_number_hash,\n    sender_phone_hash\n  )\n  values (\n    collection,\n    auth.uid(),\n    member_public_id,\n    expected_amount_rwf,\n    receiver_hash,\n    null\n  )\n  returning * into intent;\n\n  return intent;\nend;\n$$;\n\ncreate or replace function create_contribution_intent(\n  collection uuid,\n  p_expected_amount_rwf bigint default null,\n  p_sender_phone_hash text default null\n)\nreturns table (\n  id uuid,\n  collection_id uuid,\n  expected_amount_rwf bigint,\n  receiver_momo_number text,\n  receiver_momo_number_hash text,\n  receiver_label text,\n  network text,\n  sender_phone_hash text,\n  status payment_intent_status,\n  contributor_public_id char(6),\n  created_at timestamptz,\n  expires_at timestamptz\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  receiver_row collection_receivers;\n  intent_row payment_intents;\n  member_public_id char(6);\nbegin\n  if not public.user_can_read_collection(collection, auth.uid()) then\n    raise exception 'Group is not available';\n  end if;\n\n  if p_expected_amount_rwf is null or p_expected_amount_rwf <= 0 then\n    raise exception 'Contribution amount must be above zero';\n  end if;\n\n  select p.public_id into member_public_id\n  from profiles p\n  where p.id = auth.uid();\n\n  if member_public_id is null then\n    raise exception 'Collect ID is required before contributing';\n  end if;\n\n  select *\n    into receiver_row\n  from collection_receivers cr\n  where cr.collection_id = collection and cr.is_active\n  order by cr.created_at\n  limit 1;\n\n  if receiver_row.id is null then\n    raise exception 'Group has no active receiver';\n  end if;\n\n  insert into payment_intents (\n    collection_id,\n    contributor_user_id,\n    contributor_public_id,\n    expected_amount_rwf,\n    receiver_momo_number_hash,\n    sender_phone_hash\n  )\n  values (\n    collection,\n    auth.uid(),\n    member_public_id,\n    p_expected_amount_rwf,\n    receiver_row.momo_number_hash,\n    null\n  )\n  returning * into intent_row;\n\n  return query select\n    intent_row.id,\n    intent_row.collection_id,\n    intent_row.expected_amount_rwf,\n    receiver_row.momo_number,\n    intent_row.receiver_momo_number_hash,\n    receiver_row.label,\n    receiver_row.network,\n    null::text,\n    intent_row.status,\n    intent_row.contributor_public_id,\n    intent_row.created_at,\n    intent_row.expires_at;\nend;\n$$;\n\ncreate or replace function join_group_by_slug(group_slug text)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  group_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select c.id into group_id\n  from collections c\n  where c.slug = group_slug;\n\n  if group_id is null then\n    raise exception 'Group not found';\n  end if;\n\n  if not exists (\n    select 1\n    from collection_members cm\n    where cm.collection_id = group_id\n      and cm.user_id = auth.uid()\n      and cm.status = 'active'\n  ) then\n    insert into collection_members (collection_id, user_id, role, status)\n    values (group_id, auth.uid(), 'member', 'active')\n    on conflict on constraint collection_members_collection_id_user_id_role_key do update\n      set status = 'active';\n\n    insert into audit_logs (actor_user_id, action, entity_type, entity_id)\n    values (auth.uid(), 'group.joined', 'collection', group_id);\n  end if;\n\n  return group_id;\nend;\n$$;\n\ncreate or replace function allocate_parsed_payment_event(event_id uuid)\nreturns text\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  event_row parsed_payment_events;\n  match_intent_id uuid;\n  match_collection_id uuid;\n  possible_count int;\nbegin\n  select * into event_row from parsed_payment_events where id = event_id for update;\n  if not found then\n    raise exception 'Parsed event not found';\n  end if;\n\n  if event_row.allocation_status = 'allocated' then\n    return 'already_allocated';\n  end if;\n\n  if not event_row.is_mobile_money_payment\n     or event_row.direction <> 'incoming'\n     or event_row.currency <> 'RWF'\n     or event_row.amount_rwf is null\n     or event_row.amount_rwf <= 0\n     or event_row.confidence < 0.72 then\n    update parsed_payment_events\n      set allocation_status = 'needs_review',\n          review_reason = 'Parser result is not reliable enough for automated allocation'\n      where id = event_id;\n    return 'needs_review';\n  end if;\n\n  if event_row.detected_user_public_id is not null\n     and event_row.receiver_phone_hash is not null then\n    select id, collection_id into match_intent_id, match_collection_id\n    from payment_intents\n    where status = 'pending'\n      and receiver_momo_number_hash = event_row.receiver_phone_hash\n      and expected_amount_rwf = event_row.amount_rwf\n      and contributor_public_id = event_row.detected_user_public_id\n      and event_row.created_at between created_at - interval '15 minutes'\n        and expires_at + interval '2 hours'\n    order by created_at\n    limit 1;\n\n    if match_intent_id is not null then\n      perform post_payment_from_event(\n        event_id,\n        match_intent_id,\n        match_collection_id,\n        'auto_member_intent',\n        'Matched by pending payment intent, receiver, amount, and Collect ID'\n      );\n      return 'allocated';\n    end if;\n  end if;\n\n  if event_row.receiver_phone_hash is not null then\n    select\n      count(*),\n      (array_agg(id order by created_at))[1],\n      (array_agg(collection_id order by created_at))[1]\n      into possible_count, match_intent_id, match_collection_id\n    from payment_intents\n    where status = 'pending'\n      and receiver_momo_number_hash = event_row.receiver_phone_hash\n      and expected_amount_rwf = event_row.amount_rwf\n      and event_row.created_at between created_at - interval '15 minutes'\n        and expires_at + interval '2 hours';\n\n    if possible_count = 1 then\n      perform post_payment_from_event(\n        event_id,\n        match_intent_id,\n        match_collection_id,\n        'auto_unique_amount_time',\n        'Matched as the only pending intent for receiver, amount, and time window'\n      );\n      return 'allocated';\n    elsif possible_count > 1 then\n      update parsed_payment_events\n        set allocation_status = 'ambiguous',\n            review_reason = 'Multiple pending payment intents matched receiver, amount, and time window'\n        where id = event_id;\n      return 'ambiguous';\n    end if;\n  end if;\n\n  update parsed_payment_events\n    set allocation_status = 'needs_review',\n        review_reason = 'No pending payment intent matched parsed MoMo SMS'\n    where id = event_id;\n  return 'needs_review';\nend;\n$$;\n\nrevoke execute on function report_payment_intent_paid(uuid, text)\n  from public, anon, authenticated;\n\nrevoke execute on function manual_allocate_parsed_payment_event(uuid, uuid, uuid, text)\n  from public, anon, authenticated;\n\nrevoke execute on function admin_manual_allocate_payment(uuid, uuid, uuid, text)\n  from public, anon, authenticated;\n\nrevoke execute on function request_public_collection(uuid)\n  from public, anon, authenticated;\n\nrevoke execute on function review_public_collection(uuid, boolean, text)\n  from public, anon, authenticated;\n\nrevoke execute on function admin_review_public_request(uuid, boolean, text)\n  from public, anon, authenticated;\n\nrevoke execute on function admin_list_public_requests(text, text)\n  from public, anon, authenticated;\n\nrevoke execute on function admin_moderate_collection(uuid, text, text)\n  from public, anon, authenticated;\n\nrevoke execute on function create_collection_with_owner(text, text, text, bigint, text, text, text, text, boolean, jsonb)\n  from public, anon, authenticated;\n\nrevoke execute on function create_collection_invite(uuid, text, text, member_role)\n  from public, anon, authenticated;\n\nrevoke all on public_collections_view\n  from public, anon, authenticated;\n\nrevoke all on member_public_collection_requests_view\n  from public, anon, authenticated;\n\nrevoke all on collection_summary_view\n  from public, anon, authenticated;\n\nrevoke all on member_collection_summary_view\n  from public, anon, authenticated;\n\nrevoke all on member_collections_view\n  from public, anon, authenticated;\n\nrevoke all on member_contributions_view\n  from public, anon, authenticated;\n\nrevoke all on parsed_payment_events_review_view\n  from public, anon, authenticated;\n\nrevoke all on payment_instruction_templates\n  from public, anon, authenticated;\n\ndrop function if exists admin_manual_allocate_payment(uuid, uuid, uuid, text);\ndrop function if exists manual_allocate_parsed_payment_event(uuid, uuid, uuid, text);\ndrop function if exists report_payment_intent_paid(uuid, text);\ndrop function if exists admin_moderate_collection(uuid, text, text);\ndrop function if exists admin_list_public_requests(text, text);\ndrop function if exists admin_review_public_request(uuid, boolean, text);\ndrop function if exists review_public_collection(uuid, boolean, text);\ndrop function if exists request_public_collection(uuid);\ndrop function if exists create_collection_invite(uuid, text, text, member_role);\ndrop function if exists create_collection_with_owner(text, text, text, bigint, text, text, text, text, boolean, jsonb);\ndrop view if exists member_public_collection_requests_view;\ndrop view if exists member_contributions_view;\ndrop view if exists member_collections_view;\ndrop view if exists member_collection_summary_view;\ndrop view if exists public_collections_view;\ndrop view if exists collection_summary_view;\ndrop view if exists parsed_payment_events_review_view;\ndrop table if exists payment_instruction_templates;\ndrop table if exists public_collection_requests;\n\nupdate parsed_payment_events\nset sender_name = null\nwhere sender_name is not null;\n\nrevoke select (display_name, avatar_url, anonymity_default)\n  on profiles from anon, authenticated;\n\nrevoke select (\n  category,\n  cover_image_url,\n  target_amount_rwf,\n  deadline_at,\n  visibility,\n  public_status,\n  is_recurring,\n  recurring_rule,\n  allow_anonymous,\n  contribution_visibility\n) on collections from anon, authenticated;\n\nrevoke select (anonymity_choice)\n  on payments from anon, authenticated;\n\ncreate or replace function admin_current_user()\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  profile_row profiles%rowtype;\nbegin\n  if auth.uid() is null then\n    return '{}'::jsonb;\n  end if;\n\n  select * into profile_row\n  from profiles\n  where id = auth.uid();\n\n  if profile_row.id is null then\n    return '{}'::jsonb;\n  end if;\n\n  if not exists (\n    select 1\n    from admin_user_roles aur\n    where aur.user_id = profile_row.id\n      and aur.revoked_at is null\n  ) and not coalesce(profile_row.is_platform_admin, false) then\n    return '{}'::jsonb;\n  end if;\n\n  return jsonb_build_object(\n    'user_id', profile_row.id,\n    'display_name', 'Collect ID ' || profile_row.public_id,\n    'phone_masked', mask_phone(profile_row.whatsapp_phone),\n    'roles', (\n      select coalesce(jsonb_agg(ar.name order by ar.name), '[]'::jsonb)\n      from admin_user_roles aur\n      join admin_roles ar on ar.id = aur.role_id\n      where aur.user_id = profile_row.id\n        and aur.revoked_at is null\n    ),\n    'permissions', (\n      select coalesce(jsonb_agg(distinct arp.permission_name order by arp.permission_name), '[]'::jsonb)\n      from admin_user_roles aur\n      join admin_role_permissions arp on arp.role_id = aur.role_id\n      where aur.user_id = profile_row.id\n        and aur.revoked_at is null\n    )\n  );\nend;\n$$;\n\ncreate or replace function admin_list_collections(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('collections.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(\n      _admin_row(\n        c.id,\n        c.title,\n        coalesce(cr.label, c.receiver_display_label, 'MoMo receiver'),\n        case when exists (\n          select 1 from payment_intents pi\n          where pi.collection_id = c.id and pi.status = 'pending'\n        ) then 'pending_intents' else 'active' end,\n        coalesce((\n          select count(*)::text || ' members'\n          from collection_members cm\n          where cm.collection_id = c.id and cm.status = 'active'\n        ), '0 members'),\n        c.created_at,\n        jsonb_build_object(\n          'slug', c.slug,\n          'receiver_count', (\n            select count(*)\n            from collection_receivers r\n            where r.collection_id = c.id and r.is_active\n          ),\n          'pending_intents', (\n            select count(*)\n            from payment_intents pi\n            where pi.collection_id = c.id and pi.status = 'pending'\n          )\n        )\n      )\n      order by c.created_at desc\n    )\n    from collections c\n    left join lateral (\n      select label\n      from collection_receivers r\n      where r.collection_id = c.id and r.is_active\n      order by r.created_at desc\n      limit 1\n    ) cr on true\n    where (p_search is null or c.title ilike '%' || p_search || '%' or c.slug ilike '%' || p_search || '%')\n      and (p_status is null or p_status in ('active', 'pending_intents'))\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_get_collection(p_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('collections.read');\n  return coalesce((\n    select jsonb_build_object(\n      'id', c.id,\n      'slug', c.slug,\n      'title', c.title,\n      'description', c.description,\n      'creator_user_id', c.creator_user_id,\n      'creator_label', 'Collect ID ' || p.public_id,\n      'receiver_display_label', c.receiver_display_label,\n      'created_at', c.created_at,\n      'updated_at', c.updated_at,\n      'active_receivers', (\n        select count(*)\n        from collection_receivers r\n        where r.collection_id = c.id and r.is_active\n      ),\n      'active_members', (\n        select count(*)\n        from collection_members cm\n        where cm.collection_id = c.id and cm.status = 'active'\n      ),\n      'pending_payment_intents', (\n        select count(*)\n        from payment_intents pi\n        where pi.collection_id = c.id and pi.status = 'pending'\n      )\n    )\n    from collections c\n    left join profiles p on p.id = c.creator_user_id\n    where c.id = p_id\n  ), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_list_users(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('users.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(\n      _admin_row(\n        p.id,\n        'Collect ID ' || p.public_id,\n        mask_phone(p.whatsapp_phone),\n        case when p.is_platform_admin then 'admin' else 'active' end,\n        '',\n        p.created_at,\n        jsonb_build_object('public_id', p.public_id)\n      )\n      order by p.created_at desc\n    )\n    from profiles p\n    where (\n        p_search is null\n        or p.public_id = p_search\n        or mask_phone(p.whatsapp_phone) ilike '%' || p_search || '%'\n      )\n      and (\n        p_status is null\n        or (p_status = 'admin' and p.is_platform_admin)\n        or (p_status = 'active' and not p.is_platform_admin)\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_get_user(p_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('users.read');\n  return coalesce((\n    select jsonb_build_object(\n      'id', p.id,\n      'public_id', p.public_id,\n      'public_label', 'Collect ID ' || p.public_id,\n      'whatsapp_phone', mask_phone(p.whatsapp_phone),\n      'momo_number', mask_phone(p.momo_number),\n      'is_platform_admin', p.is_platform_admin,\n      'created_at', p.created_at,\n      'updated_at', p.updated_at\n    )\n    from profiles p\n    where p.id = p_id\n  ), '{}'::jsonb);\nend;\n$$;\n\ncreate or replace function admin_list_admin_users(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('admin_users.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(\n      _admin_row(\n        p.id,\n        'Collect ID ' || p.public_id,\n        ar.name,\n        'admin',\n        '',\n        aur.created_at,\n        jsonb_build_object('public_id', p.public_id)\n      )\n      order by aur.created_at desc\n    )\n    from admin_user_roles aur\n    join profiles p on p.id = aur.user_id\n    join admin_roles ar on ar.id = aur.role_id\n    where aur.revoked_at is null\n      and (\n        p_search is null\n        or p.public_id = p_search\n        or ar.name ilike '%' || p_search || '%'\n      )\n      and (\n        p_status is null\n        or p_status = 'admin'\n        or ar.name = p_status\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ndelete from admin_role_permissions arp\nusing admin_permissions ap\nwhere arp.permission_name = ap.name\n  and ap.name in (\n    'public_requests.read',\n    'public_requests.review',\n    'collections.moderate',\n    'payments.allocate'\n  );\n\ndelete from admin_permissions\nwhere name in (\n  'public_requests.read',\n  'public_requests.review',\n  'collections.moderate',\n  'payments.allocate'\n);\n\nupdate admin_roles\nset name = 'group_ops_admin',\n    description = 'Group and SMS-first operations review'\nwhere name = 'moderation_admin';\n\ncreate or replace function admin_overview()\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('overview.read');\n  return jsonb_build_object(\n    'metrics', jsonb_build_array(\n      jsonb_build_object('label', 'Pending payment intents', 'value', (select count(*) from payment_intents where status = 'pending'), 'status', 'pending'),\n      jsonb_build_object('label', 'SMS exceptions', 'value', (select count(*) from parsed_payment_events where allocation_status in ('unallocated', 'ambiguous', 'needs_review')), 'status', 'needs_review'),\n      jsonb_build_object('label', 'Posted payments', 'value', (select count(*) from payments where status = 'posted'), 'status', 'posted'),\n      jsonb_build_object('label', 'Ledger credits RWF', 'value', coalesce((select sum(amount_rwf) from ledger_entries), 0), 'status', 'healthy')\n    )\n  );\nend;\n$$;\n\ncreate or replace function admin_list_allocations(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return admin_list_payment_events(p_search, coalesce(p_status, 'allocated'));\nend;\n$$;\n\ncreate or replace function admin_list_payment_events(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(\n      _admin_row(\n        e.id,\n        coalesce(e.transaction_id, 'Payment event'),\n        'MoMo SMS',\n        e.allocation_status::text,\n        coalesce(e.amount_rwf::text || ' RWF', ''),\n        e.created_at,\n        jsonb_build_object('collection_id', e.collection_id)\n      )\n      order by e.created_at desc\n    )\n    from parsed_payment_events e\n    where (p_status is null or e.allocation_status::text = p_status)\n      and (p_search is null or e.transaction_id ilike '%' || p_search || '%')\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_list_unallocated(p_search text default null, p_status text default null)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return jsonb_build_object('rows', coalesce((\n    select jsonb_agg(\n      _admin_row(\n        e.id,\n        coalesce(e.transaction_id, 'Payment event'),\n        'MoMo SMS',\n        e.allocation_status::text,\n        coalesce(e.amount_rwf::text || ' RWF', ''),\n        e.created_at,\n        jsonb_build_object('collection_id', e.collection_id)\n      )\n      order by e.created_at desc\n    )\n    from parsed_payment_events e\n    where (\n      (\n        p_status is null\n        and e.allocation_status in ('unallocated', 'ambiguous', 'needs_review')\n      )\n      or (\n        p_status is not null\n        and e.allocation_status::text = p_status\n      )\n    )\n    and (\n      p_search is null\n      or e.transaction_id ilike '%' || p_search || '%'\n      )\n  ), '[]'::jsonb));\nend;\n$$;\n\ncreate or replace function admin_get_payment_event(p_id uuid)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return coalesce((\n    select to_jsonb(e) - 'sender_name' || jsonb_build_object('sender_label', 'MoMo SMS')\n    from parsed_payment_events e\n    where e.id = p_id\n  ), '{}'::jsonb);\nend;\n$$;\n\nrevoke execute on function admin_list_payment_events(text, text)\n  from public, anon;\nrevoke execute on function admin_list_allocations(text, text)\n  from public, anon;\nrevoke execute on function admin_list_unallocated(text, text)\n  from public, anon;\nrevoke execute on function admin_get_payment_event(uuid)\n  from public, anon;\n\ngrant execute on function admin_list_payment_events(text, text) to authenticated;\ngrant execute on function admin_list_allocations(text, text) to authenticated;\ngrant execute on function admin_list_unallocated(text, text) to authenticated;\ngrant execute on function admin_get_payment_event(uuid) to authenticated;\n\ndrop view if exists public_profiles_view;\ndrop view if exists public_contributions_view;\n\ncreate view public_profiles_view\nwith (security_invoker = true)\nas\nselect\n  id,\n  'Collect ID ' || public_id as public_label,\n  null::text as avatar_url,\n  created_at\nfrom profiles;\n\ncreate view public_contributions_view\nwith (security_invoker = true)\nas\nselect\n  p.id as payment_id,\n  p.collection_id,\n  p.amount_rwf,\n  p.posted_at,\n  case\n    when p.contributor_public_id is not null\n      then 'Collect ID ' || p.contributor_public_id\n    else 'Collect member'\n  end as supporter_label\nfrom payments p\nwhere p.status = 'posted';\n\ncreate view member_collection_summary_view\nwith (security_invoker = true)\nas\nselect\n  c.id as collection_id,\n  c.title,\n  c.creator_user_id,\n  (\n    select coalesce(sum(le.amount_rwf) filter (where le.entry_type = 'collection_credit'), 0)::bigint\n    from ledger_entries le\n    where le.collection_id = c.id\n  ) as amount_raised_rwf,\n  (\n    select count(distinct coalesce(p.contributor_user_id::text, p.contributor_public_id, p.id::text))::bigint\n    from payments p\n    where p.collection_id = c.id\n      and p.status = 'posted'\n  ) as supporter_count,\n  (\n    select count(pi.id)::bigint\n    from payment_intents pi\n    where pi.collection_id = c.id\n      and pi.status = 'pending'\n  ) as pending_intent_count,\n  (\n    select count(distinct ppe.id)::bigint\n    from collection_receivers cr\n    join parsed_payment_events ppe\n      on ppe.receiver_user_id = cr.receiver_user_id\n     and (\n       ppe.collection_id = c.id\n       or (\n         ppe.collection_id is null\n         and ppe.receiver_phone_hash = cr.momo_number_hash\n       )\n     )\n    where cr.collection_id = c.id\n      and ppe.allocation_status in ('unallocated', 'ambiguous', 'needs_review')\n  ) as exception_event_count,\n  c.created_at,\n  c.updated_at\nfrom collections c\nwhere public.user_can_read_collection(c.id, auth.uid());\n\ncreate view member_collections_view\nwith (security_invoker = true)\nas\nselect\n  c.id,\n  c.slug,\n  c.creator_user_id,\n  c.title,\n  c.description,\n  c.currency,\n  case\n    when public.user_is_collection_admin(c.id, auth.uid())\n      or exists (\n        select 1\n        from collection_receivers receiver_check\n        where receiver_check.collection_id = c.id\n          and receiver_check.receiver_user_id = auth.uid()\n          and receiver_check.is_active\n      )\n      then cr.momo_number\n    else null\n  end as receiver_momo_number,\n  case\n    when public.user_can_read_collection(c.id, auth.uid()) then cr.label\n    else null\n  end as receiver_display_label,\n  cr.network as receiver_network,\n  c.created_at,\n  c.updated_at,\n  c.archived_at\nfrom collections c\nleft join lateral (\n  select\n    collection_receivers.momo_number,\n    collection_receivers.label,\n    collection_receivers.network\n  from collection_receivers\n  where collection_receivers.collection_id = c.id\n    and collection_receivers.is_active\n  order by collection_receivers.created_at asc\n  limit 1\n) cr on true\nwhere public.user_can_read_collection(c.id, auth.uid());\n\ncreate view member_contributions_view\nwith (security_invoker = true)\nas\nselect\n  p.collection_id,\n  p.id as payment_id,\n  p.amount_rwf,\n  p.currency,\n  p.status,\n  p.source,\n  case\n    when p.contributor_user_id = auth.uid()\n      or public.user_is_collection_admin(p.collection_id, auth.uid())\n      then p.transaction_id\n    else null\n  end as transaction_id,\n  p.posted_at,\n  p.created_at,\n  case\n    when p.contributor_user_id = auth.uid() then 'You'\n    when p.contributor_public_id is not null\n      then 'Collect ID ' || p.contributor_public_id\n    else 'Collect member'\n  end as supporter_label\nfrom payments p\nwhere p.status = 'posted'\n  and public.user_can_read_collection(p.collection_id, auth.uid());\n\nrevoke update (display_name, avatar_url, anonymity_default)\n  on profiles from authenticated;\n\ngrant select on public_profiles_view, public_contributions_view\n  to anon, authenticated;\n\ngrant select on member_collection_summary_view, member_collections_view, member_contributions_view\n  to authenticated;\n\ncreate or replace function record_sms_access_consent(\n  enabled boolean,\n  momo_number_hash text default null,\n  build_channel text default 'android_sms_access',\n  device_label text default 'flutter_app'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  consent_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  insert into receiver_mode_consents (\n    user_id,\n    enabled,\n    momo_number_hash,\n    build_channel,\n    device_label\n  )\n  values (\n    auth.uid(),\n    coalesce(enabled, false),\n    momo_number_hash,\n    nullif(build_channel, ''),\n    nullif(device_label, '')\n  )\n  returning id into consent_id;\n\n  insert into audit_logs (\n    actor_user_id,\n    action,\n    entity_type,\n    entity_id,\n    metadata\n  )\n  values (\n    auth.uid(),\n    case\n      when coalesce(enabled, false) then 'sms_access.enabled'\n      else 'sms_access.disabled'\n    end,\n    'sms_access_consent',\n    consent_id,\n    jsonb_build_object('build_channel', build_channel, 'device_label', device_label)\n  );\n\n  return consent_id;\nend;\n$$;\n\nrevoke execute on function record_receiver_mode_consent(boolean, text, text, text)\n  from public, anon, authenticated;\n\ndrop function if exists record_receiver_mode_consent(boolean, text, text, text);\n\ninsert into feature_flags (key, enabled, description)\nvalues\n  (\n    'enable_android_sms_access',\n    false,\n    'Android-only SMS app access for consented MoMo SMS ingestion'\n  )\non conflict (key) do update\nset description = excluded.description;\n\ndelete from feature_flags\nwhere key = 'enable_internal_receiver_mode';\n\ninsert into system_settings (key, value, description, is_sensitive)\nvalues\n  (\n    'payments.mode',\n    '{\\"provider\\":\\"payment_intent_momo_ussd\\",\\"country\\":\\"RW\\",\\"currency\\":\\"RWF\\"}'::jsonb,\n    'Collect payment mode: payment intent, MoMo USSD launch, and automated SMS allocation',\n    false\n  )\non conflict (key) do update\nset value = excluded.value,\n    description = excluded.description,\n    is_sensitive = excluded.is_sensitive,\n    updated_at = now();\n\nrevoke execute on function create_group_with_owner(text, text, text, text, text)\n  from public, anon;\nrevoke execute on function join_group_by_slug(text)\n  from public, anon;\nrevoke execute on function create_payment_intent(uuid, bigint, text)\n  from public, anon;\nrevoke execute on function create_contribution_intent(uuid, bigint, text)\n  from public, anon;\nrevoke execute on function record_sms_access_consent(boolean, text, text, text)\n  from public, anon;\nrevoke execute on function allocate_parsed_payment_event(uuid)\n  from public, anon, authenticated;\n\ngrant execute on function create_group_with_owner(text, text, text, text, text)\n  to authenticated;\ngrant execute on function join_group_by_slug(text)\n  to authenticated;\ngrant execute on function create_payment_intent(uuid, bigint, text)\n  to authenticated;\ngrant execute on function create_contribution_intent(uuid, bigint, text)\n  to authenticated;\ngrant execute on function record_sms_access_consent(boolean, text, text, text)\n  to authenticated;\ngrant execute on function allocate_parsed_payment_event(uuid)\n  to service_role;\n"}
20260531162852	harden_sms_first_function_grants	{"-- Remove implicit PUBLIC execution from SMS-first security-definer RPCs.\n-- Keep only the explicit roles required by the mobile app, admin PWA, and\n-- service-role allocation pipeline.\n\nrevoke execute on function admin_list_payment_events(text, text)\n  from public, anon;\nrevoke execute on function admin_list_allocations(text, text)\n  from public, anon;\nrevoke execute on function admin_list_unallocated(text, text)\n  from public, anon;\nrevoke execute on function admin_get_payment_event(uuid)\n  from public, anon;\n\nrevoke execute on function create_group_with_owner(text, text, text, text, text)\n  from public, anon;\nrevoke execute on function join_group_by_slug(text)\n  from public, anon;\nrevoke execute on function create_payment_intent(uuid, bigint, text)\n  from public, anon;\nrevoke execute on function create_contribution_intent(uuid, bigint, text)\n  from public, anon;\nrevoke execute on function record_sms_access_consent(boolean, text, text, text)\n  from public, anon;\nrevoke execute on function allocate_parsed_payment_event(uuid)\n  from public, anon, authenticated;\n\ngrant execute on function admin_list_payment_events(text, text)\n  to authenticated;\ngrant execute on function admin_list_allocations(text, text)\n  to authenticated;\ngrant execute on function admin_list_unallocated(text, text)\n  to authenticated;\ngrant execute on function admin_get_payment_event(uuid)\n  to authenticated;\n\ngrant execute on function create_group_with_owner(text, text, text, text, text)\n  to authenticated;\ngrant execute on function join_group_by_slug(text)\n  to authenticated;\ngrant execute on function create_payment_intent(uuid, bigint, text)\n  to authenticated;\ngrant execute on function create_contribution_intent(uuid, bigint, text)\n  to authenticated;\ngrant execute on function record_sms_access_consent(boolean, text, text, text)\n  to authenticated;\ngrant execute on function allocate_parsed_payment_event(uuid)\n  to service_role;\n"}
20260531190000	mobile_production_state_support	{"create table if not exists mobile_account_deletion_requests (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references profiles(id) on delete restrict,\n  reason text,\n  status text not null default 'pending'\n    check (status in ('pending', 'in_review', 'completed', 'rejected')),\n  created_at timestamptz not null default now(),\n  reviewed_at timestamptz,\n  reviewed_by uuid references profiles(id) on delete set null\n);\n\ncreate table if not exists mobile_support_requests (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references profiles(id) on delete restrict,\n  subject text not null,\n  message text not null,\n  status text not null default 'open'\n    check (status in ('open', 'in_review', 'resolved', 'closed')),\n  created_at timestamptz not null default now(),\n  resolved_at timestamptz,\n  resolved_by uuid references profiles(id) on delete set null\n);\n\nalter table mobile_account_deletion_requests enable row level security;\nalter table mobile_support_requests enable row level security;\n\ndrop policy if exists \\"account deletion own read\\" on mobile_account_deletion_requests;\ncreate policy \\"account deletion own read\\"\non mobile_account_deletion_requests\nfor select to authenticated\nusing (user_id = auth.uid() or is_platform_admin(auth.uid()));\n\ndrop policy if exists \\"support requests own read\\" on mobile_support_requests;\ncreate policy \\"support requests own read\\"\non mobile_support_requests\nfor select to authenticated\nusing (user_id = auth.uid() or is_platform_admin(auth.uid()));\n\ncreate index if not exists mobile_account_deletion_requests_user_idx\non mobile_account_deletion_requests (user_id, created_at desc);\n\ncreate index if not exists mobile_support_requests_user_idx\non mobile_support_requests (user_id, created_at desc);\n\ncreate or replace function ensure_current_profile(whatsapp_phone text default null)\nreturns profiles\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  profile_row profiles%rowtype;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select * into profile_row\n  from profiles\n  where id = auth.uid();\n\n  if profile_row.id is null then\n    insert into profiles (id, public_id, whatsapp_phone)\n    values (\n      auth.uid(),\n      generate_public_id(),\n      nullif(trim(whatsapp_phone), '')\n    )\n    returning * into profile_row;\n  elsif nullif(trim(whatsapp_phone), '') is not null\n    and coalesce(profile_row.whatsapp_phone, '') = '' then\n    update profiles\n    set whatsapp_phone = trim(whatsapp_phone)\n    where id = auth.uid()\n    returning * into profile_row;\n  end if;\n\n  return profile_row;\nend;\n$$;\n\ncreate or replace function request_account_deletion(request_reason text default null)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  request_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  insert into mobile_account_deletion_requests (user_id, reason)\n  values (auth.uid(), nullif(trim(request_reason), ''))\n  returning id into request_id;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'mobile.account_deletion_requested',\n    'profile',\n    auth.uid(),\n    jsonb_build_object('request_id', request_id)\n  );\n\n  return request_id;\nend;\n$$;\n\ncreate or replace function create_mobile_support_request(\n  request_subject text,\n  request_message text\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  request_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if nullif(trim(request_subject), '') is null then\n    raise exception 'Support subject is required';\n  end if;\n  if nullif(trim(request_message), '') is null then\n    raise exception 'Support message is required';\n  end if;\n\n  insert into mobile_support_requests (user_id, subject, message)\n  values (auth.uid(), trim(request_subject), trim(request_message))\n  returning id into request_id;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'mobile.support_requested',\n    'profile',\n    auth.uid(),\n    jsonb_build_object('request_id', request_id)\n  );\n\n  return request_id;\nend;\n$$;\n\ncreate or replace function list_collection_collect_ids(collection uuid)\nreturns table (\n  public_id text,\n  role text,\n  status text,\n  joined_at timestamptz\n)\nlanguage sql\nsecurity definer\nset search_path = public, extensions\nas $$\n  select\n    p.public_id::text,\n    cm.role::text,\n    cm.status::text,\n    cm.created_at as joined_at\n  from collection_members cm\n  join profiles p on p.id = cm.user_id\n  where cm.collection_id = collection\n    and user_can_read_collection(collection, auth.uid())\n  order by cm.created_at asc;\n$$;\n\ncreate or replace function update_collection_receiver(\n  collection uuid,\n  receiver_momo_number text,\n  receiver_momo_number_hash text,\n  receiver_label text default 'Primary MOMO receiver'\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if not user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can update the receiver';\n  end if;\n  if nullif(trim(receiver_momo_number), '') is null then\n    raise exception 'Receiver MoMo number is required';\n  end if;\n  if nullif(trim(receiver_momo_number_hash), '') is null then\n    raise exception 'Receiver MoMo hash is required';\n  end if;\n\n  update collection_receivers\n  set is_active = false\n  where collection_id = collection\n    and is_active = true;\n\n  insert into collection_receivers (\n    collection_id,\n    receiver_user_id,\n    momo_number,\n    momo_number_hash,\n    label,\n    is_active\n  )\n  values (\n    collection,\n    auth.uid(),\n    trim(receiver_momo_number),\n    trim(receiver_momo_number_hash),\n    coalesce(nullif(trim(receiver_label), ''), 'Primary MOMO receiver'),\n    true\n  );\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.receiver_updated',\n    'collection',\n    collection,\n    jsonb_build_object('receiver_label', coalesce(nullif(trim(receiver_label), ''), 'Primary MOMO receiver'))\n  );\nend;\n$$;\n\ncreate or replace function get_owner_group_health(collection uuid)\nreturns jsonb\nlanguage sql\nsecurity definer\nset search_path = public, extensions\nas $$\n  select jsonb_build_object(\n    'collection_id', collection,\n    'receiver_configured', exists (\n      select 1\n      from collection_receivers cr\n      where cr.collection_id = collection\n        and cr.is_active\n    ),\n    'sms_access_enabled', exists (\n      select 1\n      from receiver_mode_consents rmc\n      where rmc.user_id = auth.uid()\n        and rmc.enabled\n    ),\n    'pending_payment_intents', (\n      select count(*)\n      from payment_intents pi\n      where pi.collection_id = collection\n        and pi.status = 'pending'\n    ),\n    'needs_review_events', (\n      select count(*)\n      from parsed_payment_events ppe\n      where ppe.collection_id = collection\n        and ppe.allocation_status in ('unallocated', 'ambiguous', 'needs_review')\n    ),\n    'last_synced_at', (\n      select max(rps.created_at)\n      from raw_payment_sms rps\n      where rps.collection_id = collection\n    )\n  )\n  where user_is_collection_admin(collection, auth.uid());\n$$;\n\nrevoke execute on function ensure_current_profile(text) from public, anon, authenticated;\nrevoke execute on function request_account_deletion(text) from public, anon, authenticated;\nrevoke execute on function create_mobile_support_request(text, text) from public, anon, authenticated;\nrevoke execute on function list_collection_collect_ids(uuid) from public, anon, authenticated;\nrevoke execute on function update_collection_receiver(uuid, text, text, text) from public, anon, authenticated;\nrevoke execute on function get_owner_group_health(uuid) from public, anon, authenticated;\n\ngrant execute on function ensure_current_profile(text) to authenticated;\ngrant execute on function request_account_deletion(text) to authenticated;\ngrant execute on function create_mobile_support_request(text, text) to authenticated;\ngrant execute on function list_collection_collect_ids(uuid) to authenticated;\ngrant execute on function update_collection_receiver(uuid, text, text, text) to authenticated;\ngrant execute on function get_owner_group_health(uuid) to authenticated;\n"}
20261001000200	admin_gateway_reads	{"begin;\n\n-- Redacted current observations and retained owner receipts only. Identity\n-- activation is never dispatch authority or independent carrier attestation.\ncreate function collect_gateway.read_actor() returns uuid\nlanguage plpgsql volatile security definer set search_path='' as $$\ndeclare sid uuid;actor uuid;\nbegin\n if current_setting('transaction_isolation')<>'read committed' then\n  raise exception 'gateway_read_snapshot_retry' using errcode='40001';end if;\n sid:=public._lock_notification_registration_session();actor:=auth.uid();\n perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));\n perform collect_hybrid.require_roster_actor_authority(actor,sid,'platform_owner',\n  array['notifications.read','system_health.read']);\n return actor;\nend$$;\n\ncreate function collect_gateway.read_count(p_count bigint) returns bigint\nlanguage plpgsql immutable set search_path='' as $$\nbegin\n if p_count is null or p_count not between 0 and 1000000000 then\n  raise exception 'gateway_read_count_unavailable' using errcode='55000';end if;\n return p_count;\nend$$;\n\ncreate function collect_gateway.public_identity(p_device collect_gateway.devices)\nreturns jsonb language sql immutable set search_path='' as $$\n select jsonb_build_object('device_id',p_device.id,'installation_id',p_device.installation_id,\n  'key_sha256',p_device.key_sha256,'signing_certificate_sha256',p_device.signing_certificate_sha256)\n$$;\n\ncreate function collect_gateway.public_owner_receipt(p_result jsonb)\nreturns jsonb language sql immutable set search_path='' as $$\n select jsonb_build_object('device_id',p_result->'device_id','request_id',p_result->'request_id',\n  'state_at_action',p_result->'state_at_action','recorded_at',p_result->'recorded_at',\n  'replay',p_result->'replay')\n$$;\n\ncreate index gateway_devices_read_page on collect_gateway.devices(created_at desc,id desc);\ncreate index gateway_owner_receipts_device on collect_gateway.admin_requests\n ((result->>'device_id'),recorded_at desc,request_id desc);\ncreate index gateway_callback_device_kind on collect_gateway.segment_callbacks(device_id,callback_kind);\n\ncreate function public.admin_list_gateway_devices_v1(p_limit integer default 20,\n p_before_enrolled_at timestamptz default null,p_before_device_id uuid default null)\nreturns jsonb language plpgsql volatile security definer set search_path='' as $$\ndeclare result jsonb;\nbegin\n perform collect_gateway.read_actor();\n if p_limit is null or p_limit not between 1 and 50\n  or ((p_before_enrolled_at is null)<>(p_before_device_id is null))\n  or (p_before_enrolled_at is not null and not isfinite(p_before_enrolled_at)) then\n  raise exception 'gateway_read_query_invalid' using errcode='22023';end if;\n -- One Read Committed statement sees a coherent committed source snapshot.\n -- Capture its clock inside that statement, after its snapshot is acquired;\n -- a concurrently committed heartbeat/action cannot be newer than this clock\n -- yet visible in only one of the separate projections.\n with read_time as materialized(select clock_timestamp() checked_at),\n candidates as materialized(\n  select d.* from collect_gateway.devices d\n  where p_before_enrolled_at is null or (d.created_at,d.id)<(p_before_enrolled_at,p_before_device_id)\n  order by d.created_at desc,d.id desc limit p_limit+1\n ),page as materialized(select * from candidates order by created_at desc,id desc limit p_limit),\n projected as (\n  select d.created_at,d.id,\n   collect_gateway.public_identity(d::collect_gateway.devices)||jsonb_build_object(\n    'state',d.state,'enrolled_at',collect_gateway.utc(d.created_at),\n    'activated_at',collect_gateway.utc(d.activated_at),'revoked_at',collect_gateway.utc(d.revoked_at),\n    'dispatch_authority','pending','dispatch_available',false,\n    'health',case when h.id is null then null else jsonb_build_object(\n     'observation_id',h.id,'reported_at',collect_gateway.utc(h.reported_at),\n     'ingested_at',collect_gateway.utc(h.ingested_at),\n     'observation_valid_until',collect_gateway.utc(least(h.reported_at,h.ingested_at)+interval '120 seconds'),\n     'freshness',case when t.checked_at<least(h.reported_at,h.ingested_at)+interval '120 seconds'\n       then 'fresh' else 'stale' end,\n     'sms_permission',h.sms_permission,'network',h.network,'telephony',h.telephony,\n     'sim_selected',h.sim_selected,'local_pause',h.local_pause,'carrier_proof',false) end,\n    'callback_observations',jsonb_build_object('total',collect_gateway.read_count(cb.total),\n     'sent',collect_gateway.read_count(cb.sent),'delivery',collect_gateway.read_count(cb.delivery)),\n    'last_owner_action',case when a.request_id is null then null else\n     jsonb_build_object('action',a.action,'receipt',collect_gateway.public_owner_receipt(a.result)) end) value\n  from page d cross join read_time t\n  left join lateral(select o.* from collect_gateway.health_observations o where o.device_id=d.id\n    order by o.ingested_at desc,o.id desc limit 1)h on true\n  left join lateral(select r.action,r.request_id,r.result from collect_gateway.admin_requests r\n    where r.result->>'device_id'=d.id::text order by r.recorded_at desc,r.request_id desc limit 1)a on true\n  cross join lateral(select count(*) total,count(*) filter(where c.callback_kind='sent')sent,\n    count(*) filter(where c.callback_kind='delivery')delivery\n    from collect_gateway.segment_callbacks c where c.device_id=d.id)cb\n )\n select jsonb_build_object('contract_version',1,'scope','platform_global',\n  'checked_at',collect_gateway.utc(t.checked_at),\n  'sample_valid_until',collect_gateway.utc(t.checked_at+interval '60 seconds'),\n  'limit',p_limit,'total',collect_gateway.read_count((select count(*) from collect_gateway.devices)),\n  'next_cursor',case when (select count(*) from candidates)>p_limit then\n   (select jsonb_build_object('enrolled_at',collect_gateway.utc(p.created_at),'device_id',p.id)\n    from page p order by p.created_at,p.id limit 1) else null end,\n  'rows',coalesce((select jsonb_agg(p.value order by p.created_at desc,p.id desc)from projected p),'[]'::jsonb))\n into result from read_time t;\n return result;\nend$$;\n\ncreate function public.admin_get_gateway_owner_request_v1(p_request_id uuid)\nreturns jsonb language plpgsql volatile security definer set search_path='' as $$\ndeclare actor uuid;result jsonb;\nbegin\n actor:=collect_gateway.read_actor();\n if p_request_id is null then raise exception 'gateway_owner_request_invalid' using errcode='22023';end if;\n -- Original-actor reconciliation only. An absent or other-actor request is\n -- unknown, never an instruction to retry an uncertain mutation. Identity\n -- fields are public immutable pairing data; original key bytes stay private.\n with read_time as materialized(select clock_timestamp() checked_at),\n evidence as materialized(\n  select r.action,r.result,d.* from collect_gateway.admin_requests r\n  join collect_gateway.devices d on r.result->>'device_id'=d.id::text\n  where r.request_id=p_request_id and r.actor_id=actor\n )\n select jsonb_build_object('contract_version',1,'scope','platform_global',\n  'checked_at',collect_gateway.utc(t.checked_at),\n  'sample_valid_until',collect_gateway.utc(t.checked_at+interval '60 seconds'),\n  'request_id',p_request_id,'outcome',case when e.id is null then 'unknown' else 'recorded' end,\n  'action',e.action,'receipt',case when e.id is null then null else collect_gateway.public_owner_receipt(e.result) end,\n  'identity',case when e.id is null then null else\n   jsonb_build_object('device_id',e.id,'installation_id',e.installation_id,\n    'key_sha256',e.key_sha256,'signing_certificate_sha256',e.signing_certificate_sha256) end)\n into result from read_time t left join evidence e on true;\n return result;\nend$$;\n\nrevoke all on function collect_gateway.read_actor(),collect_gateway.read_count(bigint),\n collect_gateway.public_identity(collect_gateway.devices),collect_gateway.public_owner_receipt(jsonb)\n from public,anon,authenticated,service_role;\nrevoke all on function public.admin_list_gateway_devices_v1(integer,timestamptz,uuid),\n public.admin_get_gateway_owner_request_v1(uuid) from public,anon,authenticated,service_role;\ngrant execute on function public.admin_list_gateway_devices_v1(integer,timestamptz,uuid),\n public.admin_get_gateway_owner_request_v1(uuid) to authenticated;\n\n-- Provision via the database owner and preserve customized or disabled rows.\n-- Serialize the absence check to avoid firing audit guards for skipped rows.\nlock table public.admin_navigation_items in share row exclusive mode;\ninsert into public.admin_navigation_items(key,label,icon_key,route_path,required_permission,\n display_order,enabled,metadata,updated_reason)\nselect 'sms_gateway','SMS Gateway','router','/admin/sms-gateway','notifications.read',146,true,\n '{}'::jsonb,'Redacted device observations and owner action evidence; dispatch authority pending'\nwhere not exists(select 1 from public.admin_navigation_items\n where key='sms_gateway' or route_path='/admin/sms-gateway')\non conflict do nothing;\n\nnotify pgrst,'reload schema';\ncommit;\n"}
20260601230000	preserve_contribution_sender_hash	{"-- Preserve the contributor MoMo hash on payment intents created from the\n-- mobile contribution flow. The Flutter client passes p_sender_phone_hash\n-- after profile MoMo setup, and allocation/audit paths should keep that\n-- contributor-side fingerprint when available.\n\ncreate or replace function create_contribution_intent(\n  collection uuid,\n  p_expected_amount_rwf bigint default null,\n  p_sender_phone_hash text default null\n)\nreturns table (\n  id uuid,\n  collection_id uuid,\n  expected_amount_rwf bigint,\n  receiver_momo_number text,\n  receiver_momo_number_hash text,\n  receiver_label text,\n  network text,\n  sender_phone_hash text,\n  status payment_intent_status,\n  contributor_public_id char(6),\n  created_at timestamptz,\n  expires_at timestamptz\n)\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  receiver_row collection_receivers;\n  intent_row payment_intents;\n  member_public_id char(6);\nbegin\n  if not public.user_can_read_collection(collection, auth.uid()) then\n    raise exception 'Group is not available';\n  end if;\n\n  if p_expected_amount_rwf is null or p_expected_amount_rwf <= 0 then\n    raise exception 'Contribution amount must be above zero';\n  end if;\n\n  select p.public_id into member_public_id\n  from profiles p\n  where p.id = auth.uid();\n\n  if member_public_id is null then\n    raise exception 'Collect ID is required before contributing';\n  end if;\n\n  select *\n    into receiver_row\n  from collection_receivers cr\n  where cr.collection_id = collection and cr.is_active\n  order by cr.created_at\n  limit 1;\n\n  if receiver_row.id is null then\n    raise exception 'Group has no active receiver';\n  end if;\n\n  insert into payment_intents (\n    collection_id,\n    contributor_user_id,\n    contributor_public_id,\n    expected_amount_rwf,\n    receiver_momo_number_hash,\n    sender_phone_hash\n  )\n  values (\n    collection,\n    auth.uid(),\n    member_public_id,\n    p_expected_amount_rwf,\n    receiver_row.momo_number_hash,\n    nullif(trim(p_sender_phone_hash), '')\n  )\n  returning * into intent_row;\n\n  return query select\n    intent_row.id,\n    intent_row.collection_id,\n    intent_row.expected_amount_rwf,\n    receiver_row.momo_number,\n    intent_row.receiver_momo_number_hash,\n    receiver_row.label,\n    receiver_row.network,\n    intent_row.sender_phone_hash,\n    intent_row.status,\n    intent_row.contributor_public_id,\n    intent_row.created_at,\n    intent_row.expires_at;\nend;\n$$;\n\nrevoke execute on function create_contribution_intent(uuid, bigint, text)\n  from public, anon;\ngrant execute on function create_contribution_intent(uuid, bigint, text)\n  to authenticated;\n"}
20260602050000	harden_mobile_state_rls_initplan	{"-- Keep mobile support/deletion request policies aligned with Supabase\n-- performance-advisor guidance by evaluating auth.uid() once per statement.\n\ndrop policy if exists \\"account deletion own read\\" on mobile_account_deletion_requests;\ncreate policy \\"account deletion own read\\"\non mobile_account_deletion_requests\nfor select to authenticated\nusing (\n  user_id = (select auth.uid())\n  or is_platform_admin((select auth.uid()))\n);\n\ndrop policy if exists \\"support requests own read\\" on mobile_support_requests;\ncreate policy \\"support requests own read\\"\non mobile_support_requests\nfor select to authenticated\nusing (\n  user_id = (select auth.uid())\n  or is_platform_admin((select auth.uid()))\n);\n"}
20260607130500	update_collection_profile_rpc	{"create or replace function update_collection_profile(\n  collection uuid,\n  group_name text,\n  group_description text,\n  group_image_url text default null,\n  group_accent_color_hex text default null,\n  group_is_public boolean default false,\n  group_recurring_cadence text default 'monthly'\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if not user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can update the group profile';\n  end if;\n  if nullif(trim(group_name), '') is null then\n    raise exception 'Group name is required';\n  end if;\n\n  update collections\n  set\n    title = trim(group_name),\n    description = trim(coalesce(group_description, '')),\n    cover_image_url = nullif(trim(group_image_url), ''),\n    accent_color_hex = nullif(trim(group_accent_color_hex), ''),\n    is_public = coalesce(group_is_public, false),\n    recurring_cadence = coalesce(nullif(trim(group_recurring_cadence), ''), 'monthly'),\n    updated_at = now()\n  where id = collection;\n\n  if not found then\n    raise exception 'Group not found';\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.profile_updated',\n    'collection',\n    collection,\n    jsonb_build_object(\n      'is_public', coalesce(group_is_public, false),\n      'recurring_cadence', coalesce(nullif(trim(group_recurring_cadence), ''), 'monthly')\n    )\n  );\nend;\n$$;\n\nrevoke execute on function update_collection_profile(uuid, text, text, text, text, boolean, text)\n  from public, anon, authenticated;\ngrant execute on function update_collection_profile(uuid, text, text, text, text, boolean, text)\n  to authenticated;\n"}
20260608090000	native_notifications	{"create table if not exists notification_preferences (\n  user_id uuid primary key references profiles(id) on delete cascade,\n  contribution_confirmations boolean not null default true,\n  payment_reminders boolean not null default true,\n  group_updates boolean not null default true,\n  security_notices boolean not null default true,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists notification_device_tokens (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references profiles(id) on delete cascade,\n  platform text not null check (platform in ('android', 'ios', 'web')),\n  token_hash text not null,\n  token_last_four text,\n  enabled boolean not null default true,\n  last_seen_at timestamptz not null default now(),\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  unique (user_id, token_hash)\n);\n\ncreate table if not exists notification_events (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references profiles(id) on delete cascade,\n  collection_id uuid references collections(id) on delete cascade,\n  type text not null check (type in (\n    'contribution_confirmed',\n    'payment_reminder',\n    'group_update',\n    'security_notice'\n  )),\n  title text not null,\n  body text not null,\n  deep_link text,\n  status text not null default 'queued' check (status in ('queued', 'sent', 'failed', 'read')),\n  created_at timestamptz not null default now(),\n  sent_at timestamptz,\n  read_at timestamptz\n);\n\nalter table notification_preferences enable row level security;\nalter table notification_device_tokens enable row level security;\nalter table notification_events enable row level security;\n\ndrop policy if exists \\"notification preferences own read\\" on notification_preferences;\ncreate policy \\"notification preferences own read\\" on notification_preferences\nfor select using (user_id = auth.uid());\n\ndrop policy if exists \\"notification preferences own upsert\\" on notification_preferences;\ncreate policy \\"notification preferences own upsert\\" on notification_preferences\nfor insert with check (user_id = auth.uid());\n\ndrop policy if exists \\"notification preferences own update\\" on notification_preferences;\ncreate policy \\"notification preferences own update\\" on notification_preferences\nfor update using (user_id = auth.uid()) with check (user_id = auth.uid());\n\ndrop policy if exists \\"notification device own read\\" on notification_device_tokens;\ncreate policy \\"notification device own read\\" on notification_device_tokens\nfor select using (user_id = auth.uid());\n\ndrop policy if exists \\"notification device own insert\\" on notification_device_tokens;\ncreate policy \\"notification device own insert\\" on notification_device_tokens\nfor insert with check (user_id = auth.uid());\n\ndrop policy if exists \\"notification device own update\\" on notification_device_tokens;\ncreate policy \\"notification device own update\\" on notification_device_tokens\nfor update using (user_id = auth.uid()) with check (user_id = auth.uid());\n\ndrop policy if exists \\"notification events own read\\" on notification_events;\ncreate policy \\"notification events own read\\" on notification_events\nfor select using (user_id = auth.uid());\n\ndrop policy if exists \\"notification events own update\\" on notification_events;\ncreate policy \\"notification events own update\\" on notification_events\nfor update using (user_id = auth.uid()) with check (user_id = auth.uid());\n\ncreate index if not exists notification_events_user_created_idx\non notification_events (user_id, created_at desc);\n\ncreate or replace function register_notification_device(\n  p_platform text,\n  p_token_hash text,\n  p_token_last_four text default null\n)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  insert into notification_device_tokens (\n    user_id,\n    platform,\n    token_hash,\n    token_last_four,\n    enabled,\n    last_seen_at,\n    updated_at\n  )\n  values (\n    auth.uid(),\n    p_platform,\n    p_token_hash,\n    p_token_last_four,\n    true,\n    now(),\n    now()\n  )\n  on conflict (user_id, token_hash)\n  do update set\n    platform = excluded.platform,\n    token_last_four = excluded.token_last_four,\n    enabled = true,\n    last_seen_at = now(),\n    updated_at = now();\n$$;\n\ncreate or replace function mark_notification_event_read(p_event_id uuid)\nreturns void\nlanguage sql\nsecurity definer\nset search_path = public\nas $$\n  update notification_events\n  set status = 'read',\n      read_at = now()\n  where id = p_event_id\n    and user_id = auth.uid();\n$$;\n\ncreate or replace function enqueue_notification_event(\n  p_user_id uuid,\n  p_type text,\n  p_title text,\n  p_body text,\n  p_collection_id uuid default null,\n  p_deep_link text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  inserted_id uuid;\nbegin\n  insert into notification_events (\n    user_id,\n    collection_id,\n    type,\n    title,\n    body,\n    deep_link\n  )\n  values (\n    p_user_id,\n    p_collection_id,\n    p_type,\n    p_title,\n    p_body,\n    p_deep_link\n  )\n  returning id into inserted_id;\n\n  return inserted_id;\nend;\n$$;\n\ngrant execute on function register_notification_device(text, text, text) to authenticated;\ngrant execute on function mark_notification_event_read(uuid) to authenticated;\ngrant execute on function enqueue_notification_event(uuid, text, text, text, uuid, text) to service_role;\n"}
20260611111500	harden_mobile_profile_rpcs	{"alter table collections\n  add column if not exists accent_color_hex text,\n  add column if not exists recurring_cadence text not null default 'monthly'\n    check (recurring_cadence in ('daily', 'weekly', 'monthly'));\n\nupdate collections\nset recurring_cadence = coalesce(\n  nullif(trim(recurring_rule->>'cadence'), ''),\n  recurring_cadence,\n  'monthly'\n)\nwhere recurring_rule ? 'cadence';\n\ngrant select (accent_color_hex, recurring_cadence)\n  on collections to anon, authenticated;\n\ndrop function if exists ensure_current_profile(text);\n\ncreate or replace function ensure_current_profile(p_whatsapp_phone text default null)\nreturns profiles\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  profile_row profiles%rowtype;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select * into profile_row\n  from profiles\n  where id = auth.uid();\n\n  if profile_row.id is null then\n    insert into profiles (id, public_id, whatsapp_phone)\n    values (\n      auth.uid(),\n      generate_public_id(),\n      nullif(trim(p_whatsapp_phone), '')\n    )\n    returning * into profile_row;\n  elsif nullif(trim(p_whatsapp_phone), '') is not null\n    and coalesce(profile_row.whatsapp_phone, '') = '' then\n    update profiles\n    set whatsapp_phone = trim(p_whatsapp_phone)\n    where id = auth.uid()\n    returning * into profile_row;\n  end if;\n\n  return profile_row;\nend;\n$$;\n\nrevoke execute on function ensure_current_profile(text)\n  from public, anon, authenticated;\ngrant execute on function ensure_current_profile(text) to authenticated;\n\ncreate or replace function update_collection_profile(\n  collection uuid,\n  group_name text,\n  group_description text,\n  group_image_url text default null,\n  group_accent_color_hex text default null,\n  group_is_public boolean default false,\n  group_recurring_cadence text default 'monthly'\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  clean_cadence text := coalesce(\n    nullif(trim(group_recurring_cadence), ''),\n    'monthly'\n  );\n  next_public_status collection_visibility := case\n    when coalesce(group_is_public, false) then 'public_requested'::collection_visibility\n    else 'private'::collection_visibility\n  end;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if not user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can update the group profile';\n  end if;\n  if nullif(trim(group_name), '') is null then\n    raise exception 'Group name is required';\n  end if;\n  if clean_cadence not in ('daily', 'weekly', 'monthly') then\n    raise exception 'Unsupported recurring cadence';\n  end if;\n\n  update collections\n  set\n    title = trim(group_name),\n    description = trim(coalesce(group_description, '')),\n    cover_image_url = nullif(trim(group_image_url), ''),\n    accent_color_hex = nullif(trim(group_accent_color_hex), ''),\n    public_status = next_public_status,\n    visibility = next_public_status,\n    is_recurring = true,\n    recurring_cadence = clean_cadence,\n    recurring_rule = jsonb_build_object('cadence', clean_cadence),\n    updated_at = now()\n  where id = collection;\n\n  if not found then\n    raise exception 'Group not found';\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.profile_updated',\n    'collection',\n    collection,\n    jsonb_build_object(\n      'is_public', coalesce(group_is_public, false),\n      'public_status', next_public_status::text,\n      'recurring_cadence', clean_cadence\n    )\n  );\nend;\n$$;\n\nrevoke execute on function update_collection_profile(uuid, text, text, text, text, boolean, text)\n  from public, anon, authenticated;\ngrant execute on function update_collection_profile(uuid, text, text, text, text, boolean, text)\n  to authenticated;\n\ncreate or replace view member_collections_view\nwith (security_invoker = true)\nas\nselect\n  c.id,\n  c.slug,\n  c.creator_user_id,\n  c.title,\n  c.description,\n  c.currency,\n  case\n    when public.user_is_collection_admin(c.id, auth.uid())\n      or exists (\n        select 1\n        from collection_receivers receiver_check\n        where receiver_check.collection_id = c.id\n          and receiver_check.receiver_user_id = auth.uid()\n          and receiver_check.is_active\n      )\n      then cr.momo_number\n    else null\n  end as receiver_momo_number,\n  case\n    when public.user_can_read_collection(c.id, auth.uid()) then cr.label\n    else null\n  end as receiver_display_label,\n  cr.network as receiver_network,\n  c.created_at,\n  c.updated_at,\n  c.archived_at,\n  c.accent_color_hex,\n  c.recurring_cadence\nfrom collections c\nleft join lateral (\n  select\n    collection_receivers.momo_number,\n    collection_receivers.label,\n    collection_receivers.network\n  from collection_receivers\n  where collection_receivers.collection_id = c.id\n    and collection_receivers.is_active\n  order by collection_receivers.created_at asc\n  limit 1\n) cr on true\nwhere public.user_can_read_collection(c.id, auth.uid());\n\nalter view public.member_collections_view set (security_invoker = true);\ngrant select on member_collections_view to authenticated;\n"}
20261001000300	admin_exception_reads	{"begin;\n\n-- Additive redacted reads. Captured v1 mutations and receipts remain unchanged.\ncreate function collect_ops.transaction_sms_id(p_kind text,p_source uuid)\nreturns uuid language sql stable security definer set search_path='' as $$\n select case p_kind\n  when 'raw_sms' then(select sms.id from public.raw_payment_sms sms\n   where sms.id=p_source and collect_security.rwanda_sms_scope(sms.id))\n  when 'allocation' then(select sms.id from public.parsed_payment_events e\n   join public.raw_payment_sms sms on sms.id=e.raw_sms_id\n   where e.id=p_source and collect_security.rwanda_sms_scope(sms.id))\n  when 'payment' then(select sms.id from public.payments p\n   join public.parsed_payment_events e on e.id=p.parsed_event_id\n   join public.raw_payment_sms sms on sms.id=e.raw_sms_id\n   where p.id=p_source and p.currency='RWF'\n    and e.receiver_user_id=p.receiver_user_id and e.network=p.provider_network\n    and sms.receiver_momo_number_hash=p.receiver_momo_number_hash\n    and collect_security.rwanda_sms_scope(sms.id))\n  else null::uuid end\n$$;\n\ncreate function collect_ops.public_action_receipt(p_action collect_ops.exception_actions)\nreturns jsonb language sql immutable set search_path='' as $$\n select jsonb_build_object('contract_version',1,'request_id',p_action.request_id,\n  'exception_id',p_action.exception_id,'revision',p_action.expected_revision,\n  'action',p_action.action,'recorded_at',collect_ops.utc(p_action.recorded_at),\n  'source_resolved',false,'financial_action',false,'send_action',false,\n  'escalation_delivery_verified',false)\n$$;\n\ncreate function public.admin_list_operational_exceptions_v2(p_active boolean default true,\n p_limit integer default 20,p_before_changed_at timestamptz default null,\n p_before_id uuid default null,p_source_kind text default null)\nreturns jsonb language plpgsql volatile security definer set search_path='' as $$\ndeclare result jsonb;\nbegin\n perform collect_ops.actor(false);\n if p_active is null or p_limit is null or p_limit not between 1 and 50\n  or((p_before_changed_at is null)<>(p_before_id is null))\n  or(p_before_changed_at is not null and not isfinite(p_before_changed_at))\n  or(p_source_kind is not null and p_source_kind not in('raw_sms','allocation','payment','receipt','gateway')) then\n  raise exception 'operational_exception_query_invalid' using errcode='22023';end if;\n -- One committed statement supplies time, category, page and review flags.\n -- Read freshness is independent of the retained source observation's age.\n with sample as materialized(select clock_timestamp() at),\n candidates as materialized(select e.* from collect_ops.exceptions e\n  where e.active=p_active and(p_source_kind is null or e.source_kind=p_source_kind)\n   and(p_before_changed_at is null or(e.last_changed_at,e.id)<(p_before_changed_at,p_before_id))\n  order by e.last_changed_at desc,e.id desc limit p_limit+1),\n page as materialized(select * from candidates order by last_changed_at desc,id desc limit p_limit),\n projected as(select e.last_changed_at,e.id,jsonb_build_object('id',e.id,\n  'source_kind',e.source_kind,'source_id',e.source_id,'reason_code',e.reason_code,\n  'active',e.active,'revision',e.revision,'source_sha256',e.source_sha256,\n  'first_observed_at',collect_ops.utc(e.first_observed_at),\n  'last_changed_at',collect_ops.utc(e.last_changed_at),\n  'transaction_sms_id',collect_ops.transaction_sms_id(e.source_kind,e.source_id),\n  'acknowledged',exists(select 1 from collect_ops.exception_actions a\n   where a.exception_id=e.id and a.expected_revision=e.revision and a.action='acknowledge'),\n  'escalation_requested',exists(select 1 from collect_ops.exception_actions a\n   where a.exception_id=e.id and a.expected_revision=e.revision and a.action='escalate'))value from page e)\n select jsonb_build_object('contract_version',2,'scope','platform_global',\n  'checked_at',collect_ops.utc(sample.at),'sample_valid_until',collect_ops.utc(sample.at+interval '60 seconds'),\n  'active',p_active,'source_kind',p_source_kind,'limit',p_limit,\n  'rows',coalesce((select jsonb_agg(value order by last_changed_at desc,id desc)from projected),'[]'::jsonb),\n  'next_cursor',case when(select count(*)from candidates)>p_limit then\n   (select jsonb_build_object('changed_at',collect_ops.utc(last_changed_at),'id',id)\n    from page order by last_changed_at,id limit 1)else null end,\n  'escalation_delivery_verified',false,'source_scan_complete',false)\n into result from sample;\n return result;\nend$$;\n\ncreate function public.admin_get_operational_exception_action_v2(p_request_id uuid)\nreturns jsonb language plpgsql volatile security definer set search_path='' set lock_timeout='100ms' as $$\ndeclare result jsonb;acquired boolean;\nbegin\n -- The original action holds the roster authority lock until commit. Timeout\n -- means current authority could not be established, without outcome leakage.\n perform collect_ops.actor(false);\n if p_request_id is null then raise exception 'operational_exception_action_invalid' using errcode='22023';end if;\n acquired:=pg_try_advisory_xact_lock(hashtextextended('collect-ops-action:'||p_request_id::text,0));\n with sample as materialized(select clock_timestamp() at),\n prior as materialized(select a.* from collect_ops.exception_actions a\n  where acquired and a.request_id=p_request_id and a.actor_id=auth.uid())\n select jsonb_build_object('contract_version',2,'scope','platform_global',\n  'checked_at',collect_ops.utc(sample.at),'sample_valid_until',collect_ops.utc(sample.at+interval '60 seconds'),\n  'request_id',p_request_id,'status',case when not acquired then 'in_progress'\n   when exists(select 1 from prior)then 'recorded'else 'not_recorded'end,\n  'receipt',(select collect_ops.public_action_receipt(p)from prior p))\n into result from sample;\n return result;\nexception when lock_not_available then\n raise exception 'operational_exception_authority_busy' using errcode='55P03';\nend$$;\n\nrevoke all on function collect_ops.transaction_sms_id(text,uuid),\n collect_ops.public_action_receipt(collect_ops.exception_actions) from public,anon,authenticated,service_role;\nrevoke all on function public.admin_list_operational_exceptions_v2(boolean,integer,timestamptz,uuid,text),\n public.admin_get_operational_exception_action_v2(uuid) from public,anon,authenticated,service_role;\ngrant execute on function public.admin_list_operational_exceptions_v2(boolean,integer,timestamptz,uuid,text),\n public.admin_get_operational_exception_action_v2(uuid) to authenticated;\n\n-- Preserve custom/disabled entries, including another key using this route.\nlock table public.admin_navigation_items in share row exclusive mode;\ninsert into public.admin_navigation_items(key,label,icon_key,route_path,required_permission,\n display_order,enabled,metadata,updated_reason)\nselect 'exceptions','Exceptions','warning_amber','/admin/exceptions','payments.read',147,true,\n '{}'::jsonb,'Derived operational source conditions and human review evidence'\nwhere not exists(select 1 from public.admin_navigation_items\n where key='exceptions' or route_path='/admin/exceptions')\non conflict do nothing;\nnotify pgrst,'reload schema';\ncommit;\n"}
20260611113000	harden_notification_rls_initplan	{"drop policy if exists \\"notification preferences own read\\" on notification_preferences;\ncreate policy \\"notification preferences own read\\" on notification_preferences\nfor select using (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification preferences own upsert\\" on notification_preferences;\ncreate policy \\"notification preferences own upsert\\" on notification_preferences\nfor insert with check (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification preferences own update\\" on notification_preferences;\ncreate policy \\"notification preferences own update\\" on notification_preferences\nfor update\nusing (user_id = (select auth.uid()))\nwith check (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification device own read\\" on notification_device_tokens;\ncreate policy \\"notification device own read\\" on notification_device_tokens\nfor select using (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification device own insert\\" on notification_device_tokens;\ncreate policy \\"notification device own insert\\" on notification_device_tokens\nfor insert with check (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification device own update\\" on notification_device_tokens;\ncreate policy \\"notification device own update\\" on notification_device_tokens\nfor update\nusing (user_id = (select auth.uid()))\nwith check (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification events own read\\" on notification_events;\ncreate policy \\"notification events own read\\" on notification_events\nfor select using (user_id = (select auth.uid()));\n\ndrop policy if exists \\"notification events own update\\" on notification_events;\ncreate policy \\"notification events own update\\" on notification_events\nfor update\nusing (user_id = (select auth.uid()))\nwith check (user_id = (select auth.uid()));\n"}
20260611114500	tighten_notification_rpc_grants	{"revoke execute on function register_notification_device(text, text, text)\n  from public, anon, authenticated;\ngrant execute on function register_notification_device(text, text, text)\n  to authenticated;\n\nrevoke execute on function mark_notification_event_read(uuid)\n  from public, anon, authenticated;\ngrant execute on function mark_notification_event_read(uuid)\n  to authenticated;\n\nrevoke execute on function enqueue_notification_event(uuid, text, text, text, uuid, text)\n  from public, anon, authenticated;\ngrant execute on function enqueue_notification_event(uuid, text, text, text, uuid, text)\n  to service_role;\n"}
20260611171920	admin_whatsapp_operator_login	{"create or replace function admin_bootstrap_whatsapp_operator()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  allowed_phone constant text := '+250788767816';\n  current_digits text;\n  current_phone text;\n  owner_role_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  current_digits := regexp_replace(coalesce(auth.jwt() ->> 'phone', ''), '[^0-9]', '', 'g');\n  if left(current_digits, 2) = '00' then\n    current_digits := substring(current_digits from 3);\n  end if;\n  current_phone := case\n    when current_digits = '' then ''\n    else '+' || current_digits\n  end;\n\n  if current_phone <> allowed_phone then\n    raise exception 'Registered admin WhatsApp number required';\n  end if;\n\n  if exists (\n    select 1\n    from profiles\n    where whatsapp_phone = allowed_phone\n      and id <> auth.uid()\n  ) then\n    raise exception 'Registered admin WhatsApp number belongs to another profile';\n  end if;\n\n  insert into profiles (\n    id,\n    public_id,\n    whatsapp_phone,\n    display_name,\n    is_platform_admin\n  )\n  values (\n    auth.uid(),\n    generate_public_id(),\n    allowed_phone,\n    'Collect admin',\n    true\n  )\n  on conflict (id) do update\n  set\n    whatsapp_phone = allowed_phone,\n    display_name = coalesce(nullif(profiles.display_name, ''), 'Collect admin'),\n    is_platform_admin = true,\n    updated_at = now();\n\n  select id into owner_role_id\n  from admin_roles\n  where name = 'platform_owner';\n\n  if owner_role_id is null then\n    raise exception 'Platform owner role is not configured';\n  end if;\n\n  if not exists (\n    select 1\n    from admin_user_roles\n    where user_id = auth.uid()\n      and role_id = owner_role_id\n      and revoked_at is null\n  ) then\n    insert into admin_user_roles (user_id, role_id, granted_by, reason)\n    values (\n      auth.uid(),\n      owner_role_id,\n      auth.uid(),\n      'Verified admin WhatsApp operator login'\n    );\n  end if;\n\n  perform create_audit_log(\n    'admin.bootstrap.whatsapp_operator',\n    'profile',\n    auth.uid(),\n    jsonb_build_object('phone_masked', mask_phone(allowed_phone)),\n    auth.uid()\n  );\n\n  return jsonb_build_object('ok', true);\nend;\n$$;\n\nrevoke execute on function admin_bootstrap_whatsapp_operator()\n  from public, anon, authenticated;\ngrant execute on function admin_bootstrap_whatsapp_operator() to authenticated;\n"}
20260611184934	fix_admin_whatsapp_bootstrap_phone_lookup	{"create or replace function admin_bootstrap_whatsapp_operator()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  allowed_phone constant text := '+250788767816';\n  allowed_digits constant text := '250788767816';\n  current_digits text;\n  owner_role_id uuid;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select regexp_replace(coalesce(u.phone, ''), '[^0-9]', '', 'g')\n  into current_digits\n  from auth.users u\n  where u.id = auth.uid();\n\n  if coalesce(current_digits, '') = '' then\n    current_digits := regexp_replace(\n      coalesce(auth.jwt() ->> 'phone', ''),\n      '[^0-9]',\n      '',\n      'g'\n    );\n  end if;\n\n  if left(coalesce(current_digits, ''), 2) = '00' then\n    current_digits := substring(current_digits from 3);\n  end if;\n\n  if current_digits <> allowed_digits then\n    raise exception 'Registered admin WhatsApp number required';\n  end if;\n\n  if exists (\n    select 1\n    from profiles\n    where whatsapp_phone = allowed_phone\n      and id <> auth.uid()\n  ) then\n    raise exception 'Registered admin WhatsApp number belongs to another profile';\n  end if;\n\n  insert into profiles (\n    id,\n    public_id,\n    whatsapp_phone,\n    display_name,\n    is_platform_admin\n  )\n  values (\n    auth.uid(),\n    generate_public_id(),\n    allowed_phone,\n    'Collect admin',\n    true\n  )\n  on conflict (id) do update\n  set\n    whatsapp_phone = allowed_phone,\n    display_name = coalesce(nullif(profiles.display_name, ''), 'Collect admin'),\n    is_platform_admin = true,\n    updated_at = now();\n\n  select id into owner_role_id\n  from admin_roles\n  where name = 'platform_owner';\n\n  if owner_role_id is null then\n    raise exception 'Platform owner role is not configured';\n  end if;\n\n  if not exists (\n    select 1\n    from admin_user_roles\n    where user_id = auth.uid()\n      and role_id = owner_role_id\n      and revoked_at is null\n  ) then\n    insert into admin_user_roles (user_id, role_id, granted_by, reason)\n    values (\n      auth.uid(),\n      owner_role_id,\n      auth.uid(),\n      'Verified admin WhatsApp operator login'\n    );\n  end if;\n\n  perform create_audit_log(\n    'admin.bootstrap.whatsapp_operator',\n    'profile',\n    auth.uid(),\n    jsonb_build_object('phone_masked', mask_phone(allowed_phone)),\n    auth.uid()\n  );\n\n  return jsonb_build_object('ok', true);\nend;\n$$;\n\nrevoke execute on function admin_bootstrap_whatsapp_operator()\n  from public, anon, authenticated;\ngrant execute on function admin_bootstrap_whatsapp_operator() to authenticated;\n"}
20260612103000	disable_browser_admin_bootstrap	{"-- Browser admin login must not grant platform-owner privileges.\n-- Use admin_bootstrap_platform_owner(p_user_id, p_reason) from a service-role\n-- controlled operator path for break-glass or first-owner setup.\n\ncreate or replace function admin_bootstrap_whatsapp_operator()\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\nbegin\n  raise exception 'admin_bootstrap_whatsapp_operator is disabled; use the service-role admin bootstrap workflow';\nend;\n$$;\n\nrevoke execute on function admin_bootstrap_whatsapp_operator()\n  from public, anon, authenticated;\ngrant execute on function admin_bootstrap_whatsapp_operator()\n  to service_role;\n"}
20260612110000	admin_payment_event_server_paging	{"create or replace function admin_list_payment_events(\n  p_search text default null,\n  p_status text default null,\n  p_limit integer default 25,\n  p_offset integer default 0,\n  p_sort text default 'created_at_desc'\n)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);\n  v_offset integer := greatest(coalesce(p_offset, 0), 0);\n  v_sort text := coalesce(nullif(p_sort, ''), 'created_at_desc');\n  v_result jsonb;\nbegin\n  perform assert_admin_permission('payment_events.read');\n  if v_sort not in (\n    'created_at_desc',\n    'created_at_asc',\n    'amount_desc',\n    'amount_asc'\n  ) then\n    v_sort := 'created_at_desc';\n  end if;\n\n  with filtered as (\n    select e.*\n    from parsed_payment_events e\n    where (p_status is null or e.allocation_status::text = p_status)\n      and (p_search is null or e.transaction_id ilike '%' || p_search || '%')\n  ),\n  ordered as (\n    select\n      filtered.*,\n      row_number() over (\n        order by\n          case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,\n          case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,\n          case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,\n          case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,\n          filtered.created_at desc nulls last,\n          filtered.id\n      ) as admin_rank\n    from filtered\n    order by\n      case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,\n      case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,\n      case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,\n      case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,\n      filtered.created_at desc nulls last,\n      filtered.id\n    limit v_limit\n    offset v_offset\n  )\n  select jsonb_build_object(\n    'rows',\n    coalesce(\n      jsonb_agg(\n        _admin_row(\n          ordered.id,\n          coalesce(ordered.transaction_id, 'Payment event'),\n          'MoMo SMS',\n          ordered.allocation_status::text,\n          coalesce(ordered.amount_rwf::text || ' RWF', ''),\n          ordered.created_at,\n          jsonb_build_object('collection_id', ordered.collection_id)\n        )\n        order by ordered.admin_rank\n      ),\n      '[]'::jsonb\n    ),\n    'total',\n    (select count(*) from filtered)\n  )\n  into v_result\n  from ordered;\n\n  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));\nend;\n$$;\n\ncreate or replace function admin_list_allocations(\n  p_search text default null,\n  p_status text default null,\n  p_limit integer default 25,\n  p_offset integer default 0,\n  p_sort text default 'created_at_desc'\n)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\nbegin\n  perform assert_admin_permission('payment_events.read');\n  return admin_list_payment_events(\n    p_search,\n    coalesce(p_status, 'allocated'),\n    p_limit,\n    p_offset,\n    p_sort\n  );\nend;\n$$;\n\ncreate or replace function admin_list_unallocated(\n  p_search text default null,\n  p_status text default null,\n  p_limit integer default 25,\n  p_offset integer default 0,\n  p_sort text default 'created_at_desc'\n)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  v_limit integer := least(greatest(coalesce(p_limit, 25), 1), 100);\n  v_offset integer := greatest(coalesce(p_offset, 0), 0);\n  v_sort text := coalesce(nullif(p_sort, ''), 'created_at_desc');\n  v_result jsonb;\nbegin\n  perform assert_admin_permission('payment_events.read');\n  if v_sort not in (\n    'created_at_desc',\n    'created_at_asc',\n    'amount_desc',\n    'amount_asc'\n  ) then\n    v_sort := 'created_at_desc';\n  end if;\n\n  with filtered as (\n    select e.*\n    from parsed_payment_events e\n    where (\n      (\n        p_status is null\n        and e.allocation_status in ('unallocated', 'ambiguous', 'needs_review')\n      )\n      or (\n        p_status is not null\n        and e.allocation_status::text = p_status\n      )\n    )\n    and (\n      p_search is null\n      or e.transaction_id ilike '%' || p_search || '%'\n    )\n  ),\n  ordered as (\n    select\n      filtered.*,\n      row_number() over (\n        order by\n          case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,\n          case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,\n          case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,\n          case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,\n          filtered.created_at desc nulls last,\n          filtered.id\n      ) as admin_rank\n    from filtered\n    order by\n      case when v_sort = 'created_at_asc' then filtered.created_at end asc nulls last,\n      case when v_sort = 'created_at_desc' then filtered.created_at end desc nulls last,\n      case when v_sort = 'amount_asc' then filtered.amount_rwf end asc nulls last,\n      case when v_sort = 'amount_desc' then filtered.amount_rwf end desc nulls last,\n      filtered.created_at desc nulls last,\n      filtered.id\n    limit v_limit\n    offset v_offset\n  )\n  select jsonb_build_object(\n    'rows',\n    coalesce(\n      jsonb_agg(\n        _admin_row(\n          ordered.id,\n          coalesce(ordered.transaction_id, 'Payment event'),\n          'MoMo SMS',\n          ordered.allocation_status::text,\n          coalesce(ordered.amount_rwf::text || ' RWF', ''),\n          ordered.created_at,\n          jsonb_build_object('collection_id', ordered.collection_id)\n        )\n        order by ordered.admin_rank\n      ),\n      '[]'::jsonb\n    ),\n    'total',\n    (select count(*) from filtered)\n  )\n  into v_result\n  from ordered;\n\n  return coalesce(v_result, jsonb_build_object('rows', '[]'::jsonb, 'total', 0));\nend;\n$$;\n\ngrant execute on function admin_list_payment_events(text, text, integer, integer, text) to authenticated;\ngrant execute on function admin_list_allocations(text, text, integer, integer, text) to authenticated;\ngrant execute on function admin_list_unallocated(text, text, integer, integer, text) to authenticated;\n"}
20260612111500	drop_legacy_payment_event_queue_overloads	{"drop function if exists admin_list_allocations(text, text);\ndrop function if exists admin_list_unallocated(text, text);\ndrop function if exists admin_list_payment_events(text, text);\n"}
20261001000400	receipt_supervisor_identity	{"begin;\n\n-- Dedicated signed machine identity. Initial authority is Rwanda receipt\n-- shadow health only; owner activation does not grant business or send actions.\ncreate schema collect_supervisor;\nrevoke all on schema collect_supervisor from public,anon,authenticated,service_role;\ncreate table collect_supervisor.identities(\n id uuid primary key default gen_random_uuid(),\n enrollment_request_id uuid not null unique,\n owner_actor_id uuid not null,\n owner_session_id uuid not null,\n public_key_spki_base64 text not null,\n key_sha256 text not null unique check(key_sha256 ~ '^[0-9a-f]{64}$'),\n scope text not null default 'rw_receipt_shadow' check(scope='rw_receipt_shadow'),\n state text not null default 'pending' check(state in('pending','active','revoked')),\n created_at timestamptz not null,\n expires_at timestamptz not null,\n activated_at timestamptz,\n revoked_at timestamptz,\n check(isfinite(created_at) and isfinite(expires_at) and expires_at>created_at\n  and expires_at<=created_at+interval '30 days'),\n check((state='pending'and activated_at is null and revoked_at is null)\n  or(state='active'and activated_at is not null and revoked_at is null)\n  or(state='revoked'and revoked_at is not null))\n);\ncreate table collect_supervisor.owner_requests(\n request_id uuid primary key,actor_id uuid not null,session_id uuid not null,\n action text not null check(action in('enroll','activate','revoke')),\n input jsonb not null,result jsonb not null,recorded_at timestamptz not null\n);\ncreate table collect_supervisor.requests(\n request_id uuid primary key,\n principal_id uuid not null references collect_supervisor.identities(id)on delete restrict,\n action text not null check(action in('prove_key','shadow_health')),\n key_sha256 text not null check(key_sha256 ~ '^[0-9a-f]{64}$'),\n request_sha256 text not null check(request_sha256 ~ '^[0-9a-f]{64}$'),\n issued_at timestamptz not null,recorded_at timestamptz not null,result jsonb not null,\n check(isfinite(issued_at)and isfinite(recorded_at))\n);\ncreate index supervisor_proofs on collect_supervisor.requests(principal_id,recorded_at desc)\n where action='prove_key';\ndo $$declare t text;begin\n foreach t in array array['identities','owner_requests','requests']loop\n  execute format('alter table collect_supervisor.%I enable row level security',t);\n  execute format('revoke all on collect_supervisor.%I from public,anon,authenticated,service_role',t);\n end loop;\nend$$;\ncreate function collect_supervisor.immutable_evidence()returns trigger language plpgsql set search_path=''as $$\nbegin raise exception 'supervisor_evidence_immutable'using errcode='55000';end$$;\ncreate trigger supervisor_owner_request_immutable before update or delete on collect_supervisor.owner_requests\n for each row execute function collect_supervisor.immutable_evidence();\ncreate trigger supervisor_request_immutable before update or delete on collect_supervisor.requests\n for each row execute function collect_supervisor.immutable_evidence();\ncreate function collect_supervisor.guard_identity()returns trigger language plpgsql set search_path=''as $$\nbegin\n if tg_op='DELETE'then raise exception 'supervisor_identity_retained'using errcode='55000';end if;\n if (to_jsonb(new)-array['state','activated_at','revoked_at'])is distinct from\n  (to_jsonb(old)-array['state','activated_at','revoked_at'])or old.state='revoked'\n  or(old.state='active'and new.state not in('active','revoked'))\n  or(old.activated_at is not null and new.activated_at is distinct from old.activated_at)then\n  raise exception 'supervisor_identity_immutable'using errcode='55000';end if;\n return new;\nend$$;\ncreate trigger retained_supervisor_identity before update or delete on collect_supervisor.identities\n for each row execute function collect_supervisor.guard_identity();\n\n-- The two identities must never share a signing key, regardless of enrollment\n-- order. Both insert paths take the same transaction key fence before checking\n-- the other retained namespace; revocation does not release the key for reuse.\ncreate function collect_supervisor.distinct_identity_key()returns trigger\nlanguage plpgsql volatile security definer set search_path=''as $$\nbegin\n if current_setting('transaction_isolation')<>'read committed'then\n  raise exception 'supervisor_snapshot_retry'using errcode='40001';end if;\n perform pg_advisory_xact_lock(hashtextextended('collect-dedicated-key:'||new.key_sha256,0));\n if (tg_table_schema='collect_gateway'and exists(\n  select 1 from collect_supervisor.identities where key_sha256=new.key_sha256))\n  or(tg_table_schema='collect_supervisor'and exists(\n  select 1 from collect_gateway.devices where key_sha256=new.key_sha256))then\n  raise exception 'supervisor_key_scope_conflict'using errcode='22023';end if;\n return new;\nend$$;\ncreate trigger distinct_supervisor_signing_key before insert on collect_supervisor.identities\n for each row execute function collect_supervisor.distinct_identity_key();\ncreate trigger distinct_gateway_signing_key before insert on collect_gateway.devices\n for each row execute function collect_supervisor.distinct_identity_key();\n\ncreate function collect_supervisor.owner_actor()returns uuid\nlanguage plpgsql volatile security definer set search_path=''as $$\ndeclare sid uuid;begin\n if current_setting('transaction_isolation')<>'read committed'then\n  raise exception 'supervisor_snapshot_retry'using errcode='40001';end if;\n sid:=public._lock_notification_registration_session();\n perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,'platform_owner',\n  array['admin_users.manage','notifications.manage','system_health.read']);\n if not collect_admin_access.email_identity(auth.uid())then\n  raise exception 'supervisor_current_email_owner_required'using errcode='42501';end if;\n return sid;\nend$$;\ncreate function collect_supervisor.validate_key(p_spki text,p_hash text)returns void\nlanguage plpgsql set search_path=''as $$\ndeclare der bytea;x numeric:=0;y numeric:=0;i integer;\n prime numeric:=115792089210356248762697446949407573530086143415290314195533631308867097853951;\n curve_b numeric:=41058363725152142129326129780047268409114441015993725554835256314039467401291;\nbegin\n if p_spki is null or p_spki !~ '^[A-Za-z0-9+/]{122}==$'\n  or p_hash is null or p_hash !~ '^[0-9a-f]{64}$'then\n  raise exception 'supervisor_key_invalid'using errcode='22023';end if;\n der:=decode(p_spki,'base64');\n if octet_length(der)<>91 or encode(substring(der from 1 for 27),'hex')<>\n  '3059301306072a8648ce3d020106082a8648ce3d03010703420004'\n  or replace(encode(der,'base64'),E'\\\\n','')<>p_spki\n  or encode(extensions.digest(der,'sha256'),'hex')<>p_hash then\n  raise exception 'supervisor_key_invalid'using errcode='22023';end if;\n for i in 27..58 loop x:=x*256+get_byte(der,i);end loop;\n for i in 59..90 loop y:=y*256+get_byte(der,i);end loop;\n if x>=prime or y>=prime or mod(y*y-x*x*x+3*x-curve_b,prime)<>0 then\n  raise exception 'supervisor_key_invalid'using errcode='22023';end if;\nend$$;\ncreate function collect_supervisor.owner_replay(p_request uuid,p_actor uuid,p_action text,p_input jsonb)\nreturns jsonb language plpgsql set search_path=''as $$\ndeclare prior collect_supervisor.owner_requests;begin\n select * into prior from collect_supervisor.owner_requests where request_id=p_request;\n if prior.request_id is null then return null;end if;\n if prior.actor_id<>p_actor or prior.action<>p_action or prior.input is distinct from p_input then\n  raise exception 'supervisor_owner_request_conflict'using errcode='22023';end if;\n return prior.result;\nend$$;\ncreate function public.admin_enroll_receipt_supervisor_v1(p_request_id uuid,p_public_key_spki_base64 text,\n p_key_sha256 text,p_expires_at timestamptz)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''as $$\ndeclare sid uuid;prior jsonb;input jsonb;result jsonb;principal uuid;t timestamptz;begin\n sid:=collect_supervisor.owner_actor();\n if p_request_id is null or p_expires_at is null or not isfinite(p_expires_at)then\n  raise exception 'supervisor_enrollment_invalid'using errcode='22023';end if;\n perform collect_supervisor.validate_key(p_public_key_spki_base64,p_key_sha256);\n input:=jsonb_build_array(p_public_key_spki_base64,p_key_sha256,p_expires_at);\n perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request_id::text,0));\n prior:=collect_supervisor.owner_replay(p_request_id,auth.uid(),'enroll',input);\n if prior is not null then return prior;end if;\n t:=clock_timestamp();\n if p_expires_at<t+interval '10 minutes'or p_expires_at>t+interval '30 days'\n  or exists(select 1 from collect_gateway.devices where key_sha256=p_key_sha256)then\n  raise exception 'supervisor_enrollment_invalid'using errcode='22023';end if;\n insert into collect_supervisor.identities(enrollment_request_id,owner_actor_id,owner_session_id,\n  public_key_spki_base64,key_sha256,created_at,expires_at)\n values(p_request_id,auth.uid(),sid,p_public_key_spki_base64,p_key_sha256,t,p_expires_at)returning identities.id into principal;\n result:=jsonb_build_object('contract_version',1,'principal_id',principal,'request_id',p_request_id,\n  'state_at_action','pending','scope','rw_receipt_shadow','key_sha256',p_key_sha256,\n  'expires_at',collect_gateway.utc(p_expires_at),'recorded_at',collect_gateway.utc(t));\n insert into collect_supervisor.owner_requests values(p_request_id,auth.uid(),sid,'enroll',input,result,t);\n perform public.create_audit_log('supervisor.identity.enroll','receipt_supervisor',principal,\n  jsonb_build_object('request_id',p_request_id,'scope','rw_receipt_shadow','expires_at',p_expires_at),null);\n return result;\nend$$;\ncreate function collect_supervisor.change_identity(p_principal uuid,p_request uuid,p_expected_key text,p_action text)\nreturns jsonb language plpgsql volatile security definer set search_path=''as $$\ndeclare sid uuid;item collect_supervisor.identities;prior jsonb;input jsonb;result jsonb;t timestamptz;begin\n sid:=collect_supervisor.owner_actor();\n if p_principal is null or p_request is null or p_expected_key is null\n  or p_expected_key !~ '^[0-9a-f]{64}$'or p_action not in('activate','revoke')then\n  raise exception 'supervisor_action_invalid'using errcode='22023';end if;\n input:=jsonb_build_array(p_principal,p_expected_key);\n perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-owner:'||p_request::text,0));\n prior:=collect_supervisor.owner_replay(p_request,auth.uid(),p_action,input);\n if prior is not null then return prior;end if;\n select * into item from collect_supervisor.identities where id=p_principal for update;\n if item.id is null or item.key_sha256<>p_expected_key then\n  raise exception 'supervisor_identity_unavailable'using errcode='42501';end if;\n t:=clock_timestamp();\n if p_action='activate'then\n  if item.state<>'pending'or item.expires_at<=t then\n   raise exception 'supervisor_activation_unavailable'using errcode='55000';end if;\n  if not exists(select 1 from collect_supervisor.requests where principal_id=item.id and action='prove_key'\n   and recorded_at>=t-interval '120 seconds'and issued_at>=t-interval '120 seconds'\n   and issued_at<=t+interval '30 seconds')then\n   raise exception 'supervisor_key_possession_required'using errcode='55000';end if;\n  update collect_supervisor.identities set state='active',activated_at=t where id=item.id;\n else\n  if item.state='revoked'then raise exception 'supervisor_already_revoked'using errcode='55000';end if;\n  update collect_supervisor.identities set state='revoked',revoked_at=t where id=item.id;\n end if;\n result:=jsonb_build_object('contract_version',1,'principal_id',item.id,'request_id',p_request,\n  'state_at_action',case p_action when 'activate'then 'active'else 'revoked'end,\n  'scope',item.scope,'key_sha256',item.key_sha256,'expires_at',collect_gateway.utc(item.expires_at),\n  'recorded_at',collect_gateway.utc(t));\n insert into collect_supervisor.owner_requests values(p_request,auth.uid(),sid,p_action,input,result,t);\n perform public.create_audit_log('supervisor.identity.'||p_action,'receipt_supervisor',item.id,\n  jsonb_build_object('request_id',p_request,'scope',item.scope),null);\n return result;\nend$$;\ncreate function public.admin_activate_receipt_supervisor_v1(p_principal_id uuid,p_request_id uuid,p_expected_key_sha256 text)\nreturns jsonb language sql volatile security definer set search_path=''as $$\n select collect_supervisor.change_identity(p_principal_id,p_request_id,p_expected_key_sha256,'activate')$$;\ncreate function public.admin_revoke_receipt_supervisor_v1(p_principal_id uuid,p_request_id uuid,p_expected_key_sha256 text)\nreturns jsonb language sql volatile security definer set search_path=''as $$\n select collect_supervisor.change_identity(p_principal_id,p_request_id,p_expected_key_sha256,'revoke')$$;\ncreate function public.admin_get_receipt_supervisor_owner_request_v1(p_request_id uuid)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''set lock_timeout='100ms'as $$\ndeclare prior collect_supervisor.owner_requests;begin\n perform collect_supervisor.owner_actor();\n if p_request_id is null then raise exception 'supervisor_action_invalid'using errcode='22023';end if;\n select * into prior from collect_supervisor.owner_requests where request_id=p_request_id and actor_id=auth.uid();\n return jsonb_build_object('contract_version',1,'request_id',p_request_id,\n  'status',case when prior.request_id is null then 'not_recorded'else 'recorded'end,'receipt',prior.result);\nexception when lock_not_available then raise exception 'supervisor_authority_busy'using errcode='55P03';\nend$$;\n\ncreate function collect_supervisor.require_service_identity(p_principal uuid,p_key text,p_request uuid,\n p_request_sha text,p_issued timestamptz,p_action text)returns collect_supervisor.identities\nlanguage plpgsql set search_path=''as $$\ndeclare item collect_supervisor.identities;t timestamptz;begin\n if auth.role()is distinct from 'service_role'then raise exception 'supervisor_service_required'using errcode='42501';end if;\n if current_setting('transaction_isolation')<>'read committed'then\n  raise exception 'supervisor_snapshot_retry'using errcode='40001';end if;\n if p_principal is null or p_request is null or p_key is null or p_key !~ '^[0-9a-f]{64}$'\n  or p_request_sha is null or p_request_sha !~ '^[0-9a-f]{64}$'or p_issued is null or not isfinite(p_issued)\n  or p_action is null or p_action not in('prove_key','shadow_health','reconcile')then\n  raise exception 'supervisor_request_invalid'using errcode='22023';end if;\n select * into item from collect_supervisor.identities where id=p_principal for share;\n t:=clock_timestamp();\n if item.id is null or item.state='revoked'or item.key_sha256<>p_key or item.expires_at<=t\n  or(p_action<>'prove_key'and item.state<>'active')then\n  raise exception 'supervisor_credential_unavailable'using errcode='42501';end if;\n if p_issued<t-interval '30 seconds'or p_issued>t+interval '10 seconds'then\n  raise exception 'supervisor_request_expired'using errcode='42501';end if;\n return item;\nend$$;\ncreate function public.receipt_supervisor_key_v1(p_principal_id uuid)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''as $$\ndeclare item collect_supervisor.identities;begin\n if auth.role()is distinct from 'service_role'then raise exception 'supervisor_service_required'using errcode='42501';end if;\n if current_setting('transaction_isolation')<>'read committed'then\n  raise exception 'supervisor_snapshot_retry'using errcode='40001';end if;\n select * into item from collect_supervisor.identities where id=p_principal_id for share;\n if item.id is null or item.state='revoked'or item.expires_at<=clock_timestamp()then\n  raise exception 'supervisor_credential_unavailable'using errcode='42501';end if;\n return jsonb_build_object('contract_version',1,'principal_id',item.id,'state',item.state,'scope',item.scope,\n  'public_key_spki_base64',item.public_key_spki_base64,'key_sha256',item.key_sha256,\n  'expires_at',collect_gateway.utc(item.expires_at));\nend$$;\ncreate function public.receipt_supervisor_observe_v1(p_principal_id uuid,p_request_id uuid,p_key_sha256 text,\n p_request_sha256 text,p_issued_at timestamptz,p_action text)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''as $$\ndeclare item collect_supervisor.identities;prior collect_supervisor.requests;result jsonb;t timestamptz;\n queue bigint;unknowns bigint;failures bigint;begin\n item:=collect_supervisor.require_service_identity(p_principal_id,p_key_sha256,p_request_id,p_request_sha256,p_issued_at,p_action);\n if p_action not in('prove_key','shadow_health')then raise exception 'supervisor_request_invalid'using errcode='22023';end if;\n perform pg_advisory_xact_lock(hashtextextended('collect-supervisor-request:'||p_request_id::text,0));\n -- Authority and the signed-request window are checked again after a lock wait.\n item:=collect_supervisor.require_service_identity(p_principal_id,p_key_sha256,p_request_id,p_request_sha256,p_issued_at,p_action);\n select * into prior from collect_supervisor.requests where request_id=p_request_id;\n if prior.request_id is not null then\n  if prior.principal_id<>p_principal_id or prior.key_sha256<>p_key_sha256 or prior.action<>p_action\n   or prior.request_sha256<>p_request_sha256 or prior.issued_at<>p_issued_at then\n   raise exception 'supervisor_request_conflict'using errcode='22023';end if;\n  return prior.result;\n end if;\n t:=clock_timestamp();\n if p_action='prove_key'then\n  result:=jsonb_build_object('contract_version',1,'principal_id',item.id,'request_id',p_request_id,\n   'action',p_action,'observed_at',collect_gateway.utc(t),'expires_at',collect_gateway.utc(item.expires_at),\n   'scope',item.scope,'mode','Shadow','business_handled',false,'financial_action',false,'send_action',false);\n else\n  select count(*)filter(where o.state in('queued','awaiting_confirmation')),\n   count(*)filter(where o.state in('uncertain','send_started')),\n   count(*)filter(where o.state='failed_no_send')into queue,unknowns,failures\n   from collect_hybrid.sms_notification_outbox o where collect_ops.payment_scope(o.payment_id);\n  if greatest(queue,unknowns,failures)>1000000000 then\n   raise exception 'supervisor_snapshot_unavailable'using errcode='55000';end if;\n  result:=jsonb_build_object('contract_version',1,'principal_id',item.id,'request_id',p_request_id,\n   'action',p_action,'observed_at',collect_gateway.utc(t),'sample_valid_until',collect_gateway.utc(least(t+interval '60 seconds',item.expires_at)),\n   'expires_at',collect_gateway.utc(item.expires_at),'scope',item.scope,'mode','Shadow',\n   'queued_count',queue,'unknown_count',unknowns,'failed_no_send_count',failures,\n   'dispatch_enabled',coalesce((select enabled from public.feature_flags where key='hybrid_sms_notifications'),false),\n   'business_handled',false,'financial_action',false,'send_action',false);\n end if;\n insert into collect_supervisor.requests values(p_request_id,item.id,p_action,p_key_sha256,p_request_sha256,p_issued_at,t,result);\n return result;\nend$$;\ncreate function public.receipt_supervisor_reconcile_v1(p_principal_id uuid,p_request_id uuid,p_key_sha256 text,\n p_request_sha256 text,p_issued_at timestamptz,p_target_request_id uuid)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''set lock_timeout='100ms'as $$\ndeclare item collect_supervisor.identities;prior collect_supervisor.requests;begin\n item:=collect_supervisor.require_service_identity(p_principal_id,p_key_sha256,p_request_id,p_request_sha256,p_issued_at,'reconcile');\n if p_target_request_id is null then raise exception 'supervisor_request_invalid'using errcode='22023';end if;\n if not pg_try_advisory_xact_lock(hashtextextended('collect-supervisor-request:'||p_target_request_id::text,0))then\n  return jsonb_build_object('contract_version',1,'target_request_id',p_target_request_id,'status','in_progress','receipt',null);end if;\n select * into prior from collect_supervisor.requests where request_id=p_target_request_id and principal_id=item.id;\n return jsonb_build_object('contract_version',1,'target_request_id',p_target_request_id,\n  'status',case when prior.request_id is null then 'not_recorded'else 'recorded'end,'receipt',prior.result);\nexception when lock_not_available then raise exception 'supervisor_authority_busy'using errcode='55P03';\nend$$;\nrevoke all on all functions in schema collect_supervisor from public,anon,authenticated,service_role;\nrevoke all on function public.admin_enroll_receipt_supervisor_v1(uuid,text,text,timestamptz),\n public.admin_activate_receipt_supervisor_v1(uuid,uuid,text),public.admin_revoke_receipt_supervisor_v1(uuid,uuid,text),\n public.admin_get_receipt_supervisor_owner_request_v1(uuid),public.receipt_supervisor_key_v1(uuid),\n public.receipt_supervisor_observe_v1(uuid,uuid,text,text,timestamptz,text),\n public.receipt_supervisor_reconcile_v1(uuid,uuid,text,text,timestamptz,uuid)\n from public,anon,authenticated,service_role;\ngrant execute on function public.admin_enroll_receipt_supervisor_v1(uuid,text,text,timestamptz),\n public.admin_activate_receipt_supervisor_v1(uuid,uuid,text),public.admin_revoke_receipt_supervisor_v1(uuid,uuid,text),\n public.admin_get_receipt_supervisor_owner_request_v1(uuid)to authenticated;\ngrant execute on function public.receipt_supervisor_key_v1(uuid),\n public.receipt_supervisor_observe_v1(uuid,uuid,text,text,timestamptz,text),\n public.receipt_supervisor_reconcile_v1(uuid,uuid,text,text,timestamptz,uuid)to service_role;\ncommit;\n"}
20260612113000	revoke_anon_admin_queue_paging	{"revoke execute on function admin_list_payment_events(text, text, integer, integer, text)\nfrom public, anon;\n\nrevoke execute on function admin_list_allocations(text, text, integer, integer, text)\nfrom public, anon;\n\nrevoke execute on function admin_list_unallocated(text, text, integer, integer, text)\nfrom public, anon;\n\ngrant execute on function admin_list_payment_events(text, text, integer, integer, text)\nto authenticated;\n\ngrant execute on function admin_list_allocations(text, text, integer, integer, text)\nto authenticated;\n\ngrant execute on function admin_list_unallocated(text, text, integer, integer, text)\nto authenticated;\n"}
20260619003000	profile_momo_pay_code	{"alter table public.profiles\n  add column if not exists momo_pay_code text;\n\nalter table public.profiles\n  add constraint profiles_momo_pay_code_format\n  check (momo_pay_code is null or momo_pay_code ~ '^[0-9]{5,6}$')\n  not valid;\n\nalter table public.profiles\n  validate constraint profiles_momo_pay_code_format;\n\ngrant update (momo_pay_code, updated_at) on public.profiles to authenticated;\n"}
20260622090000	market_expansion_categories_stripe_foundation	{"-- Market-expansion foundation: approved collection categories plus\n-- Stripe-safe diaspora contribution records. This is intentionally additive\n-- and keeps Rwanda MoMo/SMS allocation as the default in-country rail.\n\nalter table collections\n  add column if not exists collection_type text not null default 'ikimina'\n    check (collection_type in ('ikimina', 'sport', 'church', 'wedding', 'other')),\n  add column if not exists category_subtype text,\n  add column if not exists purpose_label text,\n  add column if not exists suggested_amount_rwf bigint\n    check (suggested_amount_rwf is null or suggested_amount_rwf > 0),\n  add column if not exists diaspora_enabled boolean not null default false,\n  add column if not exists diaspora_regions text[] not null default '{}'::text[],\n  add column if not exists moderation_status text not null default 'not_requested'\n    check (moderation_status in (\n      'not_requested',\n      'pending',\n      'approved',\n      'rejected',\n      'restricted'\n    ));\n\nupdate collections\nset collection_type = case\n  when lower(category) = 'church' then 'church'\n  when lower(category) in ('sports team', 'public figure / fan support') then 'sport'\n  when lower(category) = 'wedding' then 'wedding'\n  when lower(category) in ('family / friends', 'community event') then 'ikimina'\n  else collection_type\nend\nwhere category is not null\n  and collection_type = 'ikimina';\n\ncreate index if not exists collections_market_type_idx\n  on collections (collection_type, created_at desc);\n\ncreate index if not exists collections_diaspora_enabled_idx\n  on collections (diaspora_enabled, collection_type, created_at desc)\n  where diaspora_enabled;\n\ngrant select (\n  collection_type,\n  category_subtype,\n  purpose_label,\n  suggested_amount_rwf,\n  diaspora_enabled,\n  diaspora_regions,\n  moderation_status\n) on collections to authenticated;\n\ndrop function if exists create_group_with_owner(text, text, text, text, text);\n\ncreate or replace function create_group_with_owner(\n  group_name text,\n  group_description text default '',\n  receiver_momo_number text default null,\n  receiver_momo_number_hash text default null,\n  receiver_label text default 'Primary MOMO receiver',\n  group_collection_type text default 'ikimina',\n  group_category_subtype text default null,\n  group_purpose_label text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  created_group_id uuid;\n  base_slug text;\n  final_slug text;\n  clean_type text := coalesce(nullif(trim(group_collection_type), ''), 'ikimina');\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  if clean_type not in ('ikimina', 'sport', 'church', 'wedding', 'other') then\n    raise exception 'Unsupported collection type';\n  end if;\n\n  base_slug := normalize_slug(group_name);\n  if base_slug = '' then\n    base_slug := 'group';\n  end if;\n  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);\n\n  insert into collections (\n    slug,\n    creator_user_id,\n    title,\n    description,\n    collection_type,\n    category_subtype,\n    purpose_label,\n    receiver_display_label\n  )\n  values (\n    final_slug,\n    auth.uid(),\n    trim(group_name),\n    coalesce(group_description, ''),\n    clean_type,\n    nullif(trim(group_category_subtype), ''),\n    nullif(trim(group_purpose_label), ''),\n    receiver_label\n  )\n  returning id into created_group_id;\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values (created_group_id, auth.uid(), 'owner', 'active');\n\n  if receiver_momo_number is not null and receiver_momo_number_hash is not null then\n    insert into collection_receivers (\n      collection_id,\n      receiver_user_id,\n      momo_number,\n      momo_number_hash,\n      label\n    )\n    values (\n      created_group_id,\n      auth.uid(),\n      receiver_momo_number,\n      receiver_momo_number_hash,\n      receiver_label\n    );\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'group.created',\n    'collection',\n    created_group_id,\n    jsonb_build_object('collection_type', clean_type)\n  );\n\n  return created_group_id;\nend;\n$$;\n\nrevoke execute on function create_group_with_owner(\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text\n) from public, anon, authenticated;\ngrant execute on function create_group_with_owner(\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text\n) to authenticated;\n\ndrop function if exists update_collection_profile(uuid, text, text, text, text, boolean, text);\n\ncreate or replace function update_collection_profile(\n  collection uuid,\n  group_name text,\n  group_description text,\n  group_image_url text default null,\n  group_accent_color_hex text default null,\n  group_is_public boolean default false,\n  group_recurring_cadence text default 'monthly',\n  group_collection_type text default null,\n  group_category_subtype text default null,\n  group_purpose_label text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  clean_cadence text := coalesce(\n    nullif(trim(group_recurring_cadence), ''),\n    'monthly'\n  );\n  clean_type text := nullif(trim(group_collection_type), '');\n  next_public_status collection_visibility := case\n    when coalesce(group_is_public, false) then 'public_requested'::collection_visibility\n    else 'private'::collection_visibility\n  end;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if not user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can update the group profile';\n  end if;\n  if nullif(trim(group_name), '') is null then\n    raise exception 'Group name is required';\n  end if;\n  if clean_cadence not in ('daily', 'weekly', 'monthly') then\n    raise exception 'Unsupported recurring cadence';\n  end if;\n  if clean_type is not null and clean_type not in ('ikimina', 'sport', 'church', 'wedding', 'other') then\n    raise exception 'Unsupported collection type';\n  end if;\n\n  update collections\n  set\n    title = trim(group_name),\n    description = trim(coalesce(group_description, '')),\n    cover_image_url = nullif(trim(group_image_url), ''),\n    accent_color_hex = nullif(trim(group_accent_color_hex), ''),\n    public_status = next_public_status,\n    visibility = next_public_status,\n    is_recurring = true,\n    recurring_cadence = clean_cadence,\n    recurring_rule = jsonb_build_object('cadence', clean_cadence),\n    collection_type = coalesce(clean_type, collection_type),\n    category_subtype = nullif(trim(group_category_subtype), ''),\n    purpose_label = nullif(trim(group_purpose_label), ''),\n    updated_at = now()\n  where id = collection;\n\n  if not found then\n    raise exception 'Group not found';\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.profile_updated',\n    'collection',\n    collection,\n    jsonb_build_object(\n      'is_public', coalesce(group_is_public, false),\n      'public_status', next_public_status::text,\n      'recurring_cadence', clean_cadence,\n      'collection_type', clean_type\n    )\n  );\nend;\n$$;\n\nrevoke execute on function update_collection_profile(\n  uuid,\n  text,\n  text,\n  text,\n  text,\n  boolean,\n  text,\n  text,\n  text,\n  text\n) from public, anon, authenticated;\ngrant execute on function update_collection_profile(\n  uuid,\n  text,\n  text,\n  text,\n  text,\n  boolean,\n  text,\n  text,\n  text,\n  text\n) to authenticated;\n\ndrop view if exists member_collections_view;\n\ncreate view member_collections_view\nwith (security_invoker = true)\nas\nselect\n  c.id,\n  c.slug,\n  c.creator_user_id,\n  c.title,\n  c.description,\n  c.currency,\n  c.collection_type,\n  c.category_subtype,\n  c.purpose_label,\n  c.suggested_amount_rwf,\n  c.diaspora_enabled,\n  c.diaspora_regions,\n  c.moderation_status,\n  case\n    when public.user_is_collection_admin(c.id, auth.uid())\n      or exists (\n        select 1\n        from collection_receivers receiver_check\n        where receiver_check.collection_id = c.id\n          and receiver_check.receiver_user_id = auth.uid()\n          and receiver_check.is_active\n      )\n      then cr.momo_number\n    else null\n  end as receiver_momo_number,\n  case\n    when public.user_can_read_collection(c.id, auth.uid()) then cr.label\n    else null\n  end as receiver_display_label,\n  cr.network as receiver_network,\n  c.created_at,\n  c.updated_at,\n  c.archived_at,\n  c.accent_color_hex,\n  c.recurring_cadence\nfrom collections c\nleft join lateral (\n  select\n    collection_receivers.momo_number,\n    collection_receivers.label,\n    collection_receivers.network\n  from collection_receivers\n  where collection_receivers.collection_id = c.id\n    and collection_receivers.is_active\n  order by collection_receivers.created_at asc\n  limit 1\n) cr on true\nwhere public.user_can_read_collection(c.id, auth.uid());\n\nalter view public.member_collections_view set (security_invoker = true);\ngrant select on member_collections_view to authenticated;\n\ncreate table if not exists stripe_customers (\n  user_id uuid primary key references profiles(id) on delete cascade,\n  stripe_customer_id text unique not null,\n  livemode boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists stripe_payment_methods (\n  id uuid primary key default gen_random_uuid(),\n  user_id uuid not null references profiles(id) on delete cascade,\n  stripe_customer_id text not null,\n  stripe_payment_method_id text unique not null,\n  method_type text not null check (method_type in (\n    'us_bank_account',\n    'acss_debit'\n  )),\n  region text not null check (region in ('us', 'ca')),\n  currency text not null check (currency in ('USD', 'CAD')),\n  constraint stripe_payment_methods_domestic_currency_check check (\n    (region = 'us' and currency = 'USD' and method_type = 'us_bank_account')\n    or (region = 'ca' and currency = 'CAD' and method_type = 'acss_debit')\n  ),\n  display_bank_name text,\n  display_last4 text,\n  mandate_reference text,\n  status text not null default 'pending_setup' check (status in (\n    'pending_setup',\n    'active',\n    'inactive',\n    'revoked',\n    'failed'\n  )),\n  livemode boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists diaspora_contribution_intents (\n  id uuid primary key default gen_random_uuid(),\n  collection_id uuid not null references collections(id) on delete restrict,\n  contributor_user_id uuid not null references profiles(id) on delete restrict,\n  stripe_customer_id text not null,\n  stripe_payment_method_id text,\n  stripe_checkout_session_id text unique,\n  stripe_payment_intent_id text unique,\n  amount_minor bigint not null check (amount_minor > 0),\n  currency text not null check (currency in ('EUR', 'GBP', 'USD', 'CAD')),\n  region text not null check (region in ('eu', 'gb', 'us', 'ca')),\n  method_type text not null check (method_type in (\n    'us_bank_account',\n    'acss_debit',\n    'customer_balance_eur_bank_transfer',\n    'customer_balance_gbp_bank_transfer'\n  )),\n  constraint diaspora_contribution_intents_domestic_currency_check check (\n    (region = 'eu' and currency = 'EUR' and method_type = 'customer_balance_eur_bank_transfer')\n    or (region = 'gb' and currency = 'GBP' and method_type = 'customer_balance_gbp_bank_transfer')\n    or (region = 'us' and currency = 'USD' and method_type = 'us_bank_account')\n    or (region = 'ca' and currency = 'CAD' and method_type = 'acss_debit')\n  ),\n  collection_type_snapshot text not null check (collection_type_snapshot in (\n    'ikimina',\n    'sport',\n    'church',\n    'wedding',\n    'other'\n  )),\n  status text not null default 'pending' check (status in (\n    'pending',\n    'requires_action',\n    'processing',\n    'succeeded',\n    'failed',\n    'returned',\n    'disputed',\n    'cancelled',\n    'needs_review'\n  )),\n  failure_code text,\n  failure_message text,\n  livemode boolean not null default false,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now()\n);\n\ncreate table if not exists stripe_webhook_events (\n  event_id text primary key,\n  event_type text not null,\n  livemode boolean not null default false,\n  related_contribution_intent_id uuid references diaspora_contribution_intents(id) on delete set null,\n  processed_at timestamptz,\n  processing_status text not null default 'received' check (processing_status in (\n    'received',\n    'processed',\n    'ignored',\n    'failed',\n    'needs_review'\n  )),\n  review_reason text,\n  payload jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now()\n);\n\ncreate index if not exists stripe_payment_methods_user_idx\n  on stripe_payment_methods (user_id, region, status);\n\ncreate index if not exists diaspora_contribution_intents_collection_idx\n  on diaspora_contribution_intents (collection_id, status, created_at desc);\n\ncreate index if not exists diaspora_contribution_intents_contributor_idx\n  on diaspora_contribution_intents (contributor_user_id, status, created_at desc);\n\nalter table stripe_customers enable row level security;\nalter table stripe_payment_methods enable row level security;\nalter table diaspora_contribution_intents enable row level security;\nalter table stripe_webhook_events enable row level security;\n\ndrop policy if exists stripe_customers_owner_select on stripe_customers;\ncreate policy stripe_customers_owner_select\n  on stripe_customers for select\n  using (user_id = (select auth.uid()));\n\ndrop policy if exists stripe_payment_methods_owner_select on stripe_payment_methods;\ncreate policy stripe_payment_methods_owner_select\n  on stripe_payment_methods for select\n  using (user_id = (select auth.uid()));\n\ndrop policy if exists diaspora_contribution_intents_participant_select\n  on diaspora_contribution_intents;\ncreate policy diaspora_contribution_intents_participant_select\n  on diaspora_contribution_intents for select\n  using (\n    contributor_user_id = (select auth.uid())\n    or public.user_is_collection_admin(collection_id, (select auth.uid()))\n    or public.current_user_is_platform_admin()\n  );\n\ndrop policy if exists stripe_webhook_events_admin_select on stripe_webhook_events;\ncreate policy stripe_webhook_events_admin_select\n  on stripe_webhook_events for select\n  using (public.current_user_is_platform_admin());\n\ngrant select on stripe_customers to authenticated;\ngrant select on stripe_payment_methods to authenticated;\ngrant select on diaspora_contribution_intents to authenticated;\ngrant select on stripe_webhook_events to authenticated;\ngrant all on stripe_customers to service_role;\ngrant all on stripe_payment_methods to service_role;\ngrant all on diaspora_contribution_intents to service_role;\ngrant all on stripe_webhook_events to service_role;\n"}
20260626193000	gate_notification_enqueue_by_preferences	{"create or replace function enqueue_notification_event(\n  p_user_id uuid,\n  p_type text,\n  p_title text,\n  p_body text,\n  p_collection_id uuid default null,\n  p_deep_link text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  inserted_id uuid;\n  preference_enabled boolean;\nbegin\n  if p_type = 'contribution_confirmed' then\n    select coalesce(contribution_confirmations, true)\n    into preference_enabled\n    from notification_preferences\n    where user_id = p_user_id;\n  elsif p_type = 'payment_reminder' then\n    select coalesce(payment_reminders, true)\n    into preference_enabled\n    from notification_preferences\n    where user_id = p_user_id;\n  elsif p_type = 'group_update' then\n    select coalesce(group_updates, true)\n    into preference_enabled\n    from notification_preferences\n    where user_id = p_user_id;\n  elsif p_type = 'security_notice' then\n    select coalesce(security_notices, true)\n    into preference_enabled\n    from notification_preferences\n    where user_id = p_user_id;\n  else\n    raise exception 'invalid_notification_type';\n  end if;\n\n  if coalesce(preference_enabled, true) = false then\n    return null;\n  end if;\n\n  insert into notification_events (\n    user_id,\n    collection_id,\n    type,\n    title,\n    body,\n    deep_link\n  )\n  values (\n    p_user_id,\n    p_collection_id,\n    p_type,\n    p_title,\n    p_body,\n    p_deep_link\n  )\n  returning id into inserted_id;\n\n  return inserted_id;\nend;\n$$;\n\nrevoke execute on function enqueue_notification_event(uuid, text, text, text, uuid, text)\nfrom anon, authenticated;\ngrant execute on function enqueue_notification_event(uuid, text, text, text, uuid, text)\nto service_role;\n"}
20260627143000	restrict_admin_permission_helper_probing	{"begin;\n\ncreate or replace function is_platform_admin(user_uuid uuid default auth.uid())\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case\n    when auth.role() = 'service_role' or user_uuid = auth.uid() then\n      coalesce((select p.is_platform_admin from profiles p where p.id = user_uuid), false)\n      or exists (\n        select 1\n        from admin_user_roles aur\n        join admin_roles ar on ar.id = aur.role_id\n        where aur.user_id = user_uuid\n          and aur.revoked_at is null\n          and ar.name = 'platform_owner'\n      )\n    else false\n  end;\n$$;\n\ncreate or replace function has_admin_permission(permission text, user_uuid uuid default auth.uid())\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select case\n    when auth.role() = 'service_role' or user_uuid = auth.uid() then\n      public.is_platform_admin(user_uuid)\n      or exists (\n        select 1\n        from admin_user_roles aur\n        join admin_role_permissions arp on arp.role_id = aur.role_id\n        where aur.user_id = user_uuid\n          and aur.revoked_at is null\n          and arp.permission_name = permission\n      )\n    else false\n  end;\n$$;\n\ncreate or replace function current_user_has_admin_permission(permission text)\nreturns boolean\nlanguage sql\nstable\nsecurity definer\nset search_path = public\nas $$\n  select public.has_admin_permission(permission, auth.uid());\n$$;\n\nrevoke execute on function is_platform_admin(uuid) from public, anon;\nrevoke execute on function has_admin_permission(text, uuid) from public, anon;\nrevoke execute on function current_user_has_admin_permission(text) from public, anon;\ngrant execute on function is_platform_admin(uuid) to authenticated, service_role;\ngrant execute on function has_admin_permission(text, uuid) to authenticated, service_role;\ngrant execute on function current_user_has_admin_permission(text) to authenticated, service_role;\n\ncomment on function is_platform_admin(uuid) is\n  'Authenticated callers may evaluate only auth.uid(); service_role may evaluate arbitrary users for operator administration.';\ncomment on function has_admin_permission(text, uuid) is\n  'Authenticated callers may evaluate only auth.uid(); service_role may evaluate arbitrary users for operator administration.';\ncomment on function current_user_has_admin_permission(text) is\n  'Browser-safe current-user admin permission helper.';\n\ncommit;\n"}
20260627171000	harden_diaspora_stripe_table_grants	{"begin;\n\nrevoke select on stripe_customers from anon, authenticated;\nrevoke select on stripe_payment_methods from anon, authenticated;\nrevoke select on diaspora_contribution_intents from anon, authenticated;\nrevoke select on stripe_webhook_events from anon, authenticated;\n\ngrant all on stripe_customers to service_role;\ngrant all on stripe_payment_methods to service_role;\ngrant all on diaspora_contribution_intents to service_role;\ngrant all on stripe_webhook_events to service_role;\n\ncomment on table stripe_customers is\n  'Stripe customer mapping is service-role only; browser clients must use scoped RPCs or Edge Functions.';\ncomment on table stripe_payment_methods is\n  'Stripe payment method metadata is service-role only; browser clients must use scoped RPCs or Edge Functions.';\ncomment on table diaspora_contribution_intents is\n  'Diaspora contribution intents are service-role only for direct table reads; browser clients must use scoped RPCs or Edge Functions.';\ncomment on table stripe_webhook_events is\n  'Stripe webhook payloads are service-role only.';\n\ncommit;\n"}
20260627183000	add_admin_operator_note_rpc	{"begin;\n\ncreate or replace function admin_record_operator_note(\n  p_entity_type text,\n  p_entity_id uuid,\n  p_body text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  note_id uuid;\n  normalized_entity_type text := trim(coalesce(p_entity_type, ''));\n  normalized_body text := trim(coalesce(p_body, ''));\nbegin\n  if normalized_body = '' then\n    raise exception 'Note body is required';\n  end if;\n\n  case normalized_entity_type\n    when 'collection' then perform assert_admin_permission('collections.read');\n    when 'profile' then perform assert_admin_permission('users.read');\n    when 'payment_intent' then perform assert_admin_permission('payments.read');\n    when 'parsed_payment_event' then perform assert_admin_permission('payment_events.read');\n    when 'payment_receiver' then perform assert_admin_permission('collections.read');\n    when 'raw_payment_sms' then perform assert_admin_permission('sms.metadata.read');\n    else raise exception 'Unsupported admin note entity type: %', normalized_entity_type;\n  end case;\n\n  insert into admin_notes (entity_type, entity_id, body, created_by)\n  values (normalized_entity_type, p_entity_id, normalized_body, auth.uid())\n  returning id into note_id;\n\n  perform create_audit_log(\n    'admin.operator_note.recorded',\n    normalized_entity_type,\n    p_entity_id,\n    jsonb_build_object('note_id', note_id)\n  );\n\n  return jsonb_build_object('ok', true, 'note_id', note_id);\nend;\n$$;\n\nrevoke execute on function admin_record_operator_note(text, uuid, text)\n  from public, anon;\ngrant execute on function admin_record_operator_note(text, uuid, text)\n  to authenticated;\n\ncommit;\n"}
20260627184500	add_admin_queue_sla_policies	{"begin;\n\ncreate table if not exists admin_queue_sla_policies (\n  queue_key text primary key,\n  target text not null,\n  owner text not null,\n  escalation text not null,\n  updated_by uuid references profiles(id) on delete set null,\n  updated_at timestamptz not null default now()\n);\n\nalter table admin_queue_sla_policies enable row level security;\n\nrevoke all on admin_queue_sla_policies from anon, authenticated;\ngrant all on admin_queue_sla_policies to service_role;\n\ninsert into admin_queue_sla_policies (queue_key, target, owner, escalation)\nvalues\n  (\n    'admin_list_payment_events',\n    'Review ambiguous SMS within 4 business hours',\n    'Payments operations',\n    'Escalate failed allocation after same-day retry'\n  ),\n  (\n    'admin_list_allocations',\n    'Clear allocation reviews by next business day',\n    'Payments operations',\n    'Escalate mismatched ledger impact immediately'\n  ),\n  (\n    'admin_list_unallocated',\n    'Triage open exceptions within 4 business hours',\n    'Payments support',\n    'Escalate unresolved member impact same day'\n  ),\n  (\n    'admin_list_sms_metadata',\n    'Review failed parser metadata within 1 business day',\n    'Compliance support',\n    'Escalate raw reveal requests to compliance owner'\n  ),\n  (\n    'admin_list_collections',\n    'Respond to group support requests within 1 business day',\n    'Group operations',\n    'Escalate receiver-readiness blockers same day'\n  ),\n  (\n    'admin_list_users',\n    'Respond to account support requests within 1 business day',\n    'Member support',\n    'Escalate identity or access risk immediately'\n  ),\n  (\n    'admin_list_payments',\n    'Review pending or expired intents within 1 business day',\n    'Payments support',\n    'Escalate duplicate or disputed intent same day'\n  ),\n  (\n    'admin_list_receivers',\n    'Review receiver setup changes within 1 business day',\n    'Group operations',\n    'Escalate inactive receiver routes before launch'\n  ),\n  (\n    'admin_list_ledger',\n    'Review ledger exceptions within 1 business day',\n    'Finance operations',\n    'Escalate correction path before member messaging'\n  ),\n  (\n    'admin_list_audit_logs',\n    'Review sensitive audit events daily',\n    'Compliance owner',\n    'Escalate unexplained sensitive access immediately'\n  ),\n  (\n    'admin_list_settings',\n    'Review config changes before release window',\n    'Platform owner',\n    'Escalate unapproved production change immediately'\n  ),\n  (\n    'admin_list_feature_flags',\n    'Review rollout flags before activation',\n    'Product operations',\n    'Escalate degraded health signal immediately'\n  ),\n  (\n    'admin_list_admin_users',\n    'Review operator access weekly',\n    'Platform owner',\n    'Revoke stale or overbroad access immediately'\n  )\non conflict (queue_key) do update\nset target = excluded.target,\n    owner = excluded.owner,\n    escalation = excluded.escalation,\n    updated_at = now();\n\ncreate or replace function admin_get_queue_sla(p_queue_key text)\nreturns jsonb\nlanguage plpgsql\nstable\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  normalized_queue_key text := trim(coalesce(p_queue_key, ''));\n  policy_row admin_queue_sla_policies%rowtype;\nbegin\n  case normalized_queue_key\n    when 'admin_list_payment_events' then perform assert_admin_permission('payment_events.read');\n    when 'admin_list_allocations' then perform assert_admin_permission('payment_events.read');\n    when 'admin_list_unallocated' then perform assert_admin_permission('payment_events.read');\n    when 'admin_list_sms_metadata' then perform assert_admin_permission('sms.metadata.read');\n    when 'admin_list_collections' then perform assert_admin_permission('collections.read');\n    when 'admin_list_users' then perform assert_admin_permission('users.read');\n    when 'admin_list_payments' then perform assert_admin_permission('payments.read');\n    when 'admin_list_receivers' then perform assert_admin_permission('receivers.read');\n    when 'admin_list_ledger' then perform assert_admin_permission('ledger.read');\n    when 'admin_list_audit_logs' then perform assert_admin_permission('audit.read');\n    when 'admin_list_settings' then perform assert_admin_permission('settings.read');\n    when 'admin_list_feature_flags' then perform assert_admin_permission('feature_flags.read');\n    when 'admin_list_admin_users' then perform assert_admin_permission('admin_users.read');\n    else raise exception 'Unsupported admin queue SLA key: %', normalized_queue_key;\n  end case;\n\n  select *\n  into policy_row\n  from admin_queue_sla_policies\n  where queue_key = normalized_queue_key;\n\n  if not found then\n    return '{}'::jsonb;\n  end if;\n\n  return jsonb_build_object(\n    'queue_key', policy_row.queue_key,\n    'target', policy_row.target,\n    'owner', policy_row.owner,\n    'escalation', policy_row.escalation,\n    'updated_at', policy_row.updated_at\n  );\nend;\n$$;\n\nrevoke execute on function admin_get_queue_sla(text) from public, anon;\ngrant execute on function admin_get_queue_sla(text) to authenticated;\n\ncommit;\n"}
20261001000519	safe_unstarted_receipt_cancel	{"begin;\n\n-- Manual cancellation only. Preserve the existing receipt identity, immutable\n-- financial/payload evidence and seven-state transport contract. No retry,\n-- correction, resend, policy approval or dispatch authority is introduced.\ncreate schema collect_receipt_actions;\nrevoke all on schema collect_receipt_actions from public,anon,authenticated,service_role;\ncreate table collect_receipt_actions.revisions(\n outbox_id uuid primary key references collect_hybrid.sms_notification_outbox(id) on delete restrict,\n revision bigint not null check(revision between 1 and 1000000000)\n);\ncreate table collect_receipt_actions.cancellations(\n request_id uuid primary key,\n outbox_id uuid not null unique references collect_hybrid.sms_notification_outbox(id) on delete restrict,\n expected_revision bigint not null check(expected_revision between 1 and 999999999),\n revision bigint not null check(revision=expected_revision+1 and revision<=1000000000),\n reason_code text not null check(reason_code in('operator_cancelled','recipient_review_required','content_review_required')),\n actor_id uuid not null,\n session_id uuid not null,\n recorded_at timestamptz not null check(isfinite(recorded_at))\n);\nalter table collect_receipt_actions.revisions enable row level security;\nalter table collect_receipt_actions.cancellations enable row level security;\nrevoke all on collect_receipt_actions.revisions,collect_receipt_actions.cancellations\n from public,anon,authenticated,service_role;\n\ncreate function collect_receipt_actions.immutable_cancellation()returns trigger\nlanguage plpgsql set search_path=''as $$begin\n raise exception 'receipt_action_evidence_retained'using errcode='55000';end$$;\ncreate trigger immutable_receipt_cancellation before update or delete on collect_receipt_actions.cancellations\n for each row execute function collect_receipt_actions.immutable_cancellation();\ncreate function collect_receipt_actions.protect_revision()returns trigger\nlanguage plpgsql set search_path=''as $$begin\n if tg_op='DELETE'or new.outbox_id is distinct from old.outbox_id\n  or new.revision is distinct from old.revision+1 then\n  raise exception 'receipt_action_revision_invalid'using errcode='55000';end if;\n return new;end$$;\ncreate trigger monotonic_receipt_action_revision before update or delete on collect_receipt_actions.revisions\n for each row execute function collect_receipt_actions.protect_revision();\ncreate function collect_receipt_actions.advance_revision()returns trigger\nlanguage plpgsql security definer set search_path=''as $$declare value bigint;begin\n -- Existing rows have implicit revision1 without an install-time row write.\n -- Their first UPDATE therefore installs revision2, not revision1.\n insert into collect_receipt_actions.revisions(outbox_id,revision)\n values(new.id,case when tg_op='INSERT'then 1 else 2 end)\n on conflict(outbox_id)do update set revision=revisions.revision+1\n  where revisions.revision<1000000000 returning revision into value;\n if value is null then raise exception 'receipt_action_revision_exhausted'using errcode='55000';end if;\n return new;end$$;\ncreate trigger zzzzz_receipt_action_revision after insert or update on collect_hybrid.sms_notification_outbox\n for each row execute function collect_receipt_actions.advance_revision();\ncreate function collect_receipt_actions.protect_cancelled_receipt()returns trigger\nlanguage plpgsql security definer set search_path=''as $$begin\n if new.state is distinct from 'suppressed'and exists(select 1 from collect_receipt_actions.cancellations\n  where outbox_id=old.id)then\n  raise exception 'receipt_manual_cancellation_final'using errcode='55000';end if;\n return new;end$$;\ncreate trigger receipt_manual_cancellation_final before update on collect_hybrid.sms_notification_outbox\n for each row execute function collect_receipt_actions.protect_cancelled_receipt();\n\ncreate function collect_receipt_actions.actor(p_mutation boolean)returns uuid\nlanguage plpgsql volatile security definer set search_path=''as $$\ndeclare sid uuid;permissions text[]:=array['payments.read','notifications.read','system_health.read'];begin\n if current_setting('transaction_isolation')<>'read committed'then\n  raise exception 'receipt_action_snapshot_retry'using errcode='40001';end if;\n sid:=public._lock_notification_registration_session();\n perform pg_advisory_xact_lock(hashtext('collect_admin_combined_roster'));\n if p_mutation then permissions:=array_append(permissions,'notifications.manage');end if;\n perform collect_hybrid.require_roster_actor_authority(auth.uid(),sid,'platform_owner',permissions);\n -- No legacy phone approval fallback, including while transition mode remains.\n if not collect_admin_access.email_identity(auth.uid())then\n  raise exception 'receipt_action_current_email_owner_required'using errcode='42501';end if;\n return sid;end$$;\n\ncreate function collect_receipt_actions.rwanda_source(p_job collect_hybrid.sms_notification_outbox)\nreturns boolean language sql stable security definer set search_path=''as $$\n -- A receiving route alone cannot override a contradictory linked parser.\n select exists(select 1 from public.payments p where p.id=p_job.payment_id\n  and collect_ops.payment_scope(p.id)\n  and(p.parsed_event_id is null or collect_ops.transaction_sms_id('payment',p.id)is not null))\n$$;\n\ncreate function collect_receipt_actions.ineligible_reason(p_job collect_hybrid.sms_notification_outbox)\nreturns text language sql stable security definer set search_path=''as $$\n select case\n  when exists(select 1 from collect_receipt_actions.cancellations where outbox_id=p_job.id)then 'already_cancelled'\n  when p_job.state is distinct from 'queued'then 'state_not_queued'\n  when p_job.fence_version is distinct from 0 or p_job.attempt_count is distinct from 0\n   or p_job.claim_token is not null or p_job.claimed_by is not null or p_job.claim_expires_at is not null\n   or p_job.observed_sent_at is not null or p_job.suppression_reason is not null\n   or exists(select 1 from collect_hybrid.sms_notification_claim_requests where outbox_id=p_job.id)\n   or exists(select 1 from collect_hybrid.sms_notification_confirmations where outbox_id=p_job.id)\n   or exists(select 1 from collect_hybrid.sms_notification_attempts where outbox_id=p_job.id)\n   or exists(select 1 from collect_gateway.dispatch_arms g join collect_hybrid.sms_notification_attempts a\n    on a.id=g.attempt_id where a.outbox_id=p_job.id)then 'prior_transport_evidence'\n  when not exists(select 1 from public.payments p\n   join collect_hybrid.momo_balance_snapshots s on s.id=p_job.snapshot_id\n   join collect_hybrid.momo_journal_entries j on j.id=s.journal_entry_id\n   where p.id=p_job.payment_id and p.status='posted'and p.currency='RWF'\n    and collect_receipt_actions.rwanda_source(p_job)\n    and p.collection_id=p_job.collection_id and p.member_record_id=p_job.member_record_id\n    and p.amount_rwf=p_job.amount_rwf\n    and p_job.reference=coalesce(nullif(btrim(p.transaction_id),''),p.id::text)\n    and s.payment_id=p.id and s.collection_id=p_job.collection_id and s.member_record_id=p_job.member_record_id\n    and s.event_type='receipt'and s.delta_rwf=p_job.amount_rwf\n    and s.member_balance_after_rwf=p_job.member_balance_rwf and s.group_balance_after_rwf=p_job.group_balance_rwf\n    and j.payment_id=p.id and j.collection_id=p_job.collection_id and j.member_record_id=p_job.member_record_id\n    and j.entry_type='receipt'and j.amount_rwf=p_job.amount_rwf\n    and not exists(select 1 from collect_hybrid.momo_journal_entries r where r.payment_id=p.id and r.entry_type='reversal')\n    and(select count(*)=2 and count(*)filter(where\n      (l.account_code='momo_receiving_asset:RWF'and l.direction='debit')or\n      (l.account_code='member_savings_liability:RWF'and l.direction='credit'))=2\n     and min(l.amount_rwf)=p_job.amount_rwf and max(l.amount_rwf)=p_job.amount_rwf\n     from collect_hybrid.momo_journal_lines l where l.journal_entry_id=j.id)\n    and p_job.destination_sha256=encode(extensions.digest(p_job.destination_e164,'sha256'),'hex')\n    and p_job.message_body=case when btrim(p_job.reference)~'^[A-Za-z0-9][A-Za-z0-9._/-]{0,63}$'then\n      collect_hybrid.render_buri_munsi_receipt(p_job.amount_rwf,\n       p_job.member_balance_rwf,p_job.group_balance_rwf,p_job.reference)else null end\n    and p_job.body_sha256=encode(extensions.digest(p_job.message_body,'sha256'),'hex'))then 'source_evidence_invalid'\n  else 'eligible'end\n$$;\n\ncreate function collect_receipt_actions.receipt(p_action collect_receipt_actions.cancellations)\nreturns jsonb language sql immutable set search_path=''as $$\n select jsonb_build_object('contract_version',1,'scope','rw_receipt_manual_cancel',\n  'request_id',p_action.request_id,'outbox_id',p_action.outbox_id,'expected_revision',p_action.expected_revision,\n  'revision',p_action.revision,'action','cancel_unstarted','reason_code',p_action.reason_code,\n  'recorded_at',collect_ops.utc(p_action.recorded_at),'state_before','queued','state_after','suppressed',\n  'financial_action',false,'send_action',false,'provider_delivery_verified',false,'primary_receipt_retained',true)\n$$;\n\ncreate function public.admin_inspect_unstarted_receipt_v1(p_outbox_id uuid)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''set lock_timeout='100ms'as $$\ndeclare job collect_hybrid.sms_notification_outbox;result jsonb;begin\n perform collect_receipt_actions.actor(false);\n if p_outbox_id is null then raise exception 'receipt_action_input_invalid'using errcode='22023';end if;\n -- The same actual outbox lock protects the source/head pair used by cancel.\n select * into job from collect_hybrid.sms_notification_outbox where id=p_outbox_id for share;\n with sample as materialized(select clock_timestamp()at),\n source as materialized(select coalesce((select revision from collect_receipt_actions.revisions where outbox_id=job.id),1)revision,\n  collect_receipt_actions.ineligible_reason(job)reason\n  where job.id is not null and collect_receipt_actions.rwanda_source(job)),\n data as materialized(select revision,case when revision=1000000000 then 'revision_exhausted'else reason end reason from source)\n select jsonb_build_object('contract_version',1,'scope','rw_receipt_manual_cancel',\n  'checked_at',collect_ops.utc(sample.at),'sample_valid_until',collect_ops.utc(sample.at+interval '60 seconds'),\n  'outbox_id',p_outbox_id,'status',case when exists(select 1 from data)then 'available'else 'unavailable'end,\n  'receipt',(select jsonb_build_object('outbox_id',job.id,'revision',data.revision,'state',job.state,\n    'can_cancel',data.reason='eligible','reason_code',data.reason)from data))into result from sample;\n return result;\nexception when lock_not_available then raise exception 'receipt_action_authority_busy'using errcode='55P03';end$$;\n\ncreate function public.admin_cancel_unstarted_receipt_v1(p_request_id uuid,p_outbox_id uuid,\n p_expected_revision bigint,p_reason_code text)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''as $$\ndeclare sid uuid;job collect_hybrid.sms_notification_outbox;prior collect_receipt_actions.cancellations;\n before_revision bigint;after_revision bigint;at timestamptz;begin\n sid:=collect_receipt_actions.actor(true);\n if p_request_id is null or p_outbox_id is null or p_expected_revision is null\n  or p_expected_revision not between 1 and 999999999 or p_reason_code is null\n  or p_reason_code not in('operator_cancelled','recipient_review_required','content_review_required')then\n  raise exception 'receipt_action_input_invalid'using errcode='22023';end if;\n perform pg_advisory_xact_lock(hashtextextended('collect-receipt-cancel-request:'||p_request_id::text,0));\n select * into prior from collect_receipt_actions.cancellations where request_id=p_request_id;\n if prior.request_id is not null then\n  if prior.actor_id<>auth.uid()or prior.outbox_id<>p_outbox_id or prior.expected_revision<>p_expected_revision\n   or prior.reason_code<>p_reason_code then raise exception 'receipt_action_request_conflict'using errcode='22023';end if;\n  perform collect_receipt_actions.actor(true);\n  return collect_receipt_actions.receipt(prior);\n end if;\n select * into job from collect_hybrid.sms_notification_outbox where id=p_outbox_id for update;\n -- Revalidate natural expiry after waiting, without changing the lock order:\n -- all authority proof locks were already held before the request/outbox lock.\n perform collect_receipt_actions.actor(true);\n select coalesce((select revision from collect_receipt_actions.revisions where outbox_id=job.id),1)into before_revision;\n if job.id is null or not collect_receipt_actions.rwanda_source(job)then\n  raise exception 'receipt_action_unavailable'using errcode='55000';end if;\n if before_revision<>p_expected_revision then raise exception 'receipt_action_source_changed'using errcode='55000';end if;\n if collect_receipt_actions.ineligible_reason(job)is distinct from 'eligible'then\n  raise exception 'receipt_not_cancellable'using errcode='55000';end if;\n update collect_hybrid.sms_notification_outbox set state='suppressed',suppression_reason='manual_pre_send_cancel'\n  where id=job.id;\n select revision into after_revision from collect_receipt_actions.revisions where outbox_id=job.id;\n if after_revision is distinct from before_revision+1 then\n  raise exception 'receipt_action_revision_invalid'using errcode='55000';end if;\n at:=clock_timestamp();\n insert into collect_receipt_actions.cancellations(request_id,outbox_id,expected_revision,revision,\n  reason_code,actor_id,session_id,recorded_at)\n values(p_request_id,job.id,before_revision,after_revision,p_reason_code,auth.uid(),sid,at)returning * into prior;\n perform public.create_audit_log('notification.sms.cancelled_unstarted','sms_notification_outbox',job.id,\n  jsonb_build_object('request_id',p_request_id,'expected_revision',before_revision,'revision',after_revision,\n   'reason_code',p_reason_code,'financial_action',false,'send_action',false),null);\n return collect_receipt_actions.receipt(prior);\nend$$;\n\ncreate function public.admin_get_unstarted_receipt_action_v1(p_request_id uuid)returns jsonb\nlanguage plpgsql volatile security definer set search_path=''set lock_timeout='100ms'as $$\ndeclare result jsonb;acquired boolean;begin\n perform collect_receipt_actions.actor(false);\n if p_request_id is null then raise exception 'receipt_action_input_invalid'using errcode='22023';end if;\n acquired:=pg_try_advisory_xact_lock(hashtextextended('collect-receipt-cancel-request:'||p_request_id::text,0));\n with sample as materialized(select clock_timestamp()at),\n prior as materialized(select * from collect_receipt_actions.cancellations\n  where acquired and request_id=p_request_id and actor_id=auth.uid())\n select jsonb_build_object('contract_version',1,'scope','rw_receipt_manual_cancel',\n  'checked_at',collect_ops.utc(sample.at),'sample_valid_until',collect_ops.utc(sample.at+interval '60 seconds'),\n  'request_id',p_request_id,'status',case when not acquired then 'in_progress'\n    when exists(select 1 from prior)then 'recorded'else 'not_recorded'end,\n  'receipt',(select collect_receipt_actions.receipt(p)from prior p))into result from sample;\n return result;\nexception when lock_not_available then raise exception 'receipt_action_authority_busy'using errcode='55P03';end$$;\n\nrevoke all on all functions in schema collect_receipt_actions from public,anon,authenticated,service_role;\nrevoke all on function public.admin_inspect_unstarted_receipt_v1(uuid),\n public.admin_cancel_unstarted_receipt_v1(uuid,uuid,bigint,text),public.admin_get_unstarted_receipt_action_v1(uuid)\n from public,anon,authenticated,service_role;\ngrant execute on function public.admin_inspect_unstarted_receipt_v1(uuid),\n public.admin_cancel_unstarted_receipt_v1(uuid,uuid,bigint,text),public.admin_get_unstarted_receipt_action_v1(uuid)to authenticated;\ncommit;\n"}
20260627190000	add_admin_collection_status_rpc	{"create or replace function admin_update_collection_support_status(\n  p_collection_id uuid,\n  p_status text,\n  p_reason text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  new_visibility collection_visibility;\nbegin\n  perform assert_admin_permission('collections.moderate');\n\n  if coalesce(trim(p_reason), '') = '' then\n    raise exception 'Reason is required';\n  end if;\n\n  if p_status not in ('private', 'public_rejected', 'archived') then\n    raise exception 'Unsupported collection support status';\n  end if;\n\n  new_visibility := p_status::collection_visibility;\n\n  update collections\n    set public_status = new_visibility,\n        visibility = case\n          when new_visibility = 'archived'::collection_visibility then 'archived'::collection_visibility\n          else 'private'::collection_visibility\n        end,\n        archived_at = case\n          when new_visibility = 'archived'::collection_visibility then now()\n          else archived_at\n        end,\n        updated_at = now()\n    where id = p_collection_id;\n\n  if not found then\n    raise exception 'Collection not found';\n  end if;\n\n  perform create_audit_log(\n    'collection.support_status.updated',\n    'collection',\n    p_collection_id,\n    jsonb_build_object('status', p_status, 'reason', p_reason)\n  );\n\n  return jsonb_build_object('ok', true, 'status', p_status);\nend;\n$$;\n\nrevoke execute on function admin_update_collection_support_status(uuid, text, text)\n  from public, anon;\ngrant execute on function admin_update_collection_support_status(uuid, text, text)\n  to authenticated;\n"}
20260627191000	add_admin_feature_flag_toggle_rpc	{"begin;\n\ncreate or replace function admin_set_feature_flag(\n  p_key text,\n  p_enabled boolean,\n  p_reason text\n)\nreturns jsonb\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  normalized_key text := trim(coalesce(p_key, ''));\n  normalized_reason text := trim(coalesce(p_reason, ''));\n  flag_row feature_flags%rowtype;\nbegin\n  perform assert_admin_permission('feature_flags.manage');\n\n  if normalized_key = '' then\n    raise exception 'Feature flag key is required';\n  end if;\n\n  if normalized_reason = '' then\n    raise exception 'Feature flag change reason is required';\n  end if;\n\n  update feature_flags\n  set enabled = p_enabled,\n      updated_by = auth.uid(),\n      updated_reason = normalized_reason,\n      updated_at = now()\n  where key = normalized_key\n  returning * into flag_row;\n\n  if not found then\n    raise exception 'Feature flag not found: %', normalized_key;\n  end if;\n\n  perform create_audit_log(\n    'admin.feature_flag.updated',\n    'feature_flag',\n    null,\n    jsonb_build_object(\n      'key', flag_row.key,\n      'enabled', flag_row.enabled,\n      'reason', normalized_reason\n    )\n  );\n\n  return jsonb_build_object(\n    'ok', true,\n    'key', flag_row.key,\n    'enabled', flag_row.enabled,\n    'updated_at', flag_row.updated_at\n  );\nend;\n$$;\n\nrevoke execute on function admin_set_feature_flag(text, boolean, text)\n  from public, anon;\ngrant execute on function admin_set_feature_flag(text, boolean, text)\n  to authenticated;\n\ncommit;\n"}
20260701090000	developer_account_seed_data	{"create or replace function ensure_developer_account_data()\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  allowed_phone constant text := '+250788767816';\n  allowed_digits constant text := '250788767816';\n  developer_momo constant text := '0788767816';\n  current_digits text;\n  profile_row profiles%rowtype;\n  collection_church constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f1001';\n  collection_ikimina constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f1002';\n  payment_one constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f2001';\n  payment_two constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f2002';\n  ledger_one constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f3001';\n  ledger_two constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f3002';\n  receiver_hash text := encode(digest(allowed_phone, 'sha256'), 'hex');\nbegin\n  if auth.uid() is null then\n    return false;\n  end if;\n\n  select regexp_replace(\n    coalesce(u.phone, p.whatsapp_phone, auth.jwt() ->> 'phone', ''),\n    '[^0-9]',\n    '',\n    'g'\n  )\n  into current_digits\n  from auth.users u\n  left join profiles p on p.id = u.id\n  where u.id = auth.uid();\n\n  if left(coalesce(current_digits, ''), 2) = '00' then\n    current_digits := substring(current_digits from 3);\n  end if;\n\n  if current_digits <> allowed_digits then\n    return false;\n  end if;\n\n  if exists (\n    select 1\n    from profiles\n    where whatsapp_phone = allowed_phone\n      and id <> auth.uid()\n  ) then\n    raise exception 'Developer WhatsApp number belongs to another profile';\n  end if;\n\n  insert into profiles (\n    id,\n    public_id,\n    whatsapp_phone,\n    display_name,\n    momo_number,\n    momo_number_hash\n  )\n  values (\n    auth.uid(),\n    generate_public_id(),\n    allowed_phone,\n    'Collect developer',\n    developer_momo,\n    receiver_hash\n  )\n  on conflict (id) do update\n  set\n    whatsapp_phone = allowed_phone,\n    display_name = coalesce(nullif(profiles.display_name, ''), 'Collect developer'),\n    momo_number = coalesce(nullif(profiles.momo_number, ''), developer_momo),\n    momo_number_hash = coalesce(nullif(profiles.momo_number_hash, ''), receiver_hash),\n    updated_at = now()\n  returning * into profile_row;\n\n  insert into collections (\n    id,\n    slug,\n    creator_user_id,\n    title,\n    description,\n    category,\n    receiver_display_label,\n    public_status,\n    visibility,\n    is_recurring,\n    recurring_rule,\n    collection_type,\n    category_subtype,\n    purpose_label,\n    moderation_status,\n    created_at\n  )\n  values\n    (\n      collection_church,\n      'developer-parish-support',\n      profile_row.id,\n      'Developer parish support',\n      'Developer-owned Supabase seed for validating Collect group balances.',\n      'Church',\n      'Developer MoMo receiver',\n      'public_approved',\n      'public_approved',\n      true,\n      jsonb_build_object('cadence', 'monthly'),\n      'church',\n      'offering',\n      'Parish support',\n      'approved',\n      now() - interval '3 days'\n    ),\n    (\n      collection_ikimina,\n      'developer-ikimina-savings',\n      profile_row.id,\n      'Developer ikimina savings',\n      'Developer-owned Supabase seed for validating private group activity.',\n      'Family / friends',\n      'Developer MoMo receiver',\n      'private',\n      'private',\n      true,\n      jsonb_build_object('cadence', 'monthly'),\n      'ikimina',\n      'group_savings',\n      'Savings cycle',\n      'not_requested',\n      now() - interval '1 day'\n    )\n  on conflict (id) do update\n  set\n    creator_user_id = excluded.creator_user_id,\n    title = excluded.title,\n    description = excluded.description,\n    receiver_display_label = excluded.receiver_display_label,\n    public_status = excluded.public_status,\n    visibility = excluded.visibility,\n    is_recurring = excluded.is_recurring,\n    recurring_rule = excluded.recurring_rule,\n    collection_type = excluded.collection_type,\n    category_subtype = excluded.category_subtype,\n    purpose_label = excluded.purpose_label,\n    moderation_status = excluded.moderation_status,\n    updated_at = now();\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values\n    (collection_church, profile_row.id, 'owner', 'active'),\n    (collection_ikimina, profile_row.id, 'owner', 'active')\n  on conflict (collection_id, user_id, role) do update\n  set status = 'active';\n\n  update collection_receivers\n  set is_active = false\n  where collection_id in (collection_church, collection_ikimina)\n    and receiver_user_id = profile_row.id\n    and momo_number <> developer_momo;\n\n  insert into collection_receivers (\n    collection_id,\n    receiver_user_id,\n    momo_number,\n    momo_number_hash,\n    network,\n    label,\n    is_active\n  )\n  select seed.collection_id, profile_row.id, developer_momo, receiver_hash,\n    'mtn_momo', 'Developer MoMo receiver', true\n  from (values (collection_church), (collection_ikimina)) as seed(collection_id)\n  where not exists (\n    select 1\n    from collection_receivers cr\n    where cr.collection_id = seed.collection_id\n      and cr.receiver_user_id = profile_row.id\n      and cr.momo_number = developer_momo\n      and cr.is_active\n  );\n\n  insert into payments (\n    id,\n    collection_id,\n    contributor_user_id,\n    contributor_public_id,\n    receiver_user_id,\n    receiver_momo_number_hash,\n    amount_rwf,\n    transaction_id,\n    source,\n    status,\n    anonymity_choice,\n    posted_at,\n    created_at\n  )\n  values\n    (\n      payment_one,\n      collection_church,\n      profile_row.id,\n      profile_row.public_id,\n      profile_row.id,\n      receiver_hash,\n      25000,\n      'DEV-MOMO-0001',\n      'import',\n      'posted',\n      'public_id',\n      now() - interval '5 hours',\n      now() - interval '5 hours'\n    ),\n    (\n      payment_two,\n      collection_church,\n      profile_row.id,\n      profile_row.public_id,\n      profile_row.id,\n      receiver_hash,\n      10000,\n      'DEV-MOMO-0002',\n      'import',\n      'posted',\n      'public_id',\n      now() - interval '2 hours',\n      now() - interval '2 hours'\n    )\n  on conflict (id) do update\n  set\n    collection_id = excluded.collection_id,\n    contributor_user_id = excluded.contributor_user_id,\n    contributor_public_id = excluded.contributor_public_id,\n    receiver_user_id = excluded.receiver_user_id,\n    receiver_momo_number_hash = excluded.receiver_momo_number_hash,\n    amount_rwf = excluded.amount_rwf,\n    transaction_id = excluded.transaction_id,\n    source = excluded.source,\n    status = excluded.status,\n    anonymity_choice = excluded.anonymity_choice;\n\n  insert into ledger_entries (\n    id,\n    payment_id,\n    collection_id,\n    user_id,\n    entry_type,\n    amount_rwf,\n    visibility,\n    metadata,\n    created_at\n  )\n  values\n    (\n      ledger_one,\n      payment_one,\n      collection_church,\n      profile_row.id,\n      'collection_credit',\n      25000,\n      'public_safe',\n      jsonb_build_object('seed_owner', allowed_phone),\n      now() - interval '5 hours'\n    ),\n    (\n      ledger_two,\n      payment_two,\n      collection_church,\n      profile_row.id,\n      'collection_credit',\n      10000,\n      'public_safe',\n      jsonb_build_object('seed_owner', allowed_phone),\n      now() - interval '2 hours'\n    )\n  on conflict (id) do update\n  set\n    payment_id = excluded.payment_id,\n    collection_id = excluded.collection_id,\n    user_id = excluded.user_id,\n    amount_rwf = excluded.amount_rwf,\n    visibility = excluded.visibility,\n    metadata = excluded.metadata;\n\n  return true;\nend;\n$$;\n\nrevoke execute on function ensure_developer_account_data()\n  from public, anon, authenticated;\ngrant execute on function ensure_developer_account_data() to authenticated;\n"}
20260701100000	group_owner_controls	{"create or replace function archive_group(collection uuid)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, auth\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  update collections\n  set\n    visibility = 'archived'::collection_visibility,\n    public_status = 'archived'::collection_visibility,\n    archived_at = now()\n  where id = collection\n    and creator_user_id = auth.uid();\n\n  if not found then\n    raise exception 'Only the group owner can archive this group';\n  end if;\nend;\n$$;\n\ncreate or replace function transfer_group_ownership(\n  collection uuid,\n  new_owner_public_id text\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, auth\nas $$\ndeclare\n  current_owner uuid := auth.uid();\n  new_owner uuid;\nbegin\n  if current_owner is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select id\n  into new_owner\n  from profiles\n  where public_id = regexp_replace(coalesce(new_owner_public_id, ''), '\\\\D', '', 'g')\n  limit 1;\n\n  if new_owner is null then\n    raise exception 'Collect ID not found';\n  end if;\n\n  update collections\n  set creator_user_id = new_owner\n  where id = collection\n    and creator_user_id = current_owner;\n\n  if not found then\n    raise exception 'Only the group owner can transfer ownership';\n  end if;\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values (collection, new_owner, 'owner'::member_role, 'active'::member_status)\n  on conflict (collection_id, user_id, role)\n  do update set status = 'active'::member_status;\n\n  if new_owner <> current_owner then\n    delete from collection_members\n    where collection_id = collection\n      and user_id = current_owner\n      and role = 'owner'::member_role;\n\n    insert into collection_members (collection_id, user_id, role, status)\n    values (\n      collection,\n      current_owner,\n      'admin'::member_role,\n      'active'::member_status\n    )\n    on conflict (collection_id, user_id, role)\n    do update set status = 'active'::member_status;\n  end if;\nend;\n$$;\n\nrevoke execute on function archive_group(uuid) from public, anon, authenticated;\ngrant execute on function archive_group(uuid) to authenticated;\n\nrevoke execute on function transfer_group_ownership(uuid, text)\nfrom public, anon, authenticated;\ngrant execute on function transfer_group_ownership(uuid, text) to authenticated;\n"}
20260703170000	harden_developer_and_group_rpcs	{"create or replace function ensure_developer_account_data()\nreturns boolean\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  allowed_phone constant text := '+250788767816';\n  allowed_digits constant text := '250788767816';\n  developer_momo constant text := '0788767816';\n  current_digits text;\n  profile_row profiles%rowtype;\n  collection_church constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f1001'::uuid;\n  collection_ikimina constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f1002'::uuid;\n  payment_one constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f2001'::uuid;\n  payment_two constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f2002'::uuid;\n  ledger_one constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f3001'::uuid;\n  ledger_two constant uuid := '8db1f114-4f2b-4a6a-aec9-a0e33a1f3002'::uuid;\n  receiver_hash text := encode(digest(allowed_phone, 'sha256'), 'hex');\nbegin\n  if auth.uid() is null then\n    return false;\n  end if;\n\n  select regexp_replace(\n    coalesce(u.phone, p.whatsapp_phone, auth.jwt() ->> 'phone', ''),\n    '[^0-9]',\n    '',\n    'g'\n  )\n  into current_digits\n  from auth.users u\n  left join profiles p on p.id = u.id\n  where u.id = auth.uid();\n\n  if left(coalesce(current_digits, ''), 2) = '00' then\n    current_digits := substring(current_digits from 3);\n  end if;\n\n  if current_digits <> allowed_digits then\n    return false;\n  end if;\n\n  if exists (\n    select 1\n    from profiles\n    where whatsapp_phone = allowed_phone\n      and id <> auth.uid()\n  ) then\n    raise exception 'Developer WhatsApp number belongs to another profile';\n  end if;\n\n  insert into profiles (\n    id,\n    public_id,\n    whatsapp_phone,\n    display_name,\n    momo_number,\n    momo_number_hash\n  )\n  values (\n    auth.uid(),\n    generate_public_id(),\n    allowed_phone,\n    'Collect developer',\n    developer_momo,\n    receiver_hash\n  )\n  on conflict (id) do update\n  set\n    whatsapp_phone = allowed_phone,\n    display_name = coalesce(nullif(profiles.display_name, ''), 'Collect developer'),\n    momo_number = coalesce(nullif(profiles.momo_number, ''), developer_momo),\n    momo_number_hash = coalesce(nullif(profiles.momo_number_hash, ''), receiver_hash),\n    updated_at = now()\n  returning * into profile_row;\n\n  insert into collections (\n    id,\n    slug,\n    creator_user_id,\n    title,\n    description,\n    category,\n    receiver_display_label,\n    public_status,\n    visibility,\n    is_recurring,\n    recurring_rule,\n    collection_type,\n    category_subtype,\n    purpose_label,\n    moderation_status,\n    created_at\n  )\n  values\n    (\n      collection_church,\n      'developer-parish-support',\n      profile_row.id,\n      'Developer parish support',\n      'Developer-owned Supabase seed for validating Collect group balances.',\n      'Church',\n      'Developer MoMo receiver',\n      'public_approved',\n      'public_approved',\n      true,\n      jsonb_build_object('cadence', 'monthly'),\n      'church',\n      'offering',\n      'Parish support',\n      'approved',\n      now() - interval '3 days'\n    ),\n    (\n      collection_ikimina,\n      'developer-ikimina-savings',\n      profile_row.id,\n      'Developer ikimina savings',\n      'Developer-owned Supabase seed for validating private group activity.',\n      'Family / friends',\n      'Developer MoMo receiver',\n      'private',\n      'private',\n      true,\n      jsonb_build_object('cadence', 'monthly'),\n      'ikimina',\n      'group_savings',\n      'Savings cycle',\n      'not_requested',\n      now() - interval '1 day'\n    )\n  on conflict (id) do update\n  set\n    creator_user_id = excluded.creator_user_id,\n    title = excluded.title,\n    description = excluded.description,\n    receiver_display_label = excluded.receiver_display_label,\n    public_status = excluded.public_status,\n    visibility = excluded.visibility,\n    is_recurring = excluded.is_recurring,\n    recurring_rule = excluded.recurring_rule,\n    collection_type = excluded.collection_type,\n    category_subtype = excluded.category_subtype,\n    purpose_label = excluded.purpose_label,\n    moderation_status = excluded.moderation_status,\n    updated_at = now();\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values\n    (collection_church, profile_row.id, 'owner', 'active'),\n    (collection_ikimina, profile_row.id, 'owner', 'active')\n  on conflict (collection_id, user_id, role) do update\n  set status = 'active';\n\n  update collection_receivers\n  set is_active = false\n  where collection_id in (collection_church, collection_ikimina)\n    and receiver_user_id = profile_row.id\n    and momo_number <> developer_momo;\n\n  insert into collection_receivers (\n    collection_id,\n    receiver_user_id,\n    momo_number,\n    momo_number_hash,\n    network,\n    label,\n    is_active\n  )\n  select seed.collection_id, profile_row.id, developer_momo, receiver_hash,\n    'mtn_momo', 'Developer MoMo receiver', true\n  from (values (collection_church), (collection_ikimina)) as seed(collection_id)\n  where not exists (\n    select 1\n    from collection_receivers cr\n    where cr.collection_id = seed.collection_id\n      and cr.receiver_user_id = profile_row.id\n      and cr.momo_number = developer_momo\n      and cr.is_active\n  );\n\n  insert into payments (\n    id,\n    collection_id,\n    contributor_user_id,\n    contributor_public_id,\n    receiver_user_id,\n    receiver_momo_number_hash,\n    amount_rwf,\n    transaction_id,\n    source,\n    status,\n    anonymity_choice,\n    posted_at,\n    created_at\n  )\n  values\n    (\n      payment_one,\n      collection_church,\n      profile_row.id,\n      profile_row.public_id,\n      profile_row.id,\n      receiver_hash,\n      25000,\n      'DEV-MOMO-0001',\n      'import',\n      'posted',\n      'public_id',\n      now() - interval '5 hours',\n      now() - interval '5 hours'\n    ),\n    (\n      payment_two,\n      collection_church,\n      profile_row.id,\n      profile_row.public_id,\n      profile_row.id,\n      receiver_hash,\n      10000,\n      'DEV-MOMO-0002',\n      'import',\n      'posted',\n      'public_id',\n      now() - interval '2 hours',\n      now() - interval '2 hours'\n    )\n  on conflict (id) do update\n  set\n    collection_id = excluded.collection_id,\n    contributor_user_id = excluded.contributor_user_id,\n    contributor_public_id = excluded.contributor_public_id,\n    receiver_user_id = excluded.receiver_user_id,\n    receiver_momo_number_hash = excluded.receiver_momo_number_hash,\n    amount_rwf = excluded.amount_rwf,\n    transaction_id = excluded.transaction_id,\n    source = excluded.source,\n    status = excluded.status,\n    anonymity_choice = excluded.anonymity_choice;\n\n  insert into ledger_entries (\n    id,\n    payment_id,\n    collection_id,\n    user_id,\n    entry_type,\n    amount_rwf,\n    visibility,\n    metadata,\n    created_at\n  )\n  values\n    (\n      ledger_one,\n      payment_one,\n      collection_church,\n      profile_row.id,\n      'collection_credit',\n      25000,\n      'public_safe',\n      jsonb_build_object('seed_owner', allowed_phone),\n      now() - interval '5 hours'\n    ),\n    (\n      ledger_two,\n      payment_two,\n      collection_church,\n      profile_row.id,\n      'collection_credit',\n      10000,\n      'public_safe',\n      jsonb_build_object('seed_owner', allowed_phone),\n      now() - interval '2 hours'\n    )\n  on conflict (id) do nothing;\n\n  return true;\nend;\n$$;\n\nrevoke execute on function ensure_developer_account_data()\n  from public, anon, authenticated;\ngrant execute on function ensure_developer_account_data() to authenticated;\n\ncreate or replace function archive_group(collection uuid)\nreturns void\nlanguage plpgsql\nsecurity invoker\nset search_path = public, auth\nas $$\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  update collections\n  set\n    visibility = 'archived'::collection_visibility,\n    public_status = 'archived'::collection_visibility,\n    archived_at = now()\n  where id = collection\n    and creator_user_id = auth.uid();\n\n  if not found then\n    raise exception 'Only the group owner can archive this group';\n  end if;\nend;\n$$;\n\ncreate or replace function transfer_group_ownership(\n  collection uuid,\n  new_owner_public_id text\n)\nreturns void\nlanguage plpgsql\nsecurity invoker\nset search_path = public, auth\nas $$\ndeclare\n  current_owner uuid := auth.uid();\n  new_owner uuid;\nbegin\n  if current_owner is null then\n    raise exception 'Authentication required';\n  end if;\n\n  select id\n  into new_owner\n  from profiles\n  where public_id = regexp_replace(coalesce(new_owner_public_id, ''), '\\\\D', '', 'g')\n  limit 1;\n\n  if new_owner is null then\n    raise exception 'Collect ID not found';\n  end if;\n\n  update collections\n  set creator_user_id = new_owner\n  where id = collection\n    and creator_user_id = current_owner;\n\n  if not found then\n    raise exception 'Only the group owner can transfer ownership';\n  end if;\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values (collection, new_owner, 'owner'::member_role, 'active'::member_status)\n  on conflict (collection_id, user_id, role)\n  do update set status = 'active'::member_status;\n\n  if new_owner <> current_owner then\n    delete from collection_members\n    where collection_id = collection\n      and user_id = current_owner\n      and role = 'owner'::member_role;\n\n    insert into collection_members (collection_id, user_id, role, status)\n    values (\n      collection,\n      current_owner,\n      'admin'::member_role,\n      'active'::member_status\n    )\n    on conflict (collection_id, user_id, role)\n    do update set status = 'active'::member_status;\n  end if;\nend;\n$$;\n\nrevoke execute on function archive_group(uuid) from public, anon, authenticated;\ngrant execute on function archive_group(uuid) to authenticated;\n\nrevoke execute on function transfer_group_ownership(uuid, text)\nfrom public, anon, authenticated;\ngrant execute on function transfer_group_ownership(uuid, text) to authenticated;\n"}
20260703224559	collection_type_catalog_runtime	{"begin;\n\ncreate table if not exists collection_type_catalog (\n  key text primary key check (key in ('ikimina', 'sport', 'church', 'wedding', 'other')),\n  label text not null,\n  short_purpose text not null,\n  icon_key text not null check (icon_key ~ '^[a-z0-9_]+$'),\n  default_category_subtype text not null check (default_category_subtype ~ '^[a-z0-9_.-]+$'),\n  default_purpose_template_key text not null check (default_purpose_template_key ~ '^[a-z0-9_.-]+$'),\n  display_order integer not null default 100,\n  enabled boolean not null default true,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text\n);\n\ncreate table if not exists collection_category_subtypes (\n  collection_type_key text not null references collection_type_catalog(key) on delete cascade,\n  key text not null check (key ~ '^[a-z0-9_.-]+$'),\n  label text not null,\n  display_order integer not null default 100,\n  enabled boolean not null default true,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text,\n  primary key (collection_type_key, key)\n);\n\ncreate table if not exists collection_purpose_templates (\n  collection_type_key text not null references collection_type_catalog(key) on delete cascade,\n  key text not null check (key ~ '^[a-z0-9_.-]+$'),\n  label text not null,\n  display_order integer not null default 100,\n  enabled boolean not null default true,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text,\n  primary key (collection_type_key, key)\n);\n\ncreate table if not exists collection_type_country_rules (\n  collection_type_key text not null references collection_type_catalog(key) on delete cascade,\n  country_code text not null default 'RW' check (country_code ~ '^[A-Z]{2}$'),\n  enabled boolean not null default true,\n  min_suggested_amount_rwf bigint check (min_suggested_amount_rwf is null or min_suggested_amount_rwf > 0),\n  max_suggested_amount_rwf bigint check (max_suggested_amount_rwf is null or max_suggested_amount_rwf > 0),\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text,\n  primary key (collection_type_key, country_code),\n  constraint collection_type_country_rules_amount_order_check check (\n    min_suggested_amount_rwf is null\n    or max_suggested_amount_rwf is null\n    or min_suggested_amount_rwf <= max_suggested_amount_rwf\n  )\n);\n\ncreate index if not exists collection_type_catalog_enabled_order_idx\n  on collection_type_catalog (enabled, display_order, key);\n\ncreate index if not exists collection_category_subtypes_lookup_idx\n  on collection_category_subtypes (\n    collection_type_key,\n    enabled,\n    display_order,\n    key\n  );\n\ncreate index if not exists collection_purpose_templates_lookup_idx\n  on collection_purpose_templates (\n    collection_type_key,\n    enabled,\n    display_order,\n    key\n  );\n\ncreate index if not exists collection_type_country_rules_lookup_idx\n  on collection_type_country_rules (\n    country_code,\n    enabled,\n    collection_type_key\n  );\n\nalter table collection_type_catalog enable row level security;\nalter table collection_category_subtypes enable row level security;\nalter table collection_purpose_templates enable row level security;\nalter table collection_type_country_rules enable row level security;\n\ndrop policy if exists \\"collection type catalog public enabled read\\" on collection_type_catalog;\ncreate policy \\"collection type catalog public enabled read\\"\non collection_type_catalog for select to anon, authenticated\nusing (enabled);\n\ndrop policy if exists \\"collection type catalog admin manage\\" on collection_type_catalog;\ncreate policy \\"collection type catalog admin manage\\"\non collection_type_catalog for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ndrop policy if exists \\"collection category subtypes public enabled read\\" on collection_category_subtypes;\ncreate policy \\"collection category subtypes public enabled read\\"\non collection_category_subtypes for select to anon, authenticated\nusing (\n  enabled\n  and exists (\n    select 1\n    from collection_type_catalog ctc\n    where ctc.key = collection_category_subtypes.collection_type_key\n      and ctc.enabled\n  )\n);\n\ndrop policy if exists \\"collection category subtypes admin manage\\" on collection_category_subtypes;\ncreate policy \\"collection category subtypes admin manage\\"\non collection_category_subtypes for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ndrop policy if exists \\"collection purpose templates public enabled read\\" on collection_purpose_templates;\ncreate policy \\"collection purpose templates public enabled read\\"\non collection_purpose_templates for select to anon, authenticated\nusing (\n  enabled\n  and exists (\n    select 1\n    from collection_type_catalog ctc\n    where ctc.key = collection_purpose_templates.collection_type_key\n      and ctc.enabled\n  )\n);\n\ndrop policy if exists \\"collection purpose templates admin manage\\" on collection_purpose_templates;\ncreate policy \\"collection purpose templates admin manage\\"\non collection_purpose_templates for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ndrop policy if exists \\"collection type country rules public enabled read\\" on collection_type_country_rules;\ncreate policy \\"collection type country rules public enabled read\\"\non collection_type_country_rules for select to anon, authenticated\nusing (\n  enabled\n  and exists (\n    select 1\n    from collection_type_catalog ctc\n    where ctc.key = collection_type_country_rules.collection_type_key\n      and ctc.enabled\n  )\n);\n\ndrop policy if exists \\"collection type country rules admin manage\\" on collection_type_country_rules;\ncreate policy \\"collection type country rules admin manage\\"\non collection_type_country_rules for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ncreate or replace function get_collection_type_catalog(\n  p_country_code text default 'RW',\n  p_locale text default 'en'\n)\nreturns jsonb\nlanguage sql\nstable\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'country_code', upper(coalesce(nullif(trim(p_country_code), ''), 'RW')),\n    'locale', coalesce(nullif(trim(p_locale), ''), 'en'),\n    'types', coalesce((\n      select jsonb_agg(\n        jsonb_build_object(\n          'key', ctc.key,\n          'label', ctc.label,\n          'short_purpose', ctc.short_purpose,\n          'icon_key', ctc.icon_key,\n          'default_category_subtype', ctc.default_category_subtype,\n          'default_purpose_template_key', ctc.default_purpose_template_key,\n          'display_order', ctc.display_order,\n          'subtypes', coalesce((\n            select jsonb_agg(\n              jsonb_build_object(\n                'key', ccs.key,\n                'label', ccs.label,\n                'display_order', ccs.display_order\n              )\n              order by ccs.display_order, ccs.key\n            )\n            from collection_category_subtypes ccs\n            where ccs.collection_type_key = ctc.key\n              and ccs.enabled\n          ), '[]'::jsonb),\n          'purpose_templates', coalesce((\n            select jsonb_agg(\n              jsonb_build_object(\n                'key', cpt.key,\n                'label', cpt.label,\n                'display_order', cpt.display_order\n              )\n              order by cpt.display_order, cpt.key\n            )\n            from collection_purpose_templates cpt\n            where cpt.collection_type_key = ctc.key\n              and cpt.enabled\n          ), '[]'::jsonb)\n        )\n        order by ctc.display_order, ctc.key\n      )\n      from collection_type_catalog ctc\n      where ctc.enabled\n        and exists (\n          select 1\n          from collection_type_country_rules ctcr\n          where ctcr.collection_type_key = ctc.key\n            and ctcr.enabled\n            and ctcr.country_code = upper(coalesce(nullif(trim(p_country_code), ''), 'RW'))\n        )\n    ), '[]'::jsonb)\n  );\n$$;\n\ncreate or replace function resolve_collection_catalog_choice(\n  p_collection_type text default 'ikimina',\n  p_category_subtype text default null,\n  p_purpose_label text default null,\n  p_country_code text default 'RW'\n)\nreturns jsonb\nlanguage plpgsql\nstable\nset search_path = public\nas $$\ndeclare\n  clean_type text := coalesce(nullif(trim(p_collection_type), ''), 'ikimina');\n  clean_subtype text := nullif(trim(p_category_subtype), '');\n  clean_purpose text := nullif(trim(p_purpose_label), '');\n  clean_country text := upper(coalesce(nullif(trim(p_country_code), ''), 'RW'));\n  catalog_row collection_type_catalog%rowtype;\n  subtype_row collection_category_subtypes%rowtype;\n  purpose_row collection_purpose_templates%rowtype;\nbegin\n  select *\n  into catalog_row\n  from collection_type_catalog ctc\n  where ctc.key = clean_type\n    and ctc.enabled\n    and exists (\n      select 1\n      from collection_type_country_rules ctcr\n      where ctcr.collection_type_key = ctc.key\n        and ctcr.country_code = clean_country\n        and ctcr.enabled\n    );\n\n  if catalog_row.key is null then\n    raise exception 'Unsupported collection type';\n  end if;\n\n  clean_subtype := coalesce(clean_subtype, catalog_row.default_category_subtype);\n  select *\n  into subtype_row\n  from collection_category_subtypes ccs\n  where ccs.collection_type_key = clean_type\n    and ccs.key = clean_subtype\n    and ccs.enabled;\n\n  if subtype_row.key is null then\n    raise exception 'Unsupported collection subtype';\n  end if;\n\n  if clean_purpose is null then\n    select *\n    into purpose_row\n    from collection_purpose_templates cpt\n    where cpt.collection_type_key = clean_type\n      and cpt.key = catalog_row.default_purpose_template_key\n      and cpt.enabled;\n  else\n    select *\n    into purpose_row\n    from collection_purpose_templates cpt\n    where cpt.collection_type_key = clean_type\n      and cpt.label = clean_purpose\n      and cpt.enabled;\n  end if;\n\n  if purpose_row.key is null then\n    raise exception 'Unsupported collection purpose';\n  end if;\n\n  return jsonb_build_object(\n    'collection_type', clean_type,\n    'category_subtype', subtype_row.key,\n    'purpose_label', purpose_row.label\n  );\nend;\n$$;\n\nrevoke execute on function get_collection_type_catalog(text, text) from public, anon, authenticated;\nrevoke execute on function resolve_collection_catalog_choice(text, text, text, text) from public, anon, authenticated;\ngrant execute on function get_collection_type_catalog(text, text) to anon, authenticated;\ngrant execute on function resolve_collection_catalog_choice(text, text, text, text) to authenticated;\n\ncreate or replace function audit_collection_catalog_change()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  metadata_key text;\nbegin\n  metadata_key := case\n    when tg_op = 'DELETE' then coalesce(\n      to_jsonb(old)->>'key',\n      to_jsonb(old)->>'collection_type_key'\n    )\n    else coalesce(\n      to_jsonb(new)->>'key',\n      to_jsonb(new)->>'collection_type_key'\n    )\n  end;\n\n  if auth.uid() is not null then\n    perform create_audit_log(\n      'collection_catalog.' || lower(tg_op),\n      tg_table_name,\n      null,\n      jsonb_build_object('key', metadata_key)\n    );\n  end if;\n\n  if tg_op = 'DELETE' then\n    return old;\n  end if;\n  return new;\nend;\n$$;\n\nrevoke execute on function audit_collection_catalog_change() from public, anon, authenticated;\ngrant execute on function audit_collection_catalog_change() to service_role;\n\ndrop trigger if exists audit_collection_catalog_change_trigger on collection_type_catalog;\ncreate trigger audit_collection_catalog_change_trigger\nafter insert or update or delete on collection_type_catalog\nfor each row execute function audit_collection_catalog_change();\n\ndrop trigger if exists audit_collection_catalog_change_trigger on collection_category_subtypes;\ncreate trigger audit_collection_catalog_change_trigger\nafter insert or update or delete on collection_category_subtypes\nfor each row execute function audit_collection_catalog_change();\n\ndrop trigger if exists audit_collection_catalog_change_trigger on collection_purpose_templates;\ncreate trigger audit_collection_catalog_change_trigger\nafter insert or update or delete on collection_purpose_templates\nfor each row execute function audit_collection_catalog_change();\n\ndrop trigger if exists audit_collection_catalog_change_trigger on collection_type_country_rules;\ncreate trigger audit_collection_catalog_change_trigger\nafter insert or update or delete on collection_type_country_rules\nfor each row execute function audit_collection_catalog_change();\n\ndrop trigger if exists app_realtime_event_trigger on collection_type_catalog;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on collection_type_catalog\nfor each row execute function emit_app_realtime_event('settings');\n\ndrop trigger if exists app_realtime_event_trigger on collection_category_subtypes;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on collection_category_subtypes\nfor each row execute function emit_app_realtime_event('settings');\n\ndrop trigger if exists app_realtime_event_trigger on collection_purpose_templates;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on collection_purpose_templates\nfor each row execute function emit_app_realtime_event('settings');\n\ndrop trigger if exists app_realtime_event_trigger on collection_type_country_rules;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on collection_type_country_rules\nfor each row execute function emit_app_realtime_event('settings');\n\nrevoke all on collection_type_catalog from anon, authenticated;\nrevoke all on collection_category_subtypes from anon, authenticated;\nrevoke all on collection_purpose_templates from anon, authenticated;\nrevoke all on collection_type_country_rules from anon, authenticated;\ngrant select on collection_type_catalog to anon, authenticated;\ngrant select on collection_category_subtypes to anon, authenticated;\ngrant select on collection_purpose_templates to anon, authenticated;\ngrant select on collection_type_country_rules to anon, authenticated;\ngrant insert, update, delete on collection_type_catalog to authenticated;\ngrant insert, update, delete on collection_category_subtypes to authenticated;\ngrant insert, update, delete on collection_purpose_templates to authenticated;\ngrant insert, update, delete on collection_type_country_rules to authenticated;\n\ninsert into collection_type_catalog (\n  key,\n  label,\n  short_purpose,\n  icon_key,\n  default_category_subtype,\n  default_purpose_template_key,\n  display_order,\n  enabled\n)\nvalues\n  ('ikimina', 'Ikimina', 'Group savings', 'savings', 'group_savings', 'group_savings', 10, true),\n  ('sport', 'Sport', 'Fan club support', 'sport', 'fan_club', 'fan_club_support', 20, true),\n  ('church', 'Church', 'Offering and donations', 'church', 'offering', 'offering_and_donations', 30, true),\n  ('wedding', 'Wedding', 'Wedding contributions', 'wedding', 'committee', 'wedding_contributions', 40, true),\n  ('other', 'Other', 'Custom collection', 'collections', 'custom', 'custom_collection', 50, true)\non conflict (key) do update\nset label = excluded.label,\n    short_purpose = excluded.short_purpose,\n    icon_key = excluded.icon_key,\n    default_category_subtype = excluded.default_category_subtype,\n    default_purpose_template_key = excluded.default_purpose_template_key,\n    display_order = excluded.display_order,\n    enabled = excluded.enabled,\n    updated_at = now();\n\ninsert into collection_category_subtypes (\n  collection_type_key,\n  key,\n  label,\n  display_order,\n  enabled\n)\nvalues\n  ('ikimina', 'group_savings', 'Group savings', 10, true),\n  ('ikimina', 'family_friends', 'Family or friends', 20, true),\n  ('ikimina', 'community_event', 'Community event', 30, true),\n  ('sport', 'fan_club', 'Fan club', 10, true),\n  ('sport', 'team_support', 'Team support', 20, true),\n  ('sport', 'away_travel', 'Away travel', 30, true),\n  ('church', 'offering', 'Offering', 10, true),\n  ('church', 'tithe', 'Tithe', 20, true),\n  ('church', 'project_support', 'Project support', 30, true),\n  ('wedding', 'committee', 'Committee', 10, true),\n  ('wedding', 'gift', 'Gift', 20, true),\n  ('wedding', 'ceremony_support', 'Ceremony support', 30, true),\n  ('other', 'custom', 'Custom', 10, true)\non conflict (collection_type_key, key) do update\nset label = excluded.label,\n    display_order = excluded.display_order,\n    enabled = excluded.enabled,\n    updated_at = now();\n\ninsert into collection_purpose_templates (\n  collection_type_key,\n  key,\n  label,\n  display_order,\n  enabled\n)\nvalues\n  ('ikimina', 'group_savings', 'Group savings', 10, true),\n  ('ikimina', 'member_support', 'Member support', 20, true),\n  ('sport', 'fan_club_support', 'Fan club support', 10, true),\n  ('sport', 'away_travel', 'Away travel', 20, true),\n  ('church', 'offering_and_donations', 'Offering and donations', 10, true),\n  ('church', 'church_project', 'Church project', 20, true),\n  ('wedding', 'wedding_contributions', 'Wedding contributions', 10, true),\n  ('wedding', 'wedding_gifts', 'Wedding gifts', 20, true),\n  ('other', 'custom_collection', 'Custom collection', 10, true)\non conflict (collection_type_key, key) do update\nset label = excluded.label,\n    display_order = excluded.display_order,\n    enabled = excluded.enabled,\n    updated_at = now();\n\ninsert into collection_type_country_rules (\n  collection_type_key,\n  country_code,\n  enabled,\n  min_suggested_amount_rwf,\n  max_suggested_amount_rwf\n)\nselect key, 'RW', true, 100, null\nfrom collection_type_catalog\non conflict (collection_type_key, country_code) do update\nset enabled = excluded.enabled,\n    min_suggested_amount_rwf = excluded.min_suggested_amount_rwf,\n    max_suggested_amount_rwf = excluded.max_suggested_amount_rwf,\n    updated_at = now();\n\ncreate or replace function create_group_with_owner(\n  group_name text,\n  group_description text default '',\n  receiver_momo_number text default null,\n  receiver_momo_number_hash text default null,\n  receiver_label text default 'Primary MOMO receiver',\n  group_collection_type text default 'ikimina',\n  group_category_subtype text default null,\n  group_purpose_label text default null\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  created_group_id uuid;\n  base_slug text;\n  final_slug text;\n  catalog_choice jsonb;\n  clean_type text;\n  clean_subtype text;\n  clean_purpose_label text;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n\n  catalog_choice := resolve_collection_catalog_choice(\n    group_collection_type,\n    group_category_subtype,\n    group_purpose_label,\n    'RW'\n  );\n  clean_type := catalog_choice->>'collection_type';\n  clean_subtype := catalog_choice->>'category_subtype';\n  clean_purpose_label := catalog_choice->>'purpose_label';\n\n  base_slug := normalize_slug(group_name);\n  if base_slug = '' then\n    base_slug := 'group';\n  end if;\n  final_slug := base_slug || '-' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 8);\n\n  insert into collections (\n    slug,\n    creator_user_id,\n    title,\n    description,\n    collection_type,\n    category_subtype,\n    purpose_label,\n    receiver_display_label\n  )\n  values (\n    final_slug,\n    auth.uid(),\n    trim(group_name),\n    coalesce(group_description, ''),\n    clean_type,\n    clean_subtype,\n    clean_purpose_label,\n    receiver_label\n  )\n  returning id into created_group_id;\n\n  insert into collection_members (collection_id, user_id, role, status)\n  values (created_group_id, auth.uid(), 'owner', 'active');\n\n  if receiver_momo_number is not null and receiver_momo_number_hash is not null then\n    insert into collection_receivers (\n      collection_id,\n      receiver_user_id,\n      momo_number,\n      momo_number_hash,\n      label\n    )\n    values (\n      created_group_id,\n      auth.uid(),\n      receiver_momo_number,\n      receiver_momo_number_hash,\n      receiver_label\n    );\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'group.created',\n    'collection',\n    created_group_id,\n    jsonb_build_object(\n      'collection_type', clean_type,\n      'category_subtype', clean_subtype,\n      'purpose_label', clean_purpose_label\n    )\n  );\n\n  return created_group_id;\nend;\n$$;\n\nrevoke execute on function create_group_with_owner(\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text\n) from public, anon, authenticated;\ngrant execute on function create_group_with_owner(\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text,\n  text\n) to authenticated;\n\ncreate or replace function update_collection_profile(\n  collection uuid,\n  group_name text,\n  group_description text,\n  group_image_url text default null,\n  group_accent_color_hex text default null,\n  group_is_public boolean default false,\n  group_recurring_cadence text default 'monthly',\n  group_collection_type text default null,\n  group_category_subtype text default null,\n  group_purpose_label text default null\n)\nreturns void\nlanguage plpgsql\nsecurity definer\nset search_path = public, extensions\nas $$\ndeclare\n  clean_cadence text := coalesce(\n    nullif(trim(group_recurring_cadence), ''),\n    'monthly'\n  );\n  clean_type text;\n  clean_subtype text;\n  clean_purpose_label text;\n  catalog_choice jsonb;\n  current_type text;\n  current_subtype text;\n  current_purpose_label text;\n  next_public_status collection_visibility := case\n    when coalesce(group_is_public, false) then 'public_requested'::collection_visibility\n    else 'private'::collection_visibility\n  end;\nbegin\n  if auth.uid() is null then\n    raise exception 'Authentication required';\n  end if;\n  if not user_is_collection_admin(collection, auth.uid()) then\n    raise exception 'Only collection admins can update the group profile';\n  end if;\n  if nullif(trim(group_name), '') is null then\n    raise exception 'Group name is required';\n  end if;\n  if clean_cadence not in ('daily', 'weekly', 'monthly') then\n    raise exception 'Unsupported recurring cadence';\n  end if;\n\n  select c.collection_type, c.category_subtype, c.purpose_label\n  into current_type, current_subtype, current_purpose_label\n  from collections c\n  where c.id = collection;\n\n  if current_type is null then\n    raise exception 'Group not found';\n  end if;\n\n  catalog_choice := resolve_collection_catalog_choice(\n    coalesce(nullif(trim(group_collection_type), ''), current_type),\n    coalesce(nullif(trim(group_category_subtype), ''), current_subtype),\n    coalesce(nullif(trim(group_purpose_label), ''), current_purpose_label),\n    'RW'\n  );\n  clean_type := catalog_choice->>'collection_type';\n  clean_subtype := catalog_choice->>'category_subtype';\n  clean_purpose_label := catalog_choice->>'purpose_label';\n\n  update collections\n  set\n    title = trim(group_name),\n    description = trim(coalesce(group_description, '')),\n    cover_image_url = nullif(trim(group_image_url), ''),\n    accent_color_hex = nullif(trim(group_accent_color_hex), ''),\n    public_status = next_public_status,\n    visibility = next_public_status,\n    is_recurring = true,\n    recurring_cadence = clean_cadence,\n    recurring_rule = jsonb_build_object('cadence', clean_cadence),\n    collection_type = clean_type,\n    category_subtype = clean_subtype,\n    purpose_label = clean_purpose_label,\n    updated_at = now()\n  where id = collection;\n\n  if not found then\n    raise exception 'Group not found';\n  end if;\n\n  insert into audit_logs (actor_user_id, action, entity_type, entity_id, metadata)\n  values (\n    auth.uid(),\n    'collection.profile_updated',\n    'collection',\n    collection,\n    jsonb_build_object(\n      'is_public', coalesce(group_is_public, false),\n      'public_status', next_public_status::text,\n      'recurring_cadence', clean_cadence,\n      'collection_type', clean_type,\n      'category_subtype', clean_subtype,\n      'purpose_label', clean_purpose_label\n    )\n  );\nend;\n$$;\n\nrevoke execute on function update_collection_profile(\n  uuid,\n  text,\n  text,\n  text,\n  text,\n  boolean,\n  text,\n  text,\n  text,\n  text\n) from public, anon, authenticated;\ngrant execute on function update_collection_profile(\n  uuid,\n  text,\n  text,\n  text,\n  text,\n  boolean,\n  text,\n  text,\n  text,\n  text\n) to authenticated;\n\ncommit;\n"}
20260703225455	notification_templates_runtime	{"begin;\n\ncreate table if not exists notification_channels (\n  key text primary key check (key ~ '^[a-z0-9_.-]+$'),\n  label text not null,\n  description text not null,\n  platform text not null default 'all' check (platform in ('all', 'android', 'ios', 'web')),\n  enabled boolean not null default true,\n  display_order integer not null default 100,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text\n);\n\ncreate table if not exists notification_event_types (\n  key text primary key check (key in (\n    'contribution_confirmed',\n    'payment_reminder',\n    'group_update',\n    'security_notice'\n  )),\n  preference_key text not null check (preference_key in (\n    'contribution_confirmations',\n    'payment_reminders',\n    'group_updates',\n    'security_notices'\n  )),\n  label text not null,\n  description text not null,\n  default_channel_key text not null references notification_channels(key) on delete restrict,\n  enabled boolean not null default true,\n  display_order integer not null default 100,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text\n);\n\ncreate table if not exists notification_templates (\n  key text primary key check (key ~ '^[a-z0-9_.-]+$'),\n  event_type_key text not null references notification_event_types(key) on delete restrict,\n  locale text not null default 'en' check (locale ~ '^[a-z]{2}(-[A-Z]{2})?$'),\n  enabled boolean not null default true,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text\n);\n\ncreate table if not exists notification_template_versions (\n  id uuid primary key default gen_random_uuid(),\n  template_key text not null references notification_templates(key) on delete cascade,\n  version text not null check (version ~ '^[a-zA-Z0-9_.:-]+$'),\n  title_template text not null,\n  body_template text not null,\n  status text not null default 'draft' check (status in ('draft', 'published', 'archived')),\n  effective_at timestamptz not null default now(),\n  published_at timestamptz,\n  metadata jsonb not null default '{}'::jsonb,\n  created_at timestamptz not null default now(),\n  updated_at timestamptz not null default now(),\n  updated_by uuid references profiles(id) on delete set null,\n  updated_reason text,\n  unique (template_key, version)\n);\n\ncreate index if not exists notification_channels_enabled_order_idx\n  on notification_channels (enabled, display_order, key);\n\ncreate index if not exists notification_event_types_enabled_order_idx\n  on notification_event_types (enabled, display_order, key);\n\ncreate index if not exists notification_templates_lookup_idx\n  on notification_templates (event_type_key, locale, enabled, key);\n\ncreate index if not exists notification_template_versions_active_idx\n  on notification_template_versions (template_key, status, effective_at desc, version);\n\nalter table notification_channels enable row level security;\nalter table notification_event_types enable row level security;\nalter table notification_templates enable row level security;\nalter table notification_template_versions enable row level security;\n\ndrop policy if exists \\"notification channels public enabled read\\" on notification_channels;\ncreate policy \\"notification channels public enabled read\\"\non notification_channels for select to anon, authenticated\nusing (enabled);\n\ndrop policy if exists \\"notification channels admin manage\\" on notification_channels;\ncreate policy \\"notification channels admin manage\\"\non notification_channels for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ndrop policy if exists \\"notification event types public enabled read\\" on notification_event_types;\ncreate policy \\"notification event types public enabled read\\"\non notification_event_types for select to anon, authenticated\nusing (enabled);\n\ndrop policy if exists \\"notification event types admin manage\\" on notification_event_types;\ncreate policy \\"notification event types admin manage\\"\non notification_event_types for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ndrop policy if exists \\"notification templates public enabled read\\" on notification_templates;\ncreate policy \\"notification templates public enabled read\\"\non notification_templates for select to anon, authenticated\nusing (\n  enabled\n  and exists (\n    select 1\n    from notification_event_types net\n    where net.key = notification_templates.event_type_key\n      and net.enabled\n  )\n);\n\ndrop policy if exists \\"notification templates admin manage\\" on notification_templates;\ncreate policy \\"notification templates admin manage\\"\non notification_templates for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ndrop policy if exists \\"notification template versions public published read\\" on notification_template_versions;\ncreate policy \\"notification template versions public published read\\"\non notification_template_versions for select to anon, authenticated\nusing (\n  status = 'published'\n  and effective_at <= now()\n  and exists (\n    select 1\n    from notification_templates nt\n    join notification_event_types net on net.key = nt.event_type_key\n    where nt.key = notification_template_versions.template_key\n      and nt.enabled\n      and net.enabled\n  )\n);\n\ndrop policy if exists \\"notification template versions admin manage\\" on notification_template_versions;\ncreate policy \\"notification template versions admin manage\\"\non notification_template_versions for all to authenticated\nusing (public.has_admin_permission('settings.manage', (select auth.uid())))\nwith check (public.has_admin_permission('settings.manage', (select auth.uid())));\n\ncreate or replace function render_notification_template(\n  p_template text,\n  p_context jsonb default '{}'::jsonb\n)\nreturns text\nlanguage plpgsql\nstable\nset search_path = public\nas $$\ndeclare\n  rendered text := coalesce(p_template, '');\n  context_entry record;\nbegin\n  for context_entry in\n    select key, value\n    from jsonb_each_text(coalesce(p_context, '{}'::jsonb))\n  loop\n    rendered := replace(rendered, '{{' || context_entry.key || '}}', context_entry.value);\n  end loop;\n  return rendered;\nend;\n$$;\n\ncreate or replace function get_notification_runtime_config(p_locale text default 'en')\nreturns jsonb\nlanguage sql\nstable\nset search_path = public\nas $$\n  select jsonb_build_object(\n    'locale', coalesce(nullif(trim(p_locale), ''), 'en'),\n    'channels', coalesce((\n      select jsonb_agg(\n        jsonb_build_object(\n          'key', nc.key,\n          'label', nc.label,\n          'description', nc.description,\n          'platform', nc.platform,\n          'display_order', nc.display_order\n        )\n        order by nc.display_order, nc.key\n      )\n      from notification_channels nc\n      where nc.enabled\n    ), '[]'::jsonb),\n    'event_types', coalesce((\n      select jsonb_agg(\n        jsonb_build_object(\n          'key', net.key,\n          'preference_key', net.preference_key,\n          'label', net.label,\n          'description', net.description,\n          'default_channel_key', net.default_channel_key,\n          'display_order', net.display_order\n        )\n        order by net.display_order, net.key\n      )\n      from notification_event_types net\n      where net.enabled\n    ), '[]'::jsonb)\n  );\n$$;\n\ncreate or replace function enqueue_notification_template_event(\n  p_user_id uuid,\n  p_template_key text,\n  p_context jsonb default '{}'::jsonb,\n  p_collection_id uuid default null,\n  p_deep_link text default null,\n  p_locale text default 'en'\n)\nreturns uuid\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  template_row record;\n  inserted_id uuid;\n  preference_enabled boolean := true;\nbegin\n  select\n    nt.key,\n    net.key as event_type,\n    net.preference_key,\n    ntv.title_template,\n    ntv.body_template\n  into template_row\n  from notification_templates nt\n  join notification_event_types net on net.key = nt.event_type_key\n  join notification_template_versions ntv on ntv.template_key = nt.key\n  where nt.key = trim(p_template_key)\n    and nt.locale in (coalesce(nullif(trim(p_locale), ''), 'en'), 'en')\n    and nt.enabled\n    and net.enabled\n    and ntv.status = 'published'\n    and ntv.effective_at <= now()\n  order by\n    case when nt.locale = coalesce(nullif(trim(p_locale), ''), 'en') then 0 else 1 end,\n    ntv.effective_at desc,\n    ntv.version desc\n  limit 1;\n\n  if template_row.key is null then\n    raise exception 'notification_template_not_found';\n  end if;\n\n  select case template_row.preference_key\n    when 'contribution_confirmations' then coalesce(contribution_confirmations, true)\n    when 'payment_reminders' then coalesce(payment_reminders, true)\n    when 'group_updates' then coalesce(group_updates, true)\n    when 'security_notices' then coalesce(security_notices, true)\n    else true\n  end\n  into preference_enabled\n  from notification_preferences\n  where user_id = p_user_id;\n\n  if coalesce(preference_enabled, true) is false then\n    return null;\n  end if;\n\n  insert into notification_events (\n    user_id,\n    collection_id,\n    type,\n    title,\n    body,\n    deep_link\n  )\n  values (\n    p_user_id,\n    p_collection_id,\n    template_row.event_type,\n    render_notification_template(template_row.title_template, p_context),\n    render_notification_template(template_row.body_template, p_context),\n    p_deep_link\n  )\n  returning id into inserted_id;\n\n  return inserted_id;\nend;\n$$;\n\nrevoke execute on function render_notification_template(text, jsonb) from public, anon, authenticated;\nrevoke execute on function get_notification_runtime_config(text) from public, anon, authenticated;\nrevoke execute on function enqueue_notification_template_event(uuid, text, jsonb, uuid, text, text) from public, anon, authenticated;\ngrant execute on function get_notification_runtime_config(text) to anon, authenticated;\ngrant execute on function render_notification_template(text, jsonb) to service_role;\ngrant execute on function enqueue_notification_template_event(uuid, text, jsonb, uuid, text, text) to service_role;\n\ncreate or replace function audit_notification_runtime_change()\nreturns trigger\nlanguage plpgsql\nsecurity definer\nset search_path = public\nas $$\ndeclare\n  metadata_key text;\nbegin\n  metadata_key := case\n    when tg_op = 'DELETE' then coalesce(\n      to_jsonb(old)->>'key',\n      to_jsonb(old)->>'template_key',\n      to_jsonb(old)->>'id'\n    )\n    else coalesce(\n      to_jsonb(new)->>'key',\n      to_jsonb(new)->>'template_key',\n      to_jsonb(new)->>'id'\n    )\n  end;\n\n  if auth.uid() is not null then\n    perform create_audit_log(\n      'notification_runtime.' || lower(tg_op),\n      tg_table_name,\n      null,\n      jsonb_build_object('key', metadata_key)\n    );\n  end if;\n\n  if tg_op = 'DELETE' then\n    return old;\n  end if;\n  return new;\nend;\n$$;\n\nrevoke execute on function audit_notification_runtime_change() from public, anon, authenticated;\ngrant execute on function audit_notification_runtime_change() to service_role;\n\ndrop trigger if exists audit_notification_runtime_change_trigger on notification_channels;\ncreate trigger audit_notification_runtime_change_trigger\nafter insert or update or delete on notification_channels\nfor each row execute function audit_notification_runtime_change();\n\ndrop trigger if exists audit_notification_runtime_change_trigger on notification_event_types;\ncreate trigger audit_notification_runtime_change_trigger\nafter insert or update or delete on notification_event_types\nfor each row execute function audit_notification_runtime_change();\n\ndrop trigger if exists audit_notification_runtime_change_trigger on notification_templates;\ncreate trigger audit_notification_runtime_change_trigger\nafter insert or update or delete on notification_templates\nfor each row execute function audit_notification_runtime_change();\n\ndrop trigger if exists audit_notification_runtime_change_trigger on notification_template_versions;\ncreate trigger audit_notification_runtime_change_trigger\nafter insert or update or delete on notification_template_versions\nfor each row execute function audit_notification_runtime_change();\n\ndrop trigger if exists app_realtime_event_trigger on notification_channels;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on notification_channels\nfor each row execute function emit_app_realtime_event('settings');\n\ndrop trigger if exists app_realtime_event_trigger on notification_event_types;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on notification_event_types\nfor each row execute function emit_app_realtime_event('settings');\n\ndrop trigger if exists app_realtime_event_trigger on notification_templates;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on notification_templates\nfor each row execute function emit_app_realtime_event('settings');\n\ndrop trigger if exists app_realtime_event_trigger on notification_template_versions;\ncreate trigger app_realtime_event_trigger\nafter insert or update or delete on notification_template_versions\nfor each row execute function emit_app_realtime_event('settings');\n\nrevoke all on notification_channels from anon, authenticated;\nrevoke all on notification_event_types from anon, authenticated;\nrevoke all on notification_templates from anon, authenticated;\nrevoke all on notification_template_versions from anon, authenticated;\ngrant select on notification_channels to anon, authenticated;\ngrant select on notification_event_types to anon, authenticated;\ngrant select on notification_templates to anon, authenticated;\ngrant select on notification_template_versions to anon, authenticated;\ngrant insert, update, delete on notification_channels to authenticated;\ngrant insert, update, delete on notification_event_types to authenticated;\ngrant insert, update, delete on notification_templates to authenticated;\ngrant insert, update, delete on notification_template_versions to authenticated;\n\ninsert into notification_channels (key, label, description, platform, display_order, enabled)\nvalues\n  (\n    'collect_group_updates',\n    'Collect group updates',\n    'Contribution confirmations, payment reminders, group updates, and security notices.',\n    'all',\n    10,\n    true\n  )\non conflict (key) do update\nset label = excluded.label,\n    description = excluded.description,\n    platform = excluded.platform,\n    display_order = excluded.display_order,\n    enabled = excluded.enabled,\n    updated_at = now();\n\ninsert into notification_event_types (\n  key,\n  preference_key,\n  label,\n  description,\n  default_channel_key,\n  display_order,\n  enabled\n)\nvalues\n  ('contribution_confirmed', 'contribution_confirmations', 'Contribution confirmed', 'A contribution has been matched and posted.', 'collect_group_updates', 10, true),\n  ('payment_reminder', 'payment_reminders', 'Payment reminder', 'A contribution request is still pending.', 'collect_group_updates', 20, true),\n  ('group_update', 'group_updates', 'Group update', 'A group profile, member, or status changed.', 'collect_group_updates', 30, true),\n  ('security_notice', 'security_notices', 'Security notice', 'A security-sensitive account or group event occurred.', 'collect_group_updates', 40, true)\non conflict (key) do update\nset preference_key = excluded.preference_key,\n    label = excluded.label,\n    description = excluded.description,\n    default_channel_key = excluded.default_channel_key,\n    display_order = excluded.display_order,\n    enabled = excluded.enabled,\n    updated_at = now();\n\ninsert into notification_templates (key, event_type_key, locale, enabled)\nvalues\n  ('contribution.confirmed.default', 'contribution_confirmed', 'en', true),\n  ('payment.reminder.default', 'payment_reminder', 'en', true),\n  ('group.update.default', 'group_update', 'en', true),\n  ('security.notice.default', 'security_notice', 'en', true)\non conflict (key) do update\nset event_type_key = excluded.event_type_key,\n    locale = excluded.locale,\n    enabled = excluded.enabled,\n    updated_at = now();\n\ninsert into notification_template_versions (\n  template_key,\n  version,\n  title_template,\n  body_template,\n  status,\n  effective_at,\n  published_at\n)\nvalues\n  (\n    'contribution.confirmed.default',\n    '2026-07-04',\n    'Contribution confirmed',\n    '{{amount}} has been confirmed for {{group}}.',\n    'published',\n    '2026-07-04 00:00:00+00',\n    '2026-07-04 00:00:00+00'\n  ),\n  (\n    'payment.reminder.default',\n    '2026-07-04',\n    'Payment reminder',\n    '{{group}} is waiting for {{amount}}.',\n    'published',\n    '2026-07-04 00:00:00+00',\n    '2026-07-04 00:00:00+00'\n  ),\n  (\n    'group.update.default',\n    '2026-07-04',\n    'Group update',\n    '{{group}} has a new update.',\n    'published',\n    '2026-07-04 00:00:00+00',\n    '2026-07-04 00:00:00+00'\n  ),\n  (\n    'security.notice.default',\n    '2026-07-04',\n    'Security notice',\n    '{{detail}}',\n    'published',\n    '2026-07-04 00:00:00+00',\n    '2026-07-04 00:00:00+00'\n  )\non conflict (template_key, version) do update\nset title_template = excluded.title_template,\n    body_template = excluded.body_template,\n    status = excluded.status,\n    effective_at = excluded.effective_at,\n    published_at = excluded.published_at,\n    updated_at = now();\n\ncommit;\n"}
